      Freq_gt_2Hz = frequency_gt_2hz,
      Sporadic_Discharges = sporadic_discharges,
      LPD_LRDA_BIPD = lpd_lrda_bipd,
      Plus_Features = plus_features,
      Prior_Seizure = prior_seizure,
      BIRD_Present = bird
    )
