  if (any(is.na(c(bmpc_percent, m_protein_g_dl, flc_ratio)))) {
    stop("Error: All inputs must be numeric.")
  }

  risk_factors <- 0

  if (bmpc_percent > 20) {
    risk_factors <- risk_factors + 1
  }

  if (m_protein_g_dl > 2) {
    risk_factors <- risk_factors + 1
  }

  if (flc_ratio > 20) {
    risk_factors <- risk_factors + 1
  }

  risk_group <- ""
