  }

  score <- 0

  if (disease_group == 1) {
    score <- score + 1
  }

  if (cytogenetics == 1) {
    score <- score + 1
  }

  if (hla_match == 1) {
    score <- score + 2
  }

  if (circulating_blasts == 1) {
