  score <- 0

  if (history_thrombosis == 1) {
    score <- score + 2
  }

  if (multilumen_catheter == 1) {
    score <- score + 1
  }

  if (active_cancer == 1) {
    score <- score + 3
  }

  if (another_cvc_present == 1) {
    score <- score + 1
  }

  if (wbc_gt_12000 == 1) {
