      Age = age,
      Weight_kg = weight_kg
    )
  ))
}

calculate_tir_rosendaal <- function(data_vector, time_interval_minutes, target_min, target_max) {

  if (!is.numeric(data_vector) || any(is.infinite(data_vector))) {
    return("Error: 'data_vector' must be a finite numeric vector.")
  }
  if (!is.numeric(time_interval_minutes) || length(time_interval_minutes) != 1 || time_interval_minutes <= 0) {
    return("Error: 'time_interval_minutes' must be a single positive numeric value.")
  }
  if (!is.numeric(target_min) || !is.numeric(target_max) || length(target_min) != 1 || length(target_max) != 1) {
    return("Error: 'target_min' and 'target_max' must be single numeric values.")
  }
  if (target_min >= target_max) {
    return("Error: 'target_min' must be strictly less than 'target_max'.")
  }

  clean_data <- na.omit(data_vector)
  N <- length(clean_data)

  if (N < 2) {
    return("Warning: Need at least two non-NA data points for interpolation. TIR is 0%.")
  }

  total_time_observed <- (N - 1) * time_interval_minutes
  time_in_range <- 0

  L <- target_min
  H <- target_max

  for (i in 1:(N - 1)) {
    x1 <- clean_data[i]
    x2 <- clean_data[i + 1]
    T_interval <- time_interval_minutes

    min_x <- min(x1, x2)
    max_x <- max(x1, x2)

    if (min_x >= L && max_x <= H) {
      time_in_range <- time_in_range + T_interval
      next
    }

    if (max_x < L || min_x > H) {
      time_in_range <- time_in_range + 0
      next
    }

    total_change <- abs(x2 - x1)

    if (total_change == 0) {
      if (x1 >= L && x1 <= H) {
        time_in_range <- time_in_range + T_interval
      }
      next
    }

    t_out_low <- 0
    t_out_high <- 0

    if (min_x < L) {
      t_out_low <- T_interval * (L - min_x) / total_change
    }

    if (max_x > H) {
      t_out_high <- T_interval * (max_x - H) / total_change
    }

    t_in <- T_interval - t_out_low - t_out_high

    time_in_range <- time_in_range + max(0, t_in)
  }

  tir_percentage <- (time_in_range / total_time_observed) * 100

  return(tir_percentage)
}

ottawa_ankle_rules <- function(age, pain_malleolar_zone, pain_midfoot_zone, tenderness_distal_tibia_fibula, tenderness_medial_malleolus, tenderness_lateral_malleolus, tenderness_base_5th_metatarsal, tenderness_navicular, inability_to_bear_weight) {

  age <- as.numeric(age)
  pain_malleolar_zone <- as.numeric(pain_malleolar_zone)
  pain_midfoot_zone <- as.numeric(pain_midfoot_zone)
  tenderness_distal_tibia_fibula <- as.numeric(tenderness_distal_tibia_fibula)
  tenderness_medial_malleolus <- as.numeric(tenderness_medial_malleolus)
  tenderness_lateral_malleolus <- as.numeric(tenderness_lateral_malleolus)
  tenderness_base_5th_metatarsal <- as.numeric(tenderness_base_5th_metatarsal)
  tenderness_navicular <- as.numeric(tenderness_navicular)
  inability_to_bear_weight <- as.numeric(inability_to_bear_weight)

  if (any(is.na(c(age, pain_malleolar_zone, pain_midfoot_zone, tenderness_distal_tibia_fibula, tenderness_medial_malleolus, tenderness_lateral_malleolus, tenderness_base_5th_metatarsal, tenderness_navicular, inability_to_bear_weight)))) {
    stop("Error: All inputs must be numeric.")
  }

  ankle_xray_indicated <- FALSE
  foot_xray_indicated <- FALSE

  if (pain_malleolar_zone == 1) {
    if (tenderness_distal_tibia_fibula == 1 || tenderness_medial_malleolus == 1 || tenderness_lateral_malleolus == 1 || inability_to_bear_weight == 1) {
      ankle_xray_indicated <- TRUE
    }
  }

  if (pain_midfoot_zone == 1) {
    if (tenderness_base_5th_metatarsal == 1 || tenderness_navicular == 1 || inability_to_bear_weight == 1) {
      foot_xray_indicated <- TRUE
    }
  }

  recommendation <- ""
  if (ankle_xray_indicated && foot_xray_indicated) {
    recommendation <- "Ankle and Foot X-ray Series Indicated"
  } else if (ankle_xray_indicated) {
    recommendation <- "Ankle X-ray Series Indicated"
  } else if (foot_xray_indicated) {
    recommendation <- "Foot X-ray Series Indicated"
  } else {
    recommendation <- "X-rays Not Indicated (99% sensitivity for ruling out fracture)"
  }

  return(list(
    Result = recommendation,
    Imaging_Indicated = list(
      Ankle_Xray = ankle_xray_indicated,
      Foot_Xray = foot_xray_indicated
    ),
    Inputs = list(
      Age = age,
      Malleolar_Pain = pain_malleolar_zone == 1,
      Midfoot_Pain = pain_midfoot_zone == 1,
      Tenderness_Medial = tenderness_medial_malleolus == 1,
      Tenderness_Lateral = tenderness_lateral_malleolus == 1,
      Tenderness_5th_Metatarsal = tenderness_base_5th_metatarsal == 1,
      Tenderness_Navicular = tenderness_navicular == 1,
      Cant_Bear_Weight = inability_to_bear_weight == 1
    )
  ))
}

ottawa_copd_risk_scale <- function(history_copd, history_intubation, history_revascularization, sa02_on_arrival, ecg_ischemia, antianginal_medication, heart_rate_on_arrival, cxr_pulmonary_venous_congestion, hemoglobin_on_arrival, bun_on_arrival) {

  history_copd <- as.numeric(history_copd)
  history_intubation <- as.numeric(history_intubation)
  history_revascularization <- as.numeric(history_revascularization)
  sa02_on_arrival <- as.numeric(sa02_on_arrival)
  ecg_ischemia <- as.numeric(ecg_ischemia)
  antianginal_medication <- as.numeric(antianginal_medication)
  heart_rate_on_arrival <- as.numeric(heart_rate_on_arrival)
  cxr_pulmonary_venous_congestion <- as.numeric(cxr_pulmonary_venous_congestion)
  hemoglobin_on_arrival <- as.numeric(hemoglobin_on_arrival)
  bun_on_arrival <- as.numeric(bun_on_arrival)

  if (any(is.na(c(history_copd, history_intubation, history_revascularization, sa02_on_arrival, ecg_ischemia, antianginal_medication, heart_rate_on_arrival, cxr_pulmonary_venous_congestion, hemoglobin_on_arrival, bun_on_arrival)))) {
    stop("Error: All inputs must be numeric.")
  }

  score <- 0

  if (history_copd == 0) score <- score + 0
  else score <- score + 0

  if (history_intubation == 1) {
    score <- score + 2
  }

  if (history_revascularization == 1) {
    score <- score + 1
  }

  if (sa02_on_arrival < 92) {
    score <- score + 2
  }

  if (ecg_ischemia == 1) {
    score <- score + 2
  }

  if (antianginal_medication == 1) {
    score <- score + 1
  }

  if (heart_rate_on_arrival >= 110) {
    score <- score + 2
  }

  if (cxr_pulmonary_venous_congestion == 1) {
    score <- score + 2
  }

  if (hemoglobin_on_arrival < 100) { # g/L
    score <- score + 3
  }

  if (bun_on_arrival > 12) { # mmol/L
    score <- score + 1
  }

  risk_percent <- ""
  if (score <= 0) risk_percent <- "0.0%"
  else if (score == 1) risk_percent <- "1.8%"
  else if (score == 2) risk_percent <- "2.9%"
  else if (score == 3) risk_percent <- "4.3%"
  else if (score == 4) risk_percent <- "6.3%"
  else if (score == 5) risk_percent <- "9.4%"
  else if (score == 6) risk_percent <- "13.9%"
  else if (score == 7) risk_percent <- "21.9%"
  else if (score == 8) risk_percent <- "29.9%"
  else if (score == 9) risk_percent <- "39.5%"
  else risk_percent <- "50.0%"

  return(list(
    Ottawa_COPD_Risk_Score = score,
    Risk_Short_Term_Adverse_Event = risk_percent,
    Inputs = list(
      Hx_Intubation = history_intubation == 1,
      Hx_Revascularization = history_revascularization == 1,
      Low_SaO2 = sa02_on_arrival < 92,
      ECG_Ischemia = ecg_ischemia == 1,
      AntiAnginals = antianginal_medication == 1,
      Tachycardia = heart_rate_on_arrival >= 110,
      CXR_Congestion = cxr_pulmonary_venous_congestion == 1,
      Low_Hemoglobin = hemoglobin_on_arrival < 100,
      High_BUN = bun_on_arrival > 12
    )
  ))
}

ottawa_heart_failure_risk_scale <- function(stroke_tia_history, intubation_history, heart_rate_arrival, oxygen_sat_arrival, heart_rate_walk_test, ecg_ischemia, urea_mmol_l, co2_mmol_l, troponin_elevated, nt_probnp) {

  stroke_tia_history <- as.numeric(stroke_tia_history)
  intubation_history <- as.numeric(intubation_history)
  heart_rate_arrival <- as.numeric(heart_rate_arrival)
  oxygen_sat_arrival <- as.numeric(oxygen_sat_arrival)
  heart_rate_walk_test <- as.numeric(heart_rate_walk_test)
  ecg_ischemia <- as.numeric(ecg_ischemia)
  urea_mmol_l <- as.numeric(urea_mmol_l)
  co2_mmol_l <- as.numeric(co2_mmol_l)
  troponin_elevated <- as.numeric(troponin_elevated)
  nt_probnp <- as.numeric(nt_probnp)

  if (any(is.na(c(stroke_tia_history, intubation_history, heart_rate_arrival, oxygen_sat_arrival, heart_rate_walk_test, ecg_ischemia, urea_mmol_l, co2_mmol_l, troponin_elevated, nt_probnp)))) {
    stop("Error: All inputs must be numeric.")
  }

  score <- 0

  if (stroke_tia_history == 1) score <- score + 1

  if (intubation_history == 1) score <- score + 2

  if (heart_rate_arrival >= 110) score <- score + 2

  if (oxygen_sat_arrival < 90) score <- score + 1

  if (heart_rate_walk_test >= 110) score <- score + 1 # Or if unable to perform walk test

  if (ecg_ischemia == 1) score <- score + 2

  if (urea_mmol_l >= 12) score <- score + 1

  if (co2_mmol_l >= 35) score <- score + 2

  if (troponin_elevated == 1) score <- score + 2

  if (nt_probnp >= 5000) score <- score + 1

  risk_category <- ""
  sae_risk_14d <- ""
  recommendation <- ""

  if (score == 0) {
    risk_category <- "Low Risk"
    sae_risk_14d <- "2.8%"
    recommendation <- "Consider discharge with close follow-up."
  } else if (score <= 2) {
    risk_category <- "Moderate Risk"
    sae_risk_14d <- "5.1 - 9.2%"
    recommendation <- "Consider admission or close observation (Score > 1 often used as admission threshold)."
  } else if (score <= 4) {
    risk_category <- "High Risk"
    sae_risk_14d <- "15.9 - 26.1%"
    recommendation <- "Admission recommended."
  } else {
    risk_category <- "Very High Risk"
    sae_risk_14d <- "39.8 - 89.0%"
    recommendation <- "Admission to monitored setting recommended."
  }

  return(list(
    OHFRS_Score = score,
    Risk_Category = risk_category,
    Risk_Serious_Adverse_Event_14d = sae_risk_14d,
    Recommendation = recommendation,
    Inputs = list(
      Hx_Stroke_TIA = stroke_tia_history == 1,
      Hx_Intubation = intubation_history == 1,
      HR_Arrival_ge_110 = heart_rate_arrival >= 110,
      SaO2_Arrival_lt_90 = oxygen_sat_arrival < 90,
      HR_Walk_ge_110_or_Unable = heart_rate_walk_test >= 110,
      ECG_Ischemia = ecg_ischemia == 1,
      Urea_ge_12 = urea_mmol_l >= 12,
      CO2_ge_35 = co2_mmol_l >= 35,
      Trop_Elevated = troponin_elevated == 1,
      NT_proBNP_ge_5000 = nt_probnp >= 5000
    )
  ))
}

ottawa_knee_rule <- function(age, isolated_patella_tenderness, fibula_head_tenderness, inability_to_flex_90, inability_to_bear_weight) {

  age <- as.numeric(age)
  isolated_patella_tenderness <- as.numeric(isolated_patella_tenderness)
  fibula_head_tenderness <- as.numeric(fibula_head_tenderness)
  inability_to_flex_90 <- as.numeric(inability_to_flex_90)
  inability_to_bear_weight <- as.numeric(inability_to_bear_weight)

  if (any(is.na(c(age, isolated_patella_tenderness, fibula_head_tenderness, inability_to_flex_90, inability_to_bear_weight)))) {
    stop("Error: All inputs must be numeric.")
  }

  xray_indicated <- FALSE
  reasons <- c()

  if (age >= 55) {
    xray_indicated <- TRUE
    reasons <- c(reasons, "Age >= 55")
  }

  if (isolated_patella_tenderness == 1) {
    xray_indicated <- TRUE
    reasons <- c(reasons, "Isolated tenderness of the patella")
  }

  if (fibula_head_tenderness == 1) {
    xray_indicated <- TRUE
    reasons <- c(reasons, "Tenderness at the head of the fibula")
  }

  if (inability_to_flex_90 == 1) {
    xray_indicated <- TRUE
    reasons <- c(reasons, "Inability to flex knee to 90 degrees")
  }

  if (inability_to_bear_weight == 1) {
    xray_indicated <- TRUE
    reasons <- c(reasons, "Inability to bear weight (4 steps)")
  }

  recommendation <- ""
  sensitivity <- ""

  if (xray_indicated) {
    recommendation <- "Knee X-ray Series Indicated"
    sensitivity <- "98.5% Sensitivity for fracture"
  } else {
    recommendation <- "Knee X-ray Not Indicated"
    sensitivity <- "High sensitivity for ruling out fracture (98.5%)"
  }

  return(list(
    Result = recommendation,
    Reasoning = if (length(reasons) > 0) reasons else "No high-risk criteria met",
    Test_Characteristics = sensitivity,
    Inputs = list(
      Age = age,
      Patella_Tenderness = isolated_patella_tenderness == 1,
      Fibula_Tenderness = fibula_head_tenderness == 1,
      Flexion_Limit = inability_to_flex_90 == 1,
      Weight_Bearing_Issue = inability_to_bear_weight == 1
    )
  ))
}

ottawa_sah_rule <- function(age, neck_pain_stiffness, witnessed_loc, onset_exertion, thunderclap_headache, limited_neck_flexion) {

  age <- as.numeric(age)
  neck_pain_stiffness <- as.numeric(neck_pain_stiffness)
  witnessed_loc <- as.numeric(witnessed_loc)
  onset_exertion <- as.numeric(onset_exertion)
  thunderclap_headache <- as.numeric(thunderclap_headache)
  limited_neck_flexion <- as.numeric(limited_neck_flexion)

  if (any(is.na(c(age, neck_pain_stiffness, witnessed_loc, onset_exertion, thunderclap_headache, limited_neck_flexion)))) {
    stop("Error: All inputs must be numeric.")
  }

  if (age < 15) {
    warning("Ottawa SAH Rule is not validated for patients under 15 years of age.")
  }

  high_risk_criteria <- FALSE
  reasons <- c()

  if (age >= 40) {
    high_risk_criteria <- TRUE
    reasons <- c(reasons, "Age >= 40")
  }

  if (neck_pain_stiffness == 1) {
    high_risk_criteria <- TRUE
    reasons <- c(reasons, "Neck pain or stiffness")
  }

  if (witnessed_loc == 1) {
    high_risk_criteria <- TRUE
    reasons <- c(reasons, "Witnessed loss of consciousness")
  }

  if (onset_exertion == 1) {
    high_risk_criteria <- TRUE
    reasons <- c(reasons, "Onset during exertion")
  }

  if (thunderclap_headache == 1) {
    high_risk_criteria <- TRUE
    reasons <- c(reasons, "Thunderclap headache (peaking instantly)")
  }

  if (limited_neck_flexion == 1) {
    high_risk_criteria <- TRUE
    reasons <- c(reasons, "Limited neck flexion on exam")
  }

  recommendation <- ""
  sensitivity <- ""

  if (high_risk_criteria) {
    recommendation <- "Investigate for Subarachnoid Hemorrhage (CT Head usually indicated)."
    sensitivity <- "100% Sensitivity (Rules IN need for workup, not diagnosis)"
  } else {
    recommendation <- "Rule Out SAH (High Sensitivity: 100%). Investigation likely not needed if all criteria absent."
    sensitivity <- "100% Sensitivity"
  }

  return(list(
    Result = recommendation,
    Criteria_Met = if (length(reasons) > 0) reasons else "None (All criteria negative)",
    Test_Sensitivity = sensitivity,
    Inputs = list(
      Age = age,
      Neck_Pain = neck_pain_stiffness == 1,
      Witnessed_LOC = witnessed_loc == 1,
      Exertion_Onset = onset_exertion == 1,
      Thunderclap = thunderclap_headache == 1,
      Limited_Neck_Flexion = limited_neck_flexion == 1
    )
  ))
}

convert_lab_units <- function(value, analyte, from_unit, to_unit) {

  conversion_table <- list(
    "Glucose" = list(us_unit = "mg/dL", si_unit = "mmol/L", factor = 0.0555),
    "Creatinine" = list(us_unit = "mg/dL", si_unit = "umol/L", factor = 88.4),
    "BUN" = list(us_unit = "mg/dL", si_unit = "mmol/L", factor = 0.357),
    "Cholesterol" = list(us_unit = "mg/dL", si_unit = "mmol/L", factor = 0.0259),
    "Triglycerides" = list(us_unit = "mg/dL", si_unit = "mmol/L", factor = 0.0113),
    "Calcium" = list(us_unit = "mg/dL", si_unit = "mmol/L", factor = 0.25),
    "Magnesium" = list(us_unit = "mg/dL", si_unit = "mmol/L", factor = 0.4114),
    "Bilirubin" = list(us_unit = "mg/dL", si_unit = "umol/L", factor = 17.1),
    "Sodium" = list(us_unit = "mEq/L", si_unit = "mmol/L", factor = 1.0),
    "Potassium" = list(us_unit = "mEq/L", si_unit = "mmol/L", factor = 1.0),
    "Hemoglobin" = list(us_unit = "g/dL", si_unit = "g/L", factor = 10.0),
    "Albumin" = list(us_unit = "g/dL", si_unit = "g/L", factor = 10.0),
    "Total Protein" = list(us_unit = "g/dL", si_unit = "g/L", factor = 10.0),
    "Iron" = list(us_unit = "ug/dL", si_unit = "umol/L", factor = 0.1791),
    "Ferritin" = list(us_unit = "ng/mL", si_unit = "pmol/L", factor = 2.247)
  )

  if (!is.numeric(value) || length(value) != 1 || is.na(value) || is.infinite(value)) {
    return("Error: 'value' must be a single finite numeric value.")
  }

  analyte_norm <- tolower(trimws(analyte))
  from_unit_norm <- tolower(trimws(from_unit))
  to_unit_norm <- tolower(trimws(to_unit))

  if (!is.character(analyte) || length(analyte) != 1) {
    return("Error: 'analyte' must be a single character string.")
  }
  if (!is.character(from_unit) || length(from_unit) != 1) {
    return("Error: 'from_unit' must be a single character string.")
  }
  if (!is.character(to_unit) || length(to_unit) != 1) {
    return("Error: 'to_unit' must be a single character string.")
  }

  analyte_names <- tolower(names(conversion_table))
  match_index <- match(analyte_norm, analyte_names)

  if (is.na(match_index)) {
    return(paste0("Error: Analyte '", analyte, "' not supported. Supported: ",
                  paste(names(conversion_table), collapse = ", ")))
  }

  analyte_key <- names(conversion_table)[match_index]
  conversion <- conversion_table[[analyte_key]]

  valid_systems <- c("us", "si")
  if (!(from_unit_norm %in% valid_systems) || !(to_unit_norm %in% valid_systems)) {
    return("Error: Unit systems must be 'US' or 'SI'.")
  }

  if (from_unit_norm == to_unit_norm) {
    return(c(value, switch(from_unit_norm, "us" = conversion$us_unit, "si" = conversion$si_unit)))
  }

  factor <- conversion$factor

  if (from_unit_norm == "us" && to_unit_norm == "si") {
    converted_value <- value * factor
    target_unit <- conversion$si_unit

  } else if (from_unit_norm == "si" && to_unit_norm == "us") {
    converted_value <- value / factor
    target_unit <- conversion$us_unit

  } else {
    return("Error: Internal logic failure during unit conversion.")
  }

  return(c(converted_value, target_unit))
}

overall_neuropathy_limitations_scale <- function(arm_symptoms, wash_hair, turn_key, use_knife, fasten_buttons, leg_symptoms, walking_status) {

  arm_symptoms <- as.numeric(arm_symptoms)
  wash_hair <- as.numeric(wash_hair)
  turn_key <- as.numeric(turn_key)
  use_knife <- as.numeric(use_knife)
  fasten_buttons <- as.numeric(fasten_buttons)
  leg_symptoms <- as.numeric(leg_symptoms)
  walking_status <- tolower(as.character(walking_status))

  if (any(is.na(c(arm_symptoms, wash_hair, turn_key, use_knife, fasten_buttons, leg_symptoms)))) {
    stop("Error: All numeric/binary inputs must be valid.")
  }

  if (!walking_status %in% c("normal", "symptoms_only", "difficulty_running", "difficulty_walking", "unilateral_support", "bilateral_support", "wheelchair", "bedbound")) {
    stop("Error: Walking status must be one of: 'normal', 'symptoms_only', 'difficulty_running', 'difficulty_walking', 'unilateral_support', 'bilateral_support', 'wheelchair', 'bedbound'.")
  }

  arm_score <- 0

  if (arm_symptoms == 1) {
    impossible_count <- 0
    difficulty_count <- 0

    task_scores <- c(wash_hair, turn_key, use_knife, fasten_buttons)

    for (score in task_scores) {
      if (score == 2) impossible_count <- impossible_count + 1
      if (score == 1) difficulty_count <- difficulty_count + 1
    }

    if (impossible_count >= 3) {
      arm_score <- 5
    } else if (impossible_count == 2) {
      arm_score <- 4
    } else if (impossible_count == 1) {
      arm_score <- 3
    } else if (difficulty_count > 0) {
      arm_score <- 2
    } else {
      arm_score <- 1
    }
  }

  leg_score <- 0

  if (walking_status == "bedbound") {
    leg_score <- 7
  } else if (walking_status == "wheelchair") {
    leg_score <- 6
  } else if (walking_status == "bilateral_support") {
    leg_score <- 5
  } else if (walking_status == "unilateral_support") {
    leg_score <- 4
  } else if (walking_status == "difficulty_walking") {
    leg_score <- 3
  } else if (walking_status == "difficulty_running") {
    leg_score <- 2
  } else if (walking_status == "symptoms_only") {
    leg_score <- 1
  } else {
    if (leg_symptoms == 1) {
      leg_score <- 1
    } else {
      leg_score <- 0
    }
  }

  total_score <- arm_score + leg_score

  return(list(
    ONLS_Total_Score = total_score,
    Arm_Scale_Score = arm_score,
    Leg_Scale_Score = leg_score,
    Interpretation = "Higher scores indicate greater disability (Max 12).",
    Inputs = list(
      Arm_Symptoms = arm_symptoms == 1,
      Arm_Tasks = list(Hair=wash_hair, Key=turn_key, Knife=use_knife, Buttons=fasten_buttons),
      Leg_Status = walking_status
    )
  ))
}

oxygenation_index <- function(mean_airway_pressure, fio2_percent, pao2) {

  mean_airway_pressure <- as.numeric(mean_airway_pressure)
  fio2_percent <- as.numeric(fio2_percent)
  pao2 <- as.numeric(pao2)

  if (any(is.na(c(mean_airway_pressure, fio2_percent, pao2)))) {
    stop("Error: All inputs must be numeric.")
  }

  if (pao2 <= 0) {
    stop("Error: PaO2 must be positive.")
  }

  if (fio2_percent <= 1) {
    warning("FiO2 appears to be a fraction (0-1). Converting to percent (0-100).")
    fio2_percent <- fio2_percent * 100
  }

  oi <- (fio2_percent * mean_airway_pressure) / pao2

  interpretation <- ""
  if (oi <= 25) {
    interpretation <- "Good Outcome Likely (if maintained). Continue conventional management."
  } else if (oi > 25 && oi < 40) {
    interpretation <- "High Risk of Mortality (>50%). Consider High Frequency Oscillatory Ventilation (HFOV) or Inhaled Nitric Oxide (iNO)."
  } else {
    interpretation <- "Very High Risk of Mortality (>80%). Consider Extracorporeal Membrane Oxygenation (ECMO)."
  }

  return(list(
    Oxygenation_Index = round(oi, 2),
    Interpretation = interpretation,
    Inputs = list(
      MAP = mean_airway_pressure,
      FiO2_Percent = fio2_percent,
      PaO2 = pao2
    )
  ))
}

neck_disability_index <- function(pain_intensity, personal_care, lifting, reading, headaches, concentration, work, driving, sleeping, recreation) {

  inputs <- c(pain_intensity, personal_care, lifting, reading, headaches, concentration, work, driving, sleeping, recreation)

  if (any(is.na(inputs))) {
    stop("Error: All 10 inputs must be numeric.")
  }

  if (any(inputs < 0) || any(inputs > 5)) {
    stop("Error: All item scores must be integers between 0 and 5.")
  }

  total_score <- sum(inputs)
  percentage <- total_score * 2

  disability_level <- ""

  if (total_score <= 4) {
    disability_level <- "No Disability"
  } else if (total_score <= 14) {
    disability_level <- "Mild Disability"
  } else if (total_score <= 24) {
    disability_level <- "Moderate Disability"
  } else if (total_score <= 34) {
    disability_level <- "Severe Disability"
  } else {
    disability_level <- "Complete Disability"
  }

  return(list(
    NDI_Score_Raw = total_score,
    NDI_Percentage = paste0(percentage, "%"),
    Interpretation = disability_level,
    Inputs = list(
      Q1_Pain = pain_intensity,
      Q2_Personal_Care = personal_care,
      Q3_Lifting = lifting,
      Q4_Reading = reading,
      Q5_Headaches = headaches,
      Q6_Concentration = concentration,
      Q7_Work = work,
      Q8_Driving = driving,
      Q9_Sleeping = sleeping,
      Q10_Recreation = recreation
    )
  ))
}

nedocs_score <- function(total_patients_ed, total_ed_beds, admits_in_ed, total_hospital_beds, ventilated_patients_ed, longest_admit_time_hrs, wait_time_last_patient_hrs) {

  total_patients_ed <- as.numeric(total_patients_ed)
  total_ed_beds <- as.numeric(total_ed_beds)
  admits_in_ed <- as.numeric(admits_in_ed)
  total_hospital_beds <- as.numeric(total_hospital_beds)
  ventilated_patients_ed <- as.numeric(ventilated_patients_ed)
  longest_admit_time_hrs <- as.numeric(longest_admit_time_hrs)
  wait_time_last_patient_hrs <- as.numeric(wait_time_last_patient_hrs)

  if (any(is.na(c(total_patients_ed, total_ed_beds, admits_in_ed, total_hospital_beds, ventilated_patients_ed, longest_admit_time_hrs, wait_time_last_patient_hrs)))) {
    stop("Error: All inputs must be numeric.")
  }

  if (total_ed_beds == 0 || total_hospital_beds == 0) {
    stop("Error: Bed counts cannot be zero.")
  }

  ratio_ed_beds <- total_patients_ed / total_ed_beds
  ratio_hospital_beds <- admits_in_ed / total_hospital_beds

  score <- -20 + (85.8 * ratio_ed_beds) + (600 * ratio_hospital_beds) + (13.4 * ventilated_patients_ed) + (0.93 * longest_admit_time_hrs) + (5.64 * wait_time_last_patient_hrs)

  if (score > 200) score <- 200
  if (score < 0) score <- 0

  status <- ""
  if (score <= 20) {
    status <- "Not Busy"
  } else if (score <= 60) {
    status <- "Busy"
  } else if (score <= 100) {
    status <- "Overcrowded"
  } else if (score <= 140) {
    status <- "Severely Overcrowded"
  } else if (score <= 180) {
    status <- "Dangerous Overcrowding"
  } else {
    status <- "Disaster"
  }

  return(list(
    NEDOCS_Score = round(score, 0),
    Status = status,
    Inputs = list(
      Total_Patients = total_patients_ed,
      Total_ED_Beds = total_ed_beds,
      Admits_Waiting = admits_in_ed,
      Total_Hospital_Beds = total_hospital_beds,
      Vents = ventilated_patients_ed,
      Longest_Admit_Wait = longest_admit_time_hrs,
      Last_Patient_Wait = wait_time_last_patient_hrs
    )
  ))
}

neonatal_eos_calculator <- function(gestational_age_weeks, highest_maternal_temp_c, rom_hours, gbs_status, intrapartum_antibiotics, neonatal_appearance, baseline_incidence_per_1000 = 0.5) {

  gestational_age_weeks <- as.numeric(gestational_age_weeks)
  highest_maternal_temp_c <- as.numeric(highest_maternal_temp_c)
  rom_hours <- as.numeric(rom_hours)
  baseline_incidence_per_1000 <- as.numeric(baseline_incidence_per_1000)

  gbs_status <- tolower(as.character(gbs_status))
  intrapartum_antibiotics <- tolower(as.character(intrapartum_antibiotics))
  neonatal_appearance <- tolower(as.character(neonatal_appearance))

  if (any(is.na(c(gestational_age_weeks, highest_maternal_temp_c, rom_hours, baseline_incidence_per_1000)))) {
    stop("Error: Numeric inputs are required for age, temperature, ROM duration, and incidence.")
  }

  if (gestational_age_weeks < 34) {
    return(list(Error = "This calculator is validated for infants >= 34 weeks gestational age."))
  }

  valid_gbs <- c("positive", "negative", "unknown")
  if (!gbs_status %in% valid_gbs) stop("Error: GBS status must be 'positive', 'negative', or 'unknown'.")

  valid_abx <- c("none", "specific_lt_2", "specific_2_to_3_9", "specific_ge_4", "broad_lt_2", "broad_2_to_3_9", "broad_ge_4")
  if (!intrapartum_antibiotics %in% valid_abx) stop("Error: Invalid antibiotic category.")

  valid_appearance <- c("well_appearing", "equivocal", "clinical_illness")
  if (!neonatal_appearance %in% valid_appearance) stop("Error: Neonatal appearance must be 'well_appearing', 'equivocal', or 'clinical_illness'.")

  intercept <- -5.962

  coeff_ga <- -0.191 * (gestational_age_weeks - 40)

  temp_baseline <- 37.8
  coeff_temp <- 0
  if (highest_maternal_temp_c > 37.5) {
    coeff_temp <- 0.598 * (highest_maternal_temp_c - temp_baseline)
  }

  coeff_rom <- 0.026 * rom_hours

  coeff_gbs_abx <- 0
  if (gbs_status == "negative" || gbs_status == "unknown") {
    coeff_gbs_abx <- 0
  } else {
    if (intrapartum_antibiotics == "none" || intrapartum_antibiotics == "specific_lt_2" || intrapartum_antibiotics == "broad_lt_2") {
      coeff_gbs_abx <- 0.68
    } else if (intrapartum_antibiotics == "specific_2_to_3_9" || intrapartum_antibiotics == "broad_2_to_3_9") {
      coeff_gbs_abx <- 0.40
    } else {
      coeff_gbs_abx <- -1.18
    }
  }

  logit_prior <- intercept + coeff_ga + coeff_temp + coeff_rom + coeff_gbs_abx

  ref_incidence <- 0.6 / 1000
  user_incidence <- baseline_incidence_per_1000 / 1000
  offset <- log(user_incidence / (1 - user_incidence)) - log(ref_incidence / (1 - ref_incidence))

  logit_prior_adjusted <- logit_prior + offset
  prob_prior <- 1 / (1 + exp(-logit_prior_adjusted))

  odds_prior <- prob_prior / (1 - prob_prior)

  lr_clinical <- 1.0
  if (neonatal_appearance == "well_appearing") {
    lr_clinical <- 0.41
  } else if (neonatal_appearance == "equivocal") {
    lr_clinical <- 6.2
  } else {
    lr_clinical <- 54.0
  }

  odds_posterior <- odds_prior * lr_clinical
  prob_posterior <- odds_posterior / (1 + odds_posterior)
  risk_per_1000 <- prob_posterior * 1000

  recommendation <- ""
  if (neonatal_appearance == "clinical_illness") {
    recommendation <- "NICU Admission, Blood Culture, Empiric Antibiotics."
  } else if (neonatal_appearance == "equivocal") {
    if (risk_per_1000 >= 1) {
      recommendation <- "Blood Culture, Empiric Antibiotics, Monitor Vitals."
    } else {
      recommendation <- "Blood Culture, Monitor Vitals (Antibiotics may not be needed)."
    }
  } else {
    if (risk_per_1000 < 1) {
      recommendation <- "Routine Newborn Care."
    } else if (risk_per_1000 < 3) {
      recommendation <- "Blood Culture (optional), Monitor Vitals q4h for 24h."
    } else {
      recommendation <- "Blood Culture, Monitor Vitals, Consider Empiric Antibiotics."
    }
  }

  return(list(
    EOS_Risk_Per_1000 = round(risk_per_1000, 2),
    Clinical_Presentation = neonatal_appearance,
    Recommendation = recommendation,
    Inputs = list(
      GA = gestational_age_weeks,
      Max_Temp = highest_maternal_temp_c,
      ROM = rom_hours,
      GBS_Abx_Status = paste(gbs_status, "/", intrapartum_antibiotics),
      Baseline_Incidence = baseline_incidence_per_1000
    )
  ))
}

neonatal_partial_exchange <- function(weight_kg, current_hct, desired_hct = 55, blood_volume_ml_kg = 80) {

  weight_kg <- as.numeric(weight_kg)
  current_hct <- as.numeric(current_hct)
  desired_hct <- as.numeric(desired_hct)
  blood_volume_ml_kg <- as.numeric(blood_volume_ml_kg)

  if (any(is.na(c(weight_kg, current_hct, desired_hct, blood_volume_ml_kg)))) {
    stop("Error: All inputs must be numeric.")
  }

  if (current_hct <= desired_hct) {
    return(list(
      Volume_to_Exchange_mL = 0,
      Message = "Current hematocrit is already at or below the desired target."
    ))
  }

  total_blood_volume <- weight_kg * blood_volume_ml_kg

  exchange_volume <- (total_blood_volume * (current_hct - desired_hct)) / current_hct

  return(list(
    Volume_to_Exchange_mL = round(exchange_volume, 1),
    Total_Blood_Volume_mL = round(total_blood_volume, 1),
    Inputs = list(
      Weight_kg = weight_kg,
      Current_Hct = current_hct,
      Desired_Hct = desired_hct,
      Blood_Volume_Est = blood_volume_ml_kg
    )
  ))
}

nps_pain_scale <- function(intensity, sharp, hot, dull, cold, sensitive, itchy, unpleasant, deep, surface) {

  inputs <- c(intensity, sharp, hot, dull, cold, sensitive, itchy, unpleasant, deep, surface)

  if (any(is.na(inputs))) {
    stop("Error: All 10 inputs must be numeric.")
  }

  if (any(inputs < 0) || any(inputs > 10)) {
    stop("Error: All item scores must be integers between 0 and 10.")
  }

  total_score <- sum(inputs)

  return(list(
    NPS_Total_Score = total_score,
    Interpretation = "The NPS is an evaluative tool. Higher scores indicate greater severity of specific neuropathic pain qualities. It is primarily used to monitor response to treatment across different pain domains.",
    Domain_Scores = list(
      Intensity_Global = intensity,
      Sharpness = sharp,
      Heat = hot,
      Dullness = dull,
      Cold = cold,
      Sensitivity = sensitive,
      Itchy = itchy,
      Unpleasantness = unpleasant,
      Deep_Pain = deep,
      Surface_Pain = surface
    )
  ))
}

neutrophil_lymphocyte_ratio <- function(neutrophil_count, lymphocyte_count) {

  neutrophil_count <- as.numeric(neutrophil_count)
  lymphocyte_count <- as.numeric(lymphocyte_count)

  if (any(is.na(c(neutrophil_count, lymphocyte_count)))) {
    stop("Error: All inputs must be numeric.")
  }

  if (lymphocyte_count <= 0) {
    stop("Error: Lymphocyte count must be greater than 0 to calculate ratio.")
  }

  nlr <- neutrophil_count / lymphocyte_count

  interpretation <- "The Neutrophil-to-Lymphocyte Ratio (NLR) is an inflammatory marker. Normal physiological stress typically yields values between 1 and 3. Values > 3.0-4.0 often indicate systemic inflammation, infection (e.g., sepsis, COVID-19), or poor prognosis in various malignancies. Values > 10 are associated with severe stress or critical illness."

  return(list(
    NLR = round(nlr, 2),
    Interpretation = interpretation,
    Inputs = list(
      Neutrophils = neutrophil_count,
      Lymphocytes = lymphocyte_count
    )
  ))
}

qsofa_sepsis_score <- function(respiratory_rate, systolic_bp, gcs_score) {

  respiratory_rate <- as.numeric(respiratory_rate)
  systolic_bp <- as.numeric(systolic_bp)
  gcs_score <- as.numeric(gcs_score)

  if (any(is.na(c(respiratory_rate, systolic_bp, gcs_score)))) {
    stop("Error: All inputs must be numeric.")
  }

  if (gcs_score < 3 || gcs_score > 15) {
    stop("Error: GCS score must be between 3 and 15.")
  }

  score <- 0

  if (respiratory_rate >= 22) {
    score <- score + 1
  }

  if (systolic_bp <= 100) {
    score <- score + 1
  }

  if (gcs_score < 15) {
    score <- score + 1
  }

  risk_category <- ""
  mortality_risk <- ""

  if (score >= 2) {
    risk_category <- "High Risk"
    mortality_risk <- "Increased risk of in-hospital mortality (3- to 14-fold increase). Assess for evidence of organ dysfunction (SOFA)."
  } else {
    risk_category <- "Low Risk"
    mortality_risk <- "Not high risk for in-hospital mortality based on qSOFA alone. Continue to monitor."
  }

  return(list(
    qSOFA_Score = score,
    Risk_Category = risk_category,
    Interpretation = mortality_risk,
    Inputs = list(
      RR_ge_22 = respiratory_rate >= 22,
      SBP_le_100 = systolic_bp <= 100,
      GCS_lt_15 = gcs_score < 15
    )
  ))
}

qcsi_score <- function(respiratory_rate, oxygen_saturation, o2_flow_rate) {

  respiratory_rate <- as.numeric(respiratory_rate)
  oxygen_saturation <- as.numeric(oxygen_saturation)
  o2_flow_rate <- as.numeric(o2_flow_rate)

  if (any(is.na(c(respiratory_rate, oxygen_saturation, o2_flow_rate)))) {
    stop("Error: All inputs must be numeric.")
  }

  score <- 0

  if (respiratory_rate <= 22) {
    score <- score + 0
  } else if (respiratory_rate <= 28) {
    score <- score + 1
  } else {
    score <- score + 2
  }

  if (oxygen_saturation > 92) {
    score <- score + 0
  } else if (oxygen_saturation >= 89) {
    score <- score + 2
  } else {
    score <- score + 5
  }

  if (o2_flow_rate <= 0) {
    score <- score + 0
  } else if (o2_flow_rate <= 2) {
    score <- score + 4
  } else if (o2_flow_rate <= 4) {
    score <- score + 5
  } else {
    score <- score + 6
  }

  risk_level <- ""
  critical_illness_risk <- ""

  if (score <= 3) {
    risk_level <- "Low Risk"
    critical_illness_risk <- "4%"
  } else if (score <= 6) {
    risk_level <- "Low-Intermediate Risk"
    critical_illness_risk <- "30%"
  } else if (score <= 9) {
    risk_level <- "High-Intermediate Risk"
    critical_illness_risk <- "44%"
  } else {
    risk_level <- "High Risk"
    critical_illness_risk <- "57%"
  }

  return(list(
    qCSI_Score = score,
    Risk_Category = risk_level,
    Est_24hr_Critical_Illness_Risk = critical_illness_risk,
    Inputs = list(
      RR = respiratory_rate,
      SpO2 = oxygen_saturation,
      O2_Flow_L_min = o2_flow_rate
    )
  ))
}

qids_depression_score <- function(sleep_onset, sleep_mid_nocturnal, sleep_early_waking, sleep_hypersomnia, mood_sadness, appetite_decreased, appetite_increased, weight_decreased, weight_increased, concentration, view_of_self, thoughts_death_suicide, general_interest, energy_level, psychomotor_slowing, psychomotor_agitation) {

  inputs <- c(sleep_onset, sleep_mid_nocturnal, sleep_early_waking, sleep_hypersomnia, mood_sadness, appetite_decreased, appetite_increased, weight_decreased, weight_increased, concentration, view_of_self, thoughts_death_suicide, general_interest, energy_level, psychomotor_slowing, psychomotor_agitation)

  if (any(is.na(inputs))) {
    stop("Error: All 16 inputs must be numeric.")
  }

  if (any(inputs < 0) || any(inputs > 3)) {
    stop("Error: All item scores must be integers between 0 and 3.")
  }

  domain_sleep <- max(sleep_onset, sleep_mid_nocturnal, sleep_early_waking, sleep_hypersomnia)

  domain_mood <- mood_sadness

  domain_appetite_weight <- max(appetite_decreased, appetite_increased, weight_decreased, weight_increased)

  domain_concentration <- concentration

  domain_self_view <- view_of_self

  domain_suicide <- thoughts_death_suicide

  domain_interest <- general_interest

  domain_energy <- energy_level

  domain_psychomotor <- max(psychomotor_slowing, psychomotor_agitation)

  total_score <- domain_sleep + domain_mood + domain_appetite_weight + domain_concentration + domain_self_view + domain_suicide + domain_interest + domain_energy + domain_psychomotor

  severity <- ""

  if (total_score <= 5) {
    severity <- "No Depression"
  } else if (total_score <= 10) {
    severity <- "Mild Depression"
  } else if (total_score <= 15) {
    severity <- "Moderate Depression"
  } else if (total_score <= 20) {
    severity <- "Severe Depression"
  } else {
    severity <- "Very Severe Depression"
  }

  return(list(
    QIDS_Total_Score = total_score,
    Severity_Category = severity,
    Domain_Scores = list(
      Sleep = domain_sleep,
      Mood = domain_mood,
      Appetite_Weight = domain_appetite_weight,
      Concentration = domain_concentration,
      Self_View = domain_self_view,
      Suicide = domain_suicide,
      Interest = domain_interest,
      Energy = domain_energy,
      Psychomotor = domain_psychomotor
    )
  ))
}

radiation_bed_calculator <- function(dose_per_fraction_gy, number_of_fractions, alpha_beta_ratio) {

  dose_per_fraction_gy <- as.numeric(dose_per_fraction_gy)
  number_of_fractions <- as.numeric(number_of_fractions)
  alpha_beta_ratio <- as.numeric(alpha_beta_ratio)

  if (any(is.na(c(dose_per_fraction_gy, number_of_fractions, alpha_beta_ratio)))) {
    stop("Error: All inputs must be numeric.")
  }

  if (dose_per_fraction_gy <= 0 || number_of_fractions <= 0 || alpha_beta_ratio <= 0) {
    stop("Error: Inputs must be positive numbers.")
  }

  total_dose_gy <- dose_per_fraction_gy * number_of_fractions

  bed <- total_dose_gy * (1 + (dose_per_fraction_gy / alpha_beta_ratio))

  eqd2 <- bed / (1 + (2 / alpha_beta_ratio))

  return(list(
    BED_Gy = round(bed, 2),
    EQD2_Gy = round(eqd2, 2),
    Total_Physical_Dose_Gy = total_dose_gy,
    Inputs = list(
      Dose_Per_Fraction = dose_per_fraction_gy,
      Fractions = number_of_fractions,
      Alpha_Beta_Ratio = alpha_beta_ratio
    )
  ))
}

rads_smoke_inhalation_score <- function(quadrant1_finding, quadrant2_finding, quadrant3_finding, quadrant4_finding) {

  quadrant1_finding <- tolower(as.character(quadrant1_finding))
  quadrant2_finding <- tolower(as.character(quadrant2_finding))
  quadrant3_finding <- tolower(as.character(quadrant3_finding))
  quadrant4_finding <- tolower(as.character(quadrant4_finding))

  valid_findings <- c("normal", "interstitial", "ground_glass", "consolidation")

  if (!all(c(quadrant1_finding, quadrant2_finding, quadrant3_finding, quadrant4_finding) %in% valid_findings)) {
    stop("Error: Findings must be 'normal', 'interstitial', 'ground_glass', or 'consolidation'.")
  }

  get_points <- function(finding) {
    if (finding == "normal") return(0)
    if (finding == "interstitial") return(1)
    if (finding == "ground_glass") return(2)
    if (finding == "consolidation") return(3)
    return(0)
  }

  q1_points <- get_points(quadrant1_finding)
  q2_points <- get_points(quadrant2_finding)
  q3_points <- get_points(quadrant3_finding)
  q4_points <- get_points(quadrant4_finding)

  total_score <- q1_points + q2_points + q3_points + q4_points

  risk_category <- ""
  if (total_score <= 8) {
    risk_category <- "Lower Risk (Score <= 8)"
  } else {
    risk_category <- "High Risk (Score > 8)"
  }

  return(list(
    RADS_Score = total_score,
    Risk_Category = risk_category,
    Inputs = list(
      Quadrant_1 = q1_points,
      Quadrant_2 = q2_points,
      Quadrant_3 = q3_points,
      Quadrant_4 = q4_points
    )
  ))
}

rai_cll_staging <- function(lymphocytosis, lymphadenopathy, organomegaly, hemoglobin_lt_11, platelets_lt_100) {

  lymphocytosis <- as.numeric(lymphocytosis)
  lymphadenopathy <- as.numeric(lymphadenopathy)
  organomegaly <- as.numeric(organomegaly)
  hemoglobin_lt_11 <- as.numeric(hemoglobin_lt_11)
  platelets_lt_100 <- as.numeric(platelets_lt_100)

  if (any(is.na(c(lymphocytosis, lymphadenopathy, organomegaly, hemoglobin_lt_11, platelets_lt_100)))) {
    stop("Error: All inputs must be numeric (0 or 1).")
  }

  stage <- "Not Staged"
  risk_group <- "N/A"
  survival <- "N/A"

  if (lymphocytosis == 1) {
    if (platelets_lt_100 == 1) {
      stage <- "Stage IV"
      risk_group <- "High Risk"
      survival <- "1.5 - 4 years (Historical)"
    } else if (hemoglobin_lt_11 == 1) {
      stage <- "Stage III"
      risk_group <- "High Risk"
      survival <- "1.5 - 4 years (Historical)"
    } else if (organomegaly == 1) {
      stage <- "Stage II"
      risk_group <- "Intermediate Risk"
      survival <- "6 - 8 years (Historical)"
    } else if (lymphadenopathy == 1) {
      stage <- "Stage I"
      risk_group <- "Intermediate Risk"
      survival <- "8 - 9 years (Historical)"
    } else {
      stage <- "Stage 0"
      risk_group <- "Low Risk"
      survival <- "> 10 years (Historical)"
    }
  } else {
    stage <- "Not CLL (Lymphocytosis is required for diagnosis)"
  }

  return(list(
    Rai_Stage = stage,
    Risk_Category = risk_group,
    Median_Survival = survival,
    Inputs = list(
      Lymphocytosis_Present = lymphocytosis == 1,
      Lymphadenopathy = lymphadenopathy == 1,
      Hepatomegaly_Splenomegaly = organomegaly == 1,
      Anemia_Hb_lt_11 = hemoglobin_lt_11 == 1,
      Thrombocytopenia_Plt_lt_100 = platelets_lt_100 == 1
    )
  ))
}

ransons_criteria <- function(age, wbc_count, glucose_mg_dl, ldh, ast, hct_fall_percent, bun_increase_mg_dl, calcium_mg_dl, pao2_mmhg, base_deficit_meq_l, fluid_sequestration_liters, etiology = "non_biliary") {

  age <- as.numeric(age)
  wbc_count <- as.numeric(wbc_count)
  glucose_mg_dl <- as.numeric(glucose_mg_dl)
  ldh <- as.numeric(ldh)
  ast <- as.numeric(ast)
  hct_fall_percent <- as.numeric(hct_fall_percent)
  bun_increase_mg_dl <- as.numeric(bun_increase_mg_dl)
  calcium_mg_dl <- as.numeric(calcium_mg_dl)
  pao2_mmhg <- as.numeric(pao2_mmhg)
  base_deficit_meq_l <- as.numeric(base_deficit_meq_l)
  fluid_sequestration_liters <- as.numeric(fluid_sequestration_liters)
  etiology <- tolower(as.character(etiology))

  if (any(is.na(c(age, wbc_count, glucose_mg_dl, ldh, ast, hct_fall_percent, bun_increase_mg_dl, calcium_mg_dl, base_deficit_meq_l, fluid_sequestration_liters)))) {
    stop("Error: All inputs must be numeric.")
  }

  if (!etiology %in% c("non_biliary", "biliary")) {
    stop("Error: Etiology must be 'non_biliary' (Alcohol/Other) or 'biliary' (Gallstone).")
  }

  score <- 0

  if (etiology == "non_biliary") {

    if (age > 55) score <- score + 1
    if (wbc_count > 16000) score <- score + 1
    if (glucose_mg_dl > 200) score <- score + 1
    if (ldh > 350) score <- score + 1
    if (ast > 250) score <- score + 1

    if (hct_fall_percent > 10) score <- score + 1
    if (bun_increase_mg_dl > 5) score <- score + 1
    if (calcium_mg_dl < 8) score <- score + 1
    if (pao2_mmhg < 60) score <- score + 1
    if (base_deficit_meq_l > 4) score <- score + 1
    if (fluid_sequestration_liters > 6) score <- score + 1

  } else {

    if (age > 70) score <- score + 1
    if (wbc_count > 18000) score <- score + 1
    if (glucose_mg_dl > 220) score <- score + 1
    if (ldh > 400) score <- score + 1
    if (ast > 250) score <- score + 1

    if (hct_fall_percent > 10) score <- score + 1
    if (bun_increase_mg_dl > 2) score <- score + 1
    if (calcium_mg_dl < 8) score <- score + 1
    if (base_deficit_meq_l > 5) score <- score + 1
    if (fluid_sequestration_liters > 4) score <- score + 1

  }

  mortality <- ""
  if (score <= 2) {
    mortality <- "0 - 3%"
  } else if (score >= 3 && score <= 4) {
    mortality <- "15%"
  } else if (score >= 5 && score <= 6) {
    mortality <- "40%"
  } else {
    mortality <- "100%"
  }

  return(list(
    Ranson_Score = score,
    Mortality_Risk = mortality,
    Etiology = etiology,
    Inputs = list(
      Age = age,
      WBC = wbc_count,
      Glucose = glucose_mg_dl,
      LDH = ldh,
      AST = ast,
      Hct_Fall = hct_fall_percent,
      BUN_Rise = bun_increase_mg_dl,
      Calcium = calcium_mg_dl,
      PaO2 = pao2_mmhg,
      Base_Deficit = base_deficit_meq_l,
      Fluid_Sequestration_L = fluid_sequestration_liters
    )
  ))
}

race_stroke_scale <- function(facial_palsy, arm_motor, leg_motor, head_gaze_deviation, aphasia_or_agnosia) {

  facial_palsy <- as.numeric(facial_palsy)
  arm_motor <- as.numeric(arm_motor)
  leg_motor <- as.numeric(leg_motor)
  head_gaze_deviation <- as.numeric(head_gaze_deviation)
  aphasia_or_agnosia <- as.numeric(aphasia_or_agnosia)

  if (any(is.na(c(facial_palsy, arm_motor, leg_motor, head_gaze_deviation, aphasia_or_agnosia)))) {
    stop("Error: All inputs must be numeric.")
  }

  if (facial_palsy < 0 || facial_palsy > 2) stop("Error: Facial Palsy score must be 0, 1, or 2.")
  if (arm_motor < 0 || arm_motor > 2) stop("Error: Arm Motor score must be 0, 1, or 2.")
  if (leg_motor < 0 || leg_motor > 2) stop("Error: Leg Motor score must be 0, 1, or 2.")
  if (head_gaze_deviation < 0 || head_gaze_deviation > 1) stop("Error: Head/Gaze Deviation score must be 0 or 1.")
  if (aphasia_or_agnosia < 0 || aphasia_or_agnosia > 2) stop("Error: Cortical sign score must be 0, 1, or 2.")

  score <- facial_palsy + arm_motor + leg_motor + head_gaze_deviation + aphasia_or_agnosia

  lvo_likelihood <- ""
  sensitivity <- ""
  specificity <- ""

  if (score >= 5) {
    lvo_likelihood <- "High Probability of Large Vessel Occlusion (LVO)"
    sensitivity <- "0.85"
    specificity <- "0.68"
  } else {
    lvo_likelihood <- "Lower Probability of LVO"
    sensitivity <- "N/A"
    specificity <- "N/A"
  }

  return(list(
    RACE_Score = score,
    Interpretation = lvo_likelihood,
    Performance_at_Cutoff_5 = list(
      Sensitivity = sensitivity,
      Specificity = specificity
    ),
    Inputs = list(
      Face = facial_palsy,
      Arm = arm_motor,
      Leg = leg_motor,
      Gaze = head_gaze_deviation,
      Cortical = aphasia_or_agnosia
    )
  ))
}

rems_score <- function(age_years, heart_rate, respiratory_rate, systolic_bp, gcs_score, oxygen_saturation) {

  age_years <- as.numeric(age_years)
  heart_rate <- as.numeric(heart_rate)
  respiratory_rate <- as.numeric(respiratory_rate)
  systolic_bp <- as.numeric(systolic_bp)
  gcs_score <- as.numeric(gcs_score)
  oxygen_saturation <- as.numeric(oxygen_saturation)

  if (any(is.na(c(age_years, heart_rate, respiratory_rate, systolic_bp, gcs_score, oxygen_saturation)))) {
    stop("Error: All inputs must be numeric.")
  }

  if (gcs_score < 3 || gcs_score > 15) {
    stop("Error: GCS score must be between 3 and 15.")
  }

  score <- 0

  if (age_years < 45) {
    score <- score + 0
  } else if (age_years >= 45 && age_years <= 54) {
    score <- score + 2
  } else if (age_years >= 55 && age_years <= 64) {
    score <- score + 3
  } else if (age_years >= 65 && age_years <= 74) {
    score <- score + 5
  } else {
    score <- score + 6
  }

  if (heart_rate >= 70 && heart_rate <= 109) {
    score <- score + 0
  } else if ((heart_rate >= 55 && heart_rate <= 69) || (heart_rate >= 110 && heart_rate <= 139)) {
    score <- score + 2
  } else if ((heart_rate >= 40 && heart_rate <= 54) || (heart_rate >= 140 && heart_rate <= 179)) {
    score <- score + 3
  } else {
    score <- score + 4
  }

  if (respiratory_rate >= 12 && respiratory_rate <= 24) {
    score <- score + 0
  } else if ((respiratory_rate >= 10 && respiratory_rate <= 11) || (respiratory_rate >= 25 && respiratory_rate <= 34)) {
    score <- score + 2
  } else if ((respiratory_rate >= 6 && respiratory_rate <= 9) || (respiratory_rate >= 35 && respiratory_rate <= 49)) {
    score <- score + 3
  } else {
    score <- score + 4
  }

  if (systolic_bp >= 90 && systolic_bp <= 129) {
    score <- score + 0
  } else if ((systolic_bp >= 70 && systolic_bp <= 89) || (systolic_bp >= 130 && systolic_bp <= 149)) {
    score <- score + 2
  } else if ((systolic_bp >= 40 && systolic_bp <= 69) || (systolic_bp >= 150 && systolic_bp <= 179)) {
    score <- score + 3
  } else {
    score <- score + 4
  }

  if (gcs_score > 13) {
    score <- score + 0
  } else if (gcs_score >= 11 && gcs_score <= 13) {
    score <- score + 2
  } else if (gcs_score >= 8 && gcs_score <= 10) {
    score <- score + 3
  } else {
    score <- score + 4
  }

  if (oxygen_saturation > 89) {
    score <- score + 0
  } else if (oxygen_saturation >= 86 && oxygen_saturation <= 89) {
    score <- score + 1
  } else if (oxygen_saturation >= 75 && oxygen_saturation <= 85) {
    score <- score + 3
  } else {
    score <- score + 4
  }

  mortality_risk <- ""
  if (score <= 5) {
    mortality_risk <- "Low Risk (<10%)"
  } else if (score <= 11) {
    mortality_risk <- "Intermediate Risk"
  } else {
    mortality_risk <- "High Risk (>20-30%)"
  }

  return(list(
    REMS_Score = score,
    Mortality_Risk = mortality_risk,
    Inputs = list(
      Age = age_years,
      HR = heart_rate,
      RR = respiratory_rate,
      SBP = systolic_bp,
      GCS = gcs_score,
      SpO2 = oxygen_saturation
    )
  ))
}

rapid_acetabular_score <- function(sex, tonnis_grade, cam_morphology) {

  sex <- tolower(as.character(sex))
  tonnis_grade <- as.numeric(tonnis_grade)
  cam_morphology <- as.numeric(cam_morphology)

  if (!sex %in% c("male", "female")) {
    stop("Error: Sex must be 'male' or 'female'.")
  }

  if (!tonnis_grade %in% c(0, 1, 2)) {
    stop("Error: Tonnis grade must be 0, 1, or 2. Grade 3 is a contraindication for hip arthroscopy.")
  }

  if (!cam_morphology %in% c(0, 1)) {
    stop("Error: Cam morphology must be numeric 0 (Absent) or 1 (Present).")
  }

  score <- 0

  if (sex == "male") {
    score <- score + 1
  }

  if (tonnis_grade == 1) {
    score <- score + 2
  } else if (tonnis_grade == 2) {
    score <- score + 3
  }

  if (cam_morphology == 1) {
    score <- score + 1
  }

  risk_text <- ""
  if (score == 0) {
    risk_text <- "Low Risk (~10.5% probability of ALAD Grade 3-4)"
  } else if (score >= 4) {
    risk_text <- "High Risk (Up to ~88% probability of ALAD Grade 3-4). Prepare for cartilage repair/restoration."
  } else {
    risk_text <- "Intermediate Risk (Probability increases with score)"
  }

  return(list(
    RAPID_Score = score,
    Risk_Prediction = risk_text,
    Inputs = list(
      Sex = sex,
      Tonnis_Grade = tonnis_grade,
      Cam_Morphology = if (cam_morphology == 1) "Present (>55 deg)" else "Absent"
    )
  ))
}

rapid_pleural_infection_score <- function(bun, age, purulent_fluid, hospital_acquired, albumin, bun_units = "mg/dL", albumin_units = "g/dL") {

  bun <- as.numeric(bun)
  age <- as.numeric(age)
  purulent_fluid <- as.numeric(purulent_fluid)
  hospital_acquired <- as.numeric(hospital_acquired)
  albumin <- as.numeric(albumin)

  if (any(is.na(c(bun, age, purulent_fluid, hospital_acquired, albumin)))) {
    stop("Error: All inputs must be numeric.")
  }

  bun_mg_dl <- bun
  if (bun_units == "mmol/L") {
    bun_mg_dl <- bun * 2.8
  }

  alb_g_dl <- albumin
  if (albumin_units == "g/L") {
    alb_g_dl <- albumin / 10
  }

  score <- 0

  if (bun_mg_dl < 14) {
    score <- score + 0
  } else if (bun_mg_dl >= 14 && bun_mg_dl <= 23) {
    score <- score + 1
  } else {
    score <- score + 2
  }

  if (age < 50) {
    score <- score + 0
  } else if (age >= 50 && age <= 70) {
    score <- score + 1
  } else {
    score <- score + 2
  }

  if (purulent_fluid == 0) {
    score <- score + 1
  }

  if (hospital_acquired == 1) {
    score <- score + 1
  }

  if (alb_g_dl < 2.7) {
    score <- score + 1
  }

  risk_category <- ""
  mortality_3mo <- ""

  if (score <= 2) {
    risk_category <- "Low Risk"
    mortality_3mo <- "1.5%"
  } else if (score <= 4) {
    risk_category <- "Medium Risk"
    mortality_3mo <- "18-30%"
  } else {
    risk_category <- "High Risk"
    mortality_3mo <- "40-50%"
  }

  return(list(
    RAPID_Score = score,
    Risk_Category = risk_category,
    Est_3_Month_Mortality = mortality_3mo,
    Inputs = list(
      BUN_mg_dL = round(bun_mg_dl, 1),
      Age = age,
      Purulence = purulent_fluid == 1,
      Hospital_Acquired = hospital_acquired == 1,
      Albumin_g_dL = round(alb_g_dl, 1)
    )
  ))
}

rsbi_score <- function(respiratory_rate, tidal_volume, volume_units = "L") {

  respiratory_rate <- as.numeric(respiratory_rate)
  tidal_volume <- as.numeric(tidal_volume)
  volume_units <- tolower(as.character(volume_units))

  if (any(is.na(c(respiratory_rate, tidal_volume)))) {
    stop("Error: All inputs must be numeric.")
  }

  if (tidal_volume <= 0) {
    stop("Error: Tidal volume must be positive.")
  }

  vt_liters <- tidal_volume
  if (volume_units == "ml") {
    vt_liters <- tidal_volume / 1000
  }

  rsbi <- respiratory_rate / vt_liters

  interpretation <- ""
  if (rsbi < 105) {
    interpretation <- "Predictive of successful extubation (Probability ~80%)."
  } else {
    interpretation <- "Predictive of extubation failure (Probability ~95%)."
  }

  return(list(
    RSBI_Score = round(rsbi, 1),
    Interpretation = interpretation,
    Inputs = list(
      RR = respiratory_rate,
      Vt_L = vt_liters
    )
  ))
}

rbc_compatibility_screen <- function(units_needed, antigens_selected) {

  units_needed <- as.numeric(units_needed)
  antigens_selected <- tolower(as.character(antigens_selected))

  if (is.na(units_needed) || units_needed <= 0) {
    stop("Error: Units needed must be a positive number.")
  }

  antigen_neg_freq <- c(
    "d" = 0.15,
    "c_big" = 0.32,
    "c_little" = 0.20,
    "e_big" = 0.71,
    "e_little" = 0.02,
    "k_big" = 0.91,
    "k_little" = 0.002,
    "fya" = 0.34,
    "fyb" = 0.17,
    "jka" = 0.23,
    "jkb" = 0.26,
    "lea" = 0.78,
    "leb" = 0.28,
    "m" = 0.22,
    "n" = 0.28,
    "s_big" = 0.45,
    "s_little" = 0.11,
    "p1" = 0.21
  )

  combined_frequency <- 1.0
  selected_freqs <- list()

  for (antigen in antigens_selected) {
    if (antigen %in% names(antigen_neg_freq)) {
      freq <- antigen_neg_freq[[antigen]]
      combined_frequency <- combined_frequency * freq
      selected_freqs[[antigen]] <- freq
    } else {
      stop(paste("Error: Antigen", antigen, "not recognized. Use standard codes (e.g., 'k_big', 'fya', 's_little')."))
    }
  }

  units_to_screen <- units_needed / combined_frequency

  return(list(
    Units_to_Screen = ceiling(units_to_screen),
    Combined_Antigen_Negative_Frequency = round(combined_frequency, 4),
    Inputs = list(
      Units_Needed = units_needed,
      Antigens = antigens_selected
    )
  ))
}

rcvs2_score <- function(recurrent_thunderclap_headache, carotid_artery_involvement, vasoconstrictive_trigger, sex, subarachnoid_hemorrhage) {

  recurrent_thunderclap_headache <- as.numeric(recurrent_thunderclap_headache)
  carotid_artery_involvement <- as.numeric(carotid_artery_involvement)
  vasoconstrictive_trigger <- as.numeric(vasoconstrictive_trigger)
  sex <- tolower(as.character(sex))
  subarachnoid_hemorrhage <- as.numeric(subarachnoid_hemorrhage)

  if (any(is.na(c(recurrent_thunderclap_headache, carotid_artery_involvement, vasoconstrictive_trigger, subarachnoid_hemorrhage)))) {
    stop("Error: All inputs must be numeric (0 or 1).")
  }

  if (!sex %in% c("male", "female")) {
    stop("Error: Sex must be 'male' or 'female'.")
  }

  score <- 0

  if (recurrent_thunderclap_headache == 1) {
    score <- score + 5
  }

  if (carotid_artery_involvement == 1) {
    score <- score - 2
  }

  if (vasoconstrictive_trigger == 1) {
    score <- score + 3
  }

  if (sex == "female") {
    score <- score + 1
  }

  if (subarachnoid_hemorrhage == 1) {
    score <- score + 1
  }

  risk_level <- ""
  interpretation <- ""

  if (score >= 5) {
    risk_level <- "High Likelihood"
    interpretation <- "Diagnosis of RCVS is highly likely (Sensitivity ~90%, Specificity ~99%). Avoid steroids and vasoconstrictive agents."
  } else if (score <= 2) {
    risk_level <- "Low Likelihood"
    interpretation <- "Diagnosis of RCVS is highly unlikely (Sensitivity ~85%, Specificity 100%). Consider alternative etiologies (e.g., PACNS)."
  } else {
    risk_level <- "Equivocal"
    interpretation <- "Diagnosis is uncertain (Score 3-4). Further diagnostic evaluation required."
  }

  return(list(
    RCVS2_Score = score,
    Risk_Category = risk_level,
    Interpretation = interpretation,
    Inputs = list(
      Recurrent_TCH = recurrent_thunderclap_headache == 1,
      Carotid_Involvement = carotid_artery_involvement == 1,
      Trigger_Identified = vasoconstrictive_trigger == 1,
      Sex = sex,
      SAH_Present = subarachnoid_hemorrhage == 1
    )
  ))
}

reach_b_score <- function(sex, age, alt_u_l, hbeag_positive, hbv_dna, dna_units = "IU/mL") {

  sex <- tolower(as.character(sex))
  age <- as.numeric(age)
  alt_u_l <- as.numeric(alt_u_l)
  hbeag_positive <- as.numeric(hbeag_positive)
  hbv_dna <- as.numeric(hbv_dna)

  if (any(is.na(c(age, alt_u_l, hbeag_positive, hbv_dna)))) {
    stop("Error: All inputs must be numeric.")
  }

  if (!sex %in% c("male", "female")) {
    stop("Error: Sex must be 'male' or 'female'.")
  }

  hbv_dna_copies <- hbv_dna
  if (dna_units == "IU/mL") {
    hbv_dna_copies <- hbv_dna * 5
  }

  score <- 0

  if (sex == "male") {
    score <- score + 2
  }

  if (age >= 30 && age <= 34) score <- score + 0
  else if (age >= 35 && age <= 39) score <- score + 1
  else if (age >= 40 && age <= 44) score <- score + 2
  else if (age >= 45 && age <= 49) score <- score + 3
  else if (age >= 50 && age <= 54) score <- score + 4
  else if (age >= 55 && age <= 59) score <- score + 5
  else if (age >= 60 && age <= 64) score <- score + 6
  else if (age >= 65) score <- score + 7

  if (alt_u_l >= 15 && alt_u_l < 45) {
    score <- score + 1
  } else if (alt_u_l >= 45) {
    score <- score + 2
  }

  if (hbeag_positive == 1) {
    score <- score + 2
  }

  if (hbv_dna_copies >= 10000 && hbv_dna_copies < 100000) {
    score <- score + 3
  } else if (hbv_dna_copies >= 100000 && hbv_dna_copies < 1000000) {
    score <- score + 5
  } else if (hbv_dna_copies >= 1000000) {
    score <- score + 4
  }

  risk_3yr <- 0.0
  risk_5yr <- 0.0
  risk_10yr <- 0.0

  if (score == 0) { risk_3yr <- 0.0; risk_5yr <- 0.0; risk_10yr <- 0.0 }
  else if (score == 1) { risk_3yr <- 0.0; risk_5yr <- 0.0; risk_10yr <- 0.1 }
  else if (score == 2) { risk_3yr <- 0.0; risk_5yr <- 0.0; risk_10yr <- 0.2 }
  else if (score == 3) { risk_3yr <- 0.0; risk_5yr <- 0.1; risk_10yr <- 0.4 }
  else if (score == 4) { risk_3yr <- 0.0; risk_5yr <- 0.1; risk_10yr <- 0.6 }
  else if (score == 5) { risk_3yr <- 0.0; risk_5yr <- 0.2; risk_10yr <- 1.0 }
  else if (score == 6) { risk_3yr <- 0.1; risk_5yr <- 0.3; risk_10yr <- 1.6 }
  else if (score == 7) { risk_3yr <- 0.1; risk_5yr <- 0.5; risk_10yr <- 2.6 }
  else if (score == 8) { risk_3yr <- 0.2; risk_5yr <- 0.9; risk_10yr <- 4.2 }
  else if (score == 9) { risk_3yr <- 0.3; risk_5yr <- 1.4; risk_10yr <- 6.7 }
  else if (score == 10) { risk_3yr <- 0.5; risk_5yr <- 2.3; risk_10yr <- 10.5 }
  else if (score == 11) { risk_3yr <- 0.8; risk_5yr <- 3.6; risk_10yr <- 16.2 }
  else if (score == 12) { risk_3yr <- 1.3; risk_5yr <- 5.7; risk_10yr <- 24.3 }
  else if (score == 13) { risk_3yr <- 2.1; risk_5yr <- 8.9; risk_10yr <- 35.0 }
  else if (score == 14) { risk_3yr <- 3.3; risk_5yr <- 13.6; risk_10yr <- 48.2 }
  else if (score == 15) { risk_3yr <- 5.1; risk_5yr <- 20.3; risk_10yr <- 62.8 }
  else if (score == 16) { risk_3yr <- 7.9; risk_5yr <- 29.3; risk_10yr <- 76.8 }
  else if (score >= 17) { risk_3yr <- 12.1; risk_5yr <- 40.6; risk_10yr <- 88.0 }

  return(list(
    REACH_B_Score = score,
    HCC_Risk_3_Year = paste0(risk_3yr, "%"),
    HCC_Risk_5_Year = paste0(risk_5yr, "%"),
    HCC_Risk_10_Year = paste0(risk_10yr, "%"),
    Inputs = list(
      Sex = sex,
      Age = age,
      ALT = alt_u_l,
      HBeAg_Positive = hbeag_positive == 1,
      HBV_DNA_Copies = hbv_dna_copies
    )
  ))
}

readmits_score_ami <- function(age, sex, creatinine, bnp, diabetes, pci_performed, optimal_therapies, systolic_bp) {

  age <- as.numeric(age)
  sex <- tolower(as.character(sex))
  creatinine <- as.numeric(creatinine)
  bnp <- as.numeric(bnp)
  diabetes <- as.numeric(diabetes)
  pci_performed <- as.numeric(pci_performed)
  optimal_therapies <- as.numeric(optimal_therapies)
  systolic_bp <- as.numeric(systolic_bp)

  if (any(is.na(c(age, creatinine, bnp, diabetes, pci_performed, optimal_therapies, systolic_bp)))) {
    stop("Error: All inputs must be numeric.")
  }

  if (!sex %in% c("male", "female")) {
    stop("Error: Sex must be 'male' or 'female'.")
  }

  score <- 0

  if (creatinine > 1.2) {
    score <- score + 1
  }

  if (bnp > 200) {
    score <- score + 1
  }

  if (age >= 65 && age <= 74) {
    score <- score + 1
  } else if (age >= 75) {
    score <- score + 2
  }

  if (diabetes == 1) {
    score <- score + 1
  }

  if (sex == "male") {
    score <- score + 1
  }

  if (pci_performed == 0) {
    score <- score + 1
  }

  if (optimal_therapies == 0) {
    score <- score + 1
  }

  if (systolic_bp < 100) {
    score <- score + 1
  }

  risk_category <- ""
  readmission_prob <- ""

  if (score <= 2) {
    risk_category <- "Low Risk"
    readmission_prob <- "Approx. 10%"
  } else if (score <= 4) {
    risk_category <- "Intermediate Risk"
    readmission_prob <- "Approx. 18%"
  } else {
    risk_category <- "High Risk"
    readmission_prob <- "> 28%"
  }

  return(list(
    READMITS_Score = score,
    Risk_Category = risk_category,
    Est_30_Day_Readmission = readmission_prob,
    Inputs = list(
      Renal_Insufficiency = creatinine > 1.2,
      Elevated_BNP = bnp > 200,
      Age_Points = if (age >= 75) 2 else if (age >= 65) 1 else 0,
      Diabetes = diabetes == 1,
      Male_Sex = sex == "male",
      No_Intervention = pci_performed == 0,
      Incomplete_Therapies = optimal_therapies == 0,
      Low_SBP = systolic_bp < 100
    )
  ))
}

rebound_hyperbilirubinemia_score <- function(gestational_age_weeks, age_initiation_hours, tsb_termination_mg_dl, aap_threshold_mg_dl) {

  gestational_age_weeks <- as.numeric(gestational_age_weeks)
  age_initiation_hours <- as.numeric(age_initiation_hours)
  tsb_termination_mg_dl <- as.numeric(tsb_termination_mg_dl)
  aap_threshold_mg_dl <- as.numeric(aap_threshold_mg_dl)

  if (any(is.na(c(gestational_age_weeks, age_initiation_hours, tsb_termination_mg_dl, aap_threshold_mg_dl)))) {
    stop("Error: All inputs must be numeric.")
  }

  if (gestational_age_weeks < 35) {
    return(list(Error = "This score is validated for infants >= 35 weeks gestational age."))
  }

  ga_points <- 0
  if (gestational_age_weeks < 38) {
    ga_points <- 15
  }

  age_initiation_days <- age_initiation_hours / 24
  age_points <- 7 * age_initiation_days

  relative_tsb <- aap_threshold_mg_dl - tsb_termination_mg_dl
  tsb_points <- 4 * relative_tsb

  score <- 15 * (if (gestational_age_weeks < 38) 1 else 0) - 7 * age_initiation_days - 4 * relative_tsb + 50
  score <- round(score, 1)

  probability <- ""
  if (score < 20) {
    probability <- "< 4%"
  } else if (score < 30) {
    probability <- "< 10%"
  } else if (score < 40) {
    probability <- "~ 11 - 20%"
  } else {
    probability <- "> 20%"
  }

  return(list(
    Rebound_Score = score,
    Rebound_Risk_Probability = probability,
    Inputs = list(
      GA_Weeks = gestational_age_weeks,
      Initiation_Age_Hours = age_initiation_hours,
      Termination_TSB = tsb_termination_mg_dl,
      AAP_Threshold = aap_threshold_mg_dl
    )
  ))
}

rosier_stroke_scale <- function(loss_of_consciousness, seizure_activity, asymmetric_facial_weakness, asymmetric_arm_weakness, asymmetric_leg_weakness, speech_disturbance, visual_field_defect) {

  loss_of_consciousness <- as.numeric(loss_of_consciousness)
  seizure_activity <- as.numeric(seizure_activity)
  asymmetric_facial_weakness <- as.numeric(asymmetric_facial_weakness)
  asymmetric_arm_weakness <- as.numeric(asymmetric_arm_weakness)
  asymmetric_leg_weakness <- as.numeric(asymmetric_leg_weakness)
  speech_disturbance <- as.numeric(speech_disturbance)
  visual_field_defect <- as.numeric(visual_field_defect)

  if (any(is.na(c(loss_of_consciousness, seizure_activity, asymmetric_facial_weakness, asymmetric_arm_weakness, asymmetric_leg_weakness, speech_disturbance, visual_field_defect)))) {
    stop("Error: All inputs must be numeric (0 or 1).")
  }

  score <- 0

  if (loss_of_consciousness == 1) {
    score <- score - 1
  }

  if (seizure_activity == 1) {
    score <- score - 1
  }

  if (asymmetric_facial_weakness == 1) {
    score <- score + 1
  }

  if (asymmetric_arm_weakness == 1) {
    score <- score + 1
  }

  if (asymmetric_leg_weakness == 1) {
    score <- score + 1
  }

  if (speech_disturbance == 1) {
    score <- score + 1
  }

  if (visual_field_defect == 1) {
    score <- score + 1
  }

  diagnosis <- ""
  sensitivity <- ""
  specificity <- ""

  if (score > 0) {
    diagnosis <- "Stroke Likely (Score > 0)"
    sensitivity <- "83%"
    specificity <- "44%"
  } else {
    diagnosis <- "Stroke Unlikely (Score <= 0)"
    sensitivity <- "N/A"
    specificity <- "N/A"
  }

  return(list(
    ROSIER_Score = score,
    Likelihood = diagnosis,
    Test_Characteristics = list(
      Sensitivity = sensitivity,
      Specificity = specificity
    ),
    Inputs = list(
      LOC = loss_of_consciousness == 1,
      Seizure = seizure_activity == 1,
      Face = asymmetric_facial_weakness == 1,
      Arm = asymmetric_arm_weakness == 1,
      Leg = asymmetric_leg_weakness == 1,
      Speech = speech_disturbance == 1,
      Visual = visual_field_defect == 1
    )
  ))
}

