rest_lgs_screen <- function(onset_lt_9y, drug_resistant, cognitive_impairment, tonic_seizures, atonic_seizures, atypical_absence) {

  onset_lt_9y <- as.numeric(onset_lt_9y)
  drug_resistant <- as.numeric(drug_resistant)
  cognitive_impairment <- as.numeric(cognitive_impairment)
  tonic_seizures <- as.numeric(tonic_seizures)
  atonic_seizures <- as.numeric(atonic_seizures)
  atypical_absence <- as.numeric(atypical_absence)

  if (any(is.na(c(onset_lt_9y, drug_resistant, cognitive_impairment, tonic_seizures, atonic_seizures, atypical_absence)))) {
    stop("Error: All inputs must be numeric (0 or 1).")
  }

  core_criteria_met <- (onset_lt_9y == 1 && drug_resistant == 1 && cognitive_impairment == 1)

  seizure_types_met <- (tonic_seizures == 1 || atonic_seizures == 1 || atypical_absence == 1)

  result <- ""
  recommendation <- ""

  if (core_criteria_met && seizure_types_met) {
    result <- "Positive Screen (High Suspicion for LGS)"
    recommendation <- "Refer to epilepsy specialist for EEG (slow spike-and-wave) and comprehensive evaluation."
  } else {
    result <- "Negative Screen"
    recommendation <- "Does not meet full clinical profile for LGS screening criteria."
  }

  return(list(
    Screening_Result = result,
    Recommendation = recommendation,
    Inputs = list(
      Onset_lt_9_Years = onset_lt_9y == 1,
      Drug_Resistant = drug_resistant == 1,
      Cognitive_Impairment = cognitive_impairment == 1,
      LGS_Seizure_Types_Present = seizure_types_met
    )
  ))
}

regiscar_dress_score <- function(fever_gt_385, lymphadenopathy, eosinophil_count, atypical_lymphocytes, skin_extent_gt_50, skin_suggestive_features, organ_involvement_count, other_causes_excluded, resolution_gt_15_days = 1) {

  fever_gt_385 <- as.numeric(fever_gt_385)
  lymphadenopathy <- as.numeric(lymphadenopathy)
  eosinophil_count <- as.numeric(eosinophil_count)
  atypical_lymphocytes <- as.numeric(atypical_lymphocytes)
  skin_extent_gt_50 <- as.numeric(skin_extent_gt_50)
  skin_suggestive_features <- as.numeric(skin_suggestive_features)
  organ_involvement_count <- as.numeric(organ_involvement_count)
  other_causes_excluded <- as.numeric(other_causes_excluded)
  resolution_gt_15_days <- as.numeric(resolution_gt_15_days)

  if (any(is.na(c(fever_gt_385, lymphadenopathy, eosinophil_count, atypical_lymphocytes, skin_extent_gt_50, skin_suggestive_features, organ_involvement_count, other_causes_excluded, resolution_gt_15_days)))) {
    stop("Error: All inputs must be numeric.")
  }

  score <- 0

  if (fever_gt_385 == 1) {
    score <- score + 1
  }

  if (lymphadenopathy == 1) {
    score <- score + 1
  }

  if (eosinophil_count >= 1500) {
    score <- score + 2
  } else if (eosinophil_count >= 700) {
    score <- score + 1
  }

  if (atypical_lymphocytes == 1) {
    score <- score + 1
  }

  if (skin_extent_gt_50 == 1) {
    score <- score + 1
  }

  if (skin_suggestive_features == 1) {
    score <- score + 1
  }

  if (organ_involvement_count >= 2) {
    score <- score + 2
  } else if (organ_involvement_count == 1) {
    score <- score + 1
  }

  if (other_causes_excluded == 1) {
    score <- score + 1
  }

  if (resolution_gt_15_days == 0) {
    score <- score - 1
  }

  diagnosis <- ""

  if (score < 2) {
    diagnosis <- "No DRESS"
  } else if (score >= 2 && score <= 3) {
    diagnosis <- "Possible DRESS"
  } else if (score >= 4 && score <= 5) {
    diagnosis <- "Probable DRESS"
  } else {
    diagnosis <- "Definite DRESS"
  }

  return(list(
    RegiSCAR_Score = score,
    Diagnosis = diagnosis,
    Inputs = list(
      Fever = fever_gt_385 == 1,
      Lymphadenopathy = lymphadenopathy == 1,
      Eosinophils = eosinophil_count,
      Atypical_Lymphs = atypical_lymphocytes == 1,
      Rash_Extent_gt_50 = skin_extent_gt_50 == 1,
      Rash_Features = skin_suggestive_features == 1,
      Organ_Count = organ_involvement_count,
      Causes_Excluded = other_causes_excluded == 1,
      Resolution_gt_15d = resolution_gt_15_days == 1
    )
  ))
}

reids_colposcopic_index <- function(lesion_margin, acetowhitening_color, vascular_patterns, iodine_staining) {

  lesion_margin <- as.numeric(lesion_margin)
  acetowhitening_color <- as.numeric(acetowhitening_color)
  vascular_patterns <- as.numeric(vascular_patterns)
  iodine_staining <- as.numeric(iodine_staining)

  if (any(is.na(c(lesion_margin, acetowhitening_color, vascular_patterns, iodine_staining)))) {
    stop("Error: All inputs must be numeric.")
  }

  if (any(c(lesion_margin, acetowhitening_color, vascular_patterns, iodine_staining) < 0) ||
      any(c(lesion_margin, acetowhitening_color, vascular_patterns, iodine_staining) > 2)) {
    stop("Error: All item scores must be integers between 0 and 2.")
  }

  total_score <- lesion_margin + acetowhitening_color + vascular_patterns + iodine_staining

  histology_prediction <- ""
  if (total_score <= 2) {
    histology_prediction <- "Likely HPV or CIN I (Low-grade disease)"
  } else if (total_score <= 5) {
    histology_prediction <- "Likely CIN I or CIN II (Intermediate-grade disease)"
  } else {
    histology_prediction <- "Likely CIN II or CIN III (High-grade disease)"
  }

  return(list(
    RCI_Score = total_score,
    Predicted_Histology = histology_prediction,
    Inputs = list(
      Margin = lesion_margin,
      Color = acetowhitening_color,
      Vessels = vascular_patterns,
      Iodine = iodine_staining
    )
  ))
}

relative_fat_mass <- function(sex, height, waist, units = "cm") {

  sex <- tolower(as.character(sex))
  height <- as.numeric(height)
  waist <- as.numeric(waist)

  if (any(is.na(c(height, waist)))) {
    stop("Error: Height and Waist must be numeric.")
  }

  if (height <= 0 || waist <= 0) {
    stop("Error: Height and Waist must be positive.")
  }

  if (!sex %in% c("male", "female")) {
    stop("Error: Sex must be 'male' or 'female'.")
  }

  ratio <- height / waist

  rfm <- 0
  cutoff_obesity <- 0

  if (sex == "male") {
    rfm <- 64 - (20 * ratio)
    cutoff_obesity <- 22.8
  } else {
    rfm <- 76 - (20 * ratio)
    cutoff_obesity <- 33.9
  }

  category <- ""
  if (rfm >= cutoff_obesity) {
    category <- "Obesity (High Body Fat)"
  } else {
    category <- "Non-Obese"
  }

  return(list(
    RFM_Percentage = round(rfm, 1),
    Interpretation = category,
    Inputs = list(
      Sex = sex,
      Height = height,
      Waist = waist,
      Units = units
    )
  ))
}

renal_nephrometry_score <- function(radius_cm, exophytic_percent, nearness_collecting_system_mm, anterior_posterior, location_polar_lines) {

  radius_cm <- as.numeric(radius_cm)
  exophytic_percent <- as.numeric(exophytic_percent)
  nearness_collecting_system_mm <- as.numeric(nearness_collecting_system_mm)
  anterior_posterior <- tolower(as.character(anterior_posterior))
  location_polar_lines <- tolower(as.character(location_polar_lines))

  if (any(is.na(c(radius_cm, exophytic_percent, nearness_collecting_system_mm)))) {
    stop("Error: Radius, Exophytic percent, and Nearness must be numeric.")
  }

  if (!anterior_posterior %in% c("anterior", "posterior", "neither")) {
    stop("Error: Anterior/Posterior must be 'anterior', 'posterior', or 'neither'.")
  }

  if (!location_polar_lines %in% c("entirely_above_below", "crosses_polar_line", "gt_50_percent_across_polar_line_or_axial")) {
    stop("Error: Location must be 'entirely_above_below', 'crosses_polar_line', or 'gt_50_percent_across_polar_line_or_axial'.")
  }

  r_score <- 0
  if (radius_cm <= 4) {
    r_score <- 1
  } else if (radius_cm > 4 && radius_cm < 7) {
    r_score <- 2
  } else {
    r_score <- 3
  }

  e_score <- 0
  if (exophytic_percent >= 50) {
    e_score <- 1
  } else if (exophytic_percent < 50 && exophytic_percent > 0) {
    e_score <- 2
  } else {
    e_score <- 3
  }

  n_score <- 0
  if (nearness_collecting_system_mm >= 7) {
    n_score <- 1
  } else if (nearness_collecting_system_mm > 4 && nearness_collecting_system_mm < 7) {
    n_score <- 2
  } else {
    n_score <- 3
  }

  a_score <- ""
  if (anterior_posterior == "anterior") {
    a_score <- "a"
  } else if (anterior_posterior == "posterior") {
    a_score <- "p"
  } else {
    a_score <- "x"
  }

  l_score <- 0
  if (location_polar_lines == "entirely_above_below") {
    l_score <- 1
  } else if (location_polar_lines == "crosses_polar_line") {
    l_score <- 2
  } else {
    l_score <- 3
  }

  total_score <- r_score + e_score + n_score + l_score

  complexity <- ""
  if (total_score >= 4 && total_score <= 6) {
    complexity <- "Low Complexity"
  } else if (total_score >= 7 && total_score <= 9) {
    complexity <- "Moderate Complexity"
  } else {
    complexity <- "High Complexity"
  }

  nephrometry_score <- paste0(total_score, a_score)

  return(list(
    RENAL_Score = nephrometry_score,
    Complexity_Level = complexity,
    Inputs = list(
      Radius_Score = r_score,
      Exophytic_Score = e_score,
      Nearness_Score = n_score,
      Anterior_Posterior = a_score,
      Location_Score = l_score
    )
  ))
}

resect90_lung_mortality_score <- function(age, sex, ecog_ps, dlco_percent, bmi, creatinine, anemia, arrhythmia, right_sided_resection, thoracotomy_approach, malignant_diagnosis, num_resected_segments, creatinine_units = "mg/dL") {

  age <- as.numeric(age)
  ecog_ps <- as.numeric(ecog_ps)
  dlco_percent <- as.numeric(dlco_percent)
  bmi <- as.numeric(bmi)
  creatinine <- as.numeric(creatinine)
  num_resected_segments <- as.numeric(num_resected_segments)

  sex <- tolower(as.character(sex))
  anemia <- as.numeric(anemia)
  arrhythmia <- as.numeric(arrhythmia)
  right_sided_resection <- as.numeric(right_sided_resection)
  thoracotomy_approach <- as.numeric(thoracotomy_approach)
  malignant_diagnosis <- as.numeric(malignant_diagnosis)

  if (any(is.na(c(age, ecog_ps, dlco_percent, bmi, creatinine, num_resected_segments, anemia, arrhythmia, right_sided_resection, thoracotomy_approach, malignant_diagnosis)))) {
    stop("Error: All inputs must be numeric/valid.")
  }

  if (!sex %in% c("male", "female")) {
    stop("Error: Sex must be 'male' or 'female'.")
  }

  creat_umol <- creatinine
  if (creatinine_units == "mg/dL") {
    creat_umol <- creatinine * 88.42
  }

  male_val <- if (sex == "male") 1 else 0

  logit <- -6.036 +
    (0.041 * age) +
    (0.493 * male_val) +
    (0.183 * ecog_ps) -
    (0.029 * dlco_percent) -
    (0.056 * bmi) +
    (0.005 * creat_umol) +
    (0.242 * anemia) +
    (0.608 * arrhythmia) +
    (0.379 * right_sided_resection) +
    (0.179 * num_resected_segments) +
    (0.634 * thoracotomy_approach) +
    (0.769 * malignant_diagnosis)

  prob <- 1 / (1 + exp(-logit))
  prob_percent <- prob * 100

  return(list(
    RESECT90_Score_Percent = round(prob_percent, 1),
    Interpretation = "Estimated probability of 90-day mortality following lung resection.",
    Inputs = list(
      Age = age,
      Sex = sex,
      ECOG = ecog_ps,
      DLCO = dlco_percent,
      BMI = bmi,
      Creatinine_umol = round(creat_umol, 1),
      Anemia = anemia == 1,
      Arrhythmia = arrhythmia == 1,
      Right_Sided = right_sided_resection == 1,
      Thoracotomy = thoracotomy_approach == 1,
      Malignant = malignant_diagnosis == 1,
      Segments = num_resected_segments
    )
  ))
}

resp_ecmo_score <- function(age, immunocompromised, mv_duration_hours, diagnosis_category, cns_dysfunction, acute_infection_non_pulm, neuromuscular_blockade, nitric_oxide_use, bicarbonate_use, cardiac_arrest, paco2_mmhg, pip_cmh2o) {

  age <- as.numeric(age)
  immunocompromised <- as.numeric(immunocompromised)
  mv_duration_hours <- as.numeric(mv_duration_hours)
  diagnosis_category <- tolower(as.character(diagnosis_category))
  cns_dysfunction <- as.numeric(cns_dysfunction)
  acute_infection_non_pulm <- as.numeric(acute_infection_non_pulm)
  neuromuscular_blockade <- as.numeric(neuromuscular_blockade)
  nitric_oxide_use <- as.numeric(nitric_oxide_use)
  bicarbonate_use <- as.numeric(bicarbonate_use)
  cardiac_arrest <- as.numeric(cardiac_arrest)
  paco2_mmhg <- as.numeric(paco2_mmhg)
  pip_cmh2o <- as.numeric(pip_cmh2o)

  if (any(is.na(c(age, immunocompromised, mv_duration_hours, cns_dysfunction, acute_infection_non_pulm, neuromuscular_blockade, nitric_oxide_use, bicarbonate_use, cardiac_arrest, paco2_mmhg, pip_cmh2o)))) {
    stop("Error: All numeric/binary inputs must be valid.")
  }

  valid_diagnoses <- c("viral_pneumonia", "bacterial_pneumonia", "asthma", "trauma_burn", "aspiration_pneumonitis", "other_acute_respiratory", "chronic_non_respiratory")
  if (!diagnosis_category %in% valid_diagnoses) {
    stop("Error: Diagnosis must be one of: 'viral_pneumonia', 'bacterial_pneumonia', 'asthma', 'trauma_burn', 'aspiration_pneumonitis', 'other_acute_respiratory', or 'chronic_non_respiratory'.")
  }

  score <- 0

  if (age >= 18 && age <= 49) {
    score <- score + 0
  } else if (age >= 50 && age <= 59) {
    score <- score - 2
  } else if (age >= 60) {
    score <- score - 3
  }

  if (immunocompromised == 1) {
    score <- score - 2
  }

  if (mv_duration_hours < 48) {
    score <- score + 3
  } else if (mv_duration_hours >= 48 && mv_duration_hours <= 168) {
    score <- score + 1
  } else {
    score <- score + 0
  }

  if (diagnosis_category == "viral_pneumonia" || diagnosis_category == "bacterial_pneumonia" || diagnosis_category == "trauma_burn" || diagnosis_category == "aspiration_pneumonitis") {
    score <- score + 3
  } else if (diagnosis_category == "asthma") {
    score <- score + 11
  } else if (diagnosis_category == "other_acute_respiratory") {
    score <- score + 1
  } else {
    score <- score + 0
  }

  if (cns_dysfunction == 1) {
    score <- score - 7
  }

  if (acute_infection_non_pulm == 1) {
    score <- score - 3
  }

  if (neuromuscular_blockade == 1) {
    score <- score + 1
  }

  if (nitric_oxide_use == 1) {
    score <- score - 1
  }

  if (bicarbonate_use == 1) {
    score <- score - 2
  }

  if (cardiac_arrest == 1) {
    score <- score - 2
  }

  if (paco2_mmhg >= 75) {
    score <- score - 2
  }

  if (pip_cmh2o >= 42) {
    score <- score - 2
  }

  risk_class <- ""
  survival_prob <- ""

  if (score >= 6) {
    risk_class <- "Risk Class I"
    survival_prob <- "92%"
  } else if (score >= 3) {
    risk_class <- "Risk Class II"
    survival_prob <- "76%"
  } else if (score >= -1) {
    risk_class <- "Risk Class III"
    survival_prob <- "57%"
  } else if (score >= -6) {
    risk_class <- "Risk Class IV"
    survival_prob <- "33%"
  } else {
    risk_class <- "Risk Class V"
    survival_prob <- "18%"
  }

  return(list(
    RESP_Score = score,
    Risk_Class = risk_class,
    Est_Hospital_Survival = survival_prob,
    Inputs = list(
      Age = age,
      Immunocompromised = immunocompromised == 1,
      MV_Duration_Hours = mv_duration_hours,
      Diagnosis = diagnosis_category,
      CNS_Dysfunction = cns_dysfunction == 1,
      Non_Pulm_Infection = acute_infection_non_pulm == 1,
      NMB = neuromuscular_blockade == 1,
      Nitric_Oxide = nitric_oxide_use == 1,
      Bicarbonate = bicarbonate_use == 1,
      Cardiac_Arrest = cardiac_arrest == 1,
      PaCO2 = paco2_mmhg,
      PIP = pip_cmh2o
    )
  ))
}

rdos_score <- function(heart_rate, respiratory_rate, restlessness, paradoxical_breathing, accessory_muscle_use, grunting, nasal_flaring, look_of_fear) {

  heart_rate <- as.numeric(heart_rate)
  respiratory_rate <- as.numeric(respiratory_rate)
  restlessness <- tolower(as.character(restlessness))
  paradoxical_breathing <- as.numeric(paradoxical_breathing)
  accessory_muscle_use <- tolower(as.character(accessory_muscle_use))
  grunting <- as.numeric(grunting)
  nasal_flaring <- as.numeric(nasal_flaring)
  look_of_fear <- as.numeric(look_of_fear)

  if (any(is.na(c(heart_rate, respiratory_rate, paradoxical_breathing, grunting, nasal_flaring, look_of_fear)))) {
    stop("Error: All inputs must be valid numbers or categories.")
  }

  if (!restlessness %in% c("none", "occasional", "frequent")) {
    stop("Error: Restlessness must be 'none', 'occasional', or 'frequent'.")
  }

  if (!accessory_muscle_use %in% c("none", "slight", "pronounced")) {
    stop("Error: Accessory Muscle Use must be 'none', 'slight', or 'pronounced'.")
  }

  score <- 0

  if (heart_rate < 90) {
    score <- score + 0
  } else if (heart_rate >= 90 && heart_rate <= 109) {
    score <- score + 1
  } else {
    score <- score + 2
  }

  if (respiratory_rate <= 18) {
    score <- score + 0
  } else if (respiratory_rate >= 19 && respiratory_rate <= 30) {
    score <- score + 1
  } else {
    score <- score + 2
  }

  if (restlessness == "none") {
    score <- score + 0
  } else if (restlessness == "occasional") {
    score <- score + 1
  } else {
    score <- score + 2
  }

  if (paradoxical_breathing == 1) {
    score <- score + 2
  }

  if (accessory_muscle_use == "none") {
    score <- score + 0
  } else if (accessory_muscle_use == "slight") {
    score <- score + 1
  } else {
    score <- score + 2
  }

  if (grunting == 1) {
    score <- score + 2
  }

  if (nasal_flaring == 1) {
    score <- score + 2
  }

  if (look_of_fear == 1) {
    score <- score + 2
  }

  interpretation <- ""
  if (score < 3) {
    interpretation <- "Little or No Respiratory Distress"
  } else {
    interpretation <- "Moderate to Severe Respiratory Distress (Palliation indicated)"
  }

  return(list(
    RDOS_Score = score,
    Interpretation = interpretation,
    Inputs = list(
      HR = heart_rate,
      RR = respiratory_rate,
      Restlessness = restlessness,
      Paradoxical_Breathing = paradoxical_breathing == 1,
      Accessory_Muscles = accessory_muscle_use,
      Grunting = grunting == 1,
      Nasal_Flaring = nasal_flaring == 1,
      Fear = look_of_fear == 1
    )
  ))
}

respiratory_score_asthma_liu <- function(age_years, respiratory_rate, wheezing_score, retractions_score) {

  age_years <- as.numeric(age_years)
  respiratory_rate <- as.numeric(respiratory_rate)
  wheezing_score <- as.numeric(wheezing_score)
  retractions_score <- as.numeric(retractions_score)

  if (any(is.na(c(age_years, respiratory_rate, wheezing_score, retractions_score)))) {
    stop("Error: All inputs must be numeric.")
  }

  if (any(c(wheezing_score, retractions_score) < 0) || any(c(wheezing_score, retractions_score) > 3)) {
    stop("Error: Wheezing and Retractions scores must be integers between 0 and 3.")
  }

  rr_score <- 0

  if (age_years < 2) {
    if (respiratory_rate < 40) rr_score <- 0
    else if (respiratory_rate <= 59) rr_score <- 1
    else if (respiratory_rate <= 69) rr_score <- 2
    else rr_score <- 3
  } else if (age_years >= 2 && age_years <= 5) {
    if (respiratory_rate < 30) rr_score <- 0
    else if (respiratory_rate <= 39) rr_score <- 1
    else if (respiratory_rate <= 49) rr_score <- 2
    else rr_score <- 3
  } else {
    if (respiratory_rate < 20) rr_score <- 0
    else if (respiratory_rate <= 24) rr_score <- 1
    else if (respiratory_rate <= 29) rr_score <- 2
    else rr_score <- 3
  }

  total_score <- rr_score + wheezing_score + retractions_score

  severity <- ""
  if (total_score <= 3) {
    severity <- "Mild Exacerbation"
  } else if (total_score <= 7) {
    severity <- "Moderate Exacerbation"
  } else {
    severity <- "Severe Exacerbation"
  }

  return(list(
    Respiratory_Score = total_score,
    Severity_Classification = severity,
    Inputs = list(
      Age = age_years,
      RR_Value = respiratory_rate,
      RR_Points = rr_score,
      Wheezing_Points = wheezing_score,
      Retractions_Points = retractions_score
    )
  ))
}

rescue_ihca_score <- function(age, history_renal_insufficiency, time_of_arrest_day, initial_rhythm_shockable, etiology_cardiac) {

  age <- as.numeric(age)
  history_renal_insufficiency <- as.numeric(history_renal_insufficiency)
  time_of_arrest_day <- as.numeric(time_of_arrest_day)
  initial_rhythm_shockable <- as.numeric(initial_rhythm_shockable)
  etiology_cardiac <- as.numeric(etiology_cardiac)

  if (any(is.na(c(age, history_renal_insufficiency, time_of_arrest_day, initial_rhythm_shockable, etiology_cardiac)))) {
    stop("Error: All inputs must be numeric.")
  }

  score <- 0

  if (age < 60) {
    score <- score + 6
  } else if (age >= 60 && age <= 74) {
    score <- score + 2
  } else {
    score <- score + 0
  }

  if (history_renal_insufficiency == 1) {
    score <- score - 2
  }

  if (time_of_arrest_day == 1) {
    score <- score + 2
  }

  if (initial_rhythm_shockable == 1) {
    score <- score + 2
  }

  if (etiology_cardiac == 1) {
    score <- score + 4
  }

  survival_probability <- ""

  if (score >= 12) {
    survival_probability <- "57%"
  } else if (score >= 10) {
    survival_probability <- "38%"
  } else if (score >= 7) {
    survival_probability <- "22%"
  } else if (score >= 2) {
    survival_probability <- "8%"
  } else {
    survival_probability <- "2%"
  }

  return(list(
    RESCUE_IHCA_Score = score,
    Est_Survival_to_Discharge = survival_probability,
    Inputs = list(
      Age = age,
      Renal_Insufficiency = history_renal_insufficiency == 1,
      Arrest_Time_0800_1659 = time_of_arrest_day == 1,
      Shockable_Rhythm = initial_rhythm_shockable == 1,
      Cardiac_Etiology = etiology_cardiac == 1
    )
  ))
}

reveal_pah_risk_score <- function(who_group1_subgroup, age_years, male_sex, renal_insufficiency, nyha_class, systolic_bp, heart_rate, hospitalizations_6mo, six_min_walk_distance, bnp_level = NULL, nt_probnp_level = NULL, pericardial_effusion, dlco_predicted, mrap_gt_20, pvr_lt_5) {

  who_group1_subgroup <- tolower(as.character(who_group1_subgroup))
  age_years <- as.numeric(age_years)
  male_sex <- as.numeric(male_sex)
  renal_insufficiency <- as.numeric(renal_insufficiency)
  nyha_class <- as.numeric(nyha_class)
  systolic_bp <- as.numeric(systolic_bp)
  heart_rate <- as.numeric(heart_rate)
  hospitalizations_6mo <- as.numeric(hospitalizations_6mo)
  six_min_walk_distance <- as.numeric(six_min_walk_distance)
  pericardial_effusion <- as.numeric(pericardial_effusion)
  dlco_predicted <- as.numeric(dlco_predicted)
  mrap_gt_20 <- as.numeric(mrap_gt_20)
  pvr_lt_5 <- as.numeric(pvr_lt_5)

  if (any(is.na(c(age_years, male_sex, renal_insufficiency, nyha_class, systolic_bp, heart_rate, hospitalizations_6mo, six_min_walk_distance, pericardial_effusion, dlco_predicted, mrap_gt_20, pvr_lt_5)))) {
    stop("Error: All inputs must be numeric.")
  }

  score <- 0

  if (who_group1_subgroup == "portopulmonary") {
    score <- score + 3
  } else if (who_group1_subgroup == "familial" || who_group1_subgroup == "heritable") {
    score <- score + 2
  } else if (who_group1_subgroup == "ctd") {
    score <- score + 1
  } else {
    score <- score + 0
  }

  if (male_sex == 1 && age_years > 60) {
    score <- score + 2
  }

  if (renal_insufficiency == 1) {
    score <- score + 1
  }

  if (nyha_class == 1) {
    score <- score - 1
  } else if (nyha_class == 3) {
    score <- score + 1
  } else if (nyha_class == 4) {
    score <- score + 2
  }

  if (systolic_bp < 110) {
    score <- score + 1
  }

  if (heart_rate > 96) {
    score <- score + 1
  }

  if (hospitalizations_6mo == 1) {
    score <- score + 1
  }

  if (six_min_walk_distance >= 440) {
    score <- score - 2
  } else if (six_min_walk_distance >= 320 && six_min_walk_distance < 440) {
    score <- score - 1
  } else if (six_min_walk_distance < 165) {
    score <- score + 1
  }

  if (!is.null(nt_probnp_level)) {
    if (nt_probnp_level < 300) score <- score - 2
    else if (nt_probnp_level >= 1100) score <- score + 2
  } else if (!is.null(bnp_level)) {
    if (bnp_level < 50) score <- score - 2
    else if (bnp_level >= 800) score <- score + 2
    else if (bnp_level >= 200) score <- score + 1
  }

  if (pericardial_effusion == 1) {
    score <- score + 1
  }

  if (dlco_predicted < 40) {
    score <- score + 1
  }

  if (mrap_gt_20 == 1) {
    score <- score + 1
  }

  if (pvr_lt_5 == 1) {
    score <- score - 1
  }

  risk_group <- ""
  mortality_risk_12mo <- ""

  if (score <= 6) {
    risk_group <- "Low Risk"
    mortality_risk_12mo <- "< 2.6%"
  } else if (score <= 8) {
    risk_group <- "Intermediate Risk"
    mortality_risk_12mo <- "6.2 - 7.0%"
  } else {
    risk_group <- "High Risk"
    mortality_risk_12mo <- "> 10.7%"
  }

  return(list(
    REVEAL_2_0_Score = score,
    Risk_Group = risk_group,
    Mortality_Risk_12_Month = mortality_risk_12mo,
    Inputs = list(
      Subgroup = who_group1_subgroup,
      Male_gt_60 = (male_sex == 1 && age_years > 60),
      Renal_Insufficiency = renal_insufficiency == 1,
      NYHA_Class = nyha_class,
      SBP_lt_110 = systolic_bp < 110,
      HR_gt_96 = heart_rate > 96,
      Recent_Hospitalization = hospitalizations_6mo == 1,
      Walk_Distance = six_min_walk_distance,
      BNP_NTproBNP = if(!is.null(nt_probnp_level)) paste("NT-proBNP:", nt_probnp_level) else paste("BNP:", bnp_level),
      Pericardial_Effusion = pericardial_effusion == 1,
      DLCO_lt_40 = dlco_predicted < 40,
      mRAP_gt_20 = mrap_gt_20 == 1,
      PVR_lt_5 = pvr_lt_5 == 1
    )
  ))
}

alsfrs_r_score <- function(speech, salivation, swallowing, handwriting, cutting_food, dressing_hygiene, turning_in_bed, walking, climbing_stairs, dyspnea, orthopnea, respiratory_insufficiency) {

  inputs <- c(speech, salivation, swallowing, handwriting, cutting_food, dressing_hygiene, turning_in_bed, walking, climbing_stairs, dyspnea, orthopnea, respiratory_insufficiency)

  if (any(is.na(inputs))) {
    stop("Error: All 12 inputs must be numeric.")
  }

  if (any(inputs < 0) || any(inputs > 4)) {
    stop("Error: All item scores must be integers between 0 and 4.")
  }

  total_score <- sum(inputs)

  bulbar_score <- speech + salivation + swallowing
  fine_motor_score <- handwriting + cutting_food + dressing_hygiene
  gross_motor_score <- turning_in_bed + walking + climbing_stairs
  respiratory_score <- dyspnea + orthopnea + respiratory_insufficiency

  return(list(
    ALSFRS_R_Score = total_score,
    Interpretation = "Scores range from 0 (worst function) to 48 (normal function).",
    Subscores = list(
      Bulbar = bulbar_score,
      Fine_Motor = fine_motor_score,
      Gross_Motor = gross_motor_score,
      Respiratory = respiratory_score
    ),
