revised_cardiac_risk_index <- function(high_risk_surgery, ischemic_heart_disease, congestive_heart_failure, cerebrovascular_disease, insulin_treatment, preop_creatinine_gt_2) {

  high_risk_surgery <- as.numeric(high_risk_surgery)
  ischemic_heart_disease <- as.numeric(ischemic_heart_disease)
  congestive_heart_failure <- as.numeric(congestive_heart_failure)
  cerebrovascular_disease <- as.numeric(cerebrovascular_disease)
  insulin_treatment <- as.numeric(insulin_treatment)
  preop_creatinine_gt_2 <- as.numeric(preop_creatinine_gt_2)

  if (any(is.na(c(high_risk_surgery, ischemic_heart_disease, congestive_heart_failure, cerebrovascular_disease, insulin_treatment, preop_creatinine_gt_2)))) {
    stop("Error: All inputs must be numeric (0 or 1).")
  }

  score <- 0

  if (high_risk_surgery == 1) score <- score + 1
  if (ischemic_heart_disease == 1) score <- score + 1
  if (congestive_heart_failure == 1) score <- score + 1
  if (cerebrovascular_disease == 1) score <- score + 1
  if (insulin_treatment == 1) score <- score + 1
  if (preop_creatinine_gt_2 == 1) score <- score + 1

  risk_class <- ""
  cardiac_event_risk <- ""

  if (score == 0) {
    risk_class <- "Class I"
    cardiac_event_risk <- "0.4% (Low Risk)"
  } else if (score == 1) {
    risk_class <- "Class II"
    cardiac_event_risk <- "0.9% (Low Risk)"
  } else if (score == 2) {
    risk_class <- "Class III"
    cardiac_event_risk <- "6.6% (Moderate Risk)"
  } else {
    risk_class <- "Class IV"
    cardiac_event_risk <- ">= 11% (High Risk)"
  }

  return(list(
    RCRI_Score = score,
    Risk_Class = risk_class,
    Est_Major_Cardiac_Event_Risk = cardiac_event_risk,
    Inputs = list(
      High_Risk_Surgery = high_risk_surgery == 1,
      Ischemic_Heart_Disease = ischemic_heart_disease == 1,
      CHF = congestive_heart_failure == 1,
      Cerebrovascular_Disease = cerebrovascular_disease == 1,
      Insulin_Use = insulin_treatment == 1,
      Creatinine_gt_2 = preop_creatinine_gt_2 == 1
    )
  ))
}

ipss_r_mds_score <- function(hemoglobin_g_dl, anc_x10_9_l, platelet_count_x10_9_l, bone_marrow_blasts_percent, cytogenetics_risk_group) {

  hemoglobin_g_dl <- as.numeric(hemoglobin_g_dl)
  anc_x10_9_l <- as.numeric(anc_x10_9_l)
  platelet_count_x10_9_l <- as.numeric(platelet_count_x10_9_l)
  bone_marrow_blasts_percent <- as.numeric(bone_marrow_blasts_percent)
  cytogenetics_risk_group <- tolower(as.character(cytogenetics_risk_group))

  if (any(is.na(c(hemoglobin_g_dl, anc_x10_9_l, platelet_count_x10_9_l, bone_marrow_blasts_percent)))) {
    stop("Error: All laboratory inputs must be numeric.")
  }

  if (!cytogenetics_risk_group %in% c("very_good", "good", "intermediate", "poor", "very_poor")) {
    stop("Error: Cytogenetics risk group must be 'very_good', 'good', 'intermediate', 'poor', or 'very_poor'.")
  }

  score <- 0

  if (cytogenetics_risk_group == "very_good") {
    score <- score + 0
  } else if (cytogenetics_risk_group == "good") {
    score <- score + 1
  } else if (cytogenetics_risk_group == "intermediate") {
    score <- score + 2
  } else if (cytogenetics_risk_group == "poor") {
    score <- score + 3
  } else {
    score <- score + 4
  }

  if (bone_marrow_blasts_percent <= 2) {
    score <- score + 0
  } else if (bone_marrow_blasts_percent > 2 && bone_marrow_blasts_percent < 5) {
    score <- score + 1
  } else if (bone_marrow_blasts_percent >= 5 && bone_marrow_blasts_percent <= 10) {
    score <- score + 2
  } else if (bone_marrow_blasts_percent > 10) {
    score <- score + 3
  }

  if (hemoglobin_g_dl >= 10) {
    score <- score + 0
  } else if (hemoglobin_g_dl >= 8 && hemoglobin_g_dl < 10) {
    score <- score + 1
  } else {
    score <- score + 1.5
  }

  if (platelet_count_x10_9_l >= 100) {
    score <- score + 0
  } else if (platelet_count_x10_9_l >= 50 && platelet_count_x10_9_l < 100) {
    score <- score + 0.5
  } else {
    score <- score + 1
  }

  if (anc_x10_9_l >= 0.8) {
    score <- score + 0
  } else {
    score <- score + 0.5
  }

  risk_category <- ""
  median_survival <- ""
  aml_progression_risk_25 <- ""

  if (score <= 1.5) {
    risk_category <- "Very Low Risk"
    median_survival <- "8.8 years"
    aml_progression_risk_25 <- "NR (Not Reached)"
  } else if (score > 1.5 && score <= 3.0) {
    risk_category <- "Low Risk"
    median_survival <- "5.3 years"
    aml_progression_risk_25 <- "10.8 years"
  } else if (score > 3.0 && score <= 4.5) {
    risk_category <- "Intermediate Risk"
    median_survival <- "3.0 years"
    aml_progression_risk_25 <- "3.2 years"
  } else if (score > 4.5 && score <= 6.0) {
    risk_category <- "High Risk"
    median_survival <- "1.6 years"
    aml_progression_risk_25 <- "1.4 years"
  } else {
    risk_category <- "Very High Risk"
    median_survival <- "0.8 years"
    aml_progression_risk_25 <- "0.7 years"
  }

  return(list(
    IPSS_R_Score = score,
    Risk_Category = risk_category,
    Median_Overall_Survival = median_survival,
    Time_to_25_Percent_AML_Evolution = aml_progression_risk_25,
    Inputs = list(
      Hemoglobin = hemoglobin_g_dl,
      ANC = anc_x10_9_l,
      Platelets = platelet_count_x10_9_l,
      BM_Blasts = bone_marrow_blasts_percent,
      Cytogenetics = cytogenetics_risk_group
    )
  ))
}

rome_iv_child_nausea_vomiting <- function(bothersome_nausea_frequency, bothersome_vomiting_frequency, self_induced_vomiting, eating_disorder, medical_condition_explained) {

  bothersome_nausea_frequency <- as.numeric(bothersome_nausea_frequency)
  bothersome_vomiting_frequency <- as.numeric(bothersome_vomiting_frequency)
  self_induced_vomiting <- as.numeric(self_induced_vomiting)
  eating_disorder <- as.numeric(eating_disorder)
  medical_condition_explained <- as.numeric(medical_condition_explained)

  if (any(is.na(c(bothersome_nausea_frequency, bothersome_vomiting_frequency, self_induced_vomiting, eating_disorder, medical_condition_explained)))) {
    stop("Error: All inputs must be numeric (0 or 1, or frequency code).")
  }

  symptom_met <- FALSE

  if (bothersome_nausea_frequency >= 2) {
    symptom_met <- TRUE
  }

  if (bothersome_vomiting_frequency >= 2) {
    symptom_met <- TRUE
  }

  exclusions_met <- TRUE
  if (self_induced_vomiting == 1) exclusions_met <- FALSE
  if (eating_disorder == 1) exclusions_met <- FALSE
  if (medical_condition_explained == 1) exclusions_met <- FALSE

  diagnosis <- ""
  if (symptom_met && exclusions_met) {
    diagnosis <- "Criteria Met for Functional Nausea/Vomiting"
  } else {
    diagnosis <- "Criteria Not Met"
  }

  return(list(
    Diagnosis = diagnosis,
    Criteria_Check = list(
      Symptom_Frequency_Met = symptom_met,
      Exclusions_Cleared = exclusions_met
    ),
    Inputs = list(
      Nausea_Freq = bothersome_nausea_frequency,
      Vomiting_Freq = bothersome_vomiting_frequency,
      Self_Induced = self_induced_vomiting == 1,
      Eating_Disorder = eating_disorder == 1,
      Explained_By_Other = medical_condition_explained == 1
    )
  ))
}

rome_iv_child_ibs <- function(pain_frequency_days_month, related_to_defecation, change_stool_frequency, change_stool_form, pain_resolves_with_constipation_resolution, medical_condition_explained) {

