  if (medical_condition_explained == 1) {
    criteria_met <- FALSE
  }

  diagnosis <- ""
  if (criteria_met) {
    diagnosis <- "Criteria Met for Irritable Bowel Syndrome (IBS)"
  } else {
    diagnosis <- "Criteria Not Met"
  }

  return(list(
    Diagnosis = diagnosis,
    Inputs = list(
      Pain_Freq_Days = pain_frequency_days_month,
      Defecation_Related = related_to_defecation == 1,
      Change_Freq = change_stool_frequency == 1,
      Change_Form = change_stool_form == 1,
      Pain_Resolves_Constipation = pain_resolves_with_constipation_resolution == 1,
      Explained_By_Other = medical_condition_explained == 1
