rome_iv_cnvs <- function(nausea_at_least_1_day_per_week, vomiting_at_least_1_day_per_week, self_induced_vomiting_present, eating_disorder_present, regurgitation_present, rumination_present, organic_systemic_metabolic_disease_excluded, symptom_onset_ge_6_months_ago, symptoms_active_last_3_months) {

  nausea_at_least_1_day_per_week <- as.numeric(nausea_at_least_1_day_per_week)
  vomiting_at_least_1_day_per_week <- as.numeric(vomiting_at_least_1_day_per_week)
  self_induced_vomiting_present <- as.numeric(self_induced_vomiting_present)
  eating_disorder_present <- as.numeric(eating_disorder_present)
  regurgitation_present <- as.numeric(regurgitation_present)
  rumination_present <- as.numeric(rumination_present)
  organic_systemic_metabolic_disease_excluded <- as.numeric(organic_systemic_metabolic_disease_excluded)
  symptom_onset_ge_6_months_ago <- as.numeric(symptom_onset_ge_6_months_ago)
  symptoms_active_last_3_months <- as.numeric(symptoms_active_last_3_months)

  if (any(is.na(c(nausea_at_least_1_day_per_week, vomiting_at_least_1_day_per_week, self_induced_vomiting_present, eating_disorder_present, regurgitation_present, rumination_present, organic_systemic_metabolic_disease_excluded, symptom_onset_ge_6_months_ago, symptoms_active_last_3_months)))) {
    stop("Error: All inputs must be numeric (0 or 1).")
  }

  criteria_met <- FALSE

  core_symptoms_met <- (nausea_at_least_1_day_per_week == 1 || vomiting_at_least_1_day_per_week == 1)

  exclusions_met <- (self_induced_vomiting_present == 0 && eating_disorder_present == 0 && regurgitation_present == 0 && rumination_present == 0)

  disease_excluded <- (organic_systemic_metabolic_disease_excluded == 1)

  duration_met <- (symptom_onset_ge_6_months_ago == 1 && symptoms_active_last_3_months == 1)

  if (core_symptoms_met && exclusions_met && disease_excluded && duration_met) {
    criteria_met <- TRUE
  }

  diagnosis <- ""
  if (criteria_met) {
    diagnosis <- "Criteria Met for Chronic Nausea Vomiting Syndrome (CNVS)"
  } else {
    diagnosis <- "Criteria Not Met"
  }

  return(list(
    Diagnosis = diagnosis,
    Inputs = list(
      Core_Symptoms_Frequency_Met = core_symptoms_met,
      Exclusions_Cleared = exclusions_met,
      Organic_Disease_Excluded = disease_excluded,
      Duration_Criteria_Met = duration_met
    )
  ))
}

