rome_iv_functional_biliary_sod <- function(episode_pain, other_pain_excluded, normal_liver_enzymes, normal_pancreatic_enzymes, normal_imaging, not_explained_by_other_condition, manometry_normal_or_high) {

  episode_pain <- as.numeric(episode_pain)
  other_pain_excluded <- as.numeric(other_pain_excluded)
  normal_liver_enzymes <- as.numeric(normal_liver_enzymes)
  normal_pancreatic_enzymes <- as.numeric(normal_pancreatic_enzymes)
  normal_imaging <- as.numeric(normal_imaging)
  not_explained_by_other_condition <- as.numeric(not_explained_by_other_condition)
  manometry_normal_or_high <- as.numeric(manometry_normal_or_high)

  if (any(is.na(c(episode_pain, other_pain_excluded, normal_liver_enzymes, normal_pancreatic_enzymes, normal_imaging, not_explained_by_other_condition, manometry_normal_or_high)))) {
    stop("Error: All inputs must be numeric (0 or 1).")
  }

  general_criteria_met <- (episode_pain == 1 && other_pain_excluded == 1 && normal_liver_enzymes == 1 && normal_pancreatic_enzymes == 1 && normal_imaging == 1 && not_explained_by_other_condition == 1)

  diagnosis <- ""

  if (general_criteria_met) {
    if (manometry_normal_or_high == 1) {
      diagnosis <- "Functional Biliary Sphincter of Oddi Disorder (SOD) - Type I or II"
    } else {
      diagnosis <- "Functional Biliary Sphincter of Oddi Disorder (SOD) - Type III"
