      Normal_Liver_Enzymes = normal_liver_enzymes == 1,
      Normal_Pancreatic_Enzymes = normal_pancreatic_enzymes == 1,
      Normal_Imaging = normal_imaging == 1,
      Not_Other_Condition = not_explained_by_other_condition == 1,
      Manometry_Positive = manometry_normal_or_high == 1
    )
  ))
}

