rome_iv_functional_constipation <- function(stool_frequency_lt_2_week, straining_ge_25_percent, lumpy_hard_stool_ge_25_percent, sensation_incomplete_evacuation_ge_25_percent, sensation_anorectal_blockage_ge_25_percent, manual_maneuver_ge_25_percent, loose_stool_absent, sufficient_criteria_met) {

  stool_frequency_lt_2_week <- as.numeric(stool_frequency_lt_2_week)
  straining_ge_25_percent <- as.numeric(straining_ge_25_percent)
  lumpy_hard_stool_ge_25_percent <- as.numeric(lumpy_hard_stool_ge_25_percent)
  sensation_incomplete_evacuation_ge_25_percent <- as.numeric(sensation_incomplete_evacuation_ge_25_percent)
  sensation_anorectal_blockage_ge_25_percent <- as.numeric(sensation_anorectal_blockage_ge_25_percent)
  manual_maneuver_ge_25_percent <- as.numeric(manual_maneuver_ge_25_percent)
  loose_stool_absent <- as.numeric(loose_stool_absent)
  sufficient_criteria_met <- as.numeric(sufficient_criteria_met)

  if (any(is.na(c(stool_frequency_lt_2_week, straining_ge_25_percent, lumpy_hard_stool_ge_25_percent, sensation_incomplete_evacuation_ge_25_percent, sensation_anorectal_blockage_ge_25_percent, manual_maneuver_ge_25_percent, loose_stool_absent, sufficient_criteria_met)))) {
    stop("Error: All inputs must be numeric (0 or 1).")
  }

  criteria_count <- sum(stool_frequency_lt_2_week, straining_ge_25_percent, lumpy_hard_stool_ge_25_percent, sensation_incomplete_evacuation_ge_25_percent, sensation_anorectal_blockage_ge_25_percent, manual_maneuver_ge_25_percent)

  core_criteria_met <- (sufficient_criteria_met == 1)

  if (loose_stool_absent == 0) {
    core_criteria_met <- FALSE
  }

  diagnosis <- ""
  if (core_criteria_met) {
    diagnosis <- "Criteria Met for Functional Constipation"
  } else {
    diagnosis <- "Criteria Not Met"
  }

  return(list(
    Diagnosis = diagnosis,
    Criteria_Count = criteria_count,
    Inputs = list(
      Q1_lt_2_stools_week = stool_frequency_lt_2_week == 1,
      Q2_Straining_ge_25pct = straining_ge_25_percent == 1,
      Q3_Hard_Stools_ge_25pct = lumpy_hard_stool_ge_25_percent == 1,
      Q4_Incomplete_ge_25pct = sensation_incomplete_evacuation_ge_25_percent == 1,
      Q5_Anorectal_Blockage_ge_25pct = sensation_anorectal_blockage_ge_25_percent == 1,
      Q6_Manual_Maneuver_ge_25pct = manual_maneuver_ge_25_percent == 1,
      Q7_Loose_Stool_Absent = loose_stool_absent == 1
    )
  ))
}

rome_iv_functional_defecation_disorders <- function(straining_ge_25_percent, sensation_incomplete_evacuation_ge_25_percent, sensation_anorectal_blockage_ge_25_percent, manual_maneuver_ge_25_percent, inadequate_defecatory_propulsion, dyssynergic_defecation, other_conditions_excluded) {

  straining_ge_25_percent <- as.numeric(straining_ge_25_percent)
  sensation_incomplete_evacuation_ge_25_percent <- as.numeric(sensation_incomplete_evacuation_ge_25_percent)
  sensation_anorectal_blockage_ge_25_percent <- as.numeric(sensation_anorectal_blockage_ge_25_percent)
  manual_maneuver_ge_25_percent <- as.numeric(manual_maneuver_ge_25_percent)
  inadequate_defecatory_propulsion <- as.numeric(inadequate_defecatory_propulsion)
  dyssynergic_defecation <- as.numeric(dyssynergic_defecation)
  other_conditions_excluded <- as.numeric(other_conditions_excluded)

  if (any(is.na(c(straining_ge_25_percent, sensation_incomplete_evacuation_ge_25_percent, sensation_anorectal_blockage_ge_25_percent, manual_maneuver_ge_25_percent, inadequate_defecatory_propulsion, dyssynergic_defecation, other_conditions_excluded)))) {
    stop("Error: All inputs must be numeric (0 or 1).")
  }

  criteria_met <- TRUE

  if (other_conditions_excluded == 0) {
    criteria_met <- FALSE
  }

  if (inadequate_defecatory_propulsion == 0 && dyssynergic_defecation == 0) {
    criteria_met <- FALSE
  }

  symptoms_count <- straining_ge_25_percent + sensation_incomplete_evacuation_ge_25_percent + sensation_anorectal_blockage_ge_25_percent + manual_maneuver_ge_25_percent

  if (symptoms_count < 2) {
    criteria_met <- FALSE
  }

  diagnosis <- ""
  if (criteria_met) {
    if (inadequate_defecatory_propulsion == 1 && dyssynergic_defecation == 0) {
      diagnosis <- "Inadequate Defecatory Propulsion"
    } else if (dyssynergic_defecation == 1) {
      diagnosis <- "Dyssynergic Defecation"
    } else {
      diagnosis <- "Functional Defecation Disorder"
    }
  } else {
    diagnosis <- "Criteria Not Met"
  }

  return(list(
    Diagnosis = diagnosis,
    Inputs = list(
      Q1_Straining = straining_ge_25_percent == 1,
      Q2_Incomplete = sensation_incomplete_evacuation_ge_25_percent == 1,
      Q3_Blockage = sensation_anorectal_blockage_ge_25_percent == 1,
      Q4_Manual_Maneuver = manual_maneuver_ge_25_percent == 1,
      Manometry_Propulsion = inadequate_defecatory_propulsion == 1,
      Manometry_Dyssynergia = dyssynergic_defecation == 1,
      Other_Excluded = other_conditions_excluded == 1
    )
  ))
}

