rome_iv_functional_dyspepsia <- function(postprandial_fullness, early_satiation, epigastric_pain, epigastric_burning, organic_disease_excluded, symptom_onset_ge_6_months, symptoms_active_last_3_months) {

  postprandial_fullness <- as.numeric(postprandial_fullness)
  early_satiation <- as.numeric(early_satiation)
  epigastric_pain <- as.numeric(epigastric_pain)
  epigastric_burning <- as.numeric(epigastric_burning)
  organic_disease_excluded <- as.numeric(organic_disease_excluded)
  symptom_onset_ge_6_months <- as.numeric(symptom_onset_ge_6_months)
  symptoms_active_last_3_months <- as.numeric(symptoms_active_last_3_months)

  if (any(is.na(c(postprandial_fullness, early_satiation, epigastric_pain, epigastric_burning, organic_disease_excluded, symptom_onset_ge_6_months, symptoms_active_last_3_months)))) {
    stop("Error: All inputs must be numeric (0 or 1).")
  }

  pds_criteria_met <- (postprandial_fullness == 1 || early_satiation == 1)
  eps_criteria_met <- (epigastric_pain == 1 || epigastric_burning == 1)

  duration_met <- (symptom_onset_ge_6_months == 1 && symptoms_active_last_3_months == 1)

  diagnosis <- "Criteria Not Met"

  if (organic_disease_excluded == 1 && duration_met) {
    if (pds_criteria_met && eps_criteria_met) {
      diagnosis <- "Overlap Functional Dyspepsia (PDS + EPS)"
    } else if (pds_criteria_met) {
      diagnosis <- "Postprandial Distress Syndrome (PDS)"
    } else if (eps_criteria_met) {
      diagnosis <- "Epigastric Pain Syndrome (EPS)"
    } else {
      diagnosis <- "Criteria Not Met (Insufficient Symptoms)"
    }
  } else if (organic_disease_excluded == 0) {
    diagnosis <- "Criteria Not Met (Organic disease not excluded)"
  } else {
    diagnosis <- "Criteria Not Met (Duration requirements not met)"
  }

  return(list(
    Diagnosis = diagnosis,
    Inputs = list(
      Postprandial_Fullness = postprandial_fullness == 1,
      Early_Satiation = early_satiation == 1,
      Epigastric_Pain = epigastric_pain == 1,
      Epigastric_Burning = epigastric_burning == 1,
      Organic_Excluded = organic_disease_excluded == 1,
      Chronicity_Met = duration_met
    )
  ))
}

