  crying_duration_hours <- as.numeric(crying_duration_hours)
  fussiness_duration_hours <- as.numeric(fussiness_duration_hours)
  days_per_week_frequency <- as.numeric(days_per_week_frequency)
  symptom_onset_age <- as.numeric(symptom_onset_age)
  symptom_resolution_age <- as.numeric(symptom_resolution_age)
  other_causes_excluded <- as.numeric(other_causes_excluded)

  if (any(is.na(c(crying_duration_hours, fussiness_duration_hours, days_per_week_frequency, symptom_onset_age, symptom_resolution_age, other_causes_excluded)))) {
    stop("Error: All inputs must be numeric.")
  }

  criteria_met <- TRUE

  total_crying_fussing <- crying_duration_hours + fussiness_duration_hours

  if (symptom_onset_age > 5) {
    criteria_met <- FALSE
  }

  if (symptom_resolution_age > 5) {
    criteria_met <- FALSE
  }

  if (total_crying_fussing < 3) {
    criteria_met <- FALSE
  }

  if (days_per_week_frequency < 3) {
    criteria_met <- FALSE
  }

  if (other_causes_excluded == 0) {
    criteria_met <- FALSE
  }

  diagnosis <- ""
  if (criteria_met) {
    diagnosis <- "Criteria Met for Infant Colic"
  } else {
    diagnosis <- "Criteria Not Met"
  }

  return(list(
    Diagnosis = diagnosis,
    Inputs = list(
      Total_Crying_Fussing_Hrs = total_crying_fussing,
      Frequency_Days_Week = days_per_week_frequency,
      Onset_le_5_Months = symptom_onset_age <= 5,
      Resolution_le_5_Months = symptom_resolution_age <= 5,
      No_Other_Cause = other_causes_excluded == 1
    )
  ))
}

