rome_iv_ibs_criteria <- function(pain_frequency_days_month, related_to_defecation, change_stool_frequency, change_stool_form, organic_causes_excluded) {

  pain_frequency_days_month <- as.numeric(pain_frequency_days_month)
  related_to_defecation <- as.numeric(related_to_defecation)
  change_stool_frequency <- as.numeric(change_stool_frequency)
  change_stool_form <- as.numeric(change_stool_form)
  organic_causes_excluded <- as.numeric(organic_causes_excluded)

  if (any(is.na(c(pain_frequency_days_month, related_to_defecation, change_stool_frequency, change_stool_form, organic_causes_excluded)))) {
    stop("Error: All inputs must be numeric.")
  }

  criteria_met <- TRUE

  if (pain_frequency_days_month < 1) {
    criteria_met <- FALSE
  }

  ibs_features_count <- related_to_defecation + change_stool_frequency + change_stool_form

  if (ibs_features_count < 1) {
    criteria_met <- FALSE
  }

  if (organic_causes_excluded == 0) {
    criteria_met <- FALSE
  }

  diagnosis <- ""
  if (criteria_met) {
    if (change_stool_form == 1) {
      if (related_to_defecation == 1) {
        diagnosis <- "Meets Criteria for Irritable Bowel Syndrome (IBS)"
      } else {
        diagnosis <- "Meets Criteria for Irritable Bowel Syndrome (IBS)"
      }
    } else {
      diagnosis <- "Meets Criteria for Irritable Bowel Syndrome (IBS)"
    }
  } else {
    diagnosis <- "Criteria Not Met"
  }

  return(list(
    Diagnosis = diagnosis,
    IBS_Features_Count = ibs_features_count,
    Inputs = list(
      Pain_Freq_Days_Month = pain_frequency_days_month,
      Defecation_Related = related_to_defecation == 1,
      Change_Freq = change_stool_frequency == 1,
      Change_Form = change_stool_form == 1,
      Organic_Excluded = organic_causes_excluded == 1
    )
  ))
}

