rome_iv_opioid_induced_constipation <- function(opioid_use_ge_3mo, symptom_onset_after_opioid, straining_ge_25_percent, lumpy_hard_stool_ge_25_percent, sensation_incomplete_evacuation_ge_25_percent, sensation_anorectal_blockage_ge_25_percent, manual_maneuver_ge_25_percent, lt_3_sbm_per_week, insufficient_criteria_for_ibs) {

  opioid_use_ge_3mo <- as.numeric(opioid_use_ge_3mo)
  symptom_onset_after_opioid <- as.numeric(symptom_onset_after_opioid)
  straining_ge_25_percent <- as.numeric(straining_ge_25_percent)
  lumpy_hard_stool_ge_25_percent <- as.numeric(lumpy_hard_stool_ge_25_percent)
  sensation_incomplete_evacuation_ge_25_percent <- as.numeric(sensation_incomplete_evacuation_ge_25_percent)
  sensation_anorectal_blockage_ge_25_percent <- as.numeric(sensation_anorectal_blockage_ge_25_percent)
  manual_maneuver_ge_25_percent <- as.numeric(manual_maneuver_ge_25_percent)
  lt_3_sbm_per_week <- as.numeric(lt_3_sbm_per_week)
  insufficient_criteria_for_ibs <- as.numeric(insufficient_criteria_for_ibs)

  if (any(is.na(c(opioid_use_ge_3mo, symptom_onset_after_opioid, straining_ge_25_percent, lumpy_hard_stool_ge_25_percent, sensation_incomplete_evacuation_ge_25_percent, sensation_anorectal_blockage_ge_25_percent, manual_maneuver_ge_25_percent, lt_3_sbm_per_week, insufficient_criteria_for_ibs)))) {
    stop("Error: All inputs must be numeric (0 or 1).")
  }

  criteria_count <- sum(straining_ge_25_percent, lumpy_hard_stool_ge_25_percent, sensation_incomplete_evacuation_ge_25_percent, sensation_anorectal_blockage_ge_25_percent, manual_maneuver_ge_25_percent, lt_3_sbm_per_week)

  core_criteria_met <- (criteria_count >= 2)

  oic_specific_met <- (opioid_use_ge_3mo == 1 && symptom_onset_after_opioid == 1)

  diagnosis <- ""
  if (core_criteria_met && oic_specific_met && insufficient_criteria_for_ibs == 1) {
    diagnosis <- "Criteria Met for Opioid-Induced Constipation (OIC)"
  } else {
    diagnosis <- "Criteria Not Met"
  }

  return(list(
    Diagnosis = diagnosis,
    Constipation_Criteria_Count = criteria_count,
    Inputs = list(
      Opioid_Use_ge_3mo = opioid_use_ge_3mo == 1,
      Symptom_Onset_After_Opioid = symptom_onset_after_opioid == 1,
      Insufficient_IBS_Criteria = insufficient_criteria_for_ibs == 1
    )
  ))
}

