rome_iv_biliary_pain_criteria <- function(location, severity, course, other_pain_excluded, normal_imaging, not_explained_by_other_condition, symptom_onset_ge_6_months, symptoms_active_last_3_months) {

  location <- tolower(as.character(location))
  severity <- as.numeric(severity)
  course <- tolower(as.character(course))
  other_pain_excluded <- as.numeric(other_pain_excluded)
  normal_imaging <- as.numeric(normal_imaging)
  not_explained_by_other_condition <- as.numeric(not_explained_by_other_condition)
  symptom_onset_ge_6_months <- as.numeric(symptom_onset_ge_6_months)
  symptoms_active_last_3_months <- as.numeric(symptoms_active_last_3_months)

  if (any(is.na(c(severity, other_pain_excluded, normal_imaging, not_explained_by_other_condition, symptom_onset_ge_6_months, symptoms_active_last_3_months)))) {
    stop("Error: All inputs must be numeric.")
  }

  if (!location %in% c("epigastrium", "ruq", "both")) {
    stop("Error: Pain location must be 'epigastrium', 'ruq', or 'both'.")
  }

  if (!course %in% c("bouts", "steady")) {
    stop("Error: Pain course must be 'bouts' (rapidly builds up/subsides) or 'steady' (pain plateau).")
  }

  criteria_met <- TRUE

  pain_characteristics_count <- 0
  if (location %in% c("epigastrium", "ruq", "both")) pain_characteristics_count <- pain_characteristics_count + 1
  if (severity == 1) pain_characteristics_count <- pain_characteristics_count + 1
  if (course == "bouts" || course == "steady") pain_characteristics_count <- pain_characteristics_count + 1

  if (pain_characteristics_count < 3) criteria_met <- FALSE

  if (other_pain_excluded == 0) criteria_met <- FALSE

  if (normal_imaging == 0) criteria_met <- FALSE

  if (not_explained_by_other_condition == 0) criteria_met <- FALSE

  if (symptom_onset_ge_6_months == 0) criteria_met <- FALSE

  if (symptoms_active_last_3_months == 0) criteria_met <- FALSE

  diagnosis <- ""
  if (criteria_met) {
    diagnosis <- "Criteria Met for Functional Biliary Pain"
  } else {
    diagnosis <- "Criteria Not Met"
  }

  return(list(
    Diagnosis = diagnosis,
    Inputs = list(
      Location = location,
      Severity = severity,
      Course = course,
      Other_Pain_Excluded = other_pain_excluded == 1,
      Normal_Imaging = normal_imaging == 1,
      Not_Other_Condition = not_explained_by_other_condition == 1,
      Chronicity_Met = (symptom_onset_ge_6_months == 1 && symptoms_active_last_3_months == 1)
    )
  ))
}

