rome_iv_child_abdominal_migraine <- function(paroxysmal_pain_duration, median_episodes_ge_2_per_year, pain_periumbilical_midline_poorly_localized, pain_severity_moderate_severe, pain_fully_resolves_hours_days, associated_symptoms_count, not_explained_by_other_condition, symptom_onset_ge_6_months, symptoms_active_last_3_months) {

  paroxysmal_pain_duration <- as.numeric(paroxysmal_pain_duration)
  median_episodes_ge_2_per_year <- as.numeric(median_episodes_ge_2_per_year)
  pain_periumbilical_midline_poorly_localized <- as.numeric(pain_periumbilical_midline_poorly_localized)
  pain_severity_moderate_severe <- as.numeric(pain_severity_moderate_severe)
  pain_fully_resolves_hours_days <- as.numeric(pain_fully_resolves_hours_days)
  associated_symptoms_count <- as.numeric(associated_symptoms_count)
  not_explained_by_other_condition <- as.numeric(not_explained_by_other_condition)
  symptom_onset_ge_6_months <- as.numeric(symptom_onset_ge_6_months)
  symptoms_active_last_3_months <- as.numeric(symptoms_active_last_3_months)

  if (any(is.na(c(paroxysmal_pain_duration, median_episodes_ge_2_per_year, pain_periumbilical_midline_poorly_localized, pain_severity_moderate_severe, pain_fully_resolves_hours_days, associated_symptoms_count, not_explained_by_other_condition, symptom_onset_ge_6_months, symptoms_active_last_3_months)))) {
    stop("Error: All inputs must be numeric.")
  }

  core_pain_met <- (paroxysmal_pain_duration >= 2 && paroxysmal_pain_duration <= 72 && median_episodes_ge_2_per_year == 1)

  pain_characteristics_met <- (pain_periumbilical_midline_poorly_localized == 1 && pain_severity_moderate_severe == 1 && pain_fully_resolves_hours_days == 1)

  chronicity_met <- (symptom_onset_ge_6_months == 1 && symptoms_active_last_3_months == 1)

  criteria_met <- FALSE
  if (core_pain_met && pain_characteristics_met && associated_symptoms_count >= 2 && not_explained_by_other_condition == 1 && chronicity_met) {
    criteria_met <- TRUE
  }

  diagnosis <- ""
  if (criteria_met) {
    diagnosis <- "Criteria Met for Abdominal Migraine"
  } else {
    diagnosis <- "Criteria Not Met"
  }

  return(list(
    Diagnosis = diagnosis,
    Inputs = list(
      Pain_Characteristics_Met = pain_characteristics_met,
      Episode_Frequency_Met = median_episodes_ge_2_per_year == 1,
      Associated_Symptoms_Count = associated_symptoms_count,
      Chronicity_Met = chronicity_met
    )
  ))
}

