rome_iv_belching_disorders <- function(symptoms_ge_3_day_week, aerophagia_excluded, supragastric_belch_type, gastric_belch_type, symptom_onset_ge_6_months, symptoms_active_last_3_months) {

  symptoms_ge_3_day_week <- as.numeric(symptoms_ge_3_day_week)
  aerophagia_excluded <- as.numeric(aerophagia_excluded)
  supragastric_belch_type <- as.numeric(supragastric_belch_type)
  gastric_belch_type <- as.numeric(gastric_belch_type)
  symptom_onset_ge_6_months <- as.numeric(symptom_onset_ge_6_months)
  symptoms_active_last_3_months <- as.numeric(symptoms_active_last_3_months)

  if (any(is.na(c(symptoms_ge_3_day_week, aerophagia_excluded, supragastric_belch_type, gastric_belch_type, symptom_onset_ge_6_months, symptoms_active_last_3_months)))) {
    stop("Error: All inputs must be numeric.")
  }

  if (supragastric_belch_type == 1 && gastric_belch_type == 1) {
    stop("Error: Belch types are typically mutually exclusive for primary diagnosis; choose the predominant one.")
  }

  criteria_met <- TRUE

  if (symptoms_ge_3_day_week == 0) {
    criteria_met <- FALSE
  }

  if (aerophagia_excluded == 0) {
    criteria_met <- FALSE
  }

  if (supragastric_belch_type == 0 && gastric_belch_type == 0) {
    criteria_met <- FALSE
  }

  if (symptom_onset_ge_6_months == 0) {
    criteria_met <- FALSE
  }

  if (symptoms_active_last_3_months == 0) {
    criteria_met <- FALSE
  }

  diagnosis <- ""

  if (criteria_met) {
    if (supragastric_belch_type == 1) {
      diagnosis <- "Supragastric Belching"
    } else {
      diagnosis <- "Gastric Belching"
    }
  } else {
    diagnosis <- "Criteria Not Met"
  }

  return(list(
    Diagnosis = diagnosis,
    Inputs = list(
      Frequency_ge_3_day_wk = symptoms_ge_3_day_week == 1,
      Aerophagia_Excluded = aerophagia_excluded == 1,
      Supragastric_Present = supragastric_belch_type == 1,
      Gastric_Present = gastric_belch_type == 1,
      Chronicity_Met = (symptom_onset_ge_6_months == 1 && symptoms_active_last_3_months == 1)
    )
  ))
}

rome_iii_ibs_criteria <- function(pain_discomfort_frequency, pain_relief_by_defecation, pain_onset_associated_with_frequency_change, pain_onset_associated_with_consistency_change, symptoms_onset_ge_6_months_ago, symptoms_active_last_3_months, no_structural_disease_excluded) {

  pain_discomfort_frequency <- as.numeric(pain_discomfort_frequency)
  pain_relief_by_defecation <- as.numeric(pain_relief_by_defecation)
  pain_onset_associated_with_frequency_change <- as.numeric(pain_onset_associated_with_frequency_change)
  pain_onset_associated_with_consistency_change <- as.numeric(pain_onset_associated_with_consistency_change)
  symptoms_onset_ge_6_months_ago <- as.numeric(symptoms_onset_ge_6_months_ago)
  symptoms_active_last_3_months <- as.numeric(symptoms_active_last_3_months)
  no_structural_disease_excluded <- as.numeric(no_structural_disease_excluded)

  if (any(is.na(c(pain_discomfort_frequency, pain_relief_by_defecation, pain_onset_associated_with_frequency_change, pain_onset_associated_with_consistency_change, no_structural_disease_excluded, symptoms_onset_ge_6_months_ago, symptoms_active_last_3_months)))) {
    stop("Error: All inputs must be numeric.")
  }

  core_pain_met <- (pain_discomfort_frequency >= 3)

  features_met_count <- pain_relief_by_defecation + pain_onset_associated_with_frequency_change + pain_onset_associated_with_consistency_change

  duration_met <- (symptoms_onset_ge_6_months_ago == 1 && symptoms_active_last_3_months == 1)

  ibs_criteria_met <- FALSE
  if (core_pain_met && features_met_count >= 2 && duration_met && no_structural_disease_excluded == 1) {
    ibs_criteria_met <- TRUE
  }

  diagnosis <- ""
  if (ibs_criteria_met) {
    diagnosis <- "Criteria Met for Irritable Bowel Syndrome (IBS)"
  } else {
    diagnosis <- "Criteria Not Met"
  }

  return(list(
    Diagnosis = diagnosis,
    IBS_Features_Count = features_met_count,
    Inputs = list(
      Pain_Freq_ge_3_day_mo = pain_discomfort_frequency,
      Pain_Relief = pain_relief_by_defecation == 1,
      Change_Frequency = pain_onset_associated_with_frequency_change == 1,
      Change_Consistency = pain_onset_associated_with_consistency_change == 1,
      Chronicity_Met = duration_met
    )
  ))
}

