rose_syncope_score <- function(bnp_level, heart_rate, positive_fecal_occult_blood, hemoglobin, chest_pain, ecg_q_waves, oxygen_saturation) {

  bnp_level <- as.numeric(bnp_level)
  heart_rate <- as.numeric(heart_rate)
  positive_fecal_occult_blood <- as.numeric(positive_fecal_occult_blood)
  hemoglobin <- as.numeric(hemoglobin)
  chest_pain <- as.numeric(chest_pain)
  ecg_q_waves <- as.numeric(ecg_q_waves)
  oxygen_saturation <- as.numeric(oxygen_saturation)

  if (any(is.na(c(bnp_level, heart_rate, positive_fecal_occult_blood, hemoglobin, chest_pain, ecg_q_waves, oxygen_saturation)))) {
    stop("Error: All inputs must be numeric.")
  }

  risk_factors <- c()

  if (bnp_level >= 300) {
    risk_factors <- c(risk_factors, "BNP >= 300 pg/mL")
  }

  if (heart_rate <= 50) {
    risk_factors <- c(risk_factors, "Bradycardia (<= 50 bpm)")
  }

  if (positive_fecal_occult_blood == 1) {
    risk_factors <- c(risk_factors, "Positive Fecal Occult Blood")
  }

  if (hemoglobin <= 9.0) {
    risk_factors <- c(risk_factors, "Anemia (Hb <= 9.0 g/dL)")
  }

  if (chest_pain == 1) {
    risk_factors <- c(risk_factors, "Chest Pain with Syncope")
  }

  if (ecg_q_waves == 1) {
    risk_factors <- c(risk_factors, "ECG Q Waves (Pathological)")
  }

  if (oxygen_saturation <= 94) {
    risk_factors <- c(risk_factors, "Oxygen Saturation <= 94%")
  }

  risk_category <- ""
  recommendation <- ""

  if (length(risk_factors) == 0) {
    risk_category <- "Low Risk"
    recommendation <- "Patient likely safe for discharge (Negative Predictive Value approx. 98.5% for serious outcomes)."
  } else {
    risk_category <- "High Risk"
    recommendation <- "Admission advised for further evaluation and monitoring."
  }

  return(list(
    Risk_Category = risk_category,
    Recommendation = recommendation,
    Risk_Factors_Present = if (length(risk_factors) > 0) risk_factors else "None",
    Inputs = list(
      BNP = bnp_level,
      HR = heart_rate,
      FOBT = positive_fecal_occult_blood == 1,
      Hb = hemoglobin,
      Chest_Pain = chest_pain == 1,
      Q_Waves = ecg_q_waves == 1,
      SpO2 = oxygen_saturation
    )
  ))
}

roth_hypoxia_score <- function(max_count_reached, duration_seconds) {

  max_count_reached <- as.numeric(max_count_reached)
  duration_seconds <- as.numeric(duration_seconds)

  if (any(is.na(c(max_count_reached, duration_seconds)))) {
    stop("Error: Inputs must be numeric.")
  }

  interpretation <- ""
  spo2_prediction <- ""

  if (max_count_reached < 7) {
    interpretation <- "High Risk of Hypoxia"
    spo2_prediction <- "Sensitivity 91% for SpO2 < 95%"
  } else if (max_count_reached < 10) {
    interpretation <- "Intermediate Risk of Hypoxia"
    spo2_prediction <- "Sensitivity 82-84% for SpO2 < 95%"
  } else {
    interpretation <- "Low Risk of Hypoxia"
    spo2_prediction <- "SpO2 likely >= 95%"
  }

  return(list(
    Max_Count = max_count_reached,
    Counting_Time = duration_seconds,
    Risk_Category = interpretation,
    Diagnostic_Performance = spo2_prediction
  ))
}

rhmp_30_score <- function(age, sex, asa_score, housing_status) {

  age <- as.numeric(age)
  sex <- tolower(as.character(sex))
  asa_score <- as.numeric(asa_score)
  housing_status <- tolower(as.character(housing_status))

  if (any(is.na(c(age, asa_score)))) {
    stop("Error: Age and ASA Score must be numeric.")
  }

  if (!sex %in% c("male", "female")) {
    stop("Error: Sex must be 'male' or 'female'.")
  }

  if (!housing_status %in% c("independent", "institution")) {
    stop("Error: Housing status must be 'independent' or 'institution'.")
  }

  if (asa_score < 1 || asa_score > 5) {
    stop("Error: ASA Score must be between 1 and 5.")
  }

  score <- 0

  if (age >= 60 && age <= 69) {
    score <- score + 1
  } else if (age >= 70 && age <= 79) {
    score <- score + 2
  } else if (age >= 80 && age <= 89) {
    score <- score + 4
  } else if (age >= 90) {
    score <- score + 6
  }

  if (sex == "male") {
    score <- score + 2
  }

  if (asa_score == 3) {
    score <- score + 2
  } else if (asa_score == 4) {
    score <- score + 4
  } else if (asa_score == 5) {
    score <- score + 6
  }

  if (housing_status == "institution") {
    score <- score + 2
  }

  mortality_30d <- ""

  if (score <= 3) {
    mortality_30d <- "Low Risk (~0-1%)"
  } else if (score >= 4 && score <= 7) {
    mortality_30d <- "Intermediate Risk (~3-6%)"
  } else if (score >= 8 && score <= 10) {
    mortality_30d <- "High Risk (~10-18%)"
  } else {
    mortality_30d <- "Very High Risk (>25%)"
  }

  return(list(
    RHMP_30_Score = score,
    Est_30_Day_Mortality = mortality_30d,
    Inputs = list(
      Age = age,
      Sex = sex,
      ASA = asa_score,
      Housing = housing_status
    )
  ))
}

rox_index_score <- function(spo2_percent, fio2_percent, respiratory_rate) {

  spo2_percent <- as.numeric(spo2_percent)
  fio2_percent <- as.numeric(fio2_percent)
  respiratory_rate <- as.numeric(respiratory_rate)

  if (any(is.na(c(spo2_percent, fio2_percent, respiratory_rate)))) {
    stop("Error: All inputs must be numeric.")
  }

  if (respiratory_rate <= 0) {
    stop("Error: Respiratory rate must be greater than 0.")
  }

  if (fio2_percent > 1) {
    fio2_fraction <- fio2_percent / 100
  } else {
    fio2_fraction <- fio2_percent
  }

  sf_ratio <- spo2_percent / fio2_fraction

  rox_index <- sf_ratio / respiratory_rate

  risk_level <- ""
  if (rox_index < 2.85) {
    risk_level <- "High Risk of Failure (Intubation Likely)"
  } else if (rox_index < 3.85) {
    risk_level <- "Intermediate Risk (Close Monitoring Required)"
  } else if (rox_index < 4.88) {
    risk_level <- "Low-Intermediate Risk"
  } else {
    risk_level <- "Low Risk of Failure (Likely Successful HFNC)"
  }

  return(list(
    ROX_Index = round(rox_index, 2),
    Interpretation = risk_level,
    Inputs = list(
      SpO2 = spo2_percent,
      FiO2 = fio2_fraction,
      RR = respiratory_rate
    )
  ))
}

rule_of_7s_lyme <- function(headache_duration_days, csf_mononuclear_percent, seventh_nerve_palsy) {

  headache_duration_days <- as.numeric(headache_duration_days)
  csf_mononuclear_percent <- as.numeric(csf_mononuclear_percent)
  seventh_nerve_palsy <- as.numeric(seventh_nerve_palsy)

  if (any(is.na(c(headache_duration_days, csf_mononuclear_percent, seventh_nerve_palsy)))) {
    stop("Error: All inputs must be numeric.")
  }

  low_risk <- TRUE
  reasons_for_exclusion <- c()

  if (headache_duration_days >= 7) {
    low_risk <- FALSE
    reasons_for_exclusion <- c(reasons_for_exclusion, "Headache duration >= 7 days")
  }

  if (csf_mononuclear_percent >= 70) {
    low_risk <- FALSE
    reasons_for_exclusion <- c(reasons_for_exclusion, "CSF Mononuclear cells >= 70%")
  }

  if (seventh_nerve_palsy == 1) {
    low_risk <- FALSE
    reasons_for_exclusion <- c(reasons_for_exclusion, "Presence of 7th nerve palsy")
  }

  classification <- ""
  management <- ""

  if (low_risk) {
    classification <- "Low Risk for Lyme Meningitis"
    management <- "Consider discharge without empiric Lyme treatment (Negative Predictive Value 100% in derivation cohort)."
  } else {
    classification <- "Not Low Risk (Intermediate/High)"
    management <- "Consider testing and/or empiric treatment for Lyme Meningitis."
  }

  return(list(
    Risk_Classification = classification,
    Management_Guidance = management,
    Risk_Factors_Present = if (length(reasons_for_exclusion) > 0) reasons_for_exclusion else "None",
    Inputs = list(
      Headache_Days = headache_duration_days,
      CSF_Monos_Percent = csf_mononuclear_percent,
      CN7_Palsy = seventh_nerve_palsy == 1
    )
  ))
}

rule_of_nines <- function(head_percent, left_arm_percent, right_arm_percent, anterior_torso_percent, posterior_torso_percent, left_leg_percent, right_leg_percent, genitalia_percent, patient_type = "adult") {

  head_percent <- as.numeric(head_percent)
  left_arm_percent <- as.numeric(left_arm_percent)
  right_arm_percent <- as.numeric(right_arm_percent)
  anterior_torso_percent <- as.numeric(anterior_torso_percent)
  posterior_torso_percent <- as.numeric(posterior_torso_percent)
  left_leg_percent <- as.numeric(left_leg_percent)
  right_leg_percent <- as.numeric(right_leg_percent)
  genitalia_percent <- as.numeric(genitalia_percent)
  patient_type <- tolower(as.character(patient_type))

  if (any(is.na(c(head_percent, left_arm_percent, right_arm_percent, anterior_torso_percent, posterior_torso_percent, left_leg_percent, right_leg_percent, genitalia_percent)))) {
    stop("Error: All inputs must be numeric percentages (0-100).")
  }

  if (!patient_type %in% c("adult", "child")) {
    stop("Error: Patient type must be 'adult' or 'child'.")
  }

  weight_head <- 9
  weight_arm <- 9
  weight_ant_torso <- 18
  weight_post_torso <- 18
  weight_leg <- 18
  weight_genitals <- 1

  if (patient_type == "child") {
    weight_head <- 18
    weight_leg <- 13.5
  }

  tbsa <- 0

  tbsa <- tbsa + (head_percent / 100) * weight_head
  tbsa <- tbsa + (left_arm_percent / 100) * weight_arm
  tbsa <- tbsa + (right_arm_percent / 100) * weight_arm
  tbsa <- tbsa + (anterior_torso_percent / 100) * weight_ant_torso
  tbsa <- tbsa + (posterior_torso_percent / 100) * weight_post_torso
  tbsa <- tbsa + (left_leg_percent / 100) * weight_leg
  tbsa <- tbsa + (right_leg_percent / 100) * weight_leg
  tbsa <- tbsa + (genitalia_percent / 100) * weight_genitals

  return(list(
    Total_Body_Surface_Area_Burned = paste0(round(tbsa, 1), "%"),
    Inputs = list(
      Type = patient_type,
      Head = paste0(head_percent, "% of area"),
      Arms = paste0("L:", left_arm_percent, "%, R:", right_arm_percent, "%"),
      Torso = paste0("Ant:", anterior_torso_percent, "%, Post:", posterior_torso_percent, "%"),
      Legs = paste0("L:", left_leg_percent, "%, R:", right_leg_percent, "%"),
      Genitals = paste0(genitalia_percent, "%")
    )
  ))
}

mcdonald_ms_criteria_2010 <- function(clinical_attacks, clinical_lesions, dis_demonstrated, dit_demonstrated) {

  clinical_attacks <- as.numeric(clinical_attacks)
  clinical_lesions <- as.numeric(clinical_lesions)
  dis_demonstrated <- as.numeric(dis_demonstrated)
  dit_demonstrated <- as.numeric(dit_demonstrated)

  if (any(is.na(c(clinical_attacks, clinical_lesions, dis_demonstrated, dit_demonstrated)))) {
    stop("Error: All inputs must be numeric.")
  }

  diagnosis <- "Criteria Not Met / Possible CIS"
  additional_needed <- c()

  if (clinical_attacks >= 2) {
    if (clinical_lesions >= 2) {
      diagnosis <- "Multiple Sclerosis (MS)"
    } else {
      if (dis_demonstrated == 1) {
        diagnosis <- "Multiple Sclerosis (MS)"
      } else {
        additional_needed <- c(additional_needed, "Dissemination in Space (DIS)")
      }
    }
  } else if (clinical_attacks == 1) {
    if (clinical_lesions >= 2) {
      if (dit_demonstrated == 1) {
        diagnosis <- "Multiple Sclerosis (MS)"
      } else {
        additional_needed <- c(additional_needed, "Dissemination in Time (DIT)")
      }
    } else {
      if (dis_demonstrated == 1 && dit_demonstrated == 1) {
        diagnosis <- "Multiple Sclerosis (MS)"
      } else {
        if (dis_demonstrated == 0) additional_needed <- c(additional_needed, "Dissemination in Space (DIS)")
        if (dit_demonstrated == 0) additional_needed <- c(additional_needed, "Dissemination in Time (DIT)")
      }
    }
  }

  return(list(
    Diagnosis = diagnosis,
    Missing_Criteria = if (length(additional_needed) > 0) additional_needed else "None",
    Inputs = list(
      Attacks = clinical_attacks,
      Lesions = clinical_lesions,
      DIS_Met = dis_demonstrated == 1,
      DIT_Met = dit_demonstrated == 1
    )
  ))
}

revised_iss_multiple_myeloma <- function(beta2_microglobulin, albumin, ldh_elevated, high_risk_chromosomal_abnormalities) {

  beta2_microglobulin <- as.numeric(beta2_microglobulin)
  albumin <- as.numeric(albumin)
  ldh_elevated <- as.numeric(ldh_elevated)
  high_risk_chromosomal_abnormalities <- as.numeric(high_risk_chromosomal_abnormalities)

  if (any(is.na(c(beta2_microglobulin, albumin, ldh_elevated, high_risk_chromosomal_abnormalities)))) {
    stop("Error: All inputs must be numeric.")
  }

  iss_stage <- 0
  if (beta2_microglobulin < 3.5 && albumin >= 3.5) {
    iss_stage <- 1
  } else if (beta2_microglobulin >= 5.5) {
    iss_stage <- 3
  } else {
    iss_stage <- 2
  }

  r_iss_stage <- ""
  median_os <- ""
  survival_5yr <- ""

  if (iss_stage == 1 && ldh_elevated == 0 && high_risk_chromosomal_abnormalities == 0) {
    r_iss_stage <- "Stage I"
    median_os <- "Not Reached"
    survival_5yr <- "82%"
  } else if (iss_stage == 3 && (ldh_elevated == 1 || high_risk_chromosomal_abnormalities == 1)) {
    r_iss_stage <- "Stage III"
    median_os <- "43 months"
    survival_5yr <- "40%"
  } else {
    r_iss_stage <- "Stage II"
    median_os <- "83 months"
    survival_5yr <- "62%"
  }

  return(list(
    R_ISS_Stage = r_iss_stage,
    ISS_Stage_Calculated = paste("Stage", iss_stage),
    Median_Overall_Survival = median_os,
    Five_Year_Survival = survival_5yr,
    Inputs = list(
      B2M = beta2_microglobulin,
      Albumin = albumin,
      LDH_High = ldh_elevated == 1,
      High_Risk_CA = high_risk_chromosomal_abnormalities == 1
    )
  ))
}

revised_psc_risk_score <- function(age, bilirubin_mg_dl, albumin_g_dl, ast_u_l, history_variceal_bleeding) {

  age <- as.numeric(age)
  bilirubin_mg_dl <- as.numeric(bilirubin_mg_dl)
  albumin_g_dl <- as.numeric(albumin_g_dl)
  ast_u_l <- as.numeric(ast_u_l)
  history_variceal_bleeding <- as.numeric(history_variceal_bleeding)

  if (any(is.na(c(age, bilirubin_mg_dl, albumin_g_dl, ast_u_l, history_variceal_bleeding)))) {
    stop("Error: All inputs must be numeric.")
  }

  if (bilirubin_mg_dl <= 0 || ast_u_l <= 0) {
    stop("Error: Bilirubin and AST must be greater than 0 for logarithmic calculation.")
  }

  score <- (0.03 * age) + (0.54 * log(bilirubin_mg_dl)) + (0.54 * log(ast_u_l)) + (1.24 * history_variceal_bleeding) - (0.84 * albumin_g_dl)

  return(list(
    PSC_Risk_Score = round(score, 2),
    Inputs = list(
      Age = age,
      Bilirubin = bilirubin_mg_dl,
      Albumin = albumin_g_dl,
      AST = ast_u_l,
      Variceal_Bleeding = history_variceal_bleeding == 1
    )
  ))
}

revised_opioid_risk_tool <- function(sex, age, family_hx_alcohol, family_hx_illegal, family_hx_rx, personal_hx_alcohol, personal_hx_illegal, personal_hx_rx, history_sexual_abuse, psych_disease_adhd_ocd_bipolar_schizo, psych_disease_depression) {

  sex <- tolower(as.character(sex))
  age <- as.numeric(age)
  family_hx_alcohol <- as.numeric(family_hx_alcohol)
  family_hx_illegal <- as.numeric(family_hx_illegal)
  family_hx_rx <- as.numeric(family_hx_rx)
  personal_hx_alcohol <- as.numeric(personal_hx_alcohol)
  personal_hx_illegal <- as.numeric(personal_hx_illegal)
  personal_hx_rx <- as.numeric(personal_hx_rx)
  history_sexual_abuse <- as.numeric(history_sexual_abuse)
  psych_disease_adhd_ocd_bipolar_schizo <- as.numeric(psych_disease_adhd_ocd_bipolar_schizo)
  psych_disease_depression <- as.numeric(psych_disease_depression)

  if (any(is.na(c(age, family_hx_alcohol, family_hx_illegal, family_hx_rx, personal_hx_alcohol, personal_hx_illegal, personal_hx_rx, history_sexual_abuse, psych_disease_adhd_ocd_bipolar_schizo, psych_disease_depression)))) {
    stop("Error: All inputs must be numeric.")
  }

  if (!sex %in% c("male", "female")) {
    stop("Error: Sex must be 'male' or 'female'.")
  }

  score <- 0

  if (sex == "female") {
    if (family_hx_alcohol == 1) score <- score + 1
    if (family_hx_illegal == 1) score <- score + 2
    if (family_hx_rx == 1) score <- score + 4
    if (personal_hx_alcohol == 1) score <- score + 3
    if (personal_hx_illegal == 1) score <- score + 4
    if (personal_hx_rx == 1) score <- score + 5
    if (age >= 16 && age <= 45) score <- score + 1
    if (history_sexual_abuse == 1) score <- score + 3
    if (psych_disease_adhd_ocd_bipolar_schizo == 1) score <- score + 2
    if (psych_disease_depression == 1) score <- score + 1
  } else {
    if (family_hx_alcohol == 1) score <- score + 3
    if (family_hx_illegal == 1) score <- score + 3
    if (family_hx_rx == 1) score <- score + 4
    if (personal_hx_alcohol == 1) score <- score + 3
    if (personal_hx_illegal == 1) score <- score + 4
    if (personal_hx_rx == 1) score <- score + 5
    if (age >= 16 && age <= 45) score <- score + 1
    if (history_sexual_abuse == 1) score <- score + 0
    if (psych_disease_adhd_ocd_bipolar_schizo == 1) score <- score + 2
    if (psych_disease_depression == 1) score <- score + 1
  }

  risk_category <- ""
  if (score <= 3) {
    risk_category <- "Low Risk"
  } else if (score <= 7) {
    risk_category <- "Moderate Risk"
  } else {
    risk_category <- "High Risk"
  }

  return(list(
    ORT_OUD_Score = score,
    Risk_Category = risk_category,
    Inputs = list(
      Sex = sex,
      Age = age,
      Family_Hx = list(Alcohol=family_hx_alcohol, Illegal=family_hx_illegal, Rx=family_hx_rx),
      Personal_Hx = list(Alcohol=personal_hx_alcohol, Illegal=personal_hx_illegal, Rx=personal_hx_rx),
      Sexual_Abuse = history_sexual_abuse,
      Psych = list(Major=psych_disease_adhd_ocd_bipolar_schizo, Depression=psych_disease_depression)
    )
  ))
}

revised_original_aih_score <- function(sex, alp_ast_ratio, globulin_igg_ratio, autoantibody_titer, ama_positive, viral_markers_positive, drug_history_positive, alcohol_intake_low, histology_interface, histology_plasma_cells, histology_rosettes, histology_biliary, other_immune_disease, hla_dr3_dr4, treatment_response = "none") {

  sex <- tolower(as.character(sex))
  alp_ast_ratio <- as.numeric(alp_ast_ratio)
  globulin_igg_ratio <- as.numeric(globulin_igg_ratio)
  autoantibody_titer <- tolower(as.character(autoantibody_titer))
  ama_positive <- as.numeric(ama_positive)
  viral_markers_positive <- as.numeric(viral_markers_positive)
  drug_history_positive <- as.numeric(drug_history_positive)
  alcohol_intake_low <- as.numeric(alcohol_intake_low)
  histology_interface <- as.numeric(histology_interface)
  histology_plasma_cells <- as.numeric(histology_plasma_cells)
  histology_rosettes <- as.numeric(histology_rosettes)
  histology_biliary <- as.numeric(histology_biliary)
  other_immune_disease <- as.numeric(other_immune_disease)
  hla_dr3_dr4 <- as.numeric(hla_dr3_dr4)
  treatment_response <- tolower(as.character(treatment_response))

  if (any(is.na(c(alp_ast_ratio, globulin_igg_ratio)))) {
    stop("Error: Ratio inputs must be numeric.")
  }

  score <- 0

  if (sex == "female") {
    score <- score + 2
  }

  if (alp_ast_ratio < 1.5) {
    score <- score + 2
  } else if (alp_ast_ratio >= 3.0) {
    score <- score - 2
  }

  if (globulin_igg_ratio > 2.0) {
    score <- score + 3
  } else if (globulin_igg_ratio >= 1.5) {
    score <- score + 2
  } else if (globulin_igg_ratio >= 1.0) {
    score <- score + 1
  }

  if (autoantibody_titer == "gt_1_80") {
    score <- score + 3
  } else if (autoantibody_titer == "1_80") {
    score <- score + 2
  } else if (autoantibody_titer == "1_40") {
    score <- score + 1
  }

  if (ama_positive == 1) {
    score <- score - 4
  }

  if (viral_markers_positive == 1) {
    score <- score - 3
  } else {
    score <- score + 3
  }

  if (drug_history_positive == 1) {
    score <- score - 4
  } else {
    score <- score + 1
  }

  if (alcohol_intake_low == 1) {
    score <- score + 2
  } else {
    score <- score - 2
  }

  if (histology_interface == 1) score <- score + 3
  if (histology_plasma_cells == 1) score <- score + 1
  if (histology_rosettes == 1) score <- score + 1
  if (histology_biliary == 1) score <- score - 3

  if (other_immune_disease == 1) {
    score <- score + 2
  }

  if (hla_dr3_dr4 == 1) {
    score <- score + 1
  }

  if (treatment_response == "complete") {
    score <- score + 2
  } else if (treatment_response == "relapse") {
    score <- score + 3
  }

  diagnosis_pretreatment <- ""
  if (score > 15) {
    diagnosis_pretreatment <- "Definite AIH"
  } else if (score >= 10) {
    diagnosis_pretreatment <- "Probable AIH"
  } else {
    diagnosis_pretreatment <- "AIH Unlikely"
  }

  return(list(
    AIH_Score = score,
    Diagnosis = diagnosis_pretreatment,
    Inputs = list(
      Sex = sex,
      Ratios = paste("ALP:AST", alp_ast_ratio, "| IgG", globulin_igg_ratio),
      Antibodies = paste("Titer:", autoantibody_titer, "| AMA+:", ama_positive),
      History = paste("Viral+:", viral_markers_positive, "| Drug+:", drug_history_positive, "| AlcoholLow:", alcohol_intake_low),
      Histology = paste("Interface:", histology_interface, "| Plasma:", histology_plasma_cells, "| Rosettes:", histology_rosettes, "| Biliary:", histology_biliary),
      Genetic_Other = paste("Other Autoimmune:", other_immune_disease, "| HLA:", hla_dr3_dr4),
      Tx_Response = treatment_response
    )
  ))
}

revised_schwartz_gfr <- function(height, serum_creatinine, height_units = "cm", creatinine_units = "mg/dL") {

  height <- as.numeric(height)
  serum_creatinine <- as.numeric(serum_creatinine)

  if (any(is.na(c(height, serum_creatinine)))) {
    stop("Error: All inputs must be numeric.")
  }

  if (height <= 0 || serum_creatinine <= 0) {
    stop("Error: Height and creatinine must be positive.")
  }

  height_cm <- height
  if (height_units == "in") {
    height_cm <- height * 2.54
  }

  creat_mg_dl <- serum_creatinine
  if (creatinine_units == "micromol/L" || creatinine_units == "umol/L") {
    creat_mg_dl <- serum_creatinine / 88.4
  }

  k_constant <- 0.413

  gfr <- (k_constant * height_cm) / creat_mg_dl

  interpretation <- ""
  if (gfr >= 90) {
    interpretation <- "Normal kidney function"
  } else if (gfr >= 60) {
    interpretation <- "Mildly decreased kidney function"
  } else if (gfr >= 30) {
    interpretation <- "Moderately decreased kidney function"
  } else if (gfr >= 15) {
    interpretation <- "Severely decreased kidney function"
  } else {
    interpretation <- "Kidney failure"
  }

  return(list(
    Estimated_GFR = round(gfr, 1),
    Interpretation = interpretation,
    Inputs = list(
      Height_cm = round(height_cm, 1),
      Creatinine_mg_dL = round(creat_mg_dl, 2)
    )
  ))
}

revised_tokuhashi_score <- function(kps, number_extraspinal_bone_mets, number_vertebral_mets, major_organ_metastases, primary_site_group, palsy_frankel) {

  kps <- as.numeric(kps)
  number_extraspinal_bone_mets <- as.numeric(number_extraspinal_bone_mets)
  number_vertebral_mets <- as.numeric(number_vertebral_mets)
  major_organ_metastases <- tolower(as.character(major_organ_metastases))
  primary_site_group <- tolower(as.character(primary_site_group))
  palsy_frankel <- tolower(as.character(palsy_frankel))

  if (any(is.na(c(kps, number_extraspinal_bone_mets, number_vertebral_mets)))) {
    stop("Error: Numeric inputs required for KPS and metastasis counts.")
  }

  score <- 0

  if (kps < 50) {
    score <- score + 0
  } else if (kps >= 50 && kps <= 70) {
    score <- score + 1
  } else {
    score <- score + 2
  }

  if (number_extraspinal_bone_mets >= 3) {
    score <- score + 0
  } else if (number_extraspinal_bone_mets >= 1) {
    score <- score + 1
  } else {
    score <- score + 2
  }

  if (number_vertebral_mets >= 3) {
    score <- score + 0
  } else if (number_vertebral_mets == 2) {
    score <- score + 1
  } else {
    score <- score + 2
  }

  if (major_organ_metastases == "unremovable") {
    score <- score + 0
  } else if (major_organ_metastases == "removable") {
    score <- score + 1
  } else if (major_organ_metastases == "none") {
    score <- score + 2
  } else {
    stop("Error: Major organ metastases must be 'unremovable', 'removable', or 'none'.")
  }

  if (primary_site_group %in% c("lung", "osteosarcoma", "stomach", "bladder", "esophagus", "pancreas")) {
    score <- score + 0
  } else if (primary_site_group %in% c("liver", "gallbladder", "unidentified")) {
    score <- score + 1
  } else if (primary_site_group == "others") {
    score <- score + 2
  } else if (primary_site_group %in% c("kidney", "uterus")) {
    score <- score + 3
  } else if (primary_site_group == "rectum") {
    score <- score + 4
  } else if (primary_site_group %in% c("thyroid", "breast", "prostate", "carcinoid")) {
    score <- score + 5
  } else {
    stop("Error: Primary site group not recognized. Use specific cancer name or 'others'.")
  }

  if (palsy_frankel %in% c("complete", "frankel_a", "frankel_b")) {
    score <- score + 0
  } else if (palsy_frankel %in% c("incomplete", "frankel_c", "frankel_d")) {
    score <- score + 1
  } else if (palsy_frankel %in% c("none", "frankel_e")) {
    score <- score + 2
  } else {
    stop("Error: Palsy status must be 'complete', 'incomplete', or 'none'.")
  }

  prognosis <- ""
  treatment <- ""

  if (score <= 8) {
    prognosis <- "Life expectancy < 6 months"
    treatment <- "Conservative (palliative) care is typically recommended."
  } else if (score >= 9 && score <= 11) {
    prognosis <- "Life expectancy >= 6 months"
    treatment <- "Palliative surgery or excisional surgery if a single metastasis with good functional status."
  } else {
    prognosis <- "Life expectancy >= 1 year"
    treatment <- "Excisional surgery is typically recommended."
  }

  return(list(
    Tokuhashi_Score = score,
    Prognosis = prognosis,
    Treatment_Recommendation = treatment,
    Inputs = list(
      KPS = kps,
      Extraspinal_Mets = number_extraspinal_bone_mets,
      Vertebral_Mets = number_vertebral_mets,
      Organ_Mets = major_organ_metastases,
      Primary_Site = primary_site_group,
      Palsy = palsy_frankel
    )
  ))
}

revised_trauma_score <- function(gcs, systolic_bp, respiratory_rate) {

  gcs <- as.numeric(gcs)
  systolic_bp <- as.numeric(systolic_bp)
  respiratory_rate <- as.numeric(respiratory_rate)

  if (any(is.na(c(gcs, systolic_bp, respiratory_rate)))) {
    stop("Error: All inputs must be numeric.")
  }

  if (gcs < 3 || gcs > 15) {
    stop("Error: GCS must be between 3 and 15.")
  }

  gcs_coded <- 0
  if (gcs >= 13 && gcs <= 15) gcs_coded <- 4
  else if (gcs >= 9 && gcs <= 12) gcs_coded <- 3
  else if (gcs >= 6 && gcs <= 8) gcs_coded <- 2
  else if (gcs >= 4 && gcs <= 5) gcs_coded <- 1
  else gcs_coded <- 0

  sbp_coded <- 0
  if (systolic_bp > 89) sbp_coded <- 4
  else if (systolic_bp >= 76 && systolic_bp <= 89) sbp_coded <- 3
  else if (systolic_bp >= 50 && systolic_bp <= 75) sbp_coded <- 2
  else if (systolic_bp >= 1 && systolic_bp <= 49) sbp_coded <- 1
  else sbp_coded <- 0

  rr_coded <- 0
  if (respiratory_rate >= 10 && respiratory_rate <= 29) rr_coded <- 4
  else if (respiratory_rate > 29) rr_coded <- 3
  else if (respiratory_rate >= 6 && respiratory_rate <= 9) rr_coded <- 2
  else if (respiratory_rate >= 1 && respiratory_rate <= 5) rr_coded <- 1
  else rr_coded <- 0

  triage_rts <- gcs_coded + sbp_coded + rr_coded

  standard_rts <- (0.9368 * gcs_coded) + (0.7326 * sbp_coded) + (0.2908 * rr_coded)

  return(list(
    Triage_RTS = triage_rts,
    Standard_RTS = round(standard_rts, 4),
    Coded_Values = list(
      GCS_Code = gcs_coded,
      SBP_Code = sbp_coded,
      RR_Code = rr_coded
    )
  ))
}

ruis_score <- function(leakage_activity, leakage_urgency, leakage_no_activity, leakage_amount, leakage_frequency) {

  inputs <- c(leakage_activity, leakage_urgency, leakage_no_activity, leakage_amount, leakage_frequency)

  if (any(is.na(inputs))) {
    stop("Error: All inputs must be numeric.")
  }

  if (any(inputs < 0) || any(inputs > 4)) {
    stop("Error: All item scores must be integers between 0 and 3 or 4 (depending on the item).")
  }

  total_score <- sum(inputs)

  severity <- ""
  if (total_score <= 3) {
    severity <- "Slight Incontinence"
  } else if (total_score <= 8) {
    severity <- "Moderate Incontinence"
  } else {
    severity <- "Severe Incontinence"
  }

  return(list(
    RUIS_Score = total_score,
    Severity_Level = severity,
    Inputs = list(
      Q1_Activity = leakage_activity,
      Q2_Urgency = leakage_urgency,
      Q3_No_Activity = leakage_no_activity,
      Q4_Amount = leakage_amount,
      Q5_Frequency = leakage_frequency
    )
  ))
}

reynolds_risk_score_women <- function(age_years, systolic_bp_mmhg, total_cholesterol_mg_dl, hdl_cholesterol_mg_dl, hs_crp_mg_l, hba1c_percent, current_smoker, family_history_premature_mi) {

  age_years <- as.numeric(age_years)
  systolic_bp_mmhg <- as.numeric(systolic_bp_mmhg)
  total_cholesterol_mg_dl <- as.numeric(total_cholesterol_mg_dl)
  hdl_cholesterol_mg_dl <- as.numeric(hdl_cholesterol_mg_dl)
  hs_crp_mg_l <- as.numeric(hs_crp_mg_l)
  hba1c_percent <- as.numeric(hba1c_percent)
  current_smoker <- as.numeric(current_smoker)
  family_history_premature_mi <- as.numeric(family_history_premature_mi)

  if (any(is.na(c(age_years, systolic_bp_mmhg, total_cholesterol_mg_dl, hdl_cholesterol_mg_dl, hs_crp_mg_l, hba1c_percent)))) {
    stop("Error: All continuous inputs must be numeric.")
  }

  if (!current_smoker %in% c(0, 1) || !family_history_premature_mi %in% c(0, 1)) {
    stop("Error: Binary inputs must be 0 or 1.")
  }

  b_coeff <- (0.0799 * age_years) +
    (3.193 * log(systolic_bp_mmhg)) +
    (0.180 * log(hs_crp_mg_l)) +
    (1.382 * log(total_cholesterol_mg_dl)) -
    (1.172 * log(hdl_cholesterol_mg_dl)) +
    (0.134 * hba1c_percent) +
    (0.818 * current_smoker) +
    (0.438 * family_history_premature_mi)

  risk_probability <- 1 - (0.98634 ^ exp(b_coeff - 22.325))
  risk_percent <- risk_probability * 100

  risk_category <- ""
  if (risk_percent < 5) {
    risk_category <- "Low Risk"
  } else if (risk_percent < 10) {
    risk_category <- "Intermediate Risk"
  } else if (risk_percent < 20) {
    risk_category <- "High Risk"
  } else {
    risk_category <- "Very High Risk"
  }

  return(list(
    Reynolds_Risk_Score = round(risk_percent, 1),
    Risk_Category = risk_category,
    Inputs = list(
      Age = age_years,
      SBP = systolic_bp_mmhg,
      Total_Chol = total_cholesterol_mg_dl,
      HDL = hdl_cholesterol_mg_dl,
      hsCRP = hs_crp_mg_l,
      HbA1c = hba1c_percent,
      Smoker = current_smoker == 1,
      Family_Hx = family_history_premature_mi == 1
    )
  ))
}

ribscore_trauma <- function(age, fracture_count, bilateral_fractures, flail_chest, chronic_lung_disease, anticoagulant_use) {

  age <- as.numeric(age)
  fracture_count <- as.numeric(fracture_count)
  bilateral_fractures <- as.numeric(bilateral_fractures)
  flail_chest <- as.numeric(flail_chest)
  chronic_lung_disease <- as.numeric(chronic_lung_disease)
  anticoagulant_use <- as.numeric(anticoagulant_use)

  if (any(is.na(c(age, fracture_count, bilateral_fractures, flail_chest, chronic_lung_disease, anticoagulant_use)))) {
    stop("Error: All inputs must be numeric.")
  }

  score <- 0

  if (age < 45) {
    score <- score + 0
  } else if (age >= 45 && age <= 64) {
    score <- score + 1
  } else {
    score <- score + 2
  }

  if (fracture_count < 3) {
    score <- score + 0
  } else if (fracture_count >= 3 && fracture_count <= 5) {
    score <- score + 1
  } else {
    score <- score + 2
  }

  if (bilateral_fractures == 1) {
    score <- score + 2
  }

  if (flail_chest == 1) {
    score <- score + 2
  }

  if (chronic_lung_disease == 1) {
    score <- score + 2
  }

  if (anticoagulant_use == 1) {
    score <- score + 2
  }

  risk_percent <- ""
  if (score == 0) {
    risk_percent <- "0%"
  } else if (score == 1) {
    risk_percent <- "5.8%"
  } else if (score == 2) {
    risk_percent <- "12.9%"
  } else if (score == 3) {
    risk_percent <- "19.2%"
  } else if (score == 4) {
    risk_percent <- "26.1%"
  } else if (score == 5) {
    risk_percent <- "33.3%"
  } else if (score == 6) {
    risk_percent <- "38.1%"
  } else if (score == 7) {
    risk_percent <- "45.5%"
  } else {
    risk_percent <- "> 50%"
  }

  return(list(
    RibScore = score,
    Pulmonary_Complication_Risk = risk_percent,
    Inputs = list(
      Age = age,
      Fractures = fracture_count,
      Bilateral = bilateral_fractures == 1,
      Flail_Chest = flail_chest == 1,
      Chronic_Lung_Disease = chronic_lung_disease == 1,
      Anticoagulants = anticoagulant_use == 1
    )
  ))
}

richmond_agitation_sedation_scale <- function(observed_behavior, voice_stimulation = "not_applicable", physical_stimulation = "not_applicable") {

  observed_behavior <- tolower(as.character(observed_behavior))
  voice_stimulation <- tolower(as.character(voice_stimulation))
  physical_stimulation <- tolower(as.character(physical_stimulation))

  valid_behaviors <- c("combative", "very_agitated", "agitated", "restless", "alert_and_calm", "not_alert")
  if (!observed_behavior %in% valid_behaviors) {
    stop("Error: observed_behavior must be one of: 'combative', 'very_agitated', 'agitated', 'restless', 'alert_and_calm', 'not_alert'.")
  }

  score <- 0
  term <- ""
  description <- ""

  if (observed_behavior == "combative") {
    score <- 4
    term <- "Combative"
    description <- "Overtly combative, violent, immediate danger to staff."
  } else if (observed_behavior == "very_agitated") {
    score <- 3
    term <- "Very Agitated"
    description <- "Pulls or removes tube(s) or catheter(s); aggressive."
  } else if (observed_behavior == "agitated") {
    score <- 2
    term <- "Agitated"
    description <- "Frequent non-purposeful movement, fights ventilator."
  } else if (observed_behavior == "restless") {
    score <- 1
    term <- "Restless"
    description <- "Anxious but movements not aggressive vigorous."
  } else if (observed_behavior == "alert_and_calm") {
    score <- 0
    term <- "Alert and Calm"
    description <- "Spontaneously pays attention to caregiver."
  } else {
    if (voice_stimulation == "eye_contact_gt_10s") {
      score <- -1
      term <- "Drowsy"
      description <- "Not fully alert, but has sustained awakening (eye-opening/eye contact) to voice (> 10 seconds)."
    } else if (voice_stimulation == "eye_contact_lt_10s") {
      score <- -2
      term <- "Light Sedation"
      description <- "Briefly awakens with eye contact to voice (< 10 seconds)."
    } else if (voice_stimulation == "movement_no_eye_contact") {
      score <- -3
      term <- "Moderate Sedation"
      description <- "Movement or eye opening to voice (but no eye contact)."
    } else {
      if (physical_stimulation == "movement_or_eye_opening") {
        score <- -4
        term <- "Deep Sedation"
        description <- "No response to voice, but movement or eye opening to physical stimulation."
      } else {
        score <- -5
        term <- "Unarousable"
        description <- "No response to voice or physical stimulation."
      }
    }
  }

  return(list(
    RASS_Score = score,
    Term = term,
    Description = description,
    Inputs = list(
      Behavior = observed_behavior,
      Voice_Response = voice_stimulation,
      Physical_Response = physical_stimulation
    )
  ))
}

riete_hemorrhage_risk <- function(age_gt_75, recent_bleeding, cancer, creatinine_gt_1_2, hemoglobin_lt_13_or_12, pe_diagnosis) {

  age_gt_75 <- as.numeric(age_gt_75)
  recent_bleeding <- as.numeric(recent_bleeding)
  cancer <- as.numeric(cancer)
  creatinine_gt_1_2 <- as.numeric(creatinine_gt_1_2)
  hemoglobin_lt_13_or_12 <- as.numeric(hemoglobin_lt_13_or_12)
  pe_diagnosis <- as.numeric(pe_diagnosis)

  if (any(is.na(c(age_gt_75, recent_bleeding, cancer, creatinine_gt_1_2, hemoglobin_lt_13_or_12, pe_diagnosis)))) {
    stop("Error: All inputs must be numeric (0 or 1).")
  }

  score <- 0

  if (recent_bleeding == 1) {
    score <- score + 2
  }

  if (creatinine_gt_1_2 == 1) {
    score <- score + 1.5
  }

  if (hemoglobin_lt_13_or_12 == 1) {
    score <- score + 1.5
  }

  if (cancer == 1) {
    score <- score + 1
  }

  if (pe_diagnosis == 1) {
    score <- score + 1
  }

  if (age_gt_75 == 1) {
    score <- score + 1
  }

  risk_category <- ""
  major_bleeding_risk <- ""
  fatal_bleeding_risk <- ""

  if (score == 0) {
    risk_category <- "Low Risk"
    major_bleeding_risk <- "0.1%"
    fatal_bleeding_risk <- "0%"
  } else if (score <= 4) {
    risk_category <- "Intermediate Risk"
    major_bleeding_risk <- "2.8%"
    fatal_bleeding_risk <- "0.3%"
  } else {
    risk_category <- "High Risk"
    major_bleeding_risk <- "6.2%"
    fatal_bleeding_risk <- "1.2%"
  }

  return(list(
    RIETE_Score = score,
    Risk_Category = risk_category,
    Major_Bleeding_Risk_3_Months = major_bleeding_risk,
    Fatal_Bleeding_Risk_3_Months = fatal_bleeding_risk,
    Inputs = list(
      Recent_Bleeding = recent_bleeding == 1,
      Creatinine_Abnormal = creatinine_gt_1_2 == 1,
      Anemia = hemoglobin_lt_13_or_12 == 1,
      Cancer = cancer == 1,
      PE_Diagnosis = pe_diagnosis == 1,
      Age_gt_75 = age_gt_75 == 1
    )
  ))
}

rifle_criteria_aki <- function(baseline_creatinine, current_creatinine, gfr_decrease_percent, urine_output_ml_kg_hr, urine_output_duration_hours, anuria_duration_hours) {

  baseline_creatinine <- as.numeric(baseline_creatinine)
  current_creatinine <- as.numeric(current_creatinine)
  gfr_decrease_percent <- as.numeric(gfr_decrease_percent)
  urine_output_ml_kg_hr <- as.numeric(urine_output_ml_kg_hr)
  urine_output_duration_hours <- as.numeric(urine_output_duration_hours)
  anuria_duration_hours <- as.numeric(anuria_duration_hours)

  if (any(is.na(c(baseline_creatinine, current_creatinine, gfr_decrease_percent, urine_output_ml_kg_hr, urine_output_duration_hours, anuria_duration_hours)))) {
    stop("Error: All inputs must be numeric.")
  }

  creatinine_fold_increase <- 0
  if (baseline_creatinine > 0) {
    creatinine_fold_increase <- current_creatinine / baseline_creatinine
  }

  gfr_class <- "No AKI"
  if (creatinine_fold_increase >= 3 || current_creatinine >= 4.0 || gfr_decrease_percent >= 75) {
    gfr_class <- "Failure"
  } else if (creatinine_fold_increase >= 2 || gfr_decrease_percent >= 50) {
    gfr_class <- "Injury"
  } else if (creatinine_fold_increase >= 1.5 || gfr_decrease_percent >= 25) {
    gfr_class <- "Risk"
  }

  uo_class <- "No AKI"
  if (anuria_duration_hours >= 12) {
    uo_class <- "Failure"
  } else if (urine_output_ml_kg_hr < 0.3 && urine_output_duration_hours >= 24) {
    uo_class <- "Failure"
  } else if (urine_output_ml_kg_hr < 0.5 && urine_output_duration_hours >= 12) {
    uo_class <- "Injury"
  } else if (urine_output_ml_kg_hr < 0.5 && urine_output_duration_hours >= 6) {
    uo_class <- "Risk"
  }

  final_class <- "No AKI"
  if (gfr_class == "Failure" || uo_class == "Failure") {
    final_class <- "Failure"
  } else if (gfr_class == "Injury" || uo_class == "Injury") {
    final_class <- "Injury"
  } else if (gfr_class == "Risk" || uo_class == "Risk") {
    final_class <- "Risk"
  }

  return(list(
    RIFLE_Class = final_class,
    GFR_Criteria_Class = gfr_class,
    Urine_Output_Criteria_Class = uo_class,
    Inputs = list(
      Baseline_Cr = baseline_creatinine,
      Current_Cr = current_creatinine,
      GFR_Decrease_Pct = gfr_decrease_percent,
      UO_Rate = urine_output_ml_kg_hr,
      UO_Duration = urine_output_duration_hours,
      Anuria_Duration = anuria_duration_hours
    )
  ))
}

ripasa_appendicitis_score <- function(sex, age, rif_pain, pain_migration, anorexia, nausea_vomiting, symptom_duration_lt_48h, rif_tenderness, guarding, rebound_tenderness, rovsing_sign, fever, elevated_wbc, negative_urinalysis, foreign_national) {

  sex <- tolower(as.character(sex))
  age <- as.numeric(age)
  rif_pain <- as.numeric(rif_pain)
  pain_migration <- as.numeric(pain_migration)
  anorexia <- as.numeric(anorexia)
  nausea_vomiting <- as.numeric(nausea_vomiting)
  symptom_duration_lt_48h <- as.numeric(symptom_duration_lt_48h)
  rif_tenderness <- as.numeric(rif_tenderness)
  guarding <- as.numeric(guarding)
  rebound_tenderness <- as.numeric(rebound_tenderness)
  rovsing_sign <- as.numeric(rovsing_sign)
  fever <- as.numeric(fever)
  elevated_wbc <- as.numeric(elevated_wbc)
  negative_urinalysis <- as.numeric(negative_urinalysis)
  foreign_national <- as.numeric(foreign_national)

  if (any(is.na(c(age, rif_pain, pain_migration, anorexia, nausea_vomiting, symptom_duration_lt_48h, rif_tenderness, guarding, rebound_tenderness, rovsing_sign, fever, elevated_wbc, negative_urinalysis, foreign_national)))) {
    stop("Error: All inputs must be numeric.")
  }

  if (!sex %in% c("male", "female")) {
    stop("Error: Sex must be 'male' or 'female'.")
  }

  score <- 0

  if (sex == "male") {
    score <- score + 1.0
  } else {
    score <- score + 0.5
  }

  if (age < 40) {
    score <- score + 1.0
  } else {
    score <- score + 0.5
  }

  if (rif_pain == 1) {
    score <- score + 0.5
  }

  if (pain_migration == 1) {
    score <- score + 0.5
  }

  if (anorexia == 1) {
    score <- score + 1.0
  }

  if (nausea_vomiting == 1) {
    score <- score + 1.0
  }

  if (symptom_duration_lt_48h == 1) {
    score <- score + 1.0
  } else {
    score <- score + 0.5
  }

  if (rif_tenderness == 1) {
    score <- score + 1.0
  }

  if (guarding == 1) {
    score <- score + 2.0
  }

  if (rebound_tenderness == 1) {
    score <- score + 1.0
  }

  if (rovsing_sign == 1) {
    score <- score + 2.0
  }

  if (fever == 1) {
    score <- score + 1.0
  }

  if (elevated_wbc == 1) {
    score <- score + 1.0
  }

  if (negative_urinalysis == 1) {
    score <- score + 1.0
  }

  if (foreign_national == 1) {
    score <- score + 1.0
  }

  probability <- ""
  management <- ""

  if (score < 5) {
    probability <- "Unlikely (<17%)"
    management <- "Observation."
  } else if (score >= 5 && score < 7.5) {
    probability <- "Low Probability"
    management <- "Observation, repeat scoring, or abdominal ultrasound."
  } else if (score >= 7.5 && score < 12) {
    probability <- "High Probability"
    management <- "Surgical review and preparation. Appendectomy indicated if high clinical suspicion."
  } else {
    probability <- "Definite (>95%)"
    management <- "Appendectomy indicated."
  }

  return(list(
    RIPASA_Score = score,
    Appendicitis_Probability = probability,
    Recommendation = management,
    Inputs = list(
      Sex = sex,
      Age = age,
      RIF_Pain = rif_pain == 1,
      Migration = pain_migration == 1,
      Anorexia = anorexia == 1,
      Nausea_Vomiting = nausea_vomiting == 1,
      Duration_lt_48h = symptom_duration_lt_48h == 1,
      Tenderness = rif_tenderness == 1,
      Guarding = guarding == 1,
      Rebound = rebound_tenderness == 1,
      Rovsing = rovsing_sign == 1,
      Fever = fever == 1,
      High_WBC = elevated_wbc == 1,
      Neg_Urinalysis = negative_urinalysis == 1,
      Foreign_National = foreign_national == 1
    )
  ))
}

risk_malignancy_index <- function(ca125_level, menopausal_status, multilocular_cyst, solid_areas, bilateral_lesions, ascites, intraabdominal_metastases) {

  ca125_level <- as.numeric(ca125_level)
  multilocular_cyst <- as.numeric(multilocular_cyst)
  solid_areas <- as.numeric(solid_areas)
  bilateral_lesions <- as.numeric(bilateral_lesions)
  ascites <- as.numeric(ascites)
  intraabdominal_metastases <- as.numeric(intraabdominal_metastases)
  menopausal_status <- tolower(as.character(menopausal_status))

  if (any(is.na(c(ca125_level, multilocular_cyst, solid_areas, bilateral_lesions, ascites, intraabdominal_metastases)))) {
    stop("Error: All inputs must be numeric.")
  }

  if (!menopausal_status %in% c("pre", "post")) {
    stop("Error: Menopausal status must be 'pre' or 'post'.")
  }

  us_features_count <- multilocular_cyst + solid_areas + bilateral_lesions + ascites + intraabdominal_metastases

  u_score <- 0
  if (us_features_count == 0) {
    u_score <- 0
  } else if (us_features_count == 1) {
    u_score <- 1
  } else {
    u_score <- 3
  }

  m_score <- 0
  if (menopausal_status == "pre") {
    m_score <- 1
  } else {
    m_score <- 3
  }

  rmi <- u_score * m_score * ca125_level

  risk_category <- ""
  recommendation <- ""

  if (rmi >= 200) {
    risk_category <- "High Risk of Malignancy"
    recommendation <- "Referral to a gynecological oncologist is recommended."
  } else {
    risk_category <- "Low Risk of Malignancy"
    recommendation <- "Management by general gynecologist may be appropriate."
  }

  return(list(
    RMI_Score = rmi,
    Risk_Category = risk_category,
    Recommendation = recommendation,
    Inputs = list(
      CA125 = ca125_level,
      Menopausal_State = m_score,
      Ultrasound_Features_Count = us_features_count,
      Ultrasound_Score_U = u_score
    )
  ))
}

rope_risk_score <- function(age, history_hypertension, history_diabetes, history_stroke_tia, current_smoker, cortical_infarct) {

  age <- as.numeric(age)
  history_hypertension <- as.numeric(history_hypertension)
  history_diabetes <- as.numeric(history_diabetes)
  history_stroke_tia <- as.numeric(history_stroke_tia)
  current_smoker <- as.numeric(current_smoker)
  cortical_infarct <- as.numeric(cortical_infarct)

  if (any(is.na(c(age, history_hypertension, history_diabetes, history_stroke_tia, current_smoker, cortical_infarct)))) {
    stop("Error: All inputs must be numeric.")
  }

  score <- 0

  if (history_hypertension == 0) {
    score <- score + 1
  }

  if (history_diabetes == 0) {
    score <- score + 1
  }

  if (history_stroke_tia == 0) {
    score <- score + 1
  }

  if (current_smoker == 0) {
    score <- score + 1
  }

  if (cortical_infarct == 1) {
    score <- score + 1
  }

  if (age >= 18 && age <= 29) {
    score <- score + 5
  } else if (age >= 30 && age <= 39) {
    score <- score + 4
  } else if (age >= 40 && age <= 49) {
    score <- score + 3
  } else if (age >= 50 && age <= 59) {
    score <- score + 2
  } else if (age >= 60 && age <= 69) {
    score <- score + 1
  } else {
    score <- score + 0
  }

  pfo_attributable_fraction <- ""
  recurrence_risk <- ""

  if (score <= 3) {
    pfo_attributable_fraction <- "0%"
    recurrence_risk <- "High estimated 2-year recurrence rate (~20%)"
  } else if (score == 4) {
    pfo_attributable_fraction <- "38%"
    recurrence_risk <- "High estimated 2-year recurrence rate (~12%)"
  } else if (score == 5) {
    pfo_attributable_fraction <- "34%"
    recurrence_risk <- "Intermediate estimated 2-year recurrence rate (~6-8%)"
  } else if (score == 6) {
    pfo_attributable_fraction <- "62%"
    recurrence_risk <- "Intermediate estimated 2-year recurrence rate (~6-8%)"
  } else if (score == 7) {
    pfo_attributable_fraction <- "72%"
    recurrence_risk <- "Low estimated 2-year recurrence rate (~2-4%)"
  } else if (score == 8) {
    pfo_attributable_fraction <- "84%"
    recurrence_risk <- "Low estimated 2-year recurrence rate (~2-4%)"
  } else {
    pfo_attributable_fraction <- "88%"
    recurrence_risk <- "Low estimated 2-year recurrence rate (~2%)"
  }

  return(list(
    RoPE_Score = score,
    PFO_Attributable_Fraction = pfo_attributable_fraction,
    Stroke_Recurrence_Risk = recurrence_risk,
    Inputs = list(
      Age = age,
      No_Hypertension = history_hypertension == 0,
      No_Diabetes = history_diabetes == 0,
      No_Prior_Stroke_TIA = history_stroke_tia == 0,
      Non_Smoker = current_smoker == 0,
      Cortical_Infarct = cortical_infarct == 1
    )
  ))
}

rse_asthma_score <- function(bmi_ge_30, acq5_score, fev1_percent_predicted, rescue_inhaler_uses_per_day, gina_step_4_or_higher) {

  bmi_ge_30 <- as.numeric(bmi_ge_30)
  acq5_score <- as.numeric(acq5_score)
  fev1_percent_predicted <- as.numeric(fev1_percent_predicted)
  rescue_inhaler_uses_per_day <- as.numeric(rescue_inhaler_uses_per_day)
  gina_step_4_or_higher <- as.numeric(gina_step_4_or_higher)

  if (any(is.na(c(bmi_ge_30, acq5_score, fev1_percent_predicted, rescue_inhaler_uses_per_day, gina_step_4_or_higher)))) {
    stop("Error: All inputs must be numeric.")
  }

  score <- 0

  if (bmi_ge_30 == 1) {
    score <- score + 14
  }

  if (acq5_score < 1.5) {
    score <- score + 0
  } else if (acq5_score >= 1.5 && acq5_score < 2.5) {
    score <- score + 7
  } else {
    score <- score + 13
  }

  if (fev1_percent_predicted >= 90) {
    score <- score + 0
  } else if (fev1_percent_predicted >= 80) {
    score <- score + 13
  } else {
    score <- score + 20
  }

  if (rescue_inhaler_uses_per_day < 2) {
    score <- score + 0
  } else if (rescue_inhaler_uses_per_day >= 2 && rescue_inhaler_uses_per_day < 4) {
    score <- score + 11
  } else {
    score <- score + 26
  }

  if (gina_step_4_or_higher == 1) {
    score <- score + 27
  }

  risk_probability <- ""
  if (score < 15) {
    risk_probability <- "Low Risk (<10%)"
  } else if (score < 40) {
    risk_probability <- "Moderate Risk (10-30%)"
  } else {
    risk_probability <- "High Risk (>30%)"
  }

  return(list(
    RSE_Score = score,
    Risk_Category = risk_probability,
    Inputs = list(
      BMI_ge_30 = bmi_ge_30 == 1,
      ACQ5 = acq5_score,
      FEV1_Pct = fev1_percent_predicted,
      Rescue_Uses = rescue_inhaler_uses_per_day,
      GINA_Step_4_Plus = gina_step_4_or_higher == 1
    )
  ))
}

riske_score_cardiac_surgery <- function(age, shock_cardiogenic, shock_septic, immunosuppression, kidney_injury, staphylococcus_aureus, acute_renal_failure_preop, prostheses_involved_count, aortic_valve_involved) {

  age <- as.numeric(age)
  shock_cardiogenic <- as.numeric(shock_cardiogenic)
  shock_septic <- as.numeric(shock_septic)
  immunosuppression <- as.numeric(immunosuppression)
  kidney_injury <- as.numeric(kidney_injury)
  staphylococcus_aureus <- as.numeric(staphylococcus_aureus)
  acute_renal_failure_preop <- as.numeric(acute_renal_failure_preop)
  prostheses_involved_count <- as.numeric(prostheses_involved_count)
  aortic_valve_involved <- as.numeric(aortic_valve_involved)

  if (any(is.na(c(age, shock_cardiogenic, shock_septic, immunosuppression, kidney_injury, staphylococcus_aureus, acute_renal_failure_preop, prostheses_involved_count, aortic_valve_involved)))) {
    stop("Error: All inputs must be numeric.")
  }

  score <- 0

  if (age >= 18 && age <= 40) {
    score <- score + 0
  } else if (age >= 41 && age <= 60) {
    score <- score + 4
  } else if (age >= 61 && age <= 70) {
    score <- score + 9
  } else {
    score <- score + 13
  }

  if (shock_cardiogenic == 1) {
    score <- score + 6
  }

  if (shock_septic == 1) {
    score <- score + 11
  }

  if (immunosuppression == 1) {
    score <- score + 4
  }

  if (kidney_injury == 1) {
    score <- score + 5
  }

  if (staphylococcus_aureus == 1) {
    score <- score + 6
  }

  if (acute_renal_failure_preop == 1) {
    score <- score + 5
  }

  if (prostheses_involved_count == 1) {
    score <- score + 6
  } else if (prostheses_involved_count >= 2) {
    score <- score + 6
  }

  if (aortic_valve_involved == 1) {
    score <- score + 4
  }

  risk_group <- ""
  mortality_estimate <- ""

  if (score <= 10) {
    risk_group <- "Low Risk"
    mortality_estimate <- "< 10%"
  } else if (score <= 20) {
    risk_group <- "Intermediate Risk"
    mortality_estimate <- "10-20%"
  } else if (score <= 30) {
    risk_group <- "High Risk"
    mortality_estimate <- "20-40%"
  } else {
    risk_group <- "Very High Risk"
    mortality_estimate <- "> 40%"
  }

  return(list(
    RISKE_Score = score,
    Risk_Category = risk_group,
    Est_InHospital_Mortality = mortality_estimate,
    Inputs = list(
      Age = age,
      Cardiogenic_Shock = shock_cardiogenic == 1,
      Septic_Shock = shock_septic == 1,
      Immunosuppression = immunosuppression == 1,
      Kidney_Injury = kidney_injury == 1,
      S_Aureus = staphylococcus_aureus == 1,
      Preop_ARF = acute_renal_failure_preop == 1,
      Prostheses = prostheses_involved_count,
      Aortic_Valve = aortic_valve_involved == 1
    )
  ))
}

rochester_criteria_febrile_infant <- function(well_appearing, no_skeletal_soft_tissue_infection, term_infant, no_unexplained_hyperbilirubinemia, no_previous_antimicrobials, no_prior_hospitalization, no_chronic_illness, wbc_count, band_count_percent, urinalysis_wbc_hpf, stool_wbc_hpf = NULL, diarrhea_present = 0) {

  well_appearing <- as.numeric(well_appearing)
  no_skeletal_soft_tissue_infection <- as.numeric(no_skeletal_soft_tissue_infection)
  term_infant <- as.numeric(term_infant)
  no_unexplained_hyperbilirubinemia <- as.numeric(no_unexplained_hyperbilirubinemia)
  no_previous_antimicrobials <- as.numeric(no_previous_antimicrobials)
  no_prior_hospitalization <- as.numeric(no_prior_hospitalization)
  no_chronic_illness <- as.numeric(no_chronic_illness)
  wbc_count <- as.numeric(wbc_count)
  band_count_percent <- as.numeric(band_count_percent)
  urinalysis_wbc_hpf <- as.numeric(urinalysis_wbc_hpf)
  diarrhea_present <- as.numeric(diarrhea_present)

  if (any(is.na(c(well_appearing, no_skeletal_soft_tissue_infection, term_infant, no_unexplained_hyperbilirubinemia, no_previous_antimicrobials, no_prior_hospitalization, no_chronic_illness, wbc_count, band_count_percent, urinalysis_wbc_hpf)))) {
    stop("Error: All core inputs must be numeric.")
  }

  history_met <- TRUE
  if (term_infant == 0) history_met <- FALSE
  if (no_previous_antimicrobials == 0) history_met <- FALSE
  if (no_prior_hospitalization == 0) history_met <- FALSE
  if (no_chronic_illness == 0) history_met <- FALSE
  if (no_unexplained_hyperbilirubinemia == 0) history_met <- FALSE

  exam_met <- TRUE
  if (well_appearing == 0) exam_met <- FALSE
  if (no_skeletal_soft_tissue_infection == 0) exam_met <- FALSE

  labs_met <- TRUE
  if (wbc_count < 5000 || wbc_count > 15000) labs_met <- FALSE

  abs_bands <- wbc_count * (band_count_percent / 100)
  if (abs_bands >= 1500) labs_met <- FALSE

  if (urinalysis_wbc_hpf >= 10) labs_met <- FALSE

  if (diarrhea_present == 1) {
    if (is.null(stool_wbc_hpf) || is.na(as.numeric(stool_wbc_hpf))) {
      return(list(Result = "Incomplete", Message = "Stool WBC count required due to diarrhea."))
    }
    stool_wbc <- as.numeric(stool_wbc_hpf)
    if (stool_wbc >= 5) labs_met <- FALSE
  }

  risk_level <- ""
  if (history_met && exam_met && labs_met) {
    risk_level <- "Low Risk"
  } else {
    risk_level <- "High Risk"
  }

  return(list(
    Risk_Classification = risk_level,
    Inputs = list(
      History_Met = history_met,
      Exam_Met = exam_met,
      Labs_Met = labs_met
    )
  ))
}

rockall_score_complete <- function(age, systolic_bp, heart_rate, comorbidity_category, diagnosis_category, major_stigmata_present) {

  age <- as.numeric(age)
  systolic_bp <- as.numeric(systolic_bp)
  heart_rate <- as.numeric(heart_rate)
  comorbidity_category <- tolower(as.character(comorbidity_category))
  diagnosis_category <- tolower(as.character(diagnosis_category))
  major_stigmata_present <- as.numeric(major_stigmata_present)

  if (any(is.na(c(age, systolic_bp, heart_rate, major_stigmata_present)))) {
    stop("Error: All numeric inputs must be valid.")
  }

  valid_comorbs <- c("none", "cardiac_other", "renal_liver_metastatic")
  if (!comorbidity_category %in% valid_comorbs) {
    stop("Error: Comorbidity category must be 'none', 'cardiac_other', or 'renal_liver_metastatic'.")
  }

  valid_dx <- c("mallory_weiss_none", "all_other", "malignancy")
  if (!diagnosis_category %in% valid_dx) {
    stop("Error: Diagnosis category must be 'mallory_weiss_none', 'all_other', or 'malignancy'.")
  }

  score <- 0

  if (age >= 80) {
    score <- score + 2
  } else if (age >= 60) {
    score <- score + 1
  }

  if (systolic_bp < 100) {
    score <- score + 2
  } else if (heart_rate >= 100) {
    score <- score + 1
  }

  if (comorbidity_category == "renal_liver_metastatic") {
    score <- score + 3
  } else if (comorbidity_category == "cardiac_other") {
    score <- score + 2
  }

  if (diagnosis_category == "malignancy") {
    score <- score + 2
  } else if (diagnosis_category == "all_other") {
    score <- score + 1
  }

  if (major_stigmata_present == 1) {
    score <- score + 2
  }

  mortality_risk <- ""
  rebleed_risk <- ""

  if (score == 0) {
    mortality_risk <- "0%"
    rebleed_risk <- "4.9%"
  } else if (score == 1) {
    mortality_risk <- "0%"
    rebleed_risk <- "3.4%"
  } else if (score == 2) {
    mortality_risk <- "0.2%"
    rebleed_risk <- "5.3%"
  } else if (score == 3) {
    mortality_risk <- "2.9%"
    rebleed_risk <- "11.2%"
  } else if (score == 4) {
    mortality_risk <- "5.3%"
    rebleed_risk <- "14.1%"
  } else if (score == 5) {
    mortality_risk <- "10.8%"
    rebleed_risk <- "24.1%"
  } else if (score == 6) {
    mortality_risk <- "17.3%"
    rebleed_risk <- "32.9%"
  } else if (score == 7) {
    mortality_risk <- "27.0%"
    rebleed_risk <- "43.8%"
  } else {
    mortality_risk <- "41.1%"
    rebleed_risk <- "41.8%"
  }

  return(list(
    Rockall_Score = score,
    Mortality_Risk = mortality_risk,
    Rebleed_Risk = rebleed_risk,
    Inputs = list(
      Age = age,
      SBP = systolic_bp,
      HR = heart_rate,
      Comorbidity = comorbidity_category,
      Diagnosis = diagnosis_category,
      Stigmata = major_stigmata_present == 1
    )
  ))
}

