nyha_functional_classification <- function(class_grade) {

  class_grade <- as.numeric(class_grade)

  if (is.na(class_grade) || !class_grade %in% 1:4) {
    stop("Error: NYHA Class must be an integer between 1 and 4.")
  }

  description <- ""

  if (class_grade == 1) {
    description <- "No limitation of physical activity. Ordinary physical activity does not cause undue fatigue, palpitation, dyspnea (shortness of breath)."
  } else if (class_grade == 2) {
    description <- "Slight limitation of physical activity. Comfortable at rest. Ordinary physical activity results in fatigue, palpitation, dyspnea (shortness of breath)."
  } else if (class_grade == 3) {
    description <- "Marked limitation of physical activity. Comfortable at rest. Less than ordinary activity causes fatigue, palpitation, or dyspnea."
  } else {
    description <- "Unable to carry on any physical activity without discomfort. Symptoms of heart failure at rest. If any physical activity is undertaken, discomfort increases."
  }

  return(list(
    NYHA_Class = paste0("Class ", as.roman(class_grade)),
    Description = description
  ))
}

newsom_chest_pain_score <- function(age, history_chf, history_smoking, hemoptysis, history_tuberculosis, history_thromboembolism, alcohol_abuse, temp_c, oxygen_saturation, respiratory_rate, diminished_breath_sounds, rales) {

  age <- as.numeric(age)
  history_chf <- as.numeric(history_chf)
  history_smoking <- as.numeric(history_smoking)
  hemoptysis <- as.numeric(hemoptysis)
  history_tuberculosis <- as.numeric(history_tuberculosis)
  history_thromboembolism <- as.numeric(history_thromboembolism)
  alcohol_abuse <- as.numeric(alcohol_abuse)
  temp_c <- as.numeric(temp_c)
  oxygen_saturation <- as.numeric(oxygen_saturation)
  respiratory_rate <- as.numeric(respiratory_rate)
  diminished_breath_sounds <- as.numeric(diminished_breath_sounds)
  rales <- as.numeric(rales)

  if (any(is.na(c(age, history_chf, history_smoking, hemoptysis, history_tuberculosis, history_thromboembolism, alcohol_abuse, temp_c, oxygen_saturation, respiratory_rate, diminished_breath_sounds, rales)))) {
    stop("Error: All inputs must be numeric.")
  }

  risk_factors <- 0

  if (age >= 60) risk_factors <- risk_factors + 1
  if (history_chf == 1) risk_factors <- risk_factors + 1
  if (history_smoking == 1) risk_factors <- risk_factors + 1
  if (hemoptysis == 1) risk_factors <- risk_factors + 1
  if (history_tuberculosis == 1) risk_factors <- risk_factors + 1
  if (history_thromboembolism == 1) risk_factors <- risk_factors + 1
  if (alcohol_abuse == 1) risk_factors <- risk_factors + 1
  if (temp_c >= 38) risk_factors <- risk_factors + 1
  if (oxygen_saturation < 90) risk_factors <- risk_factors + 1
  if (respiratory_rate > 24) risk_factors <- risk_factors + 1
  if (diminished_breath_sounds == 1) risk_factors <- risk_factors + 1
  if (rales == 1) risk_factors <- risk_factors + 1

  risk_level <- ""
  recommendation <- ""

  if (risk_factors == 0) {
    risk_level <- "Low Risk"
    recommendation <- "Chest X-ray may not be necessary (Risk of significant findings is low)."
  } else {
    risk_level <- "Not Low Risk"
    recommendation <- "Chest X-ray is recommended."
  }

  return(list(
    Newsom_Score = risk_factors,
    Risk_Category = risk_level,
    Recommendation = recommendation,
    Inputs = list(
      Age_ge_60 = age >= 60,
      Hx_CHF = history_chf == 1,
      Hx_Smoking = history_smoking == 1,
      Hemoptysis = hemoptysis == 1,
      Hx_TB = history_tuberculosis == 1,
      Hx_Thromboembolism = history_thromboembolism == 1,
      Alcohol_Abuse = alcohol_abuse == 1,
      Fever_ge_38C = temp_c >= 38,
      SpO2_lt_90 = oxygen_saturation < 90,
      RR_gt_24 = respiratory_rate > 24,
      Diminished_Breath_Sounds = diminished_breath_sounds == 1,
      Rales = rales == 1
    )
  ))
}

