nih_stroke_scale <- function(loc_response, loc_questions, loc_commands, gaze, visual_fields, facial_palsy, motor_arm_left, motor_arm_right, motor_leg_left, motor_leg_right, limb_ataxia, sensory, best_language, dysarthria, extinction_inattention) {

  loc_response <- as.numeric(loc_response)
  loc_questions <- as.numeric(loc_questions)
  loc_commands <- as.numeric(loc_commands)
  gaze <- as.numeric(gaze)
  visual_fields <- as.numeric(visual_fields)
  facial_palsy <- as.numeric(facial_palsy)
  motor_arm_left <- as.numeric(motor_arm_left)
  motor_arm_right <- as.numeric(motor_arm_right)
  motor_leg_left <- as.numeric(motor_leg_left)
  motor_leg_right <- as.numeric(motor_leg_right)
  limb_ataxia <- as.numeric(limb_ataxia)
  sensory <- as.numeric(sensory)
  best_language <- as.numeric(best_language)
  dysarthria <- as.numeric(dysarthria)
  extinction_inattention <- as.numeric(extinction_inattention)

  if (any(is.na(c(loc_response, loc_questions, loc_commands, gaze, visual_fields, facial_palsy, motor_arm_left, motor_arm_right, motor_leg_left, motor_leg_right, limb_ataxia, sensory, best_language, dysarthria, extinction_inattention)))) {
    stop("Error: All inputs must be numeric.")
  }

  score <- loc_response + loc_questions + loc_commands + gaze + visual_fields + facial_palsy + motor_arm_left + motor_arm_right + motor_leg_left + motor_leg_right + limb_ataxia + sensory + best_language + dysarthria + extinction_inattention

  severity <- ""
  if (score == 0) {
    severity <- "No Stroke Symptoms"
  } else if (score >= 1 && score <= 4) {
    severity <- "Minor Stroke"
  } else if (score >= 5 && score <= 15) {
    severity <- "Moderate Stroke"
  } else if (score >= 16 && score <= 20) {
    severity <- "Moderate to Severe Stroke"
  } else {
    severity <- "Severe Stroke"
  }

  return(list(
    NIHSS_Score = score,
    Severity = severity,
    Inputs = list(
      LOC = list(Responsiveness = loc_response, Questions = loc_questions, Commands = loc_commands),
      Gaze = gaze,
      Visual = visual_fields,
      Face = facial_palsy,
      Motor = list(ArmL = motor_arm_left, ArmR = motor_arm_right, LegL = motor_leg_left, LegR = motor_leg_right),
      Ataxia = limb_ataxia,
      Sensory = sensory,
      Language = list(Best = best_language, Dysarthria = dysarthria),
      Extinction = extinction_inattention
    )
  ))
}

pack_years_calculator <- function(packs_per_day = NULL, cigarettes_per_day = NULL, years_smoked) {

  years_smoked <- as.numeric(years_smoked)

  if (is.na(years_smoked) || years_smoked < 0) {
    stop("Error: Years smoked must be a valid non-negative number.")
  }

  calculated_pack_years <- 0

  if (!is.null(packs_per_day)) {
    packs_per_day <- as.numeric(packs_per_day)
    if (is.na(packs_per_day) || packs_per_day < 0) stop("Error: Packs per day must be a valid non-negative number.")
    calculated_pack_years <- packs_per_day * years_smoked
  } else if (!is.null(cigarettes_per_day)) {
    cigarettes_per_day <- as.numeric(cigarettes_per_day)
    if (is.na(cigarettes_per_day) || cigarettes_per_day < 0) stop("Error: Cigarettes per day must be a valid non-negative number.")
    calculated_pack_years <- (cigarettes_per_day / 20) * years_smoked
  } else {
    stop("Error: Must provide either packs_per_day or cigarettes_per_day.")
  }

  return(list(
    Pack_Years = round(calculated_pack_years, 2),
    Inputs = list(
      Years_Smoked = years_smoked,
      Daily_Usage = if (!is.null(packs_per_day)) paste(packs_per_day, "packs/day") else paste(cigarettes_per_day, "cigarettes/day")
    )
  ))
}

padua_vte_score <- function(active_cancer, previous_vte, reduced_mobility, known_thrombophilia, recent_trauma_surgery, age, heart_respiratory_failure, acute_mi_stroke, infection_rheumatologic, bmi, hormonal_treatment) {

  active_cancer <- as.numeric(active_cancer)
  previous_vte <- as.numeric(previous_vte)
  reduced_mobility <- as.numeric(reduced_mobility)
  known_thrombophilia <- as.numeric(known_thrombophilia)
  recent_trauma_surgery <- as.numeric(recent_trauma_surgery)
  age <- as.numeric(age)
  heart_respiratory_failure <- as.numeric(heart_respiratory_failure)
  acute_mi_stroke <- as.numeric(acute_mi_stroke)
  infection_rheumatologic <- as.numeric(infection_rheumatologic)
  bmi <- as.numeric(bmi)
  hormonal_treatment <- as.numeric(hormonal_treatment)

  if (any(is.na(c(active_cancer, previous_vte, reduced_mobility, known_thrombophilia, recent_trauma_surgery, age, heart_respiratory_failure, acute_mi_stroke, infection_rheumatologic, bmi, hormonal_treatment)))) {
    stop("Error: All inputs must be numeric.")
  }

  score <- 0

  if (active_cancer == 1) {
    score <- score + 3
  }

  if (previous_vte == 1) {
    score <- score + 3
  }

  if (reduced_mobility == 1) {
    score <- score + 3
  }

  if (known_thrombophilia == 1) {
    score <- score + 3
  }

  if (recent_trauma_surgery == 1) {
    score <- score + 2
  }

  if (age >= 70) {
    score <- score + 1
  }

  if (heart_respiratory_failure == 1) {
    score <- score + 1
  }

  if (acute_mi_stroke == 1) {
    score <- score + 1
  }

  if (infection_rheumatologic == 1) {
    score <- score + 1
  }

  if (bmi >= 30) {
    score <- score + 1
  }

  if (hormonal_treatment == 1) {
    score <- score + 1
  }

  risk_category <- ""
  recommendation <- ""

  if (score < 4) {
    risk_category <- "Low Risk"
    recommendation <- "No specific prophylaxis indicated (unless clinical judgment overrides)."
  } else {
    risk_category <- "High Risk"
    recommendation <- "Pharmacologic prophylaxis indicated (LMWH, Fondaparinux, or UFH)."
  }

  return(list(
    Padua_Score = score,
    Risk_Category = risk_category,
    Recommendation = recommendation,
    Inputs = list(
      Active_Cancer = active_cancer == 1,
      Prior_VTE = previous_vte == 1,
      Reduced_Mobility = reduced_mobility == 1,
      Thrombophilia = known_thrombophilia == 1,
      Recent_Trauma_Surgery = recent_trauma_surgery == 1,
      Age = age,
      Heart_Resp_Failure = heart_respiratory_failure == 1,
      Acute_MI_Stroke = acute_mi_stroke == 1,
      Infection_Rheum = infection_rheumatologic == 1,
      BMI = bmi,
      Hormonal_Tx = hormonal_treatment == 1
    )
  ))
}

painad_score <- function(breathing, negative_vocalization, facial_expression, body_language, consolability) {

  inputs <- c(breathing, negative_vocalization, facial_expression, body_language, consolability)

  if (any(is.na(inputs))) {
    stop("Error: All inputs must be numeric.")
  }

  if (any(inputs < 0) || any(inputs > 2)) {
    stop("Error: All item scores must be integers between 0 and 2.")
  }

  total_score <- sum(inputs)

  severity <- ""
  if (total_score == 0) {
    severity <- "No Pain"
  } else if (total_score <= 3) {
    severity <- "Mild Pain"
  } else if (total_score <= 6) {
    severity <- "Moderate Pain"
  } else {
    severity <- "Severe Pain"
  }

  return(list(
    PAINAD_Score = total_score,
    Severity = severity,
    Inputs = list(
      Breathing = breathing,
      Vocalization = negative_vocalization,
      Facial = facial_expression,
      Body = body_language,
      Consolability = consolability
    )
  ))
}

peg_pain_scale <- function(pain_average, enjoyment_of_life, general_activity) {

  pain_average <- as.numeric(pain_average)
  enjoyment_of_life <- as.numeric(enjoyment_of_life)
  general_activity <- as.numeric(general_activity)

  if (any(is.na(c(pain_average, enjoyment_of_life, general_activity)))) {
    stop("Error: All inputs must be numeric.")
  }

  if (any(c(pain_average, enjoyment_of_life, general_activity) < 0) ||
      any(c(pain_average, enjoyment_of_life, general_activity) > 10)) {
    stop("Error: All item scores must be integers between 0 and 10.")
  }

  peg_score <- mean(c(pain_average, enjoyment_of_life, general_activity))

  interpretation <- ""
  if (peg_score < 4) {
    interpretation <- "Mild Pain Impact"
  } else if (peg_score <= 6) {
    interpretation <- "Moderate Pain Impact"
  } else {
    interpretation <- "Severe Pain Impact"
  }

  return(list(
    PEG_Score = round(peg_score, 1),
    Interpretation = interpretation,
    Inputs = list(
      Q1_Pain_Avg = pain_average,
      Q2_Enjoyment = enjoyment_of_life,
      Q3_Activity = general_activity
    )
  ))
}

