pancreatic_fistula_risk_score <- function(gland_texture_soft, pathology_is_adeno_or_pancreatitis, duct_diameter_mm, blood_loss_ml) {

  gland_texture_soft <- as.numeric(gland_texture_soft)
  pathology_is_adeno_or_pancreatitis <- as.numeric(pathology_is_adeno_or_pancreatitis)
  duct_diameter_mm <- as.numeric(duct_diameter_mm)
  blood_loss_ml <- as.numeric(blood_loss_ml)

  if (any(is.na(c(gland_texture_soft, pathology_is_adeno_or_pancreatitis, duct_diameter_mm, blood_loss_ml)))) {
    stop("Error: All inputs must be numeric.")
  }

  score <- 0

  if (gland_texture_soft == 1) {
    score <- score + 2
  }

  if (pathology_is_adeno_or_pancreatitis == 0) {
    score <- score + 1
  }

  if (duct_diameter_mm >= 5) {
    score <- score + 0
  } else if (duct_diameter_mm >= 4) {
    score <- score + 1
  } else if (duct_diameter_mm >= 3) {
    score <- score + 2
  } else if (duct_diameter_mm >= 2) {
    score <- score + 3
  } else {
    score <- score + 4
  }

  if (blood_loss_ml <= 400) {
    score <- score + 0
  } else if (blood_loss_ml <= 700) {
    score <- score + 1
  } else if (blood_loss_ml <= 1000) {
    score <- score + 2
  } else {
    score <- score + 3
  }

  risk_category <- ""
  fistula_risk_percent <- ""

  if (score == 0) {
    risk_category <- "Negligible Risk"
    fistula_risk_percent <- "0%"
  } else if (score <= 2) {
    risk_category <- "Low Risk"
    fistula_risk_percent <- "6 - 10%"
  } else if (score <= 6) {
    risk_category <- "Intermediate Risk"
    fistula_risk_percent <- "20 - 28%"
  } else {
    risk_category <- "High Risk"
    fistula_risk_percent <- "> 60%"
  }

  return(list(
    Fistula_Risk_Score = score,
    Risk_Category = risk_category,
    Est_Pancreatic_Fistula_Risk = fistula_risk_percent,
    Inputs = list(
      Soft_Gland = gland_texture_soft == 1,
      High_Risk_Pathology_Other = pathology_is_adeno_or_pancreatitis == 0,
      Duct_Diameter_mm = duct_diameter_mm,
      Blood_Loss_ml = blood_loss_ml
    )
  ))
}

paradise_criteria_tonsillectomy <- function(episodes_past_12_months, episodes_per_year_last_2_years, episodes_per_year_last_3_years, clinical_features_confirmed, antibiotics_given_documented) {

  episodes_past_12_months <- as.numeric(episodes_past_12_months)
  episodes_per_year_last_2_years <- as.numeric(episodes_per_year_last_2_years)
  episodes_per_year_last_3_years <- as.numeric(episodes_per_year_last_3_years)
  clinical_features_confirmed <- as.numeric(clinical_features_confirmed)
  antibiotics_given_documented <- as.numeric(antibiotics_given_documented)

  if (is.na(episodes_past_12_months)) episodes_past_12_months <- 0
  if (is.na(episodes_per_year_last_2_years)) episodes_per_year_last_2_years <- 0
  if (is.na(episodes_per_year_last_3_years)) episodes_per_year_last_3_years <- 0

  if (any(is.na(c(clinical_features_confirmed, antibiotics_given_documented)))) {
    stop("Error: Confirmation inputs must be numeric (0 or 1).")
  }

  frequency_met <- FALSE

  if (episodes_past_12_months >= 7) {
    frequency_met <- TRUE
  } else if (episodes_per_year_last_2_years >= 5) {
    frequency_met <- TRUE
  } else if (episodes_per_year_last_3_years >= 3) {
    frequency_met <- TRUE
  }

  qualifying_episodes <- (clinical_features_confirmed == 1 && antibiotics_given_documented == 1)

  recommendation <- ""

  if (frequency_met && qualifying_episodes) {
    recommendation <- "Criteria Met for Tonsillectomy"
  } else {
    recommendation <- "Criteria Not Met. Observation recommended."
  }

  return(list(
    Result = recommendation,
    Inputs = list(
      Episodes_1y = episodes_past_12_months,
      Episodes_2y_Avg = episodes_per_year_last_2_years,
      Episodes_3y_Avg = episodes_per_year_last_3_years,
      Clinical_Features_Met = clinical_features_confirmed == 1,
      Documentation_Met = antibiotics_given_documented == 1
    )
  ))
}

parkland_burn_formula <- function(weight_kg, tbsa_percent) {

  weight_kg <- as.numeric(weight_kg)
  tbsa_percent <- as.numeric(tbsa_percent)

  if (any(is.na(c(weight_kg, tbsa_percent)))) {
    stop("Error: All inputs must be numeric.")
  }

  if (weight_kg <= 0 || tbsa_percent <= 0) {
    stop("Error: Weight and TBSA must be positive.")
  }

  total_fluid_24h <- 4 * weight_kg * tbsa_percent

  first_8h_volume <- total_fluid_24h / 2
  next_16h_volume <- total_fluid_24h / 2

  rate_first_8h <- first_8h_volume / 8
  rate_next_16h <- next_16h_volume / 16

  return(list(
    Total_Fluid_24h_mL = round(total_fluid_24h, 0),
    First_8h_Volume_mL = round(first_8h_volume, 0),
    First_8h_Rate_mL_hr = round(rate_first_8h, 1),
    Next_16h_Volume_mL = round(next_16h_volume, 0),
    Next_16h_Rate_mL_hr = round(rate_next_16h, 1),
    Inputs = list(
      Weight_kg = weight_kg,
      TBSA_Percent = tbsa_percent
    )
  ))
}

patient_activity_scale_ra <- function(pain_vas, patient_global_vas, haq_ii_items) {

  pain_vas <- as.numeric(pain_vas)
  patient_global_vas <- as.numeric(patient_global_vas)

  if (any(is.na(c(pain_vas, patient_global_vas)))) {
    stop("Error: Pain and Patient Global VAS must be numeric.")
  }

  if (pain_vas < 0 || pain_vas > 10 || patient_global_vas < 0 || patient_global_vas > 10) {
    stop("Error: VAS scores must be between 0 and 10.")
  }

  if (length(haq_ii_items) != 10) {
    stop("Error: HAQ-II requires exactly 10 item scores.")
  }

  if (any(haq_ii_items < 0) || any(haq_ii_items > 3)) {
    stop("Error: HAQ-II item scores must be between 0 (No difficulty) and 3 (Unable to do).")
  }

  mean_haq <- mean(haq_ii_items)
  haq_ii_score <- mean_haq * 3.33

  pas_score <- (pain_vas * 3.33 + patient_global_vas * 3.33 + haq_ii_score * 3.33) / 3

  pas_ii_score <- (pain_vas * 3.33 + patient_global_vas * 3.33 + haq_ii_score * 3.33) / 3.33

  disease_activity <- ""
  if (pas_ii_score <= 0.25) {
    disease_activity <- "Remission"
  } else if (pas_ii_score <= 3.7) {
    disease_activity <- "Low Activity"
  } else if (pas_ii_score < 8.0) {
    disease_activity <- "Moderate Activity"
  } else {
    disease_activity <- "High Activity"
  }

  return(list(
    PAS_Score = round(pas_score, 2),
    PAS_II_Score = round(pas_ii_score, 2),
    Disease_Activity = disease_activity,
    Components = list(
      Pain_Weighted = round(pain_vas * 3.33, 2),
      Global_Weighted = round(patient_global_vas * 3.33, 2),
      HAQ_II_Score = round(haq_ii_score, 2)
    )
  ))
}

pawss_score <- function(recent_alcohol_use, bal_gt_200, previous_withdrawal, previous_seizures, previous_dts, previous_rehab, blackouts, concurrent_downer_use, concurrent_other_substance_use, autonomic_hyperactivity) {

  inputs <- c(recent_alcohol_use, bal_gt_200, previous_withdrawal, previous_seizures, previous_dts, previous_rehab, blackouts, concurrent_downer_use, concurrent_other_substance_use, autonomic_hyperactivity)

  if (any(is.na(inputs))) {
    stop("Error: All inputs must be numeric.")
  }

  if (any(!inputs %in% c(0, 1))) {
    stop("Error: All inputs must be 0 (No) or 1 (Yes).")
  }

  total_score <- sum(inputs)

  risk_category <- ""
  recommendation <- ""

  if (total_score < 4) {
    risk_category <- "Low Risk"
    recommendation <- "Low risk for complicated alcohol withdrawal syndrome. Routine monitoring is usually sufficient."
  } else {
    risk_category <- "High Risk"
    recommendation <- "High risk for complicated alcohol withdrawal syndrome (seizures/DTs). Prophylaxis and/or admission is recommended."
  }

  return(list(
    PAWSS_Score = total_score,
    Risk_Category = risk_category,
    Recommendation = recommendation,
    Inputs = list(
      Recent_Alcohol = recent_alcohol_use == 1,
      BAL_gt_200 = bal_gt_200 == 1,
      Hx_Withdrawal = previous_withdrawal == 1,
      Hx_Seizures = previous_seizures == 1,
      Hx_DTs = previous_dts == 1,
      Hx_Rehab = previous_rehab == 1,
      Blackouts = blackouts == 1,
      Downers = concurrent_downer_use == 1,
      Other_Substances = concurrent_other_substance_use == 1,
      Autonomic_Activity = autonomic_hyperactivity == 1
    )
  ))
}

preset_ecmo_score <- function(mean_arterial_pressure, lactate, arterial_ph, platelet_count, hospital_days_pre_ecmo) {

  mean_arterial_pressure <- as.numeric(mean_arterial_pressure)
  lactate <- as.numeric(lactate)
  arterial_ph <- as.numeric(arterial_ph)
  platelet_count <- as.numeric(platelet_count)
  hospital_days_pre_ecmo <- as.numeric(hospital_days_pre_ecmo)

  if (any(is.na(c(mean_arterial_pressure, lactate, arterial_ph, platelet_count, hospital_days_pre_ecmo)))) {
    stop("Error: All inputs must be numeric.")
  }

  score <- 0

  if (mean_arterial_pressure > 100) {
    score <- score + 0
  } else if (mean_arterial_pressure >= 91) {
    score <- score + 1
  } else if (mean_arterial_pressure >= 81) {
    score <- score + 2
  } else if (mean_arterial_pressure >= 71) {
    score <- score + 3
  } else {
    score <- score + 4
  }

  if (lactate <= 1.50) {
    score <- score + 0
  } else if (lactate <= 3.00) {
    score <- score + 1
  } else if (lactate <= 6.00) {
    score <- score + 2
  } else if (lactate <= 10.00) {
    score <- score + 3
  } else {
    score <- score + 4
  }

  if (arterial_ph > 7.300) {
    score <- score + 0
  } else if (arterial_ph >= 7.201) {
    score <- score + 1
  } else if (arterial_ph >= 7.101) {
    score <- score + 2
  } else {
    score <- score + 3
  }

  if (platelet_count > 200) {
    score <- score + 0
  } else if (platelet_count >= 101) {
    score <- score + 1
  } else {
    score <- score + 2
  }

  if (hospital_days_pre_ecmo <= 2) {
    score <- score + 0
  } else if (hospital_days_pre_ecmo <= 7) {
    score <- score + 1
  } else {
    score <- score + 2
  }

  risk_class <- ""
  survival_prob <- ""

  if (score <= 3) {
    risk_class <- "Risk Class I"
    survival_prob <- "74%"
  } else if (score <= 5) {
    risk_class <- "Risk Class II"
    survival_prob <- "57%"
  } else {
    risk_class <- "Risk Class III"
    survival_prob <- "22%"
  }

  return(list(
    PRESET_Score = score,
    Risk_Class = risk_class,
    Est_Hospital_Survival = survival_prob,
    Inputs = list(
      MAP = mean_arterial_pressure,
      Lactate = lactate,
      pHa = arterial_ph,
      Platelets = platelet_count,
      Hospital_Days = hospital_days_pre_ecmo
    )
  ))
}

calculate_pregnancy_due_date <- function(input_date, method = "LMP", cycle_length = 28) {

  input_date <- as.Date(input_date)

  if (is.na(input_date)) {
    stop("Error: Invalid date format. Please use YYYY-MM-DD.")
  }

  method <- tolower(method)

  estimated_due_date <- NA

  if (method == "lmp") {
    estimated_due_date <- input_date + 280
    if (cycle_length != 28) {
      estimated_due_date <- estimated_due_date + (cycle_length - 28)
    }
  } else if (method == "conception") {
    estimated_due_date <- input_date + 266
  } else if (method == "ivf_3_day") {
    estimated_due_date <- input_date + 263
  } else if (method == "ivf_5_day") {
    estimated_due_date <- input_date + 261
  } else {
    stop("Error: Method must be 'LMP', 'Conception', 'IVF_3_Day', or 'IVF_5_Day'.")
  }

  current_date <- Sys.Date()
  days_gestation <- as.numeric(current_date - (estimated_due_date - 280))

  weeks <- days_gestation %/% 7
  days <- days_gestation %% 7

  trimester <- ""
  if (weeks < 14) {
    trimester <- "1st Trimester"
  } else if (weeks < 28) {
    trimester <- "2nd Trimester"
  } else {
    trimester <- "3rd Trimester"
  }

  return(list(
    Estimated_Due_Date = format(estimated_due_date, "%Y-%m-%d"),
    Gestational_Age = paste0(weeks, " weeks, ", days, " days"),
    Current_Trimester = trimester,
    Inputs = list(
      Date_Provided = input_date,
      Method = method,
      Cycle_Length = if(method == "lmp") cycle_length else "N/A"
    )
  ))
}

pmp_mortality_score <- function(age, inpatient_status, sepsis, poor_functional_status, disseminated_cancer, cardiac_comorbidity, pulmonary_comorbidity, renal_comorbidity, liver_comorbidity, steroid_use, weight_loss, bleeding_disorder, dnr_status, obesity) {

  age <- as.numeric(age)
  inpatient_status <- as.numeric(inpatient_status)
  sepsis <- as.numeric(sepsis)
  poor_functional_status <- as.numeric(poor_functional_status)
  disseminated_cancer <- as.numeric(disseminated_cancer)
  cardiac_comorbidity <- as.numeric(cardiac_comorbidity)
  pulmonary_comorbidity <- as.numeric(pulmonary_comorbidity)
  renal_comorbidity <- as.numeric(renal_comorbidity)
  liver_comorbidity <- as.numeric(liver_comorbidity)
  steroid_use <- as.numeric(steroid_use)
  weight_loss <- as.numeric(weight_loss)
  bleeding_disorder <- as.numeric(bleeding_disorder)
  dnr_status <- as.numeric(dnr_status)
  obesity <- as.numeric(obesity)

  if (any(is.na(c(age, inpatient_status, sepsis, poor_functional_status, disseminated_cancer, cardiac_comorbidity, pulmonary_comorbidity, renal_comorbidity, liver_comorbidity, steroid_use, weight_loss, bleeding_disorder, dnr_status, obesity)))) {
    stop("Error: All inputs must be numeric (0 or 1 for binary, age in years).")
  }

  score <- 0

  if (age < 65) {
    score <- score + 0
  } else if (age >= 65 && age <= 69) {
    score <- score + 0.5
  } else if (age >= 70 && age <= 79) {
    score <- score + 1
  } else {
    score <- score + 2
  }

  if (inpatient_status == 1) score <- score + 6

  if (sepsis == 1) score <- score + 4

  if (poor_functional_status == 1) score <- score + 3

  if (disseminated_cancer == 1) score <- score + 1

  if (cardiac_comorbidity == 1) score <- score + 5

  if (pulmonary_comorbidity == 1) score <- score + 3

  if (renal_comorbidity == 1) score <- score + 1

  if (liver_comorbidity == 1) score <- score + 1

  if (steroid_use == 1) score <- score + 1

  if (weight_loss == 1) score <- score + 1

  if (bleeding_disorder == 1) score <- score + 1

  if (dnr_status == 1) score <- score + 1

  if (obesity == 1) score <- score - 1

  return(list(
    PMP_Score = score,
    Interpretation = "Higher scores indicate increased risk of 30-day postoperative mortality.",
    Inputs = list(
      Age = age,
      Inpatient = inpatient_status == 1,
      Sepsis = sepsis == 1,
      Poor_Function = poor_functional_status == 1,
      Disseminated_Cancer = disseminated_cancer == 1,
      Cardiac = cardiac_comorbidity == 1,
      Pulmonary = pulmonary_comorbidity == 1,
      Renal = renal_comorbidity == 1,
      Liver = liver_comorbidity == 1,
      Steroids = steroid_use == 1,
      Weight_Loss = weight_loss == 1,
      Bleeding_Disorder = bleeding_disorder == 1,
      DNR = dnr_status == 1,
      Obesity = obesity == 1
    )
  ))
}

prevail_prostate_cancer_survival <- function(albumin_g_l, alkaline_phosphatase_u_l, hemoglobin_g_dl, ldh_u_l, neutrophil_lymphocyte_ratio, bone_metastases_gt_10, visceral_disease, pain_score, psa_ng_ml, months_since_diagnosis) {

  albumin_g_l <- as.numeric(albumin_g_l)
  alkaline_phosphatase_u_l <- as.numeric(alkaline_phosphatase_u_l)
  hemoglobin_g_dl <- as.numeric(hemoglobin_g_dl)
  ldh_u_l <- as.numeric(ldh_u_l)
  neutrophil_lymphocyte_ratio <- as.numeric(neutrophil_lymphocyte_ratio)
  bone_metastases_gt_10 <- as.numeric(bone_metastases_gt_10)
  visceral_disease <- as.numeric(visceral_disease)
  pain_score <- as.numeric(pain_score)
  psa_ng_ml <- as.numeric(psa_ng_ml)
  months_since_diagnosis <- as.numeric(months_since_diagnosis)

  if (any(is.na(c(albumin_g_l, alkaline_phosphatase_u_l, hemoglobin_g_dl, ldh_u_l, neutrophil_lymphocyte_ratio, bone_metastases_gt_10, visceral_disease, pain_score, psa_ng_ml, months_since_diagnosis)))) {
    stop("Error: All inputs must be numeric.")
  }

  if (pain_score < 0 || pain_score > 10) {
    stop("Error: Pain score must be between 0 and 10.")
  }

  if (alkaline_phosphatase_u_l <= 0 || ldh_u_l <= 0 || psa_ng_ml <= 0 || neutrophil_lymphocyte_ratio <= 0 || months_since_diagnosis <= 0) {
    stop("Error: Logarithmic inputs (ALP, LDH, PSA, NLR, Time) must be greater than 0.")
  }

  log_alp <- log(alkaline_phosphatase_u_l)
  log_ldh <- log(ldh_u_l)
  log_psa <- log(psa_ng_ml)
  log_nlr <- log(neutrophil_lymphocyte_ratio)
  log_time <- log(months_since_diagnosis)

  prognostic_index <- (0.34 * log_alp) + (0.58 * log_ldh) + (0.11 * log_psa) + (0.25 * log_nlr) - (0.046 * albumin_g_l) - (0.13 * hemoglobin_g_dl) + (0.07 * pain_score) + (0.35 * bone_metastases_gt_10) + (0.36 * visceral_disease) - (0.20 * log_time)

  risk_group <- ""
  if (prognostic_index < 1.5) {
    risk_group <- "Low Risk"
  } else if (prognostic_index >= 1.5 && prognostic_index < 2.5) {
    risk_group <- "Intermediate Risk"
  } else {
    risk_group <- "High Risk"
  }

  return(list(
    Prognostic_Index = round(prognostic_index, 2),
    Risk_Group = risk_group,
    Inputs = list(
      Albumin = albumin_g_l,
      ALP = alkaline_phosphatase_u_l,
      Hb = hemoglobin_g_dl,
      LDH = ldh_u_l,
      NLR = neutrophil_lymphocyte_ratio,
      High_Vol_Bone_Mets = bone_metastases_gt_10 == 1,
      Visceral_Disease = visceral_disease == 1,
      Pain = pain_score,
      PSA = psa_ng_ml,
      Time_Since_Dx = months_since_diagnosis
    )
  ))
}

piama_risk_score <- function(sex, gestational_age_gt_40_weeks, parental_education_low_intermediate, parental_asthma, eczema, wheezing_frequency, wheezing_apart_from_colds, inhaled_medication) {

  sex <- tolower(as.character(sex))
  gestational_age_gt_40_weeks <- as.numeric(gestational_age_gt_40_weeks)
  parental_education_low_intermediate <- as.numeric(parental_education_low_intermediate)
  parental_asthma <- as.numeric(parental_asthma)
  eczema <- as.numeric(eczema)
  wheezing_frequency <- tolower(as.character(wheezing_frequency))
  wheezing_apart_from_colds <- as.numeric(wheezing_apart_from_colds)
  inhaled_medication <- as.numeric(inhaled_medication)

  if (!sex %in% c("male", "female")) {
    stop("Error: Sex must be 'male' or 'female'.")
  }

  if (!wheezing_frequency %in% c("none", "1_to_3", "4_or_more")) {
    stop("Error: Wheezing frequency must be 'none', '1_to_3', or '4_or_more'.")
  }

  if (any(is.na(c(gestational_age_gt_40_weeks, parental_education_low_intermediate, parental_asthma, eczema, wheezing_apart_from_colds, inhaled_medication)))) {
    stop("Error: All binary inputs must be numeric (0 or 1).")
  }

  score <- 0

  if (sex == "male") {
    score <- score + 2
  }

  if (gestational_age_gt_40_weeks == 1) {
    score <- score + 1
  }

  if (parental_education_low_intermediate == 1) {
    score <- score + 1
  }

  if (parental_asthma == 1) {
    score <- score + 2
  }

  if (eczema == 1) {
    score <- score + 1
  }

  if (wheezing_frequency == "1_to_3") {
    score <- score + 1
  } else if (wheezing_frequency == "4_or_more") {
    score <- score + 5
  }

  if (wheezing_apart_from_colds == 1) {
    score <- score + 2
  }

  if (inhaled_medication == 1) {
    score <- score + 4
  }

  risk_percent <- ""
  if (score <= 5) {
    risk_percent <- "3.4%"
  } else if (score <= 10) {
    risk_percent <- "13.0%"
  } else if (score <= 15) {
    risk_percent <- "34.4%"
  } else {
    risk_percent <- "57.1%"
  }

  return(list(
    PIAMA_Score = score,
    Asthma_Risk_Age_8 = risk_percent,
    Inputs = list(
      Sex = sex,
      Post_Term = gestational_age_gt_40_weeks == 1,
      Low_Int_Education = parental_education_low_intermediate == 1,
      Parental_Asthma = parental_asthma == 1,
      Eczema = eczema == 1,
      Wheezing_Frequency = wheezing_frequency,
      Wheeze_No_Cold = wheezing_apart_from_colds == 1,
      Inhaled_Meds = inhaled_medication == 1
    )
  ))
}

priest_score <- function(sex, age_years, respiratory_rate, oxygen_saturation, heart_rate, systolic_bp, temperature, alertness_status, performance_status) {

  sex <- tolower(as.character(sex))
  age_years <- as.numeric(age_years)
  respiratory_rate <- as.numeric(respiratory_rate)
  oxygen_saturation <- as.numeric(oxygen_saturation)
  heart_rate <- as.numeric(heart_rate)
  systolic_bp <- as.numeric(systolic_bp)
  temperature <- as.numeric(temperature)
  alertness_status <- tolower(as.character(alertness_status))
  performance_status <- as.numeric(performance_status)

  if (any(is.na(c(age_years, respiratory_rate, oxygen_saturation, heart_rate, systolic_bp, temperature, performance_status)))) {
    stop("Error: All physiological and status inputs must be numeric.")
  }

  score <- 0

  if (sex == "male") {
    score <- score + 1
  }

  if (age_years >= 50 && age_years <= 64) score <- score + 2
  else if (age_years >= 65 && age_years <= 79) score <- score + 3
  else if (age_years >= 80) score <- score + 4

  if (respiratory_rate > 24) {
    score <- score + 3
  } else if (respiratory_rate >= 21 && respiratory_rate <= 24) {
    score <- score + 2
  }

  if (oxygen_saturation < 92) {
    score <- score + 3
  } else if (oxygen_saturation == 92 || oxygen_saturation == 93) {
    score <- score + 2
  } else if (oxygen_saturation == 94 || oxygen_saturation == 95) {
    score <- score + 1
  }

  if (heart_rate > 130) {
    score <- score + 3
  } else if (heart_rate >= 111 && heart_rate <= 130) {
    score <- score + 2
  } else if (heart_rate >= 91 && heart_rate <= 110) {
    score <- score + 1
  }

  if (systolic_bp < 90) {
    score <- score + 3
  } else if (systolic_bp >= 90 && systolic_bp <= 100) {
    score <- score + 2
  } else if (systolic_bp >= 101 && systolic_bp <= 110) {
    score <- score + 1
  }

  if (temperature < 35.0) {
    score <- score + 3
  } else if (temperature >= 35.0 && temperature <= 36.0) {
    score <- score + 2
  } else if (temperature >= 36.1 && temperature <= 38.0) {
    score <- score + 0
  } else if (temperature >= 38.1 && temperature <= 39.0) {
    score <- score + 1
  } else if (temperature > 39.0) {
    score <- score + 2
  }

  if (alertness_status == "confused_or_not_alert") {
    score <- score + 3
  }

  if (performance_status == 0) {
    score <- score + 0
  } else if (performance_status == 1 || performance_status == 2) {
    score <- score + 1
  } else if (performance_status == 3 || performance_status == 4) {
    score <- score + 3
  } else {
    stop("Error: Performance status must be 0, 1, 2, 3, or 4.")
  }

  risk_category <- ""
  risk_percentage <- ""

  if (score <= 4) {
    risk_category <- "Low Risk (Score 0-4)"
    risk_percentage <- "1% risk of death or organ support"
  } else if (score <= 8) {
    risk_category <- "Medium Risk (Score 5-8)"
    risk_percentage <- "10% risk of death or organ support"
  } else if (score <= 15) {
    risk_category <- "High Risk (Score 9-15)"
    risk_percentage <- "37% risk of death or organ support"
  } else {
    risk_category <- "Very High Risk (Score > 15)"
    risk_percentage <- "62% risk of death or organ support"
  }

  return(list(
    PRIEST_Score = score,
    Risk_Category = risk_category,
    Outcome_Prediction_30_Day = risk_percentage,
    Inputs = list(
      Sex = sex,
      Age = age_years,
      RR = respiratory_rate,
      SpO2 = oxygen_saturation,
      HR = heart_rate,
      SBP = systolic_bp,
      Temp = temperature,
      Alertness = alertness_status,
      Performance_Status = performance_status
    )
  ))
}

pc_ptsd_5_screen <- function(traumatic_event_exposure, nightmares_intrusive_thoughts, avoidance, hyperarousal_startle, emotional_numbness, guilt_blame) {

  traumatic_event_exposure <- as.numeric(traumatic_event_exposure)
  nightmares_intrusive_thoughts <- as.numeric(nightmares_intrusive_thoughts)
  avoidance <- as.numeric(avoidance)
  hyperarousal_startle <- as.numeric(hyperarousal_startle)
  emotional_numbness <- as.numeric(emotional_numbness)
  guilt_blame <- as.numeric(guilt_blame)

  if (any(is.na(c(traumatic_event_exposure, nightmares_intrusive_thoughts, avoidance, hyperarousal_startle, emotional_numbness, guilt_blame)))) {
    stop("Error: All inputs must be numeric (0 or 1).")
  }

  if (traumatic_event_exposure == 0) {
    return(list(
      Result = "Negative Screen (No trauma exposure)",
      PC_PTSD_5_Score = 0,
      Recommendation = "Screening complete. No further assessment for PTSD indicated based on this tool."
    ))
  }

  score <- nightmares_intrusive_thoughts + avoidance + hyperarousal_startle + emotional_numbness + guilt_blame

  result <- ""
  recommendation <- ""

  if (score >= 3) {
    result <- "Positive Screen for PTSD"
    recommendation <- "Further assessment with a structured interview (e.g., CAPS-5) or referral to a mental health professional is indicated."
  } else {
    result <- "Negative Screen for PTSD"
    recommendation <- "Monitor. If clinical suspicion remains high, consider further evaluation."
  }

  return(list(
    PC_PTSD_5_Score = score,
    Screening_Result = result,
    Recommendation = recommendation,
    Inputs = list(
      Trauma_Exposure = traumatic_event_exposure == 1,
      Reexperiencing = nightmares_intrusive_thoughts == 1,
      Avoidance = avoidance == 1,
      Hyperarousal = hyperarousal_startle == 1,
      Numbness_Detachment = emotional_numbness == 1,
      Guilt_Blame = guilt_blame == 1
    )
  ))
}

prognostic_index_cancer <- function(crp_mg_l, wbc_count_x10_9_l) {

  crp_mg_l <- as.numeric(crp_mg_l)
  wbc_count_x10_9_l <- as.numeric(wbc_count_x10_9_l)

  if (any(is.na(c(crp_mg_l, wbc_count_x10_9_l)))) {
    stop("Error: Inputs must be numeric.")
  }

  crp_elevated <- crp_mg_l > 10
  wbc_elevated <- wbc_count_x10_9_l > 11

  score <- 0

  if (!crp_elevated && !wbc_elevated) {
    score <- 0
  } else if (crp_elevated && wbc_elevated) {
    score <- 2
  } else {
    score <- 1
  }

  prognosis <- ""
  if (score == 0) {
    prognosis <- "Good Prognosis"
  } else if (score == 1) {
    prognosis <- "Intermediate Prognosis"
  } else {
    prognosis <- "Poor Prognosis"
  }

  return(list(
    PI_Score = score,
    Prognosis_Group = prognosis,
    Inputs = list(
      CRP_mg_L = crp_mg_l,
      WBC_Count = wbc_count_x10_9_l
    )
  ))
}

promise_score_mpe <- function(hemoglobin_g_dl, crp_mg_l, wbc_count, ecog_score, cancer_type) {

  hemoglobin_g_dl <- as.numeric(hemoglobin_g_dl)
  crp_mg_l <- as.numeric(crp_mg_l)
  wbc_count <- as.numeric(wbc_count)
  ecog_score <- as.numeric(ecog_score)
  cancer_type <- tolower(as.character(cancer_type))

  if (any(is.na(c(hemoglobin_g_dl, crp_mg_l, wbc_count, ecog_score)))) {
    stop("Error: All inputs must be numeric.")
  }

  score <- 0

  if (hemoglobin_g_dl < 10) {
    score <- score + 2
  } else if (hemoglobin_g_dl < 12) {
    score <- score + 1
  } else {
    score <- score + 0
  }

  if (crp_mg_l >= 100) {
    score <- score + 2
  } else if (crp_mg_l >= 50) {
    score <- score + 1
  } else {
    score <- score + 0
  }

  if (wbc_count >= 12) {
    score <- score + 1
  } else {
    score <- score + 0
  }

  if (ecog_score >= 3) {
    score <- score + 4
  } else if (ecog_score == 2) {
    score <- score + 2
  } else {
    score <- score + 0
  }

  if (cancer_type == "mesothelioma") {
    score <- score + 4
  } else if (cancer_type %in% c("hematologic", "breast", "gynecologic")) {
    score <- score + 0
  } else {
    score <- score + 2
  }

  risk_group <- ""
  survival_3mo <- ""
  median_survival <- ""

  if (score <= 1) {
    risk_group <- "Group A (Low Risk)"
    survival_3mo <- "~90%"
    median_survival <- "339 days"
  } else if (score <= 4) {
    risk_group <- "Group B (Intermediate Risk)"
    survival_3mo <- "~75%"
    median_survival <- "135 days"
  } else if (score <= 6) {
    risk_group <- "Group C (High Risk)"
    survival_3mo <- "~50%"
    median_survival <- "54 days"
  } else {
    risk_group <- "Group D (Very High Risk)"
    survival_3mo <- "~20%"
    median_survival <- "24 days"
  }

  return(list(
    PROMISE_Score = score,
    Risk_Group = risk_group,
    Est_3_Month_Survival = survival_3mo,
    Median_Survival = median_survival,
    Inputs = list(
      Hb = hemoglobin_g_dl,
      CRP = crp_mg_l,
      WBC = wbc_count,
      ECOG = ecog_score,
      Cancer_Type = cancer_type
    )
  ))
}

prostate_tumor_volume_density <- function(prostate_length_cm, prostate_width_cm, prostate_height_cm, psa_ng_ml) {

  prostate_length_cm <- as.numeric(prostate_length_cm)
  prostate_width_cm <- as.numeric(prostate_width_cm)
  prostate_height_cm <- as.numeric(prostate_height_cm)
  psa_ng_ml <- as.numeric(psa_ng_ml)

  if (any(is.na(c(prostate_length_cm, prostate_width_cm, prostate_height_cm, psa_ng_ml)))) {
    stop("Error: All inputs must be numeric.")
  }

  if (prostate_length_cm <= 0 || prostate_width_cm <= 0 || prostate_height_cm <= 0 || psa_ng_ml <= 0) {
    stop("Error: All inputs must be positive numbers.")
  }

  prostate_volume <- 0.52 * prostate_length_cm * prostate_width_cm * prostate_height_cm

  psa_density <- psa_ng_ml / prostate_volume

  return(list(
    Prostate_Volume_cc = round(prostate_volume, 1),
    PSA_Density_ng_ml_cc = round(psa_density, 2),
    Inputs = list(
      Length_cm = prostate_length_cm,
      Width_cm = prostate_width_cm,
      Height_cm = prostate_height_cm,
      PSA_ng_mL = psa_ng_ml
    )
  ))
}

psa_doubling_time <- function(psa_date1, psa_value1, psa_date2, psa_value2, psa_date3 = NULL, psa_value3 = NULL) {

  psa_dates <- c(as.Date(psa_date1), as.Date(psa_date2))
  psa_values <- c(as.numeric(psa_value1), as.numeric(psa_value2))

  if (!is.null(psa_date3) && !is.null(psa_value3)) {
    psa_dates <- c(psa_dates, as.Date(psa_date3))
    psa_values <- c(psa_values, as.numeric(psa_value3))
  }

  if (any(is.na(psa_values)) || any(is.na(psa_dates))) {
    stop("Error: Invalid PSA values or dates. Ensure dates are YYYY-MM-DD and values are numeric.")
  }

  if (any(psa_values <= 0)) {
    stop("Error: PSA values must be greater than 0 for log calculation.")
  }

  time_months <- as.numeric(difftime(psa_dates, psa_dates[1], units = "days")) / 30.4375

  log_psa <- log(psa_values)

  model <- lm(log_psa ~ time_months)
  slope <- coef(model)[["time_months"]]

  doubling_time_months <- NA
  if (slope > 0) {
    doubling_time_months <- log(2) / slope
  } else {
    return(list(
      PSA_Doubling_Time_Months = "Infinity (PSA is stable or decreasing)",
      Slope = slope
    ))
  }

  return(list(
    PSA_Doubling_Time_Months = round(doubling_time_months, 2),
    Inputs = list(
      Dates = as.character(psa_dates),
      PSA_Values = psa_values
    )
  ))
}

psi_port_score <- function(age, sex, nursing_home, neoplastic_disease, liver_disease, congestive_heart_failure, cerebrovascular_disease, renal_disease, altered_mental_status, respiratory_rate, systolic_bp, temperature_c, heart_rate, arterial_ph, bun_mg_dl, sodium_mmol_l, glucose_mg_dl, hematocrit_percent, pao2_mmhg, pleural_effusion, sao2_percent = NULL) {

  age <- as.numeric(age)
  sex <- tolower(as.character(sex))
  nursing_home <- as.numeric(nursing_home)
  neoplastic_disease <- as.numeric(neoplastic_disease)
  liver_disease <- as.numeric(liver_disease)
  congestive_heart_failure <- as.numeric(congestive_heart_failure)
  cerebrovascular_disease <- as.numeric(cerebrovascular_disease)
  renal_disease <- as.numeric(renal_disease)
  altered_mental_status <- as.numeric(altered_mental_status)
  respiratory_rate <- as.numeric(respiratory_rate)
  systolic_bp <- as.numeric(systolic_bp)
  temperature_c <- as.numeric(temperature_c)
  heart_rate <- as.numeric(heart_rate)
  arterial_ph <- as.numeric(arterial_ph)
  bun_mg_dl <- as.numeric(bun_mg_dl)
  sodium_mmol_l <- as.numeric(sodium_mmol_l)
  glucose_mg_dl <- as.numeric(glucose_mg_dl)
  hematocrit_percent <- as.numeric(hematocrit_percent)
  pao2_mmhg <- as.numeric(pao2_mmhg)
  pleural_effusion <- as.numeric(pleural_effusion)

  if (any(is.na(c(age, nursing_home, neoplastic_disease, liver_disease, congestive_heart_failure, cerebrovascular_disease, renal_disease, altered_mental_status, respiratory_rate, systolic_bp, temperature_c, heart_rate, arterial_ph, bun_mg_dl, sodium_mmol_l, glucose_mg_dl, hematocrit_percent, pao2_mmhg, pleural_effusion)))) {
    stop("Error: All core inputs must be numeric.")
  }

  if (!sex %in% c("male", "female")) {
    stop("Error: Sex must be 'male' or 'female'.")
  }

  score <- age

  if (sex == "female") {
    score <- score - 10
  }

  if (nursing_home == 1) score <- score + 10
  if (neoplastic_disease == 1) score <- score + 30
  if (liver_disease == 1) score <- score + 20
  if (congestive_heart_failure == 1) score <- score + 10
  if (cerebrovascular_disease == 1) score <- score + 10
  if (renal_disease == 1) score <- score + 10

  if (altered_mental_status == 1) score <- score + 20
  if (respiratory_rate >= 30) score <- score + 20
  if (systolic_bp < 90) score <- score + 20
  if (temperature_c < 35 || temperature_c >= 40) score <- score + 15
  if (heart_rate >= 125) score <- score + 10

  if (arterial_ph < 7.35) score <- score + 30
  if (bun_mg_dl >= 30) score <- score + 20
  if (sodium_mmol_l < 130) score <- score + 20
  if (glucose_mg_dl >= 250) score <- score + 10
  if (hematocrit_percent < 30) score <- score + 10

  oxygen_points <- 0
  if (pao2_mmhg < 60) {
    oxygen_points <- 10
  } else if (!is.null(sao2_percent)) {
    if (as.numeric(sao2_percent) < 90) {
      oxygen_points <- 10
    }
  }
  score <- score + oxygen_points

  if (pleural_effusion == 1) score <- score + 10

  risk_class <- ""
  mortality <- ""
  recommendation <- ""

  if (score <= 70) {
    risk_class <- "Class II (Low Risk)"
    mortality <- "0.6% - 0.9%"
    recommendation <- "Outpatient Care"
  } else if (score <= 90) {
    risk_class <- "Class III (Low Risk)"
    mortality <- "0.9% - 2.8%"
    recommendation <- "Outpatient or Brief Inpatient Observation"
  } else if (score <= 130) {
    risk_class <- "Class IV (Moderate Risk)"
    mortality <- "8.2% - 9.3%"
    recommendation <- "Inpatient Admission"
  } else {
    risk_class <- "Class V (High Risk)"
    mortality <- "27.0% - 31.0%"
    recommendation <- "Inpatient Admission (Consider ICU)"
  }

  return(list(
    PSI_Score = score,
    Risk_Class = risk_class,
    Mortality_Risk = mortality,
    Recommendation = recommendation,
    Inputs = list(
      Age = age,
      Sex = sex,
      Comorbidities = list(
        Nursing_Home = nursing_home == 1,
        Neoplastic = neoplastic_disease == 1,
        Liver = liver_disease == 1,
        CHF = congestive_heart_failure == 1,
        Cerebrovascular = cerebrovascular_disease == 1,
        Renal = renal_disease == 1
      ),
      Exam = list(
        AMS = altered_mental_status == 1,
        RR = respiratory_rate,
        SBP = systolic_bp,
        Temp = temperature_c,
        HR = heart_rate
      ),
      Labs = list(
        pH = arterial_ph,
        BUN = bun_mg_dl,
        Na = sodium_mmol_l,
        Glucose = glucose_mg_dl,
        Hct = hematocrit_percent,
        PaO2 = pao2_mmhg,
        Pleural_Effusion = pleural_effusion == 1
      )
    )
  ))
}

pasi_score <- function(head_erythema, head_induration, head_desquamation, head_area_percent, arms_erythema, arms_induration, arms_desquamation, arms_area_percent, trunk_erythema, trunk_induration, trunk_desquamation, trunk_area_percent, legs_erythema, legs_induration, legs_desquamation, legs_area_percent) {

  inputs_severity <- c(head_erythema, head_induration, head_desquamation, arms_erythema, arms_induration, arms_desquamation, trunk_erythema, trunk_induration, trunk_desquamation, legs_erythema, legs_induration, legs_desquamation)
  inputs_area <- c(head_area_percent, arms_area_percent, trunk_area_percent, legs_area_percent)

  if (any(is.na(c(inputs_severity, inputs_area)))) {
    stop("Error: All inputs must be numeric.")
  }

  if (any(inputs_severity < 0) || any(inputs_severity > 4)) {
    stop("Error: Severity scores must be integers between 0 and 4.")
  }

  if (any(inputs_area < 0) || any(inputs_area > 100)) {
    stop("Error: Area percentages must be between 0 and 100.")
  }

  get_area_score <- function(percent) {
    if (percent == 0) return(0)
    if (percent < 10) return(1)
    if (percent < 30) return(2)
    if (percent < 50) return(3)
    if (percent < 70) return(4)
    if (percent < 90) return(5)
    return(6)
  }

  head_area_score <- get_area_score(head_area_percent)
  arms_area_score <- get_area_score(arms_area_percent)
  trunk_area_score <- get_area_score(trunk_area_percent)
  legs_area_score <- get_area_score(legs_area_percent)

  head_subscore <- (head_erythema + head_induration + head_desquamation) * head_area_score * 0.1
  arms_subscore <- (arms_erythema + arms_induration + arms_desquamation) * arms_area_score * 0.2
  trunk_subscore <- (trunk_erythema + trunk_induration + trunk_desquamation) * trunk_area_score * 0.3
  legs_subscore <- (legs_erythema + legs_induration + legs_desquamation) * legs_area_score * 0.4

  total_score <- head_subscore + arms_subscore + trunk_subscore + legs_subscore

  interpretation <- ""
  if (total_score <= 5) {
    interpretation <- "Mild Psoriasis"
  } else if (total_score <= 10) {
    interpretation <- "Moderate Psoriasis"
  } else {
    interpretation <- "Severe Psoriasis"
  }

  return(list(
    PASI_Score = round(total_score, 1),
    Interpretation = interpretation,
    Subscores = list(
      Head = round(head_subscore, 2),
      Upper_Limbs = round(arms_subscore, 2),
      Trunk = round(trunk_subscore, 2),
      Lower_Limbs = round(legs_subscore, 2)
    )
  ))
}

pesi_score <- function(age, sex, cancer_history, heart_failure_history, chronic_lung_disease, heart_rate, systolic_bp, respiratory_rate, temperature, altered_mental_status, oxygen_saturation) {

  age <- as.numeric(age)
  sex <- tolower(as.character(sex))
  cancer_history <- as.numeric(cancer_history)
  heart_failure_history <- as.numeric(heart_failure_history)
  chronic_lung_disease <- as.numeric(chronic_lung_disease)
  heart_rate <- as.numeric(heart_rate)
  systolic_bp <- as.numeric(systolic_bp)
  respiratory_rate <- as.numeric(respiratory_rate)
  temperature <- as.numeric(temperature)
  altered_mental_status <- as.numeric(altered_mental_status)
  oxygen_saturation <- as.numeric(oxygen_saturation)

  if (any(is.na(c(age, cancer_history, heart_failure_history, chronic_lung_disease, heart_rate, systolic_bp, respiratory_rate, temperature, altered_mental_status, oxygen_saturation)))) {
    stop("Error: All inputs must be numeric.")
  }

  if (!sex %in% c("male", "female")) {
    stop("Error: Sex must be 'male' or 'female'.")
  }

  score <- age

  if (sex == "male") {
    score <- score + 10
  }

  if (cancer_history == 1) {
    score <- score + 30
  }

  if (heart_failure_history == 1) {
    score <- score + 10
  }

  if (chronic_lung_disease == 1) {
    score <- score + 10
  }

  if (heart_rate >= 110) {
    score <- score + 20
  }

  if (systolic_bp < 100) {
    score <- score + 30
  }

  if (respiratory_rate >= 30) {
    score <- score + 20
  }

  if (temperature < 36.0) {
    score <- score + 20
  }

  if (altered_mental_status == 1) {
    score <- score + 60
  }

  if (oxygen_saturation < 90) {
    score <- score + 20
  }

  risk_class <- ""
  mortality_risk <- ""
  recommendation <- ""

  if (score <= 65) {
    risk_class <- "Class I (Very Low Risk)"
    mortality_risk <- "0 - 1.6%"
    recommendation <- "Consider outpatient management."
  } else if (score <= 85) {
    risk_class <- "Class II (Low Risk)"
    mortality_risk <- "1.7 - 3.5%"
    recommendation <- "Consider outpatient management or brief observation."
  } else if (score <= 105) {
    risk_class <- "Class III (Moderate Risk)"
    mortality_risk <- "3.2 - 7.1%"
    recommendation <- "Inpatient admission recommended."
  } else if (score <= 125) {
    risk_class <- "Class IV (High Risk)"
    mortality_risk <- "4.0 - 11.4%"
    recommendation <- "Inpatient admission recommended."
  } else {
    risk_class <- "Class V (Very High Risk)"
    mortality_risk <- "10.0 - 24.5%"
    recommendation <- "Inpatient admission recommended (Consider ICU)."
  }

  return(list(
    PESI_Score = score,
    Risk_Class = risk_class,
    Est_30_Day_Mortality = mortality_risk,
    Recommendation = recommendation,
    Inputs = list(
      Age = age,
      Sex = sex,
      Cancer = cancer_history == 1,
      Heart_Failure = heart_failure_history == 1,
      Chronic_Lung_Disease = chronic_lung_disease == 1,
      HR_ge_110 = heart_rate >= 110,
      SBP_lt_100 = systolic_bp < 100,
      RR_ge_30 = respiratory_rate >= 30,
      Temp_lt_36 = temperature < 36.0,
      Altered_Mental_Status = altered_mental_status == 1,
      O2_Sat_lt_90 = oxygen_saturation < 90
    )
  ))
}

pe_sard_bleeding_score <- function(hemoglobin, syncope, egfr) {

  hemoglobin <- as.numeric(hemoglobin)
  syncope <- as.numeric(syncope)
  egfr <- as.numeric(egfr)

  if (any(is.na(c(hemoglobin, syncope, egfr)))) {
    stop("Error: All inputs must be numeric.")
  }

  score <- 0

  if (hemoglobin < 12.0) {
    score <- score + 2.5
  }

  if (syncope == 1) {
    score <- score + 1.5
  }

  if (egfr < 60) {
    score <- score + 1.0
  }

  risk_class <- ""
  bleeding_risk <- ""

  if (score == 0) {
    risk_class <- "Low Risk"
    bleeding_risk <- "0.9%"
  } else if (score > 0 && score <= 2.5) {
    risk_class <- "Intermediate Risk"
    bleeding_risk <- "~3.0%"
  } else {
    risk_class <- "High Risk"
    bleeding_risk <- "9.0%"
  }

  return(list(
    PE_SARD_Score = score,
    Risk_Class = risk_class,
    Est_Major_Bleeding_Risk = bleeding_risk,
    Inputs = list(
      Anemia_Hb_lt_12 = hemoglobin < 12.0,
      Syncope = syncope == 1,
      Renal_Dysfunction_eGFR_lt_60 = egfr < 60
    )
  ))
}

patient_activity_scale_ii <- function(pain_vas, patient_global_vas, haq_ii_items) {

  pain_vas <- as.numeric(pain_vas)
  patient_global_vas <- as.numeric(patient_global_vas)

  if (any(is.na(c(pain_vas, patient_global_vas)))) {
    stop("Error: Pain and Patient Global VAS must be numeric.")
  }

  if (pain_vas < 0 || pain_vas > 10 || patient_global_vas < 0 || patient_global_vas > 10) {
    stop("Error: VAS scores must be between 0 and 10.")
  }

  if (length(haq_ii_items) != 10) {
    stop("Error: HAQ-II requires exactly 10 item scores.")
  }

  if (any(haq_ii_items < 0) || any(haq_ii_items > 3)) {
    stop("Error: HAQ-II item scores must be between 0 and 3.")
  }

  haq_ii_mean <- mean(haq_ii_items)
  haq_ii_adjusted <- haq_ii_mean * 3.33

  pas_ii_score <- (pain_vas + patient_global_vas + haq_ii_adjusted) / 3

  disease_activity <- ""
  if (pas_ii_score <= 0.25) {
    disease_activity <- "Remission"
  } else if (pas_ii_score <= 3.7) {
    disease_activity <- "Low Activity"
  } else if (pas_ii_score < 8.0) {
    disease_activity <- "Moderate Activity"
  } else {
    disease_activity <- "High Activity"
  }

  return(list(
    PAS_II_Score = round(pas_ii_score, 2),
    Disease_Activity = disease_activity,
    Components = list(
      Pain_VAS = pain_vas,
      Global_VAS = patient_global_vas,
      HAQ_II_Adjusted = round(haq_ii_adjusted, 2)
    )
  ))
}

pecarn_c_spine_rule <- function(gcs_score, altered_mental_status, focal_neurologic_deficit, neck_pain, torticollis, substantial_torso_injury, predisposing_condition, high_risk_mechanism) {

  gcs_score <- as.numeric(gcs_score)
  altered_mental_status <- as.numeric(altered_mental_status)
  focal_neurologic_deficit <- as.numeric(focal_neurologic_deficit)
  neck_pain <- as.numeric(neck_pain)
  torticollis <- as.numeric(torticollis)
  substantial_torso_injury <- as.numeric(substantial_torso_injury)
  predisposing_condition <- as.numeric(predisposing_condition)
  high_risk_mechanism <- as.numeric(high_risk_mechanism)

  if (any(is.na(c(gcs_score, altered_mental_status, focal_neurologic_deficit, neck_pain, torticollis, substantial_torso_injury, predisposing_condition, high_risk_mechanism)))) {
    stop("Error: All inputs must be numeric.")
  }

  if (gcs_score < 3 || gcs_score > 15) {
    stop("Error: GCS score must be between 3 and 15.")
  }

  high_risk <- FALSE
  if (gcs_score < 15) high_risk <- TRUE
  if (altered_mental_status == 1) high_risk <- TRUE
  if (focal_neurologic_deficit == 1) high_risk <- TRUE

  secondary_risk <- FALSE
  if (neck_pain == 1) secondary_risk <- TRUE
  if (torticollis == 1) secondary_risk <- TRUE
  if (substantial_torso_injury == 1) secondary_risk <- TRUE
  if (predisposing_condition == 1) secondary_risk <- TRUE
  if (high_risk_mechanism == 1) secondary_risk <- TRUE

  risk_level <- ""
  recommendation <- ""

  if (high_risk) {
    risk_level <- "High Risk"
    recommendation <- "CT scan of the cervical spine is recommended."
  } else if (secondary_risk) {
    risk_level <- "Intermediate Risk"
    recommendation <- "Radiography (plain films) or observation recommended depending on clinical suspicion."
  } else {
    risk_level <- "Low Risk"
    recommendation <- "No imaging required. Cervical spine injury is highly unlikely."
  }

  return(list(
    Risk_Level = risk_level,
    Recommendation = recommendation,
    Inputs = list(
      GCS = gcs_score,
      AMS = altered_mental_status == 1,
      Focal_Deficit = focal_neurologic_deficit == 1,
      Neck_Pain = neck_pain == 1,
      Torticollis = torticollis == 1,
      Torso_Injury = substantial_torso_injury == 1,
      Predisposing_Condition = predisposing_condition == 1,
      High_Risk_Mechanism = high_risk_mechanism == 1
    )
  ))
}

pecarn_head_injury_rule <- function(age_years, gcs_score, altered_mental_status, signs_of_skull_fracture, severe_mechanism_of_injury, loc_duration_seconds = 0, not_acting_normally = 0, non_frontal_scalp_hematoma = 0, history_of_vomiting = 0, severe_headache = 0) {

  age_years <- as.numeric(age_years)
  gcs_score <- as.numeric(gcs_score)
  altered_mental_status <- as.numeric(altered_mental_status)
  signs_of_skull_fracture <- as.numeric(signs_of_skull_fracture)
  severe_mechanism_of_injury <- as.numeric(severe_mechanism_of_injury)

  if (any(is.na(c(age_years, gcs_score, altered_mental_status, signs_of_skull_fracture, severe_mechanism_of_injury)))) {
    stop("Error: Core inputs must be numeric.")
  }

  risk_category <- ""
  recommendation <- ""
  citbi_risk <- ""

  if (age_years < 2) {

    loc_gt_5s <- as.numeric(loc_duration_seconds) > 5
    not_acting_normally <- as.numeric(not_acting_normally)
    non_frontal_scalp_hematoma <- as.numeric(non_frontal_scalp_hematoma)

    if (gcs_score < 15 || altered_mental_status == 1 || signs_of_skull_fracture == 1) {
      risk_category <- "High Risk"
      citbi_risk <- "4.4%"
      recommendation <- "CT Scan Recommended."
    } else if (non_frontal_scalp_hematoma == 1 || not_acting_normally == 1 || severe_mechanism_of_injury == 1 || loc_gt_5s) {
      risk_category <- "Intermediate Risk"
      citbi_risk <- "0.9%"
      recommendation <- "Observation vs CT Scan based on clinical judgment (experience, multiple findings, worsening symptoms, parental preference)."
    } else {
      risk_category <- "Low Risk"
      citbi_risk <- "< 0.02%"
      recommendation <- "CT Scan NOT Recommended."
    }

  } else {

    history_of_loc <- as.numeric(loc_duration_seconds) > 0
    history_of_vomiting <- as.numeric(history_of_vomiting)
    severe_headache <- as.numeric(severe_headache)

    if (gcs_score < 15 || altered_mental_status == 1 || signs_of_skull_fracture == 1) {
      risk_category <- "High Risk"
      citbi_risk <- "4.3%"
      recommendation <- "CT Scan Recommended."
    } else if (history_of_vomiting == 1 || severe_headache == 1 || severe_mechanism_of_injury == 1 || history_of_loc) {
      risk_category <- "Intermediate Risk"
      citbi_risk <- "0.9%"
      recommendation <- "Observation vs CT Scan based on clinical judgment."
    } else {
      risk_category <- "Low Risk"
      citbi_risk <- "< 0.05%"
      recommendation <- "CT Scan NOT Recommended."
    }
  }

  return(list(
    Risk_Group = risk_category,
    Risk_of_ciTBI = citbi_risk,
    Recommendation = recommendation,
    Inputs = list(
      Age = age_years,
      GCS = gcs_score,
      AMS = altered_mental_status == 1,
      Skull_Fx_Signs = signs_of_skull_fracture == 1,
      Severe_Mechanism = severe_mechanism_of_injury == 1,
      Specifics = if (age_years < 2) list(Hematoma=non_frontal_scalp_hematoma==1, NotNormal=not_acting_normally==1, LOC_gt_5s=loc_gt_5s) else list(Vomiting=history_of_vomiting==1, Headache=severe_headache==1, Any_LOC=history_of_loc)
    )
  ))
}

pecarn_pediatric_iai_algorithm <- function(abdominal_wall_trauma_seatbelt_sign, gcs_lt_14, abdominal_tenderness, thoracic_wall_trauma, abdominal_pain, decreased_breath_sounds, vomiting) {

  abdominal_wall_trauma_seatbelt_sign <- as.numeric(abdominal_wall_trauma_seatbelt_sign)
  gcs_lt_14 <- as.numeric(gcs_lt_14)
  abdominal_tenderness <- as.numeric(abdominal_tenderness)
  thoracic_wall_trauma <- as.numeric(thoracic_wall_trauma)
  abdominal_pain <- as.numeric(abdominal_pain)
  decreased_breath_sounds <- as.numeric(decreased_breath_sounds)
  vomiting <- as.numeric(vomiting)

  if (any(is.na(c(abdominal_wall_trauma_seatbelt_sign, gcs_lt_14, abdominal_tenderness, thoracic_wall_trauma, abdominal_pain, decreased_breath_sounds, vomiting)))) {
    stop("Error: All inputs must be numeric (0 or 1).")
  }

  risk_factors_count <- abdominal_wall_trauma_seatbelt_sign + gcs_lt_14 + abdominal_tenderness + thoracic_wall_trauma + abdominal_pain + decreased_breath_sounds + vomiting

  risk_category <- ""
  iai_intervention_risk <- ""
  recommendation <- ""

  if (risk_factors_count == 0) {
    risk_category <- "Very Low Risk"
    iai_intervention_risk <- "0.1% (Risk of IAI requiring acute intervention)"
    recommendation <- "CT scan usually not indicated. Observation recommended."
  } else {
    risk_category <- "Not Very Low Risk"
    if (risk_factors_count == 1) {
      iai_intervention_risk <- "1.4% (Risk increases with number of factors)"
    } else if (risk_factors_count == 2) {
      iai_intervention_risk <- "2.7%"
    } else if (risk_factors_count == 3) {
      iai_intervention_risk <- "11.5%"
    } else {
      iai_intervention_risk <- "> 20%"
    }
    recommendation <- "Consider CT scan or observation depending on clinical judgment and number of factors present."
  }

  return(list(
    PECARN_IAI_Risk_Factors = risk_factors_count,
    Risk_Category = risk_category,
    Risk_of_Intervention = iai_intervention_risk,
    Recommendation = recommendation,
    Inputs = list(
      Abdominal_Trauma_Sign = abdominal_wall_trauma_seatbelt_sign == 1,
      GCS_lt_14 = gcs_lt_14 == 1,
      Abdominal_Tenderness = abdominal_tenderness == 1,
      Thoracic_Trauma = thoracic_wall_trauma == 1,
      Abdominal_Pain = abdominal_pain == 1,
      Decreased_Breath_Sounds = decreased_breath_sounds == 1,
      Vomiting = vomiting == 1
    )
  ))
}

pecarn_rule_febrile_infant_29_60_days <- function(urinalysis_positive, absolute_neutrophil_count, procalcitonin) {

  urinalysis_positive <- as.numeric(urinalysis_positive)
  absolute_neutrophil_count <- as.numeric(absolute_neutrophil_count)
  procalcitonin <- as.numeric(procalcitonin)

  if (any(is.na(c(urinalysis_positive, absolute_neutrophil_count, procalcitonin)))) {
    stop("Error: All inputs must be numeric.")
  }

  criteria_count <- 0

  if (urinalysis_positive == 1) {
    criteria_count <- criteria_count + 1
  }

  if (absolute_neutrophil_count > 4090) {
    criteria_count <- criteria_count + 1
  }

  if (procalcitonin > 1.71) {
    criteria_count <- criteria_count + 1
  }

  risk_category <- ""
  recommendation <- ""

  if (criteria_count == 0) {
    risk_category <- "Low Risk"
    recommendation <- "Risk of serious bacterial infection (SBI) is very low (<0.5%). May consider discharge with close follow-up without lumbar puncture or empiric antibiotics, depending on clinical judgment and reliable follow-up."
  } else {
    risk_category <- "Not Low Risk"
    recommendation <- "Risk of serious bacterial infection is elevated. Further evaluation (e.g., lumbar puncture) and empiric antibiotics with observation/admission are generally recommended."
  }

  return(list(
    Risk_Classification = risk_category,
    Recommendation = recommendation,
    Inputs = list(
      UA_Positive = urinalysis_positive == 1,
      ANC_gt_4090 = absolute_neutrophil_count > 4090,
      PCT_gt_1_71 = procalcitonin > 1.71
    )
  ))
}

pediatric_appendicitis_risk_calculator <- function(sex, age_years, pain_duration_hours, abdominal_pain_migration, abdominal_guarding, maximal_tenderness_rlq, absolute_neutrophil_count) {

  sex <- tolower(as.character(sex))
  age_years <- as.numeric(age_years)
  pain_duration_hours <- as.numeric(pain_duration_hours)
  abdominal_pain_migration <- as.numeric(abdominal_pain_migration)
  abdominal_guarding <- as.numeric(abdominal_guarding)
  maximal_tenderness_rlq <- as.numeric(maximal_tenderness_rlq)
  absolute_neutrophil_count <- as.numeric(absolute_neutrophil_count)

  if (any(is.na(c(age_years, pain_duration_hours, abdominal_pain_migration, abdominal_guarding, maximal_tenderness_rlq, absolute_neutrophil_count)))) {
    stop("Error: All inputs must be numeric.")
  }

  if (!sex %in% c("male", "female")) {
    stop("Error: Sex must be 'male' or 'female'.")
  }

  points <- 0

  if (sex == "male") {
    points <- points + 2
  } else {
    points <- points + 0
  }

  if (age_years < 5) {
    points <- points + 0
  } else if (age_years >= 5 && age_years <= 12) {
    points <- points + 7
  } else { # >12 years
    points <- points + 2
  }

  if (pain_duration_hours < 24) {
    points <- points + 0
  } else if (pain_duration_hours >= 24 && pain_duration_hours <= 48) {
    points <- points + 4
  } else { # >48 hours
    points <- points + 1
  }

  if (abdominal_pain_migration == 1) {
    points <- points + 8
  } else {
    points <- points + 0
  }

  if (abdominal_guarding == 1) {
    points <- points + 12
  } else {
    points <- points + 0
  }

  if (maximal_tenderness_rlq == 1) {
    points <- points + 16
  } else {
    points <- points + 0
  }

  if (absolute_neutrophil_count < 6.75) {
    points <- points + 0
  } else if (absolute_neutrophil_count >= 6.75 && absolute_neutrophil_count < 10.75) {
    points <- points + 15
  } else if (absolute_neutrophil_count >= 10.75 && absolute_neutrophil_count < 14.55) {
    points <- points + 30
  } else { # >= 14.55
    points <- points + 49
  }

  risk_probability <- ""

  if (points < 15) {
    risk_probability <- "< 5% (Very Low Risk)"
  } else if (points >= 15 && points < 35) {
    risk_probability <- "5 - 24% (Low Risk)"
  } else if (points >= 35 && points < 60) {
    risk_probability <- "25 - 74% (Moderate Risk)"
  } else {
    risk_probability <- ">= 75% (High Risk)"
  }

  return(list(
    PARC_Score = points,
    Appendicitis_Risk_Probability = risk_probability,
    Inputs = list(
      Sex = sex,
      Age = age_years,
      Pain_Duration_hrs = pain_duration_hours,
      Pain_Migration = abdominal_pain_migration == 1,
      Guarding = abdominal_guarding == 1,
      Max_Tenderness_RLQ = maximal_tenderness_rlq == 1,
      ANC = absolute_neutrophil_count
    )
  ))
}

pediatric_appendicitis_score <- function(cough_hop_pain, anorexia, temperature_c, nausea_vomiting, rlq_tenderness, wbc_count, neutrophil_percent, migration_of_pain) {

  cough_hop_pain <- as.numeric(cough_hop_pain)
  anorexia <- as.numeric(anorexia)
  temperature_c <- as.numeric(temperature_c)
  nausea_vomiting <- as.numeric(nausea_vomiting)
  rlq_tenderness <- as.numeric(rlq_tenderness)
  wbc_count <- as.numeric(wbc_count)
  neutrophil_percent <- as.numeric(neutrophil_percent)
  migration_of_pain <- as.numeric(migration_of_pain)

  if (any(is.na(c(cough_hop_pain, anorexia, temperature_c, nausea_vomiting, rlq_tenderness, wbc_count, neutrophil_percent, migration_of_pain)))) {
    stop("Error: All inputs must be numeric.")
  }

  score <- 0

  if (cough_hop_pain == 1) {
    score <- score + 2
  }

  if (anorexia == 1) {
    score <- score + 1
  }

  if (temperature_c > 38.0) {
    score <- score + 1
  }

  if (nausea_vomiting == 1) {
    score <- score + 1
  }

  if (rlq_tenderness == 1) {
    score <- score + 2
  }

  if (wbc_count > 10000) {
    score <- score + 1
  }

  if (neutrophil_percent > 75) {
    score <- score + 1
  }

  if (migration_of_pain == 1) {
    score <- score + 1
  }

  risk_level <- ""
  recommendation <- ""

  if (score <= 2) {
    risk_level <- "Low Risk"
    recommendation <- "Consider discharge with return precautions. Probability of appendicitis is low (~0-2%)."
  } else if (score <= 6) {
    risk_level <- "Intermediate Risk"
    recommendation <- "Consider imaging (Ultrasound/CT) or surgical consultation. Probability of appendicitis is moderate (~8-48%)."
  } else {
    risk_level <- "High Risk"
    recommendation <- "Surgical consultation indicated. Probability of appendicitis is high (~78-96%)."
  }

  return(list(
    PAS_Score = score,
    Risk_Category = risk_level,
    Recommendation = recommendation,
    Inputs = list(
      Cough_Hop_Pain = cough_hop_pain == 1,
      Anorexia = anorexia == 1,
      Fever_gt_38 = temperature_c > 38.0,
      Nausea_Vomiting = nausea_vomiting == 1,
      RLQ_Tenderness = rlq_tenderness == 1,
      Leukocytosis_gt_10k = wbc_count > 10000,
      Neutrophilia_gt_75pct = neutrophil_percent > 75,
      Pain_Migration = migration_of_pain == 1
    )
  ))
}

pediatric_asthma_score <- function(age, respiratory_rate, oxygen_saturation, on_supplemental_oxygen, retractions, dyspnea, auscultation) {

  age <- as.numeric(age)
  respiratory_rate <- as.numeric(respiratory_rate)
  oxygen_saturation <- as.numeric(oxygen_saturation)
  on_supplemental_oxygen <- as.numeric(on_supplemental_oxygen)
  retractions <- tolower(as.character(retractions))
  dyspnea <- tolower(as.character(dyspnea))
  auscultation <- tolower(as.character(auscultation))

  if (any(is.na(c(age, respiratory_rate, oxygen_saturation, on_supplemental_oxygen)))) {
    stop("Error: All numeric inputs must be valid.")
  }

  rr_score <- 0
  if (age < 4) {
    if (respiratory_rate <= 30) rr_score <- 1
    else if (respiratory_rate <= 45) rr_score <- 2
    else rr_score <- 3
  } else if (age <= 15) {
    if (respiratory_rate <= 20) rr_score <- 1
    else if (respiratory_rate <= 35) rr_score <- 2
    else rr_score <- 3
  } else {
    if (respiratory_rate <= 16) rr_score <- 1
    else if (respiratory_rate <= 23) rr_score <- 2
    else rr_score <- 3
  }

  o2_score <- 0
  if (on_supplemental_oxygen == 1) {
    o2_score <- 3
  } else {
    if (oxygen_saturation > 95) o2_score <- 1
    else if (oxygen_saturation >= 90) o2_score <- 2
    else o2_score <- 3
  }

  retractions_score <- 0
  if (retractions == "none_intercostal") {
    retractions_score <- 1
  } else if (retractions == "substernal_suprasternal") {
    retractions_score <- 2
  } else if (retractions == "supraclavicular_flaring") {
    retractions_score <- 3
  } else {
    stop("Error: Retractions must be 'none_intercostal', 'substernal_suprasternal', or 'supraclavicular_flaring'.")
  }

  dyspnea_score <- 0
  if (dyspnea == "sentences") {
    dyspnea_score <- 1
  } else if (dyspnea == "phrases") {
    dyspnea_score <- 2
  } else if (dyspnea == "words") {
    dyspnea_score <- 3
  } else {
    stop("Error: Dyspnea must be 'sentences', 'phrases', or 'words'.")
  }

  auscultation_score <- 0
  if (auscultation == "end_expiratory") {
    auscultation_score <- 1
  } else if (auscultation == "throughout") {
    auscultation_score <- 2
  } else if (auscultation == "diminished") {
    auscultation_score <- 3
  } else {
    stop("Error: Auscultation must be 'end_expiratory', 'throughout', or 'diminished'.")
  }

  total_score <- rr_score + o2_score + retractions_score + dyspnea_score + auscultation_score

  severity <- ""
  if (total_score <= 7) {
    severity <- "Mild Asthma Exacerbation"
  } else if (total_score <= 11) {
    severity <- "Moderate Asthma Exacerbation"
  } else {
    severity <- "Severe Asthma Exacerbation"
  }

  return(list(
    PAS_Score = total_score,
    Severity = severity,
    Subscores = list(
      RR_Points = rr_score,
      O2_Points = o2_score,
      Retractions_Points = retractions_score,
      Dyspnea_Points = dyspnea_score,
      Auscultation_Points = auscultation_score
    )
  ))
}

pediatric_asthma_severity_score <- function(wheezing, work_of_breathing, prolongation_of_expiration) {

  wheezing <- tolower(as.character(wheezing))
  work_of_breathing <- tolower(as.character(work_of_breathing))
  prolongation_of_expiration <- tolower(as.character(prolongation_of_expiration))

  valid_levels <- c("normal_mild", "moderate", "severe")

  if (!wheezing %in% valid_levels) stop("Error: Wheezing must be 'normal_mild', 'moderate', or 'severe'.")
  if (!work_of_breathing %in% valid_levels) stop("Error: Work of breathing must be 'normal_mild', 'moderate', or 'severe'.")
  if (!prolongation_of_expiration %in% valid_levels) stop("Error: Prolongation of expiration must be 'normal_mild', 'moderate', or 'severe'.")

  score <- 0

  if (wheezing == "moderate") score <- score + 1
  else if (wheezing == "severe") score <- score + 2

  if (work_of_breathing == "moderate") score <- score + 1
  else if (work_of_breathing == "severe") score <- score + 2

  if (prolongation_of_expiration == "moderate") score <- score + 1
  else if (prolongation_of_expiration == "severe") score <- score + 2

  interpretation <- ""
  if (score < 2) {
    interpretation <- "Mild (Likely suitable for discharge)"
  } else {
    interpretation <- "Moderate to Severe (Assessment for admission/observation recommended)"
  }

  return(list(
    PASS_Score = score,
    Interpretation = interpretation,
    Inputs = list(
      Wheezing = wheezing,
      Work_of_Breathing = work_of_breathing,
      Expiration = prolongation_of_expiration
    )
  ))
}

pcdai_score <- function(abdominal_pain_score, stool_frequency_score, general_wellbeing_score, weight_score, height_score, abdominal_exam_score, perirectal_disease_score, extraintestinal_manifestations_score, hematocrit, esr, albumin_g_dl, age_years, sex) {

  abdominal_pain_score <- as.numeric(abdominal_pain_score)
  stool_frequency_score <- as.numeric(stool_frequency_score)
  general_wellbeing_score <- as.numeric(general_wellbeing_score)
  weight_score <- as.numeric(weight_score)
  height_score <- as.numeric(height_score)
  abdominal_exam_score <- as.numeric(abdominal_exam_score)
  perirectal_disease_score <- as.numeric(perirectal_disease_score)
  extraintestinal_manifestations_score <- as.numeric(extraintestinal_manifestations_score)
  hematocrit <- as.numeric(hematocrit)
  esr <- as.numeric(esr)
  albumin_g_dl <- as.numeric(albumin_g_dl)
  age_years <- as.numeric(age_years)
  sex <- tolower(as.character(sex))

  if (any(is.na(c(hematocrit, esr, albumin_g_dl, age_years)))) {
    stop("Error: Lab values and age must be numeric.")
  }

  if (!sex %in% c("male", "female")) {
    stop("Error: Sex must be 'male' or 'female'.")
  }

  valid_scores_0_5_10 <- c(0, 5, 10)
  valid_scores_0_5_10_15 <- c(0, 5, 10, 15) # Sometimes weight allows up to 10, standard is 0/5/10. Height 0/5/10.

  # Assuming standard inputs 0, 5, 10 based on MDCalc tool

  hct_score <- 0
  if (age_years < 10) {
    if (hematocrit < 28) hct_score <- 5
    else if (hematocrit <= 32) hct_score <- 2.5
    else hct_score <- 0
  } else if (sex == "male") {
    if (hematocrit < 32) hct_score <- 5
    else if (hematocrit <= 36) hct_score <- 2.5
    else hct_score <- 0
  } else {
    if (hematocrit < 29) hct_score <- 5
    else if (hematocrit <= 34) hct_score <- 2.5
    else hct_score <- 0
  }

  esr_score <- 0
  if (esr > 45) {
    esr_score <- 5
  } else if (esr >= 20) {
    esr_score <- 2.5
  } else {
    esr_score <- 0
  }

  albumin_score <- 0
  if (albumin_g_dl < 3.1) {
    albumin_score <- 10
  } else if (albumin_g_dl < 3.5) {
    albumin_score <- 5
  } else {
    albumin_score <- 0
  }

  total_score <- abdominal_pain_score + stool_frequency_score + general_wellbeing_score + weight_score + height_score + abdominal_exam_score + perirectal_disease_score + extraintestinal_manifestations_score + hct_score + esr_score + albumin_score

  activity_level <- ""
  if (total_score < 10) {
    activity_level <- "Inactive Disease (Remission)"
  } else if (total_score <= 30) {
    activity_level <- "Mild Disease Activity"
  } else {
    activity_level <- "Moderate to Severe Disease Activity"
  }

  return(list(
    PCDAI_Score = total_score,
    Disease_Activity = activity_level,
    Lab_Points = list(
      Hematocrit = hct_score,
      ESR = esr_score,
      Albumin = albumin_score
    )
  ))
}

pews_score <- function(behavior_score, cardiovascular_score, respiratory_score, nebulizer_use, persistent_vomiting) {

  behavior_score <- as.numeric(behavior_score)
  cardiovascular_score <- as.numeric(cardiovascular_score)
  respiratory_score <- as.numeric(respiratory_score)
  nebulizer_use <- as.numeric(nebulizer_use)
  persistent_vomiting <- as.numeric(persistent_vomiting)

  if (any(is.na(c(behavior_score, cardiovascular_score, respiratory_score, nebulizer_use, persistent_vomiting)))) {
    stop("Error: All inputs must be numeric.")
  }

  if (any(c(behavior_score, cardiovascular_score, respiratory_score) < 0) || any(c(behavior_score, cardiovascular_score, respiratory_score) > 3)) {
    stop("Error: Domain scores must be between 0 and 3.")
  }

  score <- behavior_score + cardiovascular_score + respiratory_score

  if (nebulizer_use == 1) {
    score <- score + 2
  }

  if (persistent_vomiting == 1) {
    score <- score + 2
  }

  risk_level <- ""
  action <- ""

  if (score <= 2) {
    risk_level <- "Low Risk"
    action <- "Routine observation."
  } else if (score == 3) {
    risk_level <- "Low-Intermediate Risk"
    action <- "Notify nurse in charge. Increase observation frequency."
  } else if (score >= 4 && score <= 6) {
    risk_level <- "Intermediate Risk"
    action <- "Notify House Officer/Attending (30 min response). Hourly observations."
  } else {
    risk_level <- "High Risk"
    action <- "Notify Registrar/ICU Team (15 min response). Continuous monitoring."
  }

  return(list(
    PEWS_Score = score,
    Risk_Level = risk_level,
    Action_Guidance = action,
    Inputs = list(
      Behavior = behavior_score,
      Cardiovascular = cardiovascular_score,
      Respiratory = respiratory_score,
      Nebulizer = nebulizer_use == 1,
      Vomiting = persistent_vomiting == 1
    )
  ))
}

pediatric_ett_size <- function(age_years) {

  age_years <- as.numeric(age_years)

  if (is.na(age_years) || age_years < 0) {
    stop("Error: Age must be a positive number.")
  }

  uncuffed_size <- (age_years / 4) + 4

  cuffed_size <- (age_years / 4) + 3.5

  depth_cm <- (age_years / 2) + 12

  if (age_years < 1) {
    if (age_years < 0.5) {
      uncuffed_size <- 3.5
      cuffed_size <- 3.0
    } else {
      uncuffed_size <- 4.0
      cuffed_size <- 3.5
    }
    depth_cm <- 10 + (age_years * 2)
  }

  return(list(
    Uncuffed_ETT_Size_mm = round(uncuffed_size, 1),
    Cuffed_ETT_Size_mm = round(cuffed_size, 1),
    Depth_of_Insertion_cm = round(depth_cm, 1),
    Inputs = list(
      Age_Years = age_years
    )
  ))
}

pfib_c_score <- function(ast, alt, platelet_count, bmi_z_score) {

  ast <- as.numeric(ast)
  alt <- as.numeric(alt)
  platelet_count <- as.numeric(platelet_count)
  bmi_z_score <- as.numeric(bmi_z_score)

  if (any(is.na(c(ast, alt, platelet_count, bmi_z_score)))) {
    stop("Error: All inputs must be numeric.")
  }

  if (platelet_count <= 0) {
    stop("Error: Platelet count must be positive.")
  }

  logit_pfib_c <- -6.892 + (0.023 * ast) + (0.028 * alt) - (0.010 * platelet_count) + (1.126 * bmi_z_score)

  pfib_c_probability <- 1 / (1 + exp(-logit_pfib_c))

  risk_category <- ""
  if (pfib_c_probability < 0.1) {
    risk_category <- "Low Risk of Advanced Fibrosis (F3-F4)"
  } else if (pfib_c_probability >= 0.1 && pfib_c_probability < 0.5) {
    risk_category <- "Indeterminate Risk"
  } else {
    risk_category <- "High Risk of Advanced Fibrosis (F3-F4)"
  }

  return(list(
    pFIB_c_Probability = round(pfib_c_probability, 4),
    Risk_Category = risk_category,
    Inputs = list(
      AST = ast,
      ALT = alt,
      Platelets = platelet_count,
      BMI_Z_Score = bmi_z_score
    )
  ))
}

pediatric_glasgow_coma_scale <- function(eye_response, verbal_response, motor_response) {

  eye_response <- as.numeric(eye_response)
  verbal_response <- as.numeric(verbal_response)
  motor_response <- as.numeric(motor_response)

  if (any(is.na(c(eye_response, verbal_response, motor_response)))) {
    stop("Error: All inputs must be numeric.")
  }

  if (eye_response < 1 || eye_response > 4) stop("Error: Eye response must be between 1 and 4.")
  if (verbal_response < 1 || verbal_response > 5) stop("Error: Verbal response must be between 1 and 5.")
  if (motor_response < 1 || motor_response > 6) stop("Error: Motor response must be between 1 and 6.")

  total_score <- eye_response + verbal_response + motor_response

  severity <- ""
  if (total_score >= 13) {
    severity <- "Mild Head Injury"
  } else if (total_score >= 9) {
    severity <- "Moderate Head Injury"
  } else {
    severity <- "Severe Head Injury (Coma)"
  }

  return(list(
    pGCS_Score = total_score,
    Severity_Classification = severity,
    Inputs = list(
      Eye = eye_response,
      Verbal = verbal_response,
      Motor = motor_response
    )
  ))
}

pediatric_ins_outs <- function(weight_kg) {

  weight_kg <- as.numeric(weight_kg)

  if (is.na(weight_kg) || weight_kg <= 0) {
    stop("Error: Weight must be a positive number.")
  }

  maintenance_rate <- 0

  if (weight_kg <= 10) {
    maintenance_rate <- 4 * weight_kg
  } else if (weight_kg <= 20) {
    maintenance_rate <- 40 + (2 * (weight_kg - 10))
  } else {
    maintenance_rate <- 60 + (1 * (weight_kg - 20))
  }

  daily_volume <- maintenance_rate * 24

  urine_output_low <- 0
  urine_output_high <- 0
  target_desc <- ""

  if (weight_kg <= 10) {
    urine_output_low <- 1.0 * weight_kg
    urine_output_high <- 2.0 * weight_kg
    target_desc <- "Infant/Young Child (1-2 mL/kg/hr)"
  } else if (weight_kg <= 30) {
    urine_output_low <- 1.0 * weight_kg
    urine_output_high <- 1.5 * weight_kg
    target_desc <- "Child (1-1.5 mL/kg/hr)"
  } else {
    urine_output_low <- 0.5 * weight_kg
    urine_output_high <- 1.0 * weight_kg
    target_desc <- "Older Child/Adolescent (0.5-1 mL/kg/hr)"
  }

  return(list(
    Maintenance_Rate_mL_hr = round(maintenance_rate, 1),
    Maintenance_Volume_24h_mL = round(daily_volume, 0),
    Target_Urine_Output_mL_hr = paste(round(urine_output_low, 1), "-", round(urine_output_high, 1)),
    Target_Description = target_desc,
    Inputs = list(
      Weight_kg = weight_kg
    )
  ))
}

pediatric_nexus_ii_head_ct <- function(skull_fracture_evidence, scalp_hematoma, neurologic_deficit, altered_alertness, abnormal_behavior, coagulopathy, persistent_vomiting) {

  skull_fracture_evidence <- as.numeric(skull_fracture_evidence)
  scalp_hematoma <- as.numeric(scalp_hematoma)
  neurologic_deficit <- as.numeric(neurologic_deficit)
  altered_alertness <- as.numeric(altered_alertness)
  abnormal_behavior <- as.numeric(abnormal_behavior)
  coagulopathy <- as.numeric(coagulopathy)
  persistent_vomiting <- as.numeric(persistent_vomiting)

  if (any(is.na(c(skull_fracture_evidence, scalp_hematoma, neurologic_deficit, altered_alertness, abnormal_behavior, coagulopathy, persistent_vomiting)))) {
    stop("Error: All inputs must be numeric (0 or 1).")
  }

  criteria_met <- FALSE

  if (skull_fracture_evidence == 1) criteria_met <- TRUE
  if (scalp_hematoma == 1) criteria_met <- TRUE
  if (neurologic_deficit == 1) criteria_met <- TRUE
  if (altered_alertness == 1) criteria_met <- TRUE
  if (abnormal_behavior == 1) criteria_met <- TRUE
  if (coagulopathy == 1) criteria_met <- TRUE
  if (persistent_vomiting == 1) criteria_met <- TRUE

  recommendation <- ""

  if (criteria_met) {
    recommendation <- "CT Head Indicated (Not Low Risk)"
  } else {
    recommendation <- "CT Head Not Indicated (Low Risk)"
  }

  return(list(
    Result = recommendation,
    Inputs = list(
      Skull_Fracture = skull_fracture_evidence == 1,
      Scalp_Hematoma = scalp_hematoma == 1,
      Neuro_Deficit = neurologic_deficit == 1,
      Altered_Alertness = altered_alertness == 1,
      Abnormal_Behavior = abnormal_behavior == 1,
      Coagulopathy = coagulopathy == 1,
      Persistent_Vomiting = persistent_vomiting == 1
    )
  ))
}

pediatric_nih_stroke_scale <- function(loc_responsiveness, loc_questions, loc_commands, gaze, visual_fields, facial_palsy, motor_arm_left, motor_arm_right, motor_leg_left, motor_leg_right, limb_ataxia, sensory, best_language, dysarthria, extinction_inattention) {

  inputs <- c(loc_responsiveness, loc_questions, loc_commands, gaze, visual_fields, facial_palsy, motor_arm_left, motor_arm_right, motor_leg_left, motor_leg_right, limb_ataxia, sensory, best_language, dysarthria, extinction_inattention)

  if (any(is.na(inputs))) {
    stop("Error: All inputs must be numeric.")
  }

  score <- sum(inputs)

  severity <- ""
  if (score == 0) {
    severity <- "No Stroke Symptoms"
  } else if (score <= 4) {
    severity <- "Minor Stroke"
  } else if (score <= 15) {
    severity <- "Moderate Stroke"
  } else if (score <= 20) {
    severity <- "Moderate to Severe Stroke"
  } else {
    severity <- "Severe Stroke"
  }

  return(list(
    PedNIHSS_Score = score,
    Severity_Level = severity,
    Inputs = list(
      LOC_Response = loc_responsiveness,
      LOC_Questions = loc_questions,
      LOC_Commands = loc_commands,
      Gaze = gaze,
      Visual = visual_fields,
      Facial_Palsy = facial_palsy,
      Motor_Arm_L = motor_arm_left,
      Motor_Arm_R = motor_arm_right,
      Motor_Leg_L = motor_leg_left,
      Motor_Leg_R = motor_leg_right,
      Ataxia = limb_ataxia,
      Sensory = sensory,
      Language = best_language,
      Dysarthria = dysarthria,
      Extinction = extinction_inattention
    )
  ))
}

pram_score <- function(suprasternal_retractions, scalene_muscle_contraction, air_entry, wheezing, oxygen_saturation) {

  suprasternal_retractions <- as.numeric(suprasternal_retractions)
  scalene_muscle_contraction <- as.numeric(scalene_muscle_contraction)
  air_entry <- as.numeric(air_entry)
  wheezing <- as.numeric(wheezing)
  oxygen_saturation <- as.numeric(oxygen_saturation)

  if (any(is.na(c(suprasternal_retractions, scalene_muscle_contraction, air_entry, wheezing, oxygen_saturation)))) {
    stop("Error: All inputs must be numeric.")
  }

  score <- 0

  if (suprasternal_retractions == 1) {
    score <- score + 2
  }

  if (scalene_muscle_contraction == 1) {
    score <- score + 2
  }

  if (air_entry == 0) {
    score <- score + 0
  } else if (air_entry == 1) {
    score <- score + 1
  } else if (air_entry == 2) {
    score <- score + 2
  } else {
    stop("Error: Air entry score must be 0 (Normal), 1 (Decreased at base), or 2 (Widespread decrease).")
  }

  if (wheezing == 0) {
    score <- score + 0
  } else if (wheezing == 1) {
    score <- score + 1
  } else if (wheezing == 2) {
    score <- score + 2
  } else if (wheezing == 3) {
    score <- score + 3
  } else {
    stop("Error: Wheezing score must be 0 (Absent), 1 (Expiratory only), 2 (Insp & Exp), or 3 (Audible without stethoscope/Silent chest).")
  }

  if (oxygen_saturation >= 95) {
    score <- score + 0
  } else if (oxygen_saturation >= 92 && oxygen_saturation <= 94) {
    score <- score + 1
  } else {
    score <- score + 2
  }

  severity <- ""
  if (score <= 3) {
    severity <- "Mild Obstruction"
  } else if (score <= 7) {
    severity <- "Moderate Obstruction"
  } else {
    severity <- "Severe Obstruction"
  }

  return(list(
    PRAM_Score = score,
    Severity_Classification = severity,
    Inputs = list(
      Suprasternal_Retractions = suprasternal_retractions == 1,
      Scalene_Contraction = scalene_muscle_contraction == 1,
      Air_Entry_Score = air_entry,
      Wheezing_Score = wheezing,
      SpO2 = oxygen_saturation
    )
  ))
}

pediatric_sepsis_criteria <- function(age_category, temp_c, heart_rate, respiratory_rate, wbc_count, bands_percent, infection_suspected, cardiovascular_dysfunction, ards_present, multiple_organ_dysfunction) {

  age_category <- tolower(as.character(age_category))
  temp_c <- as.numeric(temp_c)
  heart_rate <- as.numeric(heart_rate)
  respiratory_rate <- as.numeric(respiratory_rate)
  wbc_count <- as.numeric(wbc_count)
  bands_percent <- as.numeric(bands_percent)
  infection_suspected <- as.numeric(infection_suspected)
  cardiovascular_dysfunction <- as.numeric(cardiovascular_dysfunction)
  ards_present <- as.numeric(ards_present)
  multiple_organ_dysfunction <- as.numeric(multiple_organ_dysfunction)

  if (any(is.na(c(temp_c, heart_rate, respiratory_rate, wbc_count, bands_percent)))) {
    stop("Error: Vital signs and lab values must be numeric.")
  }

  valid_ages <- c("newborn_0_7d", "neonate_1w_1m", "infant_1m_1y", "child_2y_5y", "child_6y_12y", "adolescent_13y_18y")
  if (!age_category %in% valid_ages) {
    stop("Error: Age category must be 'newborn_0_7d', 'neonate_1w_1m', 'infant_1m_1y', 'child_2y_5y', 'child_6y_12y', or 'adolescent_13y_18y'.")
  }

  abnormal_temp <- (temp_c > 38.5 || temp_c < 36.0)

  abnormal_wbc <- FALSE
  if (bands_percent > 10) {
    abnormal_wbc <- TRUE
  } else {
    if (age_category == "newborn_0_7d") {
      if (wbc_count > 34) abnormal_wbc <- TRUE
    } else if (age_category == "neonate_1w_1m") {
      if (wbc_count > 19.5 || wbc_count < 5) abnormal_wbc <- TRUE
    } else if (age_category == "infant_1m_1y") {
      if (wbc_count > 17.5 || wbc_count < 5) abnormal_wbc <- TRUE
    } else if (age_category == "child_2y_5y") {
      if (wbc_count > 15.5 || wbc_count < 6) abnormal_wbc <- TRUE
    } else if (age_category == "child_6y_12y") {
      if (wbc_count > 13.5 || wbc_count < 4.5) abnormal_wbc <- TRUE
    } else {
      if (wbc_count > 11 || wbc_count < 4.5) abnormal_wbc <- TRUE
    }
  }

  abnormal_hr <- FALSE
  if (age_category == "newborn_0_7d") {
    if (heart_rate > 180 || heart_rate < 100) abnormal_hr <- TRUE
  } else if (age_category == "neonate_1w_1m") {
    if (heart_rate > 180 || heart_rate < 100) abnormal_hr <- TRUE
  } else if (age_category == "infant_1m_1y") {
    if (heart_rate > 180 || heart_rate < 90) abnormal_hr <- TRUE
  } else if (age_category == "child_2y_5y") {
    if (heart_rate > 140) abnormal_hr <- TRUE
  } else if (age_category == "child_6y_12y") {
    if (heart_rate > 130) abnormal_hr <- TRUE
  } else {
    if (heart_rate > 110) abnormal_hr <- TRUE
  }

  abnormal_rr <- FALSE
  if (age_category == "newborn_0_7d") {
    if (respiratory_rate > 50) abnormal_rr <- TRUE
  } else if (age_category == "neonate_1w_1m") {
    if (respiratory_rate > 40) abnormal_rr <- TRUE
  } else if (age_category == "infant_1m_1y") {
    if (respiratory_rate > 34) abnormal_rr <- TRUE
  } else if (age_category == "child_2y_5y") {
    if (respiratory_rate > 22) abnormal_rr <- TRUE
  } else if (age_category == "child_6y_12y") {
    if (respiratory_rate > 18) abnormal_rr <- TRUE
  } else {
    if (respiratory_rate > 14) abnormal_rr <- TRUE
  }

  sirs_met <- FALSE
  criteria_count <- sum(abnormal_temp, abnormal_wbc, abnormal_hr, abnormal_rr)

  if (criteria_count >= 2) {
    if (abnormal_temp || abnormal_wbc) {
      sirs_met <- TRUE
    }
  }

  sepsis_met <- (sirs_met && infection_suspected == 1)

  severe_sepsis_met <- (sepsis_met && (cardiovascular_dysfunction == 1 || ards_present == 1 || multiple_organ_dysfunction == 1))

  septic_shock_met <- (sepsis_met && cardiovascular_dysfunction == 1)

  diagnosis <- "No SIRS"
  if (septic_shock_met) {
    diagnosis <- "Septic Shock"
  } else if (severe_sepsis_met) {
    diagnosis <- "Severe Sepsis"
  } else if (sepsis_met) {
    diagnosis <- "Sepsis"
  } else if (sirs_met) {
    diagnosis <- "SIRS (Systemic Inflammatory Response Syndrome)"
  }

  return(list(
    Diagnosis = diagnosis,
    Detailed_Results = list(
      SIRS = sirs_met,
      Sepsis = sepsis_met,
      Severe_Sepsis = severe_sepsis_met,
      Septic_Shock = septic_shock_met
    ),
    Criteria_Met = list(
      Abnormal_Temp = abnormal_temp,
      Abnormal_WBC = abnormal_wbc,
      Abnormal_HR = abnormal_hr,
      Abnormal_RR = abnormal_rr
    )
  ))
}

pedsrc_bat_rule <- function(abdominal_tenderness, abdominal_wall_trauma, gcs_score, ast, alt, urinalysis_hematuria_gt_5_rbc, abnormal_xray = 0) {

  abdominal_tenderness <- as.numeric(abdominal_tenderness)
  abdominal_wall_trauma <- as.numeric(abdominal_wall_trauma)
  gcs_score <- as.numeric(gcs_score)
  ast <- as.numeric(ast)
  alt <- as.numeric(alt)
  urinalysis_hematuria_gt_5_rbc <- as.numeric(urinalysis_hematuria_gt_5_rbc)
  abnormal_xray <- as.numeric(abnormal_xray)

  if (any(is.na(c(abdominal_tenderness, abdominal_wall_trauma, gcs_score, ast, alt, urinalysis_hematuria_gt_5_rbc, abnormal_xray)))) {
    stop("Error: All inputs must be numeric.")
  }

  criteria_met <- FALSE
  reasons <- c()

  if (abdominal_tenderness == 1) {
    criteria_met <- TRUE
    reasons <- c(reasons, "Abdominal tenderness")
  }

  if (abdominal_wall_trauma == 1) {
    criteria_met <- TRUE
    reasons <- c(reasons, "Abdominal wall trauma/Seatbelt sign")
  }

  if (gcs_score < 14) {
    criteria_met <- TRUE
    reasons <- c(reasons, "GCS < 14")
  }

  if (ast > 200) {
    criteria_met <- TRUE
    reasons <- c(reasons, "AST > 200 U/L")
  }

  if (alt > 125) {
    criteria_met <- TRUE
    reasons <- c(reasons, "ALT > 125 U/L")
  }

  if (urinalysis_hematuria_gt_5_rbc == 1) {
    criteria_met <- TRUE
    reasons <- c(reasons, "Hematuria (>5 RBC/hpf)")
  }

  if (abnormal_xray == 1) {
    criteria_met <- TRUE
    reasons <- c(reasons, "Abnormal Chest/Pelvic X-ray")
  }

  result <- ""
  recommendation <- ""

  if (criteria_met) {
    result <- "Not Low Risk"
    recommendation <- "Consider abdominal CT or further observation/workup. Risk of Intra-abdominal Injury (IAI) is elevated."
  } else {
    result <- "Very Low Risk"
    recommendation <- "Risk of IAI is extremely low. CT is generally not indicated."
  }

  return(list(
    Risk_Classification = result,
    Recommendation = recommendation,
    Criteria_Present = if (length(reasons) > 0) reasons else "None",
    Inputs = list(
      Tenderness = abdominal_tenderness == 1,
      Wall_Trauma = abdominal_wall_trauma == 1,
      GCS = gcs_score,
      AST = ast,
      ALT = alt,
      Hematuria = urinalysis_hematuria_gt_5_rbc == 1,
      Abnormal_XR = abnormal_xray == 1
    )
  ))
}

pediatric_big_score <- function(base_deficit, inr, gcs) {

  base_deficit <- as.numeric(base_deficit)
  inr <- as.numeric(inr)
  gcs <- as.numeric(gcs)

  if (any(is.na(c(base_deficit, inr, gcs)))) {
    stop("Error: All inputs must be numeric.")
  }

  if (gcs < 3 || gcs > 15) {
    stop("Error: GCS must be between 3 and 15.")
  }

  if (inr < 0) {
    stop("Error: INR cannot be negative.")
  }

  score <- base_deficit + (2.5 * inr) + (15 - gcs)

  risk_category <- ""
  mortality_risk <- ""

  if (score < 16) {
    risk_category <- "Low Risk"
    mortality_risk <- "< 6% (High probability of survival)"
  } else {
    risk_category <- "High Risk"
    mortality_risk <- "Significantly Elevated (Score >= 16 predicts mortality with high specificity)"
  }

  return(list(
    BIG_Score = round(score, 1),
    Risk_Category = risk_category,
    Mortality_Prediction = mortality_risk,
    Inputs = list(
      Base_Deficit = base_deficit,
      INR = inr,
      GCS = gcs
    )
  ))
}

pediatric_trauma_score <- function(weight_kg, airway_status, systolic_bp, cns_status, open_wound_status, skeletal_fracture_status) {

  weight_kg <- as.numeric(weight_kg)
  systolic_bp <- as.numeric(systolic_bp)
  airway_status <- tolower(as.character(airway_status))
  cns_status <- tolower(as.character(cns_status))
  open_wound_status <- tolower(as.character(open_wound_status))
  skeletal_fracture_status <- tolower(as.character(skeletal_fracture_status))

  if (any(is.na(c(weight_kg, systolic_bp)))) {
    stop("Error: Weight and Systolic BP must be numeric.")
  }

  score <- 0

  if (weight_kg > 20) {
    score <- score + 2
  } else if (weight_kg >= 10 && weight_kg <= 20) {
    score <- score + 1
  } else {
    score <- score - 1
  }

  if (airway_status == "normal") {
    score <- score + 2
  } else if (airway_status == "maintainable") {
    score <- score + 1
  } else if (airway_status == "unmaintainable") {
    score <- score - 1
  } else {
    stop("Error: Airway status must be 'normal', 'maintainable', or 'unmaintainable'.")
  }

  if (systolic_bp > 90) {
    score <- score + 2
  } else if (systolic_bp >= 50 && systolic_bp <= 90) {
    score <- score + 1
  } else {
    score <- score - 1
  }

  if (cns_status == "awake") {
    score <- score + 2
  } else if (cns_status == "obtunded") {
    score <- score + 1
  } else if (cns_status == "coma") {
    score <- score - 1
  } else {
    stop("Error: CNS status must be 'awake', 'obtunded', or 'coma'.")
  }

  if (open_wound_status == "none") {
    score <- score + 2
  } else if (open_wound_status == "minor") {
    score <- score + 1
  } else if (open_wound_status == "major") {
    score <- score - 1
  } else {
    stop("Error: Open wound status must be 'none', 'minor', or 'major'.")
  }

  if (skeletal_fracture_status == "none") {
    score <- score + 2
  } else if (skeletal_fracture_status == "closed") {
    score <- score + 1
  } else if (skeletal_fracture_status == "open_multiple") {
    score <- score - 1
  } else {
    stop("Error: Skeletal fracture status must be 'none', 'closed', or 'open_multiple'.")
  }

  triage_recommendation <- ""
  mortality_risk <- ""

  if (score <= 8) {
    triage_recommendation <- "Transfer to Pediatric Trauma Center"
    mortality_risk <- "Significant Mortality Risk"
  } else {
    triage_recommendation <- "Observation / Routine Care"
    mortality_risk <- "Low Mortality Risk (0% in derivation)"
  }

  return(list(
    PTS_Score = score,
    Recommendation = triage_recommendation,
    Risk_Assessment = mortality_risk,
    Inputs = list(
      Weight = weight_kg,
      Airway = airway_status,
      SBP = systolic_bp,
      CNS = cns_status,
      Wound = open_wound_status,
      Skeletal = skeletal_fracture_status
    )
  ))
}

pucai_score <- function(abdominal_pain, rectal_bleeding, stool_consistency, stools_per_24h, nocturnal_stools, activity_level) {

  abdominal_pain <- as.numeric(abdominal_pain)
  rectal_bleeding <- as.numeric(rectal_bleeding)
  stool_consistency <- as.numeric(stool_consistency)
  stools_per_24h <- as.numeric(stools_per_24h)
  nocturnal_stools <- as.numeric(nocturnal_stools)
  activity_level <- as.numeric(activity_level)

  if (any(is.na(c(abdominal_pain, rectal_bleeding, stool_consistency, stools_per_24h, nocturnal_stools, activity_level)))) {
    stop("Error: All inputs must be numeric.")
  }

  if (any(c(abdominal_pain, rectal_bleeding, stool_consistency, stools_per_24h, nocturnal_stools, activity_level) < 0)) {
    stop("Error: Item scores cannot be negative.")
  }

  total_score <- abdominal_pain + rectal_bleeding + stool_consistency + stools_per_24h + nocturnal_stools + activity_level

  activity_class <- ""
  if (total_score < 10) {
    activity_class <- "Remission"
  } else if (total_score < 35) {
    activity_class <- "Mild Disease"
  } else if (total_score < 65) {
    activity_class <- "Moderate Disease"
  } else {
    activity_class <- "Severe Disease"
  }

  return(list(
    PUCAI_Score = total_score,
    Disease_Activity = activity_class,
    Inputs = list(
      Pain = abdominal_pain,
      Bleeding = rectal_bleeding,
      Consistency = stool_consistency,
      Frequency = stools_per_24h,
      Nocturnal = nocturnal_stools,
      Activity = activity_level
    )
  ))
}

pedis_diabetic_foot_score <- function(perfusion_grade, extent_cm2, depth_grade, infection_grade, sensation_grade) {

  perfusion_grade <- as.numeric(perfusion_grade)
  extent_cm2 <- as.numeric(extent_cm2)
  depth_grade <- as.numeric(depth_grade)
  infection_grade <- as.numeric(infection_grade)
  sensation_grade <- as.numeric(sensation_grade)

  if (any(is.na(c(perfusion_grade, extent_cm2, depth_grade, infection_grade, sensation_grade)))) {
    stop("Error: All inputs must be numeric.")
  }

  score <- 0

  if (perfusion_grade == 1) {
    score <- score + 0
  } else if (perfusion_grade == 2) {
    score <- score + 1
  } else if (perfusion_grade == 3) {
    score <- score + 2
  } else {
    if (perfusion_grade == 0) score <- score + 0
    else if (perfusion_grade > 2) score <- score + 2
  }

  if (extent_cm2 == 0) {
    score <- score + 0
  } else if (extent_cm2 < 1) {
    score <- score + 1
  } else if (extent_cm2 >= 1 && extent_cm2 <= 3) {
    score <- score + 2
  } else {
    score <- score + 3
  }

  if (depth_grade == 0) {
    score <- score + 0
  } else if (depth_grade == 1) {
    score <- score + 1
  } else if (depth_grade == 2) {
    score <- score + 2
  } else if (depth_grade == 3) {
    score <- score + 3
  }

  if (infection_grade == 1) {
    score <- score + 0
  } else if (infection_grade == 2) {
    score <- score + 1
  } else if (infection_grade == 3) {
    score <- score + 2
  } else if (infection_grade == 4) {
    score <- score + 3
  } else {
    if (infection_grade == 0) score <- score + 0
    else score <- score + infection_grade
  }

  if (sensation_grade == 1) {
    score <- score + 0
  } else if (sensation_grade == 2) {
    score <- score + 1
  } else {
    if (sensation_grade == 0) score <- score + 0
    else score <- score + 1
  }

  risk_category <- ""
  if (score < 7) {
    risk_category <- "Low Risk (Score < 7)"
  } else {
    risk_category <- "High Risk (Score >= 7). Increased risk of non-healing, amputation, or death."
  }

  return(list(
    PEDIS_Score = score,
    Risk_Assessment = risk_category,
    Inputs = list(
      Perfusion_Grade = perfusion_grade,
      Extent_Area = extent_cm2,
      Depth_Grade = depth_grade,
      Infection_Grade = infection_grade,
      Sensation_Grade = sensation_grade
    )
  ))
}

pedocs_score <- function(total_patients_registered, number_in_waiting_room) {

  total_patients_registered <- as.numeric(total_patients_registered)
  number_in_waiting_room <- as.numeric(number_in_waiting_room)

  if (any(is.na(c(total_patients_registered, number_in_waiting_room)))) {
    stop("Error: All inputs must be numeric.")
  }

  raw_score <- 33.3 * (0.11 + (0.07 * number_in_waiting_room) + (0.04 * total_patients_registered))

  score <- round(raw_score, 0)

  if (score > 200) {
    score <- 200
  }
  if (score < 0) {
    score <- 0
  }

  status <- ""

  if (score <= 20) {
    status <- "Not Busy"
  } else if (score <= 60) {
    status <- "Busy"
  } else if (score <= 100) {
    status <- "Extremely Busy but Not Overcrowded"
  } else if (score <= 140) {
    status <- "Overcrowded"
  } else if (score <= 180) {
    status <- "Severely Overcrowded"
  } else {
    status <- "Dangerously Overcrowded"
  }

  return(list(
    PEDOCS_Score = score,
    Overcrowding_Status = status,
    Inputs = list(
      Total_Registered = total_patients_registered,
      Waiting_Room = number_in_waiting_room
    )
  ))
}

peld_cr_score <- function(bilirubin, inr, albumin, creatinine, age_years, growth_failure, on_dialysis = 0, bilirubin_units = "mg/dL", albumin_units = "g/dL", creatinine_units = "mg/dL") {

  bilirubin <- as.numeric(bilirubin)
  inr <- as.numeric(inr)
  albumin <- as.numeric(albumin)
  creatinine <- as.numeric(creatinine)
  age_years <- as.numeric(age_years)
  growth_failure <- as.numeric(growth_failure)
  on_dialysis <- as.numeric(on_dialysis)

  if (any(is.na(c(bilirubin, inr, albumin, creatinine, age_years, growth_failure)))) {
    stop("Error: All core inputs must be numeric.")
  }

  bili_val <- bilirubin
  if (bilirubin_units == "umol/L") {
    bili_val <- bilirubin / 17.1
  }

  alb_val <- albumin
  if (albumin_units == "g/L") {
    alb_val <- albumin / 10
  }

  creat_val <- creatinine
  if (creatinine_units == "umol/L" || creatinine_units == "micromol/L") {
    creat_val <- creatinine / 88.4
  }

  if (bili_val < 1.0) bili_val <- 1.0
  if (inr < 1.0) inr <- 1.0

  if (on_dialysis == 1) {
    creat_val <- 4.0
  } else {
    if (creat_val < 0.1) creat_val <- 0.1
    if (creat_val > 4.0) creat_val <- 4.0
  }

  age_factor <- 0
  if (age_years < 1.0) {
    age_factor <- 0.436
  }

  growth_factor <- 0
  if (growth_failure == 1) {
    growth_factor <- 0.667
  }

  peld_score <- 10 * ((0.480 * log(bili_val)) + (1.857 * log(inr)) - (0.687 * log(alb_val)) + (0.961 * log(creat_val)) + age_factor + growth_factor)

  peld_score <- round(peld_score, 0)

  return(list(
    PELD_Cr_Score = peld_score,
    Inputs = list(
      Bilirubin_mg_dL = round(bili_val, 2),
      INR = inr,
      Albumin_g_dL = round(alb_val, 2),
      Creatinine_mg_dL = round(creat_val, 2),
      Age_Years = age_years,
      Growth_Failure = growth_failure == 1,
      Dialysis = on_dialysis == 1
    )
  ))
}

peld_score_original <- function(bilirubin, inr, albumin, age_years, growth_failure, bilirubin_units = "mg/dL", albumin_units = "g/dL") {

  bilirubin <- as.numeric(bilirubin)
  inr <- as.numeric(inr)
  albumin <- as.numeric(albumin)
  age_years <- as.numeric(age_years)
  growth_failure <- as.numeric(growth_failure)

  if (any(is.na(c(bilirubin, inr, albumin, age_years, growth_failure)))) {
    stop("Error: All inputs must be numeric.")
  }

  bili_val <- bilirubin
  if (bilirubin_units == "umol/L") {
    bili_val <- bilirubin / 17.1
  }

  alb_val <- albumin
  if (albumin_units == "g/L") {
    alb_val <- albumin / 10
  }

  if (bili_val < 1.0) bili_val <- 1.0
  if (inr < 1.0) inr <- 1.0

  score <- 10 * ((0.480 * log(bili_val)) + (1.857 * log(inr)) - (0.687 * log(alb_val)) + (0.436 * (if (age_years < 1) 1 else 0)) + (0.667 * (if (growth_failure == 1) 1 else 0)))

  return(list(
    PELD_Score = round(score, 0),
    Inputs = list(
      Bilirubin_mg_dL = round(bili_val, 2),
      INR = inr,
      Albumin_g_dL = round(alb_val, 2),
      Age_Years = age_years,
      Growth_Failure = growth_failure == 1
    )
  ))
}

salivary_gland_cancer_port_survival <- function(age_at_diagnosis, sex, charlson_deyo_score, pathologic_t_stage, ratio_nodal_positivity, grade, surgical_margin, primary_site, port_received) {

  age_at_diagnosis <- as.numeric(age_at_diagnosis)
  sex <- tolower(as.character(sex))
  charlson_deyo_score <- as.numeric(charlson_deyo_score)
  pathologic_t_stage <- as.numeric(pathologic_t_stage)
  ratio_nodal_positivity <- tolower(as.character(ratio_nodal_positivity))
  grade <- tolower(as.character(grade))
  surgical_margin <- tolower(as.character(surgical_margin))
  primary_site <- tolower(as.character(primary_site))
  port_received <- tolower(as.character(port_received))

  if (any(is.na(c(age_at_diagnosis, charlson_deyo_score, pathologic_t_stage)))) {
    stop("Error: Numeric inputs required for age, Charlson-Deyo score, and T-stage.")
  }

  if (!ratio_nodal_positivity %in% c("0", "0.1-10", "10.1-49.9", ">=50")) {
    if (ratio_nodal_positivity == "0%") ratio_nodal_positivity <- "0"
    else if (ratio_nodal_positivity == "0.1-10%") ratio_nodal_positivity <- "0.1-10"
    else if (ratio_nodal_positivity == "10.1-49.9%") ratio_nodal_positivity <- "10.1-49.9"
    else if (ratio_nodal_positivity == ">=50%") ratio_nodal_positivity <- ">=50"
    else stop("Error: Ratio of nodal positivity must be '0', '0.1-10', '10.1-49.9', or '>=50'.")
  }

  return(list(
    Note = "Exact survival probability requires specific nomogram point tables or regression coefficients (Jacobs et al. 2020).",
    Inputs = list(
      Age = age_at_diagnosis,
      Sex = sex,
      Comorbidity_Score = charlson_deyo_score,
      T_Stage = pathologic_t_stage,
      LNR_Category = ratio_nodal_positivity,
      Tumor_Grade = grade,
      Margins = surgical_margin,
      Site = primary_site,
      PORT_Status = port_received
    )
  ))
}

san_francisco_syncope_rule <- function(history_chf, hematocrit, ecg_abnormal, shortness_of_breath, systolic_bp) {

  history_chf <- as.numeric(history_chf)
  hematocrit <- as.numeric(hematocrit)
  ecg_abnormal <- as.numeric(ecg_abnormal)
  shortness_of_breath <- as.numeric(shortness_of_breath)
  systolic_bp <- as.numeric(systolic_bp)

  if (any(is.na(c(history_chf, hematocrit, ecg_abnormal, shortness_of_breath, systolic_bp)))) {
    stop("Error: All inputs must be numeric.")
  }

  criteria_met <- FALSE
  reasons <- c()

  if (history_chf == 1) {
    criteria_met <- TRUE
    reasons <- c(reasons, "History of Congestive Heart Failure")
  }

  if (hematocrit < 30) {
    criteria_met <- TRUE
    reasons <- c(reasons, "Hematocrit < 30%")
  }

  if (ecg_abnormal == 1) {
    criteria_met <- TRUE
    reasons <- c(reasons, "Abnormal ECG")
  }

  if (shortness_of_breath == 1) {
    criteria_met <- TRUE
    reasons <- c(reasons, "Shortness of Breath")
  }

  if (systolic_bp < 90) {
    criteria_met <- TRUE
    reasons <- c(reasons, "Systolic BP < 90 mmHg")
  }

  result <- ""
  sensitivity <- ""
  specificity <- ""

  if (criteria_met) {
    result <- "High Risk for Serious Outcomes"
    sensitivity <- "96-98%"
    specificity <- "56%"
  } else {
    result <- "Low Risk for Serious Outcomes"
    sensitivity <- "N/A"
    specificity <- "N/A"
  }

  return(list(
    Risk_Classification = result,
    Criteria_Present = if (length(reasons) > 0) reasons else "None",
    Test_Characteristics = list(
      Sensitivity = sensitivity,
      Specificity = specificity
    ),
    Inputs = list(
      Hx_CHF = history_chf == 1,
      Hct = hematocrit,
      Abnormal_ECG = ecg_abnormal == 1,
      SOB = shortness_of_breath == 1,
      SBP = systolic_bp
    )
  ))
}

save_ecmo_score <- function(age, weight_kg, diagnosis_category, chronic_renal_failure, acute_renal_failure, liver_failure, cns_dysfunction, intubation_duration_hours, peak_inspiratory_pressure, cardiac_arrest_pre_ecmo, diastolic_bp_pre_ecmo, pulse_pressure_pre_ecmo, bicarbonate_pre_ecmo) {

  age <- as.numeric(age)
  weight_kg <- as.numeric(weight_kg)
  diagnosis_category <- tolower(as.character(diagnosis_category))
  chronic_renal_failure <- as.numeric(chronic_renal_failure)
  acute_renal_failure <- as.numeric(acute_renal_failure)
  liver_failure <- as.numeric(liver_failure)
  cns_dysfunction <- as.numeric(cns_dysfunction)
  intubation_duration_hours <- as.numeric(intubation_duration_hours)
  peak_inspiratory_pressure <- as.numeric(peak_inspiratory_pressure)
  cardiac_arrest_pre_ecmo <- as.numeric(cardiac_arrest_pre_ecmo)
  diastolic_bp_pre_ecmo <- as.numeric(diastolic_bp_pre_ecmo)
  pulse_pressure_pre_ecmo <- as.numeric(pulse_pressure_pre_ecmo)
  bicarbonate_pre_ecmo <- as.numeric(bicarbonate_pre_ecmo)

  if (any(is.na(c(age, weight_kg, chronic_renal_failure, acute_renal_failure, liver_failure, cns_dysfunction, intubation_duration_hours, peak_inspiratory_pressure, cardiac_arrest_pre_ecmo, diastolic_bp_pre_ecmo, pulse_pressure_pre_ecmo, bicarbonate_pre_ecmo)))) {
    stop("Error: All numeric/binary inputs must be valid.")
  }

  valid_diagnoses <- c("chronic_heart_failure", "myocarditis", "refractory_vt_vf", "post_transplant", "congenital_heart_disease", "other")
  if (!diagnosis_category %in% valid_diagnoses) {
    stop("Error: Diagnosis must be 'chronic_heart_failure', 'myocarditis', 'refractory_vt_vf', 'post_transplant', 'congenital_heart_disease', or 'other'.")
  }

  score <- 0

  if (diagnosis_category == "chronic_heart_failure") score <- score - 5
  else if (diagnosis_category == "myocarditis") score <- score + 3
  else if (diagnosis_category == "refractory_vt_vf") score <- score + 2
  else if (diagnosis_category == "post_transplant") score <- score + 3
  else if (diagnosis_category == "congenital_heart_disease") score <- score - 3
  else if (diagnosis_category == "other") score <- score - 1 # Based on standard interpretations of 'other' vs CHF

  if (age >= 18 && age <= 38) score <- score + 7
  else if (age >= 39 && age <= 52) score <- score + 4
  else if (age >= 53 && age <= 62) score <- score + 3
  else score <- score + 0

  if (weight_kg < 65) score <- score + 1
  else if (weight_kg >= 65 && weight_kg <= 89) score <- score + 2
  else score <- score + 0

  if (chronic_renal_failure == 1) score <- score - 6
  if (acute_renal_failure == 1) score <- score - 3
  if (liver_failure == 1) score <- score - 3
  if (cns_dysfunction == 1) score <- score - 3

  if (intubation_duration_hours <= 10) score <- score + 0
  else if (intubation_duration_hours <= 29) score <- score - 2
  else score <- score - 4

  if (peak_inspiratory_pressure <= 20) score <- score + 3

  if (cardiac_arrest_pre_ecmo == 1) score <- score - 2

  if (diastolic_bp_pre_ecmo >= 40) score <- score + 3

  if (pulse_pressure_pre_ecmo <= 20) score <- score - 2

  if (bicarbonate_pre_ecmo <= 15) score <- score - 3

  risk_class <- ""
  survival_prob <- ""

  if (score > 5) {
    risk_class <- "Class I"
    survival_prob <- "75%"
  } else if (score >= 1 && score <= 5) {
    risk_class <- "Class II"
    survival_prob <- "58%"
  } else if (score >= -4 && score <= 0) {
    risk_class <- "Class III"
    survival_prob <- "42%"
  } else if (score >= -9 && score <= -5) {
    risk_class <- "Class IV"
    survival_prob <- "30%"
  } else {
    risk_class <- "Class V"
    survival_prob <- "18%"
  }

  return(list(
    SAVE_Score = score,
    Risk_Class = risk_class,
    Est_Hospital_Survival = survival_prob,
    Inputs = list(
      Age = age,
      Weight = weight_kg,
      Diagnosis = diagnosis_category,
      Chronic_Renal_Failure = chronic_renal_failure == 1,
      Acute_Renal_Failure = acute_renal_failure == 1,
      Liver_Failure = liver_failure == 1,
      CNS_Dysfunction = cns_dysfunction == 1,
      Intubation_Duration = intubation_duration_hours,
      PIP_le_20 = peak_inspiratory_pressure <= 20,
      Pre_ECMO_Arrest = cardiac_arrest_pre_ecmo == 1,
      Diastolic_BP_ge_40 = diastolic_bp_pre_ecmo >= 40,
      Pulse_Pressure_le_20 = pulse_pressure_pre_ecmo <= 20,
      HCO3_le_15 = bicarbonate_pre_ecmo <= 15
    )
  ))
}

schwab_england_adl_scale <- function(score_percent) {

  score_percent <- as.numeric(score_percent)

  if (is.na(score_percent)) {
    stop("Error: Input must be numeric.")
  }

  valid_scores <- seq(0, 100, by = 10)
  if (!score_percent %in% valid_scores) {
    stop("Error: Score must be a multiple of 10 between 0 and 100.")
  }

  description <- ""

  if (score_percent == 100) {
    description <- "Completely independent. Able to do all chores without slowness, difficulty or impairment. Essentially normal. Unaware of any difficulty."
  } else if (score_percent == 90) {
    description <- "Completely independent. Able to do all chores with some degree of slowness, difficulty and impairment. Might take 2x longer. Beginning to be aware of difficulty."
  } else if (score_percent == 80) {
    description <- "Completely independent in most chores. Takes 2x longer. Conscious of difficulty and slowness."
  } else if (score_percent == 70) {
    description <- "Not completely independent. More difficulty with some chores. 3-4x longer in some. Must spend a large part of the day with chores."
  } else if (score_percent == 60) {
    description <- "Some dependency. Can do most chores, but exceedingly slowly and with much effort. Errors; some impossible."
  } else if (score_percent == 50) {
    description <- "More dependent. Help with half, slower, etc. Difficulty with everything."
  } else if (score_percent == 40) {
    description <- "Very dependent. Can assist with all chores and most ADLs."
  } else if (score_percent == 30) {
    description <- "With effort, now and then does a few chores alone or begins alone. Much help needed."
  } else if (score_percent == 20) {
    description <- "Nothing alone. Can be a slight help with some chores. Severe invalid."
  } else if (score_percent == 10) {
    description <- "Totally dependent, helpless. Complete invalid."
  } else {
    description <- "Vegetative functions such as swallowing, bladder and bowel functions are not functioning. Bedridden."
  }

  return(list(
    Schwab_England_Score = paste0(score_percent, "%"),
    Description = description
  ))
}

seattle_heart_failure_model <- function(age, sex, nyha_class, ejection_fraction, systolic_bp, ischemic_etiology, weight_kg, diuretic_daily_furosemide_equiv_mg, hemoglobin_g_dl, lymphocyte_percent, uric_acid_mg_dl, sodium_meq_l, cholesterol_mg_dl, qrs_duration_ms, ace_inhibitor, beta_blocker, statin, allopurinol, aldosterone_blocker, icd_device, crt_device) {

  age <- as.numeric(age)
  nyha_class <- as.numeric(nyha_class)
  ejection_fraction <- as.numeric(ejection_fraction)
  systolic_bp <- as.numeric(systolic_bp)
  weight_kg <- as.numeric(weight_kg)
  diuretic_daily_furosemide_equiv_mg <- as.numeric(diuretic_daily_furosemide_equiv_mg)
  hemoglobin_g_dl <- as.numeric(hemoglobin_g_dl)
  lymphocyte_percent <- as.numeric(lymphocyte_percent)
  uric_acid_mg_dl <- as.numeric(uric_acid_mg_dl)
  sodium_meq_l <- as.numeric(sodium_meq_l)
  cholesterol_mg_dl <- as.numeric(cholesterol_mg_dl)
  qrs_duration_ms <- as.numeric(qrs_duration_ms)

  sex <- tolower(as.character(sex))
  ischemic_etiology <- as.numeric(ischemic_etiology)
  ace_inhibitor <- as.numeric(ace_inhibitor)
  beta_blocker <- as.numeric(beta_blocker)
  statin <- as.numeric(statin)
  allopurinol <- as.numeric(allopurinol)
  aldosterone_blocker <- as.numeric(aldosterone_blocker)
  icd_device <- as.numeric(icd_device)
  crt_device <- as.numeric(crt_device)

  if (any(is.na(c(age, nyha_class, ejection_fraction, systolic_bp, weight_kg, diuretic_daily_furosemide_equiv_mg, hemoglobin_g_dl, lymphocyte_percent, uric_acid_mg_dl, sodium_meq_l, cholesterol_mg_dl)))) {
    stop("Error: All clinical and laboratory inputs must be numeric.")
  }

  if (!sex %in% c("male", "female")) {
    stop("Error: Sex must be 'male' or 'female'.")
  }

  score <- 0

  score <- score + (age / 10) * 0.090

  if (sex == "male") {
    score <- score + 0.090
  }

  score <- score + (nyha_class * 0.16)

  if (ejection_fraction > 0) {
    score <- score + (100 / ejection_fraction) * 0.029
  }

  if (ischemic_etiology == 1) {
    score <- score + 0.30
  }

  score <- score + (systolic_bp / 10) * -0.13

  if (weight_kg > 0) {
    diuretic_per_kg <- diuretic_daily_furosemide_equiv_mg / weight_kg
    score <- score + (diuretic_per_kg * 0.16)
  }

  if (allopurinol == 1) score <- score + 0.45
  if (statin == 1) score <- score - 0.46
  if (ace_inhibitor == 1) score <- score - 0.26
  if (beta_blocker == 1) score <- score - 0.43
  if (aldosterone_blocker == 1) score <- score - 0.36

  hgb <- hemoglobin_g_dl
  if (hgb < 16) {
    score <- score + (16 - hgb) * 0.117
  } else {
    score <- score + (hgb - 16) * 0.29
  }

  lymph <- min(lymphocyte_percent, 47)
  score <- score + (lymph / 5) * -0.108

  ua <- max(uric_acid_mg_dl, 3.4)
  score <- score + (ua * 0.08)

  na_val <- min(sodium_meq_l, 138)
  score <- score + (138 - na_val) * 0.04

  chol <- cholesterol_mg_dl
  score <- score + (chol / 10) * -0.03

  if (icd_device == 1) score <- score - 0.34
  if (crt_device == 1) score <- score - 0.69

  baseline_lambda <- 0.0405

  hazard_ratio <- exp(score)

  survival_1yr <- (exp(-baseline_lambda * 1)) ^ hazard_ratio
  survival_2yr <- (exp(-baseline_lambda * 2)) ^ hazard_ratio
  survival_5yr <- (exp(-baseline_lambda * 5)) ^ hazard_ratio

  median_survival_years <- -log(0.5) / (baseline_lambda * hazard_ratio)

  return(list(
    SHFM_Score = round(score, 3),
    Est_1_Year_Survival = paste0(round(survival_1yr * 100, 1), "%"),
    Est_2_Year_Survival = paste0(round(survival_2yr * 100, 1), "%"),
    Est_5_Year_Survival = paste0(round(survival_5yr * 100, 1), "%"),
    Est_Median_Survival = paste(round(median_survival_years, 1), "years"),
    Inputs = list(
      Age = age,
      Sex = sex,
      NYHA = nyha_class,
      EF = ejection_fraction,
      Ischemic = ischemic_etiology == 1,
      Meds = list(
        ACEI = ace_inhibitor == 1,
        BB = beta_blocker == 1,
        Statin = statin == 1,
        Allopurinol = allopurinol == 1,
        AldoBlocker = aldosterone_blocker == 1,
        Diuretic_mg_kg = round(diuretic_daily_furosemide_equiv_mg / weight_kg, 2)
      ),
      Devices = list(ICD = icd_device == 1, CRT = crt_device == 1)
    )
  ))
}

sich_score <- function(ncct_probability, age, sex, history_hypertension, impaired_coagulation) {

  ncct_probability <- tolower(as.character(ncct_probability))
  age <- as.numeric(age)
  sex <- tolower(as.character(sex))
  history_hypertension <- as.numeric(history_hypertension)
  impaired_coagulation <- as.numeric(impaired_coagulation)

  if (any(is.na(c(age, history_hypertension, impaired_coagulation)))) {
    stop("Error: All inputs must be valid.")
  }

  if (!ncct_probability %in% c("low", "indeterminate", "high")) {
    stop("Error: NCCT probability must be 'low', 'indeterminate', or 'high'.")
  }

  if (!sex %in% c("male", "female")) {
    stop("Error: Sex must be 'male' or 'female'.")
  }

  score <- 0

  if (ncct_probability == "high") {
    score <- score + 2
  } else if (ncct_probability == "indeterminate") {
    score <- score + 1
  }

  if (age >= 18 && age <= 45) {
    score <- score + 2
  } else if (age >= 46 && age <= 70) {
    score <- score + 1
  }

  if (sex == "female") {
    score <- score + 1
  }

  if (history_hypertension == 0 && impaired_coagulation == 0) {
    score <- score + 1
  }

  risk_percentage <- ""
  recommendation <- ""

  if (score == 0) {
    risk_percentage <- "0%"
    recommendation <- "Low risk of vascular etiology. Angiography may not be necessary."
  } else if (score == 1) {
    risk_percentage <- "1.4%"
    recommendation <- "Low risk of vascular etiology."
  } else if (score == 2) {
    risk_percentage <- "5.1%"
    recommendation <- "Moderate risk. Consider further evaluation based on clinical judgment."
  } else if (score == 3) {
    risk_percentage <- "18.5%"
    recommendation <- "High risk. Vascular imaging (CTA/MRA or DSA) recommended."
  } else if (score == 4) {
    risk_percentage <- "39.0%"
    recommendation <- "High risk. Vascular imaging (CTA/MRA or DSA) recommended."
  } else if (score == 5) {
    risk_percentage <- "84.2%"
    recommendation <- "Very high risk. Vascular imaging (CTA/MRA or DSA) strongly recommended."
  } else {
    risk_percentage <- "100%"
    recommendation <- "Very high risk. Vascular imaging (CTA/MRA or DSA) strongly recommended."
  }

  return(list(
    sICH_Score = score,
    Risk_Probability = risk_percentage,
    Recommendation = recommendation,
    Inputs = list(
      NCCT_Probability = ncct_probability,
      Age = age,
      Sex = sex,
      History_Hypertension = history_hypertension == 1,
      Impaired_Coagulation = impaired_coagulation == 1
    )
  ))
}

sedan_score_hemorrhage <- function(glucose, early_infarct_signs, hyperdense_artery_sign, age, nihss_score, glucose_units = "mmol/L") {

  glucose <- as.numeric(glucose)
  early_infarct_signs <- as.numeric(early_infarct_signs)
  hyperdense_artery_sign <- as.numeric(hyperdense_artery_sign)
  age <- as.numeric(age)
  nihss_score <- as.numeric(nihss_score)

  if (any(is.na(c(glucose, early_infarct_signs, hyperdense_artery_sign, age, nihss_score)))) {
    stop("Error: All inputs must be numeric.")
  }

  glucose_mmol <- glucose
  if (glucose_units == "mg/dL") {
    glucose_mmol <- glucose / 18.0
  }

  score <- 0

  if (glucose_mmol > 12.0) {
    score <- score + 2
  } else if (glucose_mmol > 8.0) {
    score <- score + 1
  } else {
    score <- score + 0
  }

  if (early_infarct_signs == 1) {
    score <- score + 1
  }

  if (hyperdense_artery_sign == 1) {
    score <- score + 1
  }

  if (age > 75) {
    score <- score + 1
  }

  if (nihss_score >= 10) {
    score <- score + 1
  }

  risk_percent <- ""
  risk_category <- ""

  if (score == 0) {
    risk_percent <- "1.4%"
    risk_category <- "Low Risk"
  } else if (score == 1) {
    risk_percent <- "2.9%"
    risk_category <- "Low Risk"
  } else if (score == 2) {
    risk_percent <- "8.5%"
    risk_category <- "Moderate Risk"
  } else if (score == 3) {
    risk_percent <- "12.2%"
    risk_category <- "Moderate Risk"
  } else if (score == 4) {
    risk_percent <- "21.7%"
    risk_category <- "High Risk"
  } else if (score == 5) {
    risk_percent <- "33.3%"
    risk_category <- "High Risk"
  } else {
    risk_percent <- "44.1%"
    risk_category <- "High Risk"
  }

  return(list(
    SEDAN_Score = score,
    Risk_sICH = risk_percent,
    Risk_Category = risk_category,
    Inputs = list(
      Glucose_mmol_L = round(glucose_mmol, 2),
      Early_Infarct_Signs = early_infarct_signs == 1,
      Hyperdense_Artery = hyperdense_artery_sign == 1,
      Age_gt_75 = age > 75,
      NIHSS_ge_10 = nihss_score >= 10
    )
  ))
}

sic_score <- function(platelet_count, inr, sofa_total_score) {

  platelet_count <- as.numeric(platelet_count)
  inr <- as.numeric(inr)
  sofa_total_score <- as.numeric(sofa_total_score)

  if (any(is.na(c(platelet_count, inr, sofa_total_score)))) {
    stop("Error: All inputs must be numeric.")
  }

  score <- 0

  if (platelet_count < 100) {
    score <- score + 2
  } else if (platelet_count >= 100 && platelet_count < 150) {
    score <- score + 1
  }

  if (inr > 1.4) {
    score <- score + 2
  } else if (inr > 1.2 && inr <= 1.4) {
    score <- score + 1
  }

  if (sofa_total_score >= 2) {
    score <- score + 2
  } else if (sofa_total_score == 1) {
    score <- score + 1
  }

  classification <- ""
  if (score >= 4) {
    classification <- "Sepsis-Induced Coagulopathy (SIC)"
  } else {
    classification <- "No SIC"
  }

  return(list(
    SIC_Score = score,
    Classification = classification,
    Inputs = list(
      Platelet_Count = platelet_count,
      INR = inr,
      SOFA_Score = sofa_total_score
    )
  ))
}

scarf_score <- function(respiratory_rate, spo2, lobes_affected) {

  respiratory_rate <- as.numeric(respiratory_rate)
  spo2 <- as.numeric(spo2)
  lobes_affected <- as.numeric(lobes_affected)

  if (any(is.na(c(respiratory_rate, spo2, lobes_affected)))) {
    stop("Error: All inputs must be numeric.")
  }

  score <- 0

  if (respiratory_rate < 20) {
    score <- score + 0
  } else if (respiratory_rate >= 20 && respiratory_rate <= 24) {
    score <- score + 2
  } else if (respiratory_rate >= 25 && respiratory_rate <= 30) {
    score <- score + 4
  } else {
    score <- score + 6
  }

  if (spo2 > 96) {
    score <- score + 0
  } else if (spo2 >= 94 && spo2 <= 96) {
    score <- score + 2
  } else if (spo2 >= 90 && spo2 <= 93) {
    score <- score + 4
  } else {
    score <- score + 6
  }

  if (lobes_affected <= 1) {
    score <- score + 0
  } else if (lobes_affected >= 2 && lobes_affected <= 3) {
    score <- score + 2
  } else {
    score <- score + 5
  }

  risk_category <- ""
  progression_risk <- ""

  if (score <= 2) {
    risk_category <- "Low Risk"
    progression_risk <- "2.4%"
  } else if (score <= 6) {
    risk_category <- "Moderate Risk"
    progression_risk <- "16.1%"
  } else {
    risk_category <- "High Risk"
    progression_risk <- "58.0%"
  }

  return(list(
    SCARF_Score = score,
    Risk_Category = risk_category,
    Risk_of_Severe_Pneumonia = progression_risk,
    Inputs = list(
      RR = respiratory_rate,
      SpO2 = spo2,
      Lobes = lobes_affected
    )
  ))
}

sofa_score <- function(pao2, fio2, mechanical_ventilation, platelets, bilirubin, mean_arterial_pressure, vasopressor_level, gcs, creatinine) {

  pao2 <- as.numeric(pao2)
  fio2 <- as.numeric(fio2)
  mechanical_ventilation <- as.numeric(mechanical_ventilation)
  platelets <- as.numeric(platelets)
  bilirubin <- as.numeric(bilirubin)
  mean_arterial_pressure <- as.numeric(mean_arterial_pressure)
  vasopressor_level <- tolower(as.character(vasopressor_level))
  gcs <- as.numeric(gcs)
  creatinine <- as.numeric(creatinine)

  if (any(is.na(c(pao2, fio2, platelets, bilirubin, mean_arterial_pressure, gcs, creatinine)))) {
    stop("Error: All numeric inputs must be valid.")
  }

  fio2_fraction <- fio2
  if (fio2 > 1.0) {
    fio2_fraction <- fio2 / 100
  }

  pf_ratio <- pao2 / fio2_fraction

  respiratory_score <- 0
  if (pf_ratio < 100 && mechanical_ventilation == 1) {
    respiratory_score <- 4
  } else if (pf_ratio < 200 && mechanical_ventilation == 1) {
    respiratory_score <- 3
  } else if (pf_ratio < 300) {
    respiratory_score <- 2
  } else if (pf_ratio < 400) {
    respiratory_score <- 1
  } else {
    respiratory_score <- 0
  }

  coagulation_score <- 0
  if (platelets < 20) {
    coagulation_score <- 4
  } else if (platelets < 50) {
    coagulation_score <- 3
  } else if (platelets < 100) {
    coagulation_score <- 2
  } else if (platelets < 150) {
    coagulation_score <- 1
  } else {
    coagulation_score <- 0
  }

  liver_score <- 0
  if (bilirubin > 12.0) {
    liver_score <- 4
  } else if (bilirubin >= 6.0) {
    liver_score <- 3
  } else if (bilirubin >= 2.0) {
    liver_score <- 2
  } else if (bilirubin >= 1.2) {
    liver_score <- 1
  } else {
    liver_score <- 0
  }

  cardiovascular_score <- 0
  if (vasopressor_level == "high") {
    cardiovascular_score <- 4
  } else if (vasopressor_level == "medium") {
    cardiovascular_score <- 3
  } else if (vasopressor_level == "low") {
    cardiovascular_score <- 2
  } else if (mean_arterial_pressure < 70) {
    cardiovascular_score <- 1
  } else {
    cardiovascular_score <- 0
  }

  cns_score <- 0
  if (gcs < 6) {
    cns_score <- 4
  } else if (gcs <= 9) {
    cns_score <- 3
  } else if (gcs <= 12) {
    cns_score <- 2
  } else if (gcs <= 14) {
    cns_score <- 1
  } else {
    cns_score <- 0
  }

  renal_score <- 0
  if (creatinine > 5.0) {
    renal_score <- 4
  } else if (creatinine >= 3.5) {
    renal_score <- 3
  } else if (creatinine >= 2.0) {
    renal_score <- 2
  } else if (creatinine >= 1.2) {
    renal_score <- 1
  } else {
    renal_score <- 0
  }

  total_score <- respiratory_score + coagulation_score + liver_score + cardiovascular_score + cns_score + renal_score

  mortality <- ""
  if (total_score <= 9) {
    mortality <- "< 33%"
  } else if (total_score <= 11) {
    mortality <- "40-50%"
  } else if (total_score <= 14) {
    mortality <- "50-60%"
  } else {
    mortality <- "> 80%"
  }

  return(list(
    SOFA_Score = total_score,
    Mortality_Estimate = mortality,
    Organ_Scores = list(
      Respiratory = respiratory_score,
      Coagulation = coagulation_score,
      Liver = liver_score,
      Cardiovascular = cardiovascular_score,
      CNS = cns_score,
      Renal = renal_score
    )
  ))
}

calculate_anion_gap <- function(sodium, chloride, bicarbonate, albumin = NULL) {

  sodium <- as.numeric(sodium)
  chloride <- as.numeric(chloride)
  bicarbonate <- as.numeric(bicarbonate)

  if (any(is.na(c(sodium, chloride, bicarbonate)))) {
    stop("Error: Sodium, Chloride, and Bicarbonate must be numeric.")
  }

  anion_gap <- sodium - (chloride + bicarbonate)

  result_list <- list(
    Anion_Gap = round(anion_gap, 1),
    Inputs = list(
      Sodium = sodium,
      Chloride = chloride,
      Bicarbonate = bicarbonate
    )
  )

  if (!is.null(albumin)) {
    albumin <- as.numeric(albumin)
    if (!is.na(albumin)) {
      corrected_ag <- anion_gap + (2.5 * (4.4 - albumin))
      result_list$Corrected_Anion_Gap = round(corrected_ag, 1)
      result_list$Inputs$Albumin = albumin
    }
  }

  return(result_list)
}

calculate_saag <- function(serum_albumin, ascites_albumin) {

  serum_albumin <- as.numeric(serum_albumin)
  ascites_albumin <- as.numeric(ascites_albumin)

  if (any(is.na(c(serum_albumin, ascites_albumin)))) {
    stop("Error: All inputs must be numeric.")
  }

  saag <- serum_albumin - ascites_albumin

  interpretation <- ""
  if (saag >= 1.1) {
    interpretation <- "High Gradient (>= 1.1 g/dL). Suggests Portal Hypertension (e.g., Cirrhosis, Heart Failure, Budd-Chiari)."
  } else {
    interpretation <- "Low Gradient (< 1.1 g/dL). Suggests Non-Portal Hypertension cause (e.g., Malignancy, TB, Nephrotic Syndrome)."
  }

  return(list(
    SAAG_Score = round(saag, 2),
    Interpretation = interpretation,
    Inputs = list(
      Serum_Albumin = serum_albumin,
      Ascites_Albumin = ascites_albumin
    )
  ))
}

calculate_serum_osmolality <- function(sodium, glucose, bun, ethanol = 0, glucose_units = "mg/dL", bun_units = "mg/dL", ethanol_units = "mg/dL") {

  sodium <- as.numeric(sodium)
  glucose <- as.numeric(glucose)
  bun <- as.numeric(bun)
  ethanol <- as.numeric(ethanol)

  if (any(is.na(c(sodium, glucose, bun, ethanol)))) {
    stop("Error: All inputs must be numeric.")
  }

  gluc_term <- glucose
  if (glucose_units == "mg/dL") {
    gluc_term <- glucose / 18
  }

  bun_term <- bun
  if (bun_units == "mg/dL") {
    bun_term <- bun / 2.8
  }

  eth_term <- ethanol
  if (ethanol_units == "mg/dL") {
    eth_term <- ethanol / 4.6
  }

  osmolality <- (2 * sodium) + gluc_term + bun_term + eth_term

  return(list(
    Calculated_Osmolality = round(osmolality, 1),
    Inputs = list(
      Sodium = sodium,
      Glucose = glucose,
      BUN = bun,
      Ethanol = ethanol
    )
  ))
}

set_score <- function(stroke_associated_history_present, ecg_t_wave_inversion, troponin_elevated) {

  stroke_associated_history_present <- as.numeric(stroke_associated_history_present)
  ecg_t_wave_inversion <- as.numeric(ecg_t_wave_inversion)
  troponin_elevated <- as.numeric(troponin_elevated)

  if (any(is.na(c(stroke_associated_history_present, ecg_t_wave_inversion, troponin_elevated)))) {
    stop("Error: All inputs must be numeric (0 or 1).")
  }

  score <- 0

  if (stroke_associated_history_present == 1) {
    score <- score + 2
  }

  if (ecg_t_wave_inversion == 1) {
    score <- score + 1
  }

  if (troponin_elevated == 1) {
    score <- score + 1
  }

  recommendation <- ""
  risk_profile <- ""

  if (score < 2) {
    recommendation <- "Unlikely to have Stroke"
    risk_profile <- "Consider alternative diagnoses. (Likelihood of stroke ~17% vs ~83% mimics)."
  } else {
    recommendation <- "Stroke Likely"
    risk_profile <- "High suspicion for ischemic stroke. (Likelihood ~77-80%)."
  }

  return(list(
    SET_Score = score,
    Recommendation = recommendation,
    Risk_Profile = risk_profile,
    Inputs = list(
      Stroke_Hx_Criteria = stroke_associated_history_present == 1,
      ECG_T_Waves = ecg_t_wave_inversion == 1,
      Trop_Elevated = troponin_elevated == 1
    )
  ))
}

scap_pneumonia_score <- function(arterial_ph, systolic_bp, respiratory_rate, pao2, fio2, bun, altered_mental_status, age, multilobar_involvement, bun_units = "mg/dL") {

  arterial_ph <- as.numeric(arterial_ph)
  systolic_bp <- as.numeric(systolic_bp)
  respiratory_rate <- as.numeric(respiratory_rate)
  pao2 <- as.numeric(pao2)
  fio2 <- as.numeric(fio2)
  bun <- as.numeric(bun)
  altered_mental_status <- as.numeric(altered_mental_status)
  age <- as.numeric(age)
  multilobar_involvement <- as.numeric(multilobar_involvement)

  if (any(is.na(c(arterial_ph, systolic_bp, respiratory_rate, pao2, fio2, bun, altered_mental_status, age, multilobar_involvement)))) {
    stop("Error: All inputs must be numeric.")
  }

  fio2_fraction <- fio2
  if (fio2 > 1.0) {
    fio2_fraction <- fio2 / 100
  }

  pf_ratio <- pao2 / fio2_fraction

  bun_mg_dl <- bun
  if (bun_units == "mmol/L") {
    bun_mg_dl <- bun * 2.8
  }

  score <- 0

  if (arterial_ph < 7.30) {
    score <- score + 13
  }

  if (systolic_bp < 90) {
    score <- score + 11
  }

  if (respiratory_rate > 30) {
    score <- score + 9
  }

  if (pf_ratio < 250) {
    score <- score + 6
  }

  if (bun_mg_dl > 30) {
    score <- score + 5
  }

  if (altered_mental_status == 1) {
    score <- score + 5
  }

  if (age >= 80) {
    score <- score + 5
  }

  if (multilobar_involvement == 1) {
    score <- score + 5
  }

  risk_class <- ""
  sae_risk <- ""
  mortality_risk <- ""

  if (score <= 9) {
    risk_class <- "Low Risk (Class 1)"
    sae_risk <- "1.6%"
    mortality_risk <- "0.7%"
  } else if (score <= 19) {
    risk_class <- "Moderate Risk (Class 2)"
    sae_risk <- "13.4%"
    mortality_risk <- "4.7%"
  } else if (score <= 29) {
    risk_class <- "High Risk (Class 3)"
    sae_risk <- "44.2%"
    mortality_risk <- "18.2%"
  } else {
    risk_class <- "Very High Risk (Class 4)"
    sae_risk <- "82.3%"
    mortality_risk <- "41.7%"
  }

  return(list(
    SCAP_Score = score,
    Risk_Class = risk_class,
    Severe_Adverse_Event_Risk = sae_risk,
    In_Hospital_Mortality_Risk = mortality_risk,
    Inputs = list(
      pH_lt_7_30 = arterial_ph < 7.30,
      SBP_lt_90 = systolic_bp < 90,
      RR_gt_30 = respiratory_rate > 30,
      PF_Ratio_lt_250 = pf_ratio < 250,
      BUN_gt_30 = bun_mg_dl > 30,
      Altered_Mental_Status = altered_mental_status == 1,
      Age_ge_80 = age >= 80,
      Multilobar_Involvement = multilobar_involvement == 1
    )
  ))
}

scorten_score <- function(age_years, heart_rate, malignancy, bsa_detached_percent, bun, bicarbonate, glucose, bun_units = "mg/dL", glucose_units = "mg/dL") {

  age_years <- as.numeric(age_years)
  heart_rate <- as.numeric(heart_rate)
  malignancy <- as.numeric(malignancy)
  bsa_detached_percent <- as.numeric(bsa_detached_percent)
  bun <- as.numeric(bun)
  bicarbonate <- as.numeric(bicarbonate)
  glucose <- as.numeric(glucose)

  if (any(is.na(c(age_years, heart_rate, malignancy, bsa_detached_percent, bun, bicarbonate, glucose)))) {
    stop("Error: All inputs must be numeric.")
  }

  bun_val <- bun
  if (bun_units == "mg/dL") {
    bun_val <- bun / 2.8
  }

  glucose_val <- glucose
  if (glucose_units == "mg/dL") {
    glucose_val <- glucose / 18.0
  }

  score <- 0

  if (age_years >= 40) {
    score <- score + 1
  }

  if (heart_rate >= 120) {
    score <- score + 1
  }

  if (malignancy == 1) {
    score <- score + 1
  }

  if (bsa_detached_percent >= 10) {
    score <- score + 1
  }

  if (bun_val > 10) {
    score <- score + 1
  }

  if (bicarbonate < 20) {
    score <- score + 1
  }

  if (glucose_val > 14) {
    score <- score + 1
  }

  mortality <- ""
  if (score <= 1) {
    mortality <- "3.2%"
  } else if (score == 2) {
    mortality <- "12.1%"
  } else if (score == 3) {
    mortality <- "35.3%"
  } else if (score == 4) {
    mortality <- "58.3%"
  } else {
    mortality <- "90.0%"
  }

  return(list(
    SCORTEN_Score = score,
    Estimated_Mortality = mortality,
    Inputs = list(
      Age_ge_40 = age_years >= 40,
      HR_ge_120 = heart_rate >= 120,
      Malignancy = malignancy == 1,
      BSA_ge_10 = bsa_detached_percent >= 10,
      BUN_gt_10_mmol = bun_val > 10,
      Bicarb_lt_20 = bicarbonate < 20,
      Glucose_gt_14_mmol = glucose_val > 14
    )
  ))
}

sex_shock_score <- function(sex, age, st_segment_elevation, lvef_category, creatinine, crp, creatinine_units = "mg/dL") {

  sex <- tolower(as.character(sex))
  age <- as.numeric(age)
  st_segment_elevation <- as.numeric(st_segment_elevation)
  lvef_category <- tolower(as.character(lvef_category))
  creatinine <- as.numeric(creatinine)
  crp <- as.numeric(crp)

  if (any(is.na(c(age, st_segment_elevation, creatinine, crp)))) {
    stop("Error: All numeric inputs must be valid.")
  }

  if (!sex %in% c("male", "female")) {
    stop("Error: Sex must be 'male' or 'female'.")
  }

  if (!lvef_category %in% c("lt_35", "35_50", "gt_50")) {
    stop("Error: LVEF category must be 'lt_35', '35_50', or 'gt_50'.")
  }

  creat_umol <- creatinine
  if (creatinine_units == "mg/dL") {
    creat_umol <- creatinine * 88.42
  }

  return(list(
    Message = "Exact calculation requires the specific regression coefficients from Wang et al. (2024).",
    Inputs = list(
      Sex = sex,
      Age = age,
      STEMI_Presentation = st_segment_elevation == 1,
      LVEF_Category = lvef_category,
      Creatinine_umol_L = round(creat_umol, 1),
      CRP_mg_L = crp
    )
  ))
}

sgarbossa_criteria <- function(concordant_ste_gt_1mm, concordant_std_v1_v3, discordant_ste_gt_5mm) {

  concordant_ste_gt_1mm <- as.numeric(concordant_ste_gt_1mm)
  concordant_std_v1_v3 <- as.numeric(concordant_std_v1_v3)
  discordant_ste_gt_5mm <- as.numeric(discordant_ste_gt_5mm)

  if (any(is.na(c(concordant_ste_gt_1mm, concordant_std_v1_v3, discordant_ste_gt_5mm)))) {
    stop("Error: All inputs must be numeric.")
  }

  score <- 0

  if (concordant_ste_gt_1mm == 1) {
    score <- score + 5
  }

  if (concordant_std_v1_v3 == 1) {
    score <- score + 3
  }

  if (discordant_ste_gt_5mm == 1) {
    score <- score + 2
  }

  result <- ""
  if (score >= 3) {
    result <- "Positive for AMI (High Specificity)"
  } else {
    result <- "Negative by Original Sgarbossa Criteria"
  }

  return(list(
    Sgarbossa_Score = score,
    Result = result,
    Inputs = list(
      Concordant_STE = concordant_ste_gt_1mm == 1,
      Concordant_STD_V1_V3 = concordant_std_v1_v3 == 1,
      Discordant_STE_gt_5mm = discordant_ste_gt_5mm == 1
    )
  ))
}

shanghai_pancreatitis_score <- function(bmi, age, pleural_effusion, hematocrit, creatinine, ldh, creatinine_units = "mg/dL") {

  bmi <- as.numeric(bmi)
  age <- as.numeric(age)
  pleural_effusion <- as.numeric(pleural_effusion)
  hematocrit <- as.numeric(hematocrit)
  creatinine <- as.numeric(creatinine)
  ldh <- as.numeric(ldh)

  if (any(is.na(c(bmi, age, pleural_effusion, hematocrit, creatinine, ldh)))) {
    stop("Error: All inputs must be numeric.")
  }

  creat_mg_dl <- creatinine
  if (creatinine_units == "umol/L" || creatinine_units == "micromol/L") {
    creat_mg_dl <- creatinine / 88.4
  }

  score <- 0

  if (bmi >= 25) {
    score <- score + 1
  }

  if (age >= 60) {
    score <- score + 1
  }

  if (pleural_effusion == 1) {
    score <- score + 1
  }

  if (hematocrit >= 46) {
    score <- score + 1
  }

  if (creat_mg_dl >= 1.6) {
    score <- score + 1
  }

  if (ldh >= 340) {
    score <- score + 1
  }

  risk_category <- ""
  if (score < 2) {
    risk_category <- "Low Risk for Severe Acute Pancreatitis"
  } else {
    risk_category <- "High Risk for Severe Acute Pancreatitis"
  }

  return(list(
    Shanghai_Score = score,
    Risk_Category = risk_category,
    Inputs = list(
      BMI_ge_25 = bmi >= 25,
      Age_ge_60 = age >= 60,
      Pleural_Effusion = pleural_effusion == 1,
      Hct_ge_46 = hematocrit >= 46,
      Creatinine_ge_1_6 = creat_mg_dl >= 1.6,
      LDH_ge_340 = ldh >= 340
    )
  ))
}

shapiro_rule_bacteremia <- function(age, shaking_chills, vomiting, temperature_c, systolic_bp, wbc_count, creatinine, bands_percent, platelet_count, suspected_endocarditis, indwelling_vascular_catheter) {

  age <- as.numeric(age)
  shaking_chills <- as.numeric(shaking_chills)
  vomiting <- as.numeric(vomiting)
  temperature_c <- as.numeric(temperature_c)
  systolic_bp <- as.numeric(systolic_bp)
  wbc_count <- as.numeric(wbc_count)
  creatinine <- as.numeric(creatinine)
  bands_percent <- as.numeric(bands_percent)
  platelet_count <- as.numeric(platelet_count)
  suspected_endocarditis <- as.numeric(suspected_endocarditis)
  indwelling_vascular_catheter <- as.numeric(indwelling_vascular_catheter)

  if (any(is.na(c(age, shaking_chills, vomiting, temperature_c, systolic_bp, wbc_count, creatinine, bands_percent, platelet_count, suspected_endocarditis, indwelling_vascular_catheter)))) {
    stop("Error: All inputs must be numeric.")
  }

  major_criteria <- 0

  if (suspected_endocarditis == 1) {
    major_criteria <- major_criteria + 1
  }

  if (temperature_c > 39.4) {
    major_criteria <- major_criteria + 1
  }

  if (indwelling_vascular_catheter == 1) {
    major_criteria <- major_criteria + 1
  }

  minor_criteria <- 0

  if (age > 65) {
    minor_criteria <- minor_criteria + 1
  }

  if (shaking_chills == 1) {
    minor_criteria <- minor_criteria + 1
  }

  if (vomiting == 1) {
    minor_criteria <- minor_criteria + 1
  }

  if (systolic_bp < 90) {
    minor_criteria <- minor_criteria + 1
  }

  if (wbc_count > 18000) {
    minor_criteria <- minor_criteria + 1
  }

  if (creatinine > 2.0) {
    minor_criteria <- minor_criteria + 1
  }

  if (bands_percent > 5) {
    minor_criteria <- minor_criteria + 1
  }

  if (platelet_count < 150000) {
    minor_criteria <- minor_criteria + 1
  }

  recommendation <- ""
  if (major_criteria >= 1 || minor_criteria >= 2) {
    recommendation <- "Blood Cultures Indicated (Risk of Bacteremia Present)"
  } else {
    recommendation <- "Blood Cultures Not Indicated (Low Risk of Bacteremia)"
  }

  return(list(
    Recommendation = recommendation,
    Major_Criteria_Met = major_criteria,
    Minor_Criteria_Met = minor_criteria,
    Inputs = list(
      Age = age,
      Chills = shaking_chills == 1,
      Vomiting = vomiting == 1,
      Temp_C = temperature_c,
      SBP = systolic_bp,
      WBC = wbc_count,
      Creatinine = creatinine,
      Bands_Pct = bands_percent,
      Platelets = platelet_count,
      Endocarditis_Suspicion = suspected_endocarditis == 1,
      Vascular_Catheter = indwelling_vascular_catheter == 1
    )
  ))
}

shock_index <- function(heart_rate, systolic_bp) {

  heart_rate <- as.numeric(heart_rate)
  systolic_bp <- as.numeric(systolic_bp)

  if (any(is.na(c(heart_rate, systolic_bp)))) {
    stop("Error: All inputs must be numeric.")
  }

  if (systolic_bp == 0) {
    stop("Error: Systolic BP cannot be zero.")
  }

  si <- heart_rate / systolic_bp

  interpretation <- ""

  if (si < 0.5) {
    interpretation <- "Low (Normal range 0.5-0.7)"
  } else if (si <= 0.7) {
    interpretation <- "Normal"
  } else if (si <= 0.9) {
    interpretation <- "Elevated (Possible occult shock)"
  } else {
    interpretation <- "High (Likely shock/hemodynamic instability)"
  }

  return(list(
    Shock_Index = round(si, 2),
    Interpretation = interpretation,
    Inputs = list(
      HR = heart_rate,
      SBP = systolic_bp
    )
  ))
}

sipa_score <- function(age_years, heart_rate, systolic_bp) {

  age_years <- as.numeric(age_years)
  heart_rate <- as.numeric(heart_rate)
  systolic_bp <- as.numeric(systolic_bp)

  if (any(is.na(c(age_years, heart_rate, systolic_bp)))) {
    stop("Error: All inputs must be numeric.")
  }

  if (systolic_bp == 0) {
    stop("Error: Systolic BP cannot be zero.")
  }

  shock_index <- heart_rate / systolic_bp

  sipa_elevated <- FALSE
  cutoff <- NA

  if (age_years >= 4 && age_years <= 6) {
    cutoff <- 1.22
  } else if (age_years >= 7 && age_years <= 12) {
    cutoff <- 1.00
  } else if (age_years >= 13 && age_years <= 16) {
    cutoff <- 0.90
  }

  if (!is.na(cutoff)) {
    if (shock_index > cutoff) {
      sipa_elevated <- TRUE
    }
  }

  result_text <- ""
  if (is.na(cutoff)) {
    result_text <- "Age outside validated range for SIPA cutoffs (4-16 years)."
  } else if (sipa_elevated) {
    result_text <- "Elevated SIPA. Associated with increased risk of severe injury, need for transfusion, and mortality."
  } else {
    result_text <- "Normal SIPA for age."
  }

  return(list(
    Shock_Index = round(shock_index, 2),
    SIPA_Outcome = result_text,
    Age_Cutoff_Used = cutoff,
    Inputs = list(
      Age = age_years,
      HR = heart_rate,
      SBP = systolic_bp
    )
  ))
}

shorr_score_mrsa <- function(age, nursing_home, heart_failure, cerebrovascular_disease, diabetes, icu_admission_24h) {

  age <- as.numeric(age)
  nursing_home <- as.numeric(nursing_home)
  heart_failure <- as.numeric(heart_failure)
  cerebrovascular_disease <- as.numeric(cerebrovascular_disease)
  diabetes <- as.numeric(diabetes)
  icu_admission_24h <- as.numeric(icu_admission_24h)

  if (any(is.na(c(age, nursing_home, heart_failure, cerebrovascular_disease, diabetes, icu_admission_24h)))) {
    stop("Error: All inputs must be numeric.")
  }

  score <- 0

  if (age < 30) {
    score <- score + 0
  } else if (age >= 30 && age <= 39) {
    score <- score + 1
  } else if (age >= 40 && age <= 49) {
    score <- score + 2
  } else if (age >= 50 && age <= 59) {
    score <- score + 3
  } else if (age >= 60 && age <= 69) {
    score <- score + 4
  } else if (age >= 70 && age <= 79) {
    score <- score + 5
  } else {
    score <- score + 6
  }

  if (nursing_home == 1) {
    score <- score + 4
  }

  if (heart_failure == 1) {
    score <- score + 2
  }

  if (cerebrovascular_disease == 1) {
    score <- score + 2
  }

  if (diabetes == 1) {
    score <- score + 1
  }

  if (icu_admission_24h == 1) {
    score <- score + 2
  }

  risk_level <- ""

  if (score <= 1) {
    risk_level <- "Low Risk"
  } else if (score <= 5) {
    risk_level <- "Intermediate Risk"
  } else {
    risk_level <- "High Risk"
  }

  return(list(
    Shorr_Score = score,
    Risk_Category = risk_level,
    Inputs = list(
      Age = age,
      Nursing_Home = nursing_home == 1,
      CHF = heart_failure == 1,
      CVD = cerebrovascular_disease == 1,
      Diabetes = diabetes == 1,
      ICU = icu_admission_24h == 1
    )
  ))
}

