sickle_cell_rbc_exchange <- function(sex, height_cm, weight_kg, initial_hct_percent, target_hct_percent, replacement_hct_percent, initial_hbs_percent, target_hbs_percent) {

  sex <- tolower(as.character(sex))
  height_cm <- as.numeric(height_cm)
  weight_kg <- as.numeric(weight_kg)
  initial_hct_percent <- as.numeric(initial_hct_percent)
  target_hct_percent <- as.numeric(target_hct_percent)
  replacement_hct_percent <- as.numeric(replacement_hct_percent)
  initial_hbs_percent <- as.numeric(initial_hbs_percent)
  target_hbs_percent <- as.numeric(target_hbs_percent)

  if (any(is.na(c(height_cm, weight_kg, initial_hct_percent, target_hct_percent, replacement_hct_percent, initial_hbs_percent, target_hbs_percent)))) {
    stop("Error: All inputs must be numeric.")
  }

  if (!sex %in% c("male", "female")) {
    stop("Error: Sex must be 'male' or 'female'.")
  }

  height_m <- height_cm / 100

  tbv <- 0
  if (sex == "male") {
    tbv <- (0.3669 * (height_m ^ 3)) + (0.03219 * weight_kg) + 0.6041
  } else {
    tbv <- (0.3561 * (height_m ^ 3)) + (0.03308 * weight_kg) + 0.1833
  }

  tbv_ml <- tbv * 1000

  hct_avg <- (initial_hct_percent + target_hct_percent) / 2 / 100

  rep_hct_decimal <- replacement_hct_percent / 100

  fcr <- target_hbs_percent / initial_hbs_percent

  if (fcr <= 0) {
    volume_needed <- Inf
  } else {
    volume_needed <- (tbv_ml * hct_avg / rep_hct_decimal) * log(initial_hbs_percent / target_hbs_percent)
  }

  return(list(
    Replacement_Volume_mL = round(volume_needed, 0),
    Total_Blood_Volume_mL = round(tbv_ml, 0),
    Inputs = list(
      Sex = sex,
      Height = height_cm,
      Weight = weight_kg,
      Initial_Hct = initial_hct_percent,
      Target_Hct = target_hct_percent,
      Replacement_Hct = replacement_hct_percent,
      Initial_HbS = initial_hbs_percent,
      Target_HbS = target_hbs_percent
    )
  ))
}

simon_broome_fh_criteria <- function(adult, total_cholesterol, ldl_cholesterol, tendinous_xanthoma, fh_premature_chd, fh_hypercholesterolemia, dna_mutation, units = "mg/dL") {

  adult <- as.numeric(adult)
  total_cholesterol <- as.numeric(total_cholesterol)
  ldl_cholesterol <- as.numeric(ldl_cholesterol)
  tendinous_xanthoma <- as.numeric(tendinous_xanthoma)
  fh_premature_chd <- as.numeric(fh_premature_chd)
  fh_hypercholesterolemia <- as.numeric(fh_hypercholesterolemia)
  dna_mutation <- as.numeric(dna_mutation)

  if (any(is.na(c(total_cholesterol, ldl_cholesterol, tendinous_xanthoma, fh_premature_chd, fh_hypercholesterolemia, dna_mutation)))) {
    stop("Error: All inputs must be numeric.")
  }

  tc_mmol <- total_cholesterol
  ldl_mmol <- ldl_cholesterol

  if (units == "mg/dL") {
    tc_mmol <- total_cholesterol / 38.67
    ldl_mmol <- ldl_cholesterol / 38.67
  }

  cholesterol_criteria_met <- FALSE
  if (adult == 1) {
    if (tc_mmol > 7.5 || ldl_mmol > 4.9) {
      cholesterol_criteria_met <- TRUE
    }
  } else {
    if (tc_mmol > 6.7 || ldl_mmol > 4.0) {
      cholesterol_criteria_met <- TRUE
    }
  }

  diagnosis <- "Unlikely FH"

  if (cholesterol_criteria_met) {
    if (dna_mutation == 1) {
      diagnosis <- "Definite FH"
    } else if (tendinous_xanthoma == 1) {
      diagnosis <- "Definite FH"
    } else if (fh_premature_chd == 1 || fh_hypercholesterolemia == 1) {
      diagnosis <- "Possible FH"
    } else {
      diagnosis <- "Unlikely FH"
    }
  } else {
    diagnosis <- "Unlikely FH"
  }

  return(list(
    Diagnosis = diagnosis,
    Cholesterol_Met = cholesterol_criteria_met,
    Inputs = list(
      Adult = adult == 1,
      Total_Chol = total_cholesterol,
      LDL_Chol = ldl_cholesterol,
      Xanthoma = tendinous_xanthoma == 1,
      Family_Hx_CHD = fh_premature_chd == 1,
      Family_Hx_High_Chol = fh_hypercholesterolemia == 1,
      DNA_Mutation = dna_mutation == 1
    )
  ))
}

sdai_rheumatoid_arthritis <- function(tender_joint_count_28, swollen_joint_count_28, patient_global_assessment, provider_global_assessment, crp_mg_dl) {

  tender_joint_count_28 <- as.numeric(tender_joint_count_28)
  swollen_joint_count_28 <- as.numeric(swollen_joint_count_28)
  patient_global_assessment <- as.numeric(patient_global_assessment)
  provider_global_assessment <- as.numeric(provider_global_assessment)
  crp_mg_dl <- as.numeric(crp_mg_dl)

  if (any(is.na(c(tender_joint_count_28, swollen_joint_count_28, patient_global_assessment, provider_global_assessment, crp_mg_dl)))) {
    stop("Error: All inputs must be numeric.")
  }

  if (tender_joint_count_28 < 0 || tender_joint_count_28 > 28) stop("Error: Tender joint count must be 0-28.")
  if (swollen_joint_count_28 < 0 || swollen_joint_count_28 > 28) stop("Error: Swollen joint count must be 0-28.")
  if (patient_global_assessment < 0 || patient_global_assessment > 10) stop("Error: Patient Global Assessment must be 0-10.")
  if (provider_global_assessment < 0 || provider_global_assessment > 10) stop("Error: Provider Global Assessment must be 0-10.")
  if (crp_mg_dl < 0) stop("Error: CRP cannot be negative.")

  sdai_score <- tender_joint_count_28 + swollen_joint_count_28 + patient_global_assessment + provider_global_assessment + crp_mg_dl

  disease_activity <- ""
  if (sdai_score <= 3.3) {
    disease_activity <- "Remission"
  } else if (sdai_score <= 11.0) {
    disease_activity <- "Low Activity"
  } else if (sdai_score <= 26.0) {
    disease_activity <- "Moderate Activity"
  } else {
    disease_activity <- "High Activity"
  }

  return(list(
    SDAI_Score = round(sdai_score, 2),
    Disease_Activity = disease_activity,
    Inputs = list(
      Tender_Joints = tender_joint_count_28,
      Swollen_Joints = swollen_joint_count_28,
      Patient_Global = patient_global_assessment,
      Provider_Global = provider_global_assessment,
      CRP_mg_dL = crp_mg_dl
    )
  ))
}

saps_3_score <- function(age, admission_type, admission_source, length_of_stay_days, anatomical_system, infection_type, gcs_score, bilirubin_mg_dl, temperature_c, creatinine_mg_dl, heart_rate, wbc_count, ph_level, platelet_count, systolic_bp, mechanical_ventilation, pao2_fio2_ratio, vasoactive_drugs, comorbidities) {

  age <- as.numeric(age)
  length_of_stay_days <- as.numeric(length_of_stay_days)
  gcs_score <- as.numeric(gcs_score)
  bilirubin_mg_dl <- as.numeric(bilirubin_mg_dl)
  temperature_c <- as.numeric(temperature_c)
  creatinine_mg_dl <- as.numeric(creatinine_mg_dl)
  heart_rate <- as.numeric(heart_rate)
  wbc_count <- as.numeric(wbc_count)
  ph_level <- as.numeric(ph_level)
  platelet_count <- as.numeric(platelet_count)
  systolic_bp <- as.numeric(systolic_bp)
  pao2_fio2_ratio <- as.numeric(pao2_fio2_ratio)

  admission_type <- tolower(as.character(admission_type))
  admission_source <- tolower(as.character(admission_source))
  anatomical_system <- tolower(as.character(anatomical_system))
  infection_type <- tolower(as.character(infection_type))

  mechanical_ventilation <- as.numeric(mechanical_ventilation)
  vasoactive_drugs <- as.numeric(vasoactive_drugs)

  if (any(is.na(c(age, length_of_stay_days, gcs_score, bilirubin_mg_dl, temperature_c, creatinine_mg_dl, heart_rate, wbc_count, ph_level, platelet_count, systolic_bp)))) {
    stop("Error: All physiologic inputs must be numeric.")
  }

  points <- 0

  if (age < 40) points <- points + 0
  else if (age < 60) points <- points + 5
  else if (age < 70) points <- points + 9
  else if (age < 75) points <- points + 13
  else if (age < 80) points <- points + 15
  else points <- points + 18

  if (!is.null(comorbidities)) {
    if ("cancer_therapy" %in% comorbidities) points <- points + 3
    if ("hematologic_cancer" %in% comorbidities) points <- points + 10
    if ("cirrhosis" %in% comorbidities) points <- points + 8
    if ("aids" %in% comorbidities) points <- points + 13
    if ("heart_failure_nyha4" %in% comorbidities) points <- points + 6
    if ("metastatic_cancer" %in% comorbidities) points <- points + 13
    if ("immunosuppression" %in% comorbidities) points <- points + 7
  }

  if (admission_source == "emergency_room") points <- points + 5
  else if (admission_source == "other_icu") points <- points + 8
  else if (admission_source == "ward") points <- points + 8
  else if (admission_source == "other_hospital") points <- points + 9

  if (length_of_stay_days >= 14 && length_of_stay_days < 28) points <- points + 6
  else if (length_of_stay_days >= 28) points <- points + 7

  sys_score <- 0
  if (admission_type == "scheduled_surgical") {
    if (anatomical_system == "cardiovascular") sys_score <- -9
    else if (anatomical_system == "digestive") sys_score <- -4
    else if (anatomical_system == "neurologic") sys_score <- -5
    else if (anatomical_system == "trauma") sys_score <- -6
    else sys_score <- -5
  } else if (admission_type == "unscheduled_surgical") {
    if (anatomical_system == "cardiovascular") sys_score <- -5
    else if (anatomical_system == "digestive") sys_score <- 6
    else if (anatomical_system == "neurologic") sys_score <- 4
    else if (anatomical_system == "trauma") sys_score <- 0
    else sys_score <- 4
  } else {
    if (anatomical_system == "cardiovascular") sys_score <- 6
    else if (anatomical_system == "digestive") sys_score <- 8
    else if (anatomical_system == "neurologic") sys_score <- 12
    else if (anatomical_system == "respiratory") sys_score <- 8
    else if (anatomical_system == "renal") sys_score <- 6
    else if (anatomical_system == "hematologic") sys_score <- 10
    else if (anatomical_system == "metabolic") sys_score <- 6
    else if (anatomical_system == "trauma") sys_score <- 5
    else sys_score <- 8
  }
  points <- points + sys_score

  if (infection_type == "respiratory") points <- points + 2
  else if (infection_type == "nosocomial") points <- points + 4

  if (gcs_score <= 5) points <- points + 26
  else if (gcs_score <= 8) points <- points + 15
  else if (gcs_score <= 13) points <- points + 10
  else if (gcs_score == 14) points <- points + 2

  if (bilirubin_mg_dl >= 6.0) points <- points + 9
  else if (bilirubin_mg_dl >= 2.0) points <- points + 4

  if (temperature_c < 35.0) points <- points + 2
  else if (temperature_c >= 40.0) points <- points + 2

  if (creatinine_mg_dl >= 3.5) points <- points + 11
  else if (creatinine_mg_dl >= 2.0) points <- points + 8
  else if (creatinine_mg_dl >= 1.2) points <- points + 3

  if (heart_rate >= 120) points <- points + 7

  if (wbc_count >= 20) points <- points + 3

  if (ph_level < 7.25) points <- points + 3

  if (platelet_count < 20) points <- points + 13
  else if (platelet_count < 50) points <- points + 8
  else if (platelet_count < 100) points <- points + 5

  if (systolic_bp < 40) points <- points + 16
  else if (systolic_bp < 70) points <- points + 11
  else if (systolic_bp < 120) points <- points + 7

  if (mechanical_ventilation == 1) {
    if (pao2_fio2_ratio < 100) points <- points + 11
    else points <- points + 6
  }

  if (vasoactive_drugs == 1) points <- points + 11

  logit <- -32.6659 + 7.3068 * log(points + 20.5958)
  mortality <- exp(logit) / (1 + exp(logit))

  return(list(
    SAPS_3_Score = points,
    Predicted_Hospital_Mortality = paste0(round(mortality * 100, 1), "%"),
    Inputs = list(
      Age = age,
      Type = admission_type,
      System = anatomical_system,
      GCS = gcs_score,
      Vasoactive = vasoactive_drugs == 1,
      Ventilated = mechanical_ventilation == 1
    )
  ))
}

saps_ii_score <- function(age, heart_rate, systolic_bp, temperature_c, mechanical_ventilation_cpap, pao2, fio2, urine_output_24h_l, bun, wbc_count, potassium, sodium, bicarbonate, bilirubin, gcs, admission_type, chronic_diseases = NULL, bun_units = "mg/dL", bilirubin_units = "mg/dL") {

  age <- as.numeric(age)
  heart_rate <- as.numeric(heart_rate)
  systolic_bp <- as.numeric(systolic_bp)
  temperature_c <- as.numeric(temperature_c)
  mechanical_ventilation_cpap <- as.numeric(mechanical_ventilation_cpap)
  pao2 <- as.numeric(pao2)
  fio2 <- as.numeric(fio2)
  urine_output_24h_l <- as.numeric(urine_output_24h_l)
  bun <- as.numeric(bun)
  wbc_count <- as.numeric(wbc_count)
  potassium <- as.numeric(potassium)
  sodium <- as.numeric(sodium)
  bicarbonate <- as.numeric(bicarbonate)
  bilirubin <- as.numeric(bilirubin)
  gcs <- as.numeric(gcs)

  if (any(is.na(c(age, heart_rate, systolic_bp, temperature_c, urine_output_24h_l, bun, wbc_count, potassium, sodium, bicarbonate, bilirubin, gcs)))) {
    stop("Error: All physiologic inputs must be numeric.")
  }

  bun_val <- bun
  if (bun_units == "mmol/L") {
    bun_val <- bun * 2.8
  }

  bili_val <- bilirubin
  if (bilirubin_units == "umol/L") {
    bili_val <- bilirubin / 17.1
  }

  score <- 0

  if (age < 40) score <- score + 0
  else if (age <= 59) score <- score + 7
  else if (age <= 69) score <- score + 12
  else if (age <= 74) score <- score + 15
  else if (age <= 79) score <- score + 16
  else score <- score + 18

  if (heart_rate < 40) score <- score + 11
  else if (heart_rate <= 69) score <- score + 2
  else if (heart_rate <= 119) score <- score + 0
  else if (heart_rate <= 159) score <- score + 4
  else score <- score + 7

  if (systolic_bp < 70) score <- score + 13
  else if (systolic_bp <= 99) score <- score + 5
  else if (systolic_bp <= 199) score <- score + 0
  else score <- score + 2

  if (temperature_c < 39) score <- score + 0
  else score <- score + 3

  if (mechanical_ventilation_cpap == 1) {
    pf_ratio <- pao2 / (fio2 / 100) # Assuming fio2 is percentage 21-100, if 0-1 adjust.
    if (fio2 <= 1.0) pf_ratio <- pao2 / fio2

    if (pf_ratio < 100) score <- score + 11
    else if (pf_ratio <= 199) score <- score + 9
    else score <- score + 6
  }

  if (urine_output_24h_l < 0.5) score <- score + 11
  else if (urine_output_24h_l < 1.0) score <- score + 4
  else score <- score + 0

  if (bun_val < 28) score <- score + 0
  else if (bun_val < 84) score <- score + 6
  else score <- score + 10

  if (wbc_count < 1) score <- score + 12
  else if (wbc_count < 20) score <- score + 0
  else score <- score + 3

  if (potassium < 3) score <- score + 3
  else if (potassium < 5) score <- score + 0
  else score <- score + 3

  if (sodium < 125) score <- score + 5
  else if (sodium < 145) score <- score + 0
  else score <- score + 1

  if (bicarbonate < 15) score <- score + 6
  else if (bicarbonate < 20) score <- score + 3
  else score <- score + 0

  if (bili_val < 4) score <- score + 0
  else if (bili_val < 6) score <- score + 4
  else score <- score + 9

  if (gcs < 6) score <- score + 26
  else if (gcs <= 8) score <- score + 13
  else if (gcs <= 10) score <- score + 7
  else if (gcs <= 13) score <- score + 5
  else score <- score + 0

  if (!is.null(chronic_diseases)) {
    if ("aids" %in% chronic_diseases) score <- score + 17
    if ("hematologic_malignancy" %in% chronic_diseases) score <- score + 10
    if ("metastatic_cancer" %in% chronic_diseases) score <- score + 9
  }

  if (admission_type == "unscheduled_surgical") score <- score + 8
  else if (admission_type == "medical") score <- score + 6
  else score <- score + 0

  logit <- -7.7631 + (0.0737 * score) + (0.9971 * log(score + 1))
  mortality <- exp(logit) / (1 + exp(logit))

  return(list(
    SAPS_II_Score = score,
    Predicted_Hospital_Mortality = paste0(round(mortality * 100, 1), "%"),
    Inputs = list(
      Age = age,
      GCS = gcs,
      Type = admission_type,
      Comorbidities = chronic_diseases
    )
  ))
}

simplified_aih_score <- function(ana_or_sma_titer, lkm_titer, sla_antibody_positive, igg_level, igg_uln, liver_histology, viral_hepatitis_absent) {

  ana_or_sma_titer <- tolower(as.character(ana_or_sma_titer))
  lkm_titer <- tolower(as.character(lkm_titer))
  sla_antibody_positive <- as.numeric(sla_antibody_positive)
  igg_level <- as.numeric(igg_level)
  igg_uln <- as.numeric(igg_uln)
  liver_histology <- tolower(as.character(liver_histology))
  viral_hepatitis_absent <- as.numeric(viral_hepatitis_absent)

  if (any(is.na(c(igg_level, igg_uln, sla_antibody_positive, viral_hepatitis_absent)))) {
    stop("Error: Inputs must be valid.")
  }

  antibody_points <- 0
  if (ana_or_sma_titer == ">=1:80" || lkm_titer == ">=1:40" || sla_antibody_positive == 1) {
    antibody_points <- 2
  } else if (ana_or_sma_titer == ">=1:40") {
    antibody_points <- 1
  }

  igg_ratio <- igg_level / igg_uln
  igg_points <- 0
  if (igg_ratio > 1.10) {
    igg_points <- 2
  } else if (igg_ratio >= 1.0) {
    igg_points <- 1
  }

  histology_points <- 0
  if (liver_histology == "typical") {
    histology_points <- 2
  } else if (liver_histology == "compatible") {
    histology_points <- 1
  }

  viral_points <- 0
  if (viral_hepatitis_absent == 1) {
    viral_points <- 2
  }

  total_score <- antibody_points + igg_points + histology_points + viral_points

  diagnosis <- "Not Diagnostic"
  if (total_score >= 7) {
    diagnosis <- "Definite Autoimmune Hepatitis"
  } else if (total_score >= 6) {
    diagnosis <- "Probable Autoimmune Hepatitis"
  }

  return(list(
    Simplified_AIH_Score = total_score,
    Diagnosis = diagnosis,
    Inputs = list(
      Antibody_Score = antibody_points,
      IgG_Score = igg_points,
      Histology_Score = histology_points,
      Viral_Score = viral_points
    )
  ))
}

simplified_motor_score <- function(motor_response) {

  motor_response <- as.numeric(motor_response)

  if (is.na(motor_response) || !motor_response %in% c(0, 1, 2)) {
    stop("Error: Motor response must be 0, 1, or 2.")
  }

  interpretation <- ""
  recommendation <- ""

  if (motor_response == 2) {
    interpretation <- "Low Risk of Significant Traumatic Brain Injury"
    recommendation <- "Comparable to GCS 14-15. Outcomes generally favorable."
  } else {
    interpretation <- "High Risk of Significant Traumatic Brain Injury"
    recommendation <- "Comparable to GCS <= 13. High risk of requiring intubation, neurosurgery, or mortality. Advanced airway management and imaging indicated."
  }

  return(list(
    SMS_Score = motor_response,
    Risk_Classification = interpretation,
    Clinical_Implication = recommendation,
    Inputs = list(
      Motor_Response_Score = motor_response
    )
  ))
}

simplified_pesi_score <- function(age, cancer_history, chronic_cardiopulmonary_disease, heart_rate, systolic_bp, oxygen_saturation) {

  age <- as.numeric(age)
  cancer_history <- as.numeric(cancer_history)
  chronic_cardiopulmonary_disease <- as.numeric(chronic_cardiopulmonary_disease)
  heart_rate <- as.numeric(heart_rate)
  systolic_bp <- as.numeric(systolic_bp)
  oxygen_saturation <- as.numeric(oxygen_saturation)

  if (any(is.na(c(age, cancer_history, chronic_cardiopulmonary_disease, heart_rate, systolic_bp, oxygen_saturation)))) {
    stop("Error: All inputs must be numeric.")
  }

  score <- 0

  if (age > 80) {
    score <- score + 1
  }

  if (cancer_history == 1) {
    score <- score + 1
  }

  if (chronic_cardiopulmonary_disease == 1) {
    score <- score + 1
  }

  if (heart_rate >= 110) {
    score <- score + 1
  }

  if (systolic_bp < 100) {
    score <- score + 1
  }

  if (oxygen_saturation < 90) {
    score <- score + 1
  }

  risk_category <- ""
  mortality_risk <- ""
  recommendation <- ""

  if (score == 0) {
    risk_category <- "Low Risk"
    mortality_risk <- "1.0%"
    recommendation <- "Consider outpatient management."
  } else {
    risk_category <- "High Risk"
    mortality_risk <- "10.9%"
    recommendation <- "Inpatient admission recommended."
  }

  return(list(
    sPESI_Score = score,
    Risk_Category = risk_category,
    Est_30_Day_Mortality = mortality_risk,
    Recommendation = recommendation,
    Inputs = list(
      Age_gt_80 = age > 80,
      History_Cancer = cancer_history == 1,
      History_Cardiopulmonary = chronic_cardiopulmonary_disease == 1,
      HR_ge_110 = heart_rate >= 110,
      SBP_lt_100 = systolic_bp < 100,
      SpO2_lt_90 = oxygen_saturation < 90
    )
  ))
}

sirs_sepsis_criteria <- function(temperature_c, heart_rate, respiratory_rate, paco2_mmhg, wbc_count, bands_percent, infection_suspected, organ_dysfunction_hypotension, fluids_refractory_hypotension) {

  temperature_c <- as.numeric(temperature_c)
  heart_rate <- as.numeric(heart_rate)
  respiratory_rate <- as.numeric(respiratory_rate)
  paco2_mmhg <- as.numeric(paco2_mmhg)
  wbc_count <- as.numeric(wbc_count)
  bands_percent <- as.numeric(bands_percent)
  infection_suspected <- as.numeric(infection_suspected)
  organ_dysfunction_hypotension <- as.numeric(organ_dysfunction_hypotension)
  fluids_refractory_hypotension <- as.numeric(fluids_refractory_hypotension)

  if (any(is.na(c(temperature_c, heart_rate, wbc_count)))) {
    stop("Error: Core physiological inputs must be numeric.")
  }

  sirs_score <- 0

  if (temperature_c > 38.0 || temperature_c < 36.0) {
    sirs_score <- sirs_score + 1
  }

  if (heart_rate > 90) {
    sirs_score <- sirs_score + 1
  }

  respiratory_crit <- FALSE
  if (!is.na(respiratory_rate)) {
    if (respiratory_rate > 20) respiratory_crit <- TRUE
  }
  if (!is.na(paco2_mmhg)) {
    if (paco2_mmhg < 32) respiratory_crit <- TRUE
  }
  if (respiratory_crit) {
    sirs_score <- sirs_score + 1
  }

  wbc_crit <- FALSE
  if (!is.na(wbc_count)) {
    if (wbc_count > 12.0 || wbc_count < 4.0) wbc_crit <- TRUE
  }
  if (!is.na(bands_percent)) {
    if (bands_percent > 10) wbc_crit <- TRUE
  }
  if (wbc_crit) {
    sirs_score <- sirs_score + 1
  }

  diagnosis <- ""

  if (sirs_score < 2) {
    diagnosis <- "No SIRS"
  } else {
    if (infection_suspected == 0) {
      diagnosis <- "SIRS"
    } else {
      if (fluids_refractory_hypotension == 1) {
        diagnosis <- "Septic Shock"
      } else if (organ_dysfunction_hypotension == 1) {
        diagnosis <- "Severe Sepsis"
      } else {
        diagnosis <- "Sepsis"
      }
    }
  }

  return(list(
    Diagnosis = diagnosis,
    SIRS_Criteria_Met = sirs_score,
    Inputs = list(
      Temp_Abnormal = temperature_c > 38 || temperature_c < 36,
      Tachycardia = heart_rate > 90,
      Tachypnea_Hypocapnia = respiratory_crit,
      WBC_Abnormal_Bands = wbc_crit,
      Infection = infection_suspected == 1,
      Organ_Dysfunction = organ_dysfunction_hypotension == 1,
      Refractory_Hypotension = fluids_refractory_hypotension == 1
    )
  ))
}

slicc_sle_criteria <- function(acute_cutaneous_lupus, chronic_cutaneous_lupus, oral_ulcers, alopecia, synovitis, serositis, renal_clinical, neurologic, hemolytic_anemia, leukopenia_lymphopenia, thrombocytopenia, ana, anti_dsdna, anti_sm, antiphospholipid_antibody, low_complement, direct_coombs, biopsy_proven_nephritis) {

  inputs <- c(acute_cutaneous_lupus, chronic_cutaneous_lupus, oral_ulcers, alopecia, synovitis, serositis, renal_clinical, neurologic, hemolytic_anemia, leukopenia_lymphopenia, thrombocytopenia, ana, anti_dsdna, anti_sm, antiphospholipid_antibody, low_complement, direct_coombs, biopsy_proven_nephritis)

  if (any(is.na(inputs))) {
    stop("Error: All inputs must be numeric (0 or 1).")
  }

  clinical_score <- 0
  if (acute_cutaneous_lupus == 1) clinical_score <- clinical_score + 1
  if (chronic_cutaneous_lupus == 1) clinical_score <- clinical_score + 1
  if (oral_ulcers == 1) clinical_score <- clinical_score + 1
  if (alopecia == 1) clinical_score <- clinical_score + 1
  if (synovitis == 1) clinical_score <- clinical_score + 1
  if (serositis == 1) clinical_score <- clinical_score + 1
  if (renal_clinical == 1) clinical_score <- clinical_score + 1
  if (neurologic == 1) clinical_score <- clinical_score + 1
  if (hemolytic_anemia == 1) clinical_score <- clinical_score + 1
  if (leukopenia_lymphopenia == 1) clinical_score <- clinical_score + 1
  if (thrombocytopenia == 1) clinical_score <- clinical_score + 1

  immunologic_score <- 0
  if (ana == 1) immunologic_score <- immunologic_score + 1
  if (anti_dsdna == 1) immunologic_score <- immunologic_score + 1
  if (anti_sm == 1) immunologic_score <- immunologic_score + 1
  if (antiphospholipid_antibody == 1) immunologic_score <- immunologic_score + 1
  if (low_complement == 1) immunologic_score <- immunologic_score + 1

  if (direct_coombs == 1 && hemolytic_anemia == 0) {
    immunologic_score <- immunologic_score + 1
  }

  total_criteria <- clinical_score + immunologic_score

  diagnosis <- "Criteria Not Met"

  if (biopsy_proven_nephritis == 1) {
    if (ana == 1 || anti_dsdna == 1) {
      diagnosis <- "Systemic Lupus Erythematosus (SLE)"
    }
  }

  if (diagnosis == "Criteria Not Met") {
    if (total_criteria >= 4) {
      if (clinical_score >= 1 && immunologic_score >= 1) {
        diagnosis <- "Systemic Lupus Erythematosus (SLE)"
      }
    }
  }

  return(list(
    Diagnosis = diagnosis,
    Total_Criteria_Met = total_criteria,
    Breakdown = list(
      Clinical_Count = clinical_score,
      Immunologic_Count = immunologic_score
    ),
    Inputs = list(
      Acute_Cutaneous = acute_cutaneous_lupus == 1,
      Chronic_Cutaneous = chronic_cutaneous_lupus == 1,
      Oral_Ulcers = oral_ulcers == 1,
      Alopecia = alopecia == 1,
      Synovitis = synovitis == 1,
      Serositis = serositis == 1,
      Renal = renal_clinical == 1,
      Neurologic = neurologic == 1,
      Hemolytic_Anemia = hemolytic_anemia == 1,
      Leukopenia = leukopenia_lymphopenia == 1,
      Thrombocytopenia = thrombocytopenia == 1,
      ANA = ana == 1,
      Anti_dsDNA = anti_dsdna == 1,
      Anti_Sm = anti_sm == 1,
      AP_Antibody = antiphospholipid_antibody == 1,
      Low_Complement = low_complement == 1,
      Direct_Coombs = direct_coombs == 1,
      Biopsy_Nephritis = biopsy_proven_nephritis == 1
    )
  ))
}

smart_cop_score <- function(age, systolic_bp, multilobar_cxr, albumin_g_dl, respiratory_rate, heart_rate, confusion, arterial_ph, pao2_mmhg = NA, spo2_percent = NA, pao2_fio2_ratio = NA) {

  age <- as.numeric(age)
  systolic_bp <- as.numeric(systolic_bp)
  multilobar_cxr <- as.numeric(multilobar_cxr)
  albumin_g_dl <- as.numeric(albumin_g_dl)
  respiratory_rate <- as.numeric(respiratory_rate)
  heart_rate <- as.numeric(heart_rate)
  confusion <- as.numeric(confusion)
  arterial_ph <- as.numeric(arterial_ph)

  if (any(is.na(c(age, systolic_bp, multilobar_cxr, albumin_g_dl, respiratory_rate, heart_rate, confusion, arterial_ph)))) {
    stop("Error: All core clinical inputs must be numeric.")
  }

  score <- 0

  if (systolic_bp < 90) {
    score <- score + 2
  }

  if (multilobar_cxr == 1) {
    score <- score + 1
  }

  if (albumin_g_dl < 3.5) {
    score <- score + 1
  }

  if (age <= 50) {
    if (respiratory_rate >= 25) {
      score <- score + 1
    }
  } else {
    if (respiratory_rate >= 30) {
      score <- score + 1
    }
  }

  if (heart_rate >= 125) {
    score <- score + 1
  }

  if (confusion == 1) {
    score <- score + 1
  }

  oxygen_points <- 0
  oxygen_met <- FALSE

  if (age <= 50) {
    if (!is.na(pao2_mmhg) && pao2_mmhg < 70) oxygen_met <- TRUE
    if (!is.na(spo2_percent) && spo2_percent <= 93) oxygen_met <- TRUE
    if (!is.na(pao2_fio2_ratio) && pao2_fio2_ratio < 333) oxygen_met <- TRUE
  } else {
    if (!is.na(pao2_mmhg) && pao2_mmhg < 60) oxygen_met <- TRUE
    if (!is.na(spo2_percent) && spo2_percent <= 90) oxygen_met <- TRUE
    if (!is.na(pao2_fio2_ratio) && pao2_fio2_ratio < 250) oxygen_met <- TRUE
  }

  if (oxygen_met) {
    score <- score + 2
  }

  if (arterial_ph < 7.35) {
    score <- score + 2
  }

  risk_category <- ""
  irvs_risk <- ""

  if (score <= 2) {
    risk_category <- "Low Risk"
    irvs_risk <- "Low risk of needing Intensive Respiratory or Vasopressor Support (IRVS)."
  } else if (score <= 4) {
    risk_category <- "Moderate Risk"
    irvs_risk <- "1 in 8 chance of needing IRVS."
  } else if (score <= 6) {
    risk_category <- "High Risk"
    irvs_risk <- "1 in 3 chance of needing IRVS."
  } else {
    risk_category <- "Very High Risk"
    irvs_risk <- "2 in 3 chance of needing IRVS."
  }

  return(list(
    SMART_COP_Score = score,
    Risk_Category = risk_category,
    Prediction = irvs_risk,
    Inputs = list(
      Age = age,
      SBP_lt_90 = systolic_bp < 90,
      Multilobar = multilobar_cxr == 1,
      Albumin_lt_3_5 = albumin_g_dl < 3.5,
      High_RR = (age <= 50 && respiratory_rate >= 25) || (age > 50 && respiratory_rate >= 30),
      HR_ge_125 = heart_rate >= 125,
      Confusion = confusion == 1,
      Low_Oxygen = oxygen_met,
      pH_lt_7_35 = arterial_ph < 7.35
    )
  ))
}

sodium_correction_hyperglycemia <- function(measured_sodium, glucose, glucose_units = "mg/dL", correction_factor = 1.6) {

  measured_sodium <- as.numeric(measured_sodium)
  glucose <- as.numeric(glucose)
  correction_factor <- as.numeric(correction_factor)

  if (any(is.na(c(measured_sodium, glucose)))) {
    stop("Error: All inputs must be numeric.")
  }

  glucose_mg_dl <- glucose
  if (glucose_units == "mmol/L") {
    glucose_mg_dl <- glucose * 18.0
  }

  if (glucose_mg_dl <= 100) {
    corrected_sodium <- measured_sodium
  } else {
    correction <- ((glucose_mg_dl - 100) / 100) * correction_factor
    corrected_sodium <- measured_sodium + correction
  }

  return(list(
    Corrected_Sodium = round(corrected_sodium, 1),
    Inputs = list(
      Measured_Sodium = measured_sodium,
      Glucose_mg_dL = round(glucose_mg_dl, 0),
      Correction_Factor = correction_factor
    )
  ))
}

sodium_correction_rate <- function(current_sodium, target_sodium, time_hours, fluid_sodium, weight_kg, percent_body_water = 0.5) {

  current_sodium <- as.numeric(current_sodium)
  target_sodium <- as.numeric(target_sodium)
  time_hours <- as.numeric(time_hours)
  fluid_sodium <- as.numeric(fluid_sodium)
  weight_kg <- as.numeric(weight_kg)
  percent_body_water <- as.numeric(percent_body_water)

  if (any(is.na(c(current_sodium, target_sodium, time_hours, fluid_sodium, weight_kg, percent_body_water)))) {
    stop("Error: All inputs must be numeric.")
  }

  if (time_hours <= 0) stop("Error: Time must be greater than 0.")
  if (weight_kg <= 0) stop("Error: Weight must be positive.")

  total_body_water <- weight_kg * percent_body_water

  sodium_diff <- fluid_sodium - current_sodium

  change_in_serum_na_per_liter <- sodium_diff / (total_body_water + 1)

  volume_needed_l <- (target_sodium - current_sodium) / change_in_serum_na_per_liter

  if (volume_needed_l < 0 && (target_sodium > current_sodium)) {
    return(list(Error = "Selected fluid cannot achieve target sodium direction (e.g., trying to raise serum Na with hypotonic fluid)."))
  }

  rate_ml_hr <- (volume_needed_l * 1000) / time_hours

  return(list(
    Infusion_Rate_mL_hr = round(rate_ml_hr, 1),
    Total_Volume_L = round(volume_needed_l, 2),
    Change_In_Serum_Na_per_L_Infusate = round(change_in_serum_na_per_liter, 2),
    Inputs = list(
      Current_Na = current_sodium,
      Target_Na = target_sodium,
      Time_hrs = time_hours,
      Fluid_Na = fluid_sodium,
      TBW_Est = total_body_water
    )
  ))
}

sodium_deficit_hyponatremia <- function(current_sodium, target_sodium, weight_kg, sex, patient_type = "adult") {

  current_sodium <- as.numeric(current_sodium)
  target_sodium <- as.numeric(target_sodium)
  weight_kg <- as.numeric(weight_kg)
  sex <- tolower(as.character(sex))
  patient_type <- tolower(as.character(patient_type))

  if (any(is.na(c(current_sodium, target_sodium, weight_kg)))) {
    stop("Error: All numeric inputs must be valid.")
  }

  if (!sex %in% c("male", "female")) {
    stop("Error: Sex must be 'male' or 'female'.")
  }

  if (!patient_type %in% c("adult", "elderly", "child")) {
    stop("Error: Patient type must be 'adult', 'elderly', or 'child'.")
  }

  tbw_factor <- 0.6

  if (patient_type == "child") {
    tbw_factor <- 0.6
  } else if (patient_type == "elderly") {
    if (sex == "male") {
      tbw_factor <- 0.5
    } else {
      tbw_factor <- 0.45
    }
  } else {
    if (sex == "male") {
      tbw_factor <- 0.6
    } else {
      tbw_factor <- 0.5
    }
  }

  total_body_water <- weight_kg * tbw_factor

  sodium_deficit <- total_body_water * (target_sodium - current_sodium)

  if (sodium_deficit < 0) {
    return(list(
      Sodium_Deficit_mEq = 0,
      Message = "Target sodium is lower than current sodium. No deficit to replace."
    ))
  }

  return(list(
    Sodium_Deficit_mEq = round(sodium_deficit, 1),
    Total_Body_Water_L = round(total_body_water, 1),
    Inputs = list(
      Current_Na = current_sodium,
      Target_Na = target_sodium,
      Weight_kg = weight_kg,
      Category = paste(patient_type, sex)
    )
  ))
}

sokal_cml_index <- function(age, spleen_size_cm, platelet_count, blasts_percent) {

  age <- as.numeric(age)
  spleen_size_cm <- as.numeric(spleen_size_cm)
  platelet_count <- as.numeric(platelet_count)
  blasts_percent <- as.numeric(blasts_percent)

  if (any(is.na(c(age, spleen_size_cm, platelet_count, blasts_percent)))) {
    stop("Error: All inputs must be numeric.")
  }

  if (any(c(age, spleen_size_cm, platelet_count, blasts_percent) < 0)) {
    stop("Error: Inputs cannot be negative.")
  }

  term_age <- 0.0116 * (age - 43.4)
  term_spleen <- 0.0345 * (spleen_size_cm - 7.51)
  term_platelets <- 0.188 * ((platelet_count / 700)^2 - 0.563)
  term_blasts <- 0.0887 * (blasts_percent - 2.10)

  log_hazard <- term_age + term_spleen + term_platelets + term_blasts
  sokal_score <- exp(log_hazard)

  risk_group <- ""
  if (sokal_score < 0.8) {
    risk_group <- "Low Risk"
  } else if (sokal_score <= 1.2) {
    risk_group <- "Intermediate Risk"
  } else {
    risk_group <- "High Risk"
  }

  return(list(
    Sokal_Score = round(sokal_score, 2),
    Risk_Group = risk_group,
    Inputs = list(
      Age = age,
      Spleen_cm = spleen_size_cm,
      Platelets = platelet_count,
      Blasts_Pct = blasts_percent
    )
  ))
}

mayo_spn_risk <- function(age, smoking_history, cancer_history_gt_5y, nodule_diameter_mm, upper_lobe, spiculation) {

  age <- as.numeric(age)
  smoking_history <- as.numeric(smoking_history)
  cancer_history_gt_5y <- as.numeric(cancer_history_gt_5y)
  nodule_diameter_mm <- as.numeric(nodule_diameter_mm)
  upper_lobe <- as.numeric(upper_lobe)
  spiculation <- as.numeric(spiculation)

  if (any(is.na(c(age, smoking_history, cancer_history_gt_5y, nodule_diameter_mm, upper_lobe, spiculation)))) {
    stop("Error: All inputs must be numeric (0 or 1 for binary).")
  }

  if (nodule_diameter_mm < 0) stop("Error: Nodule diameter cannot be negative.")
  if (age < 0) stop("Error: Age cannot be negative.")

  log_odds <- -6.8272 + (0.0391 * age) + (0.7917 * smoking_history) + (1.3388 * cancer_history_gt_5y) + (0.1274 * nodule_diameter_mm) + (0.7838 * upper_lobe) + (1.0407 * spiculation)

  probability <- exp(log_odds) / (1 + exp(log_odds))

  risk_percent <- probability * 100

  risk_category <- ""
  if (risk_percent < 5) {
    risk_category <- "Low Risk"
  } else if (risk_percent <= 65) {
    risk_category <- "Intermediate Risk"
  } else {
    risk_category <- "High Risk"
  }

  return(list(
    Mayo_Malignancy_Risk_Percent = round(risk_percent, 1),
    Risk_Category = risk_category,
    Inputs = list(
      Age = age,
      Smoker = smoking_history == 1,
      Hx_Cancer_gt_5y = cancer_history_gt_5y == 1,
      Diameter_mm = nodule_diameter_mm,
      Upper_Lobe = upper_lobe == 1,
      Spiculated = spiculation == 1
    )
  ))
}

rema_mastocytosis_score <- function(sex, clinical_symptoms, tryptase_level) {

  sex <- tolower(as.character(sex))
  clinical_symptoms <- tolower(as.character(clinical_symptoms))
  tryptase_level <- as.numeric(tryptase_level)

  if (!sex %in% c("male", "female")) {
    stop("Error: Sex must be 'male' or 'female'.")
  }

  if (!clinical_symptoms %in% c("pruritus_urticaria_angioedema", "syncope_presyncope", "anaphylaxis", "other")) {
    stop("Error: Clinical symptoms must be 'pruritus_urticaria_angioedema', 'syncope_presyncope', 'anaphylaxis', or 'other'.")
  }

  if (is.na(tryptase_level)) {
    stop("Error: Tryptase level must be numeric.")
  }

  score <- 0

  if (sex == "male") {
    score <- score + 2
  } else {
    score <- score - 4
  }

  if (clinical_symptoms == "pruritus_urticaria_angioedema") {
    score <- score - 4
  } else if (clinical_symptoms == "syncope_presyncope") {
    score <- score + 3
  } else if (clinical_symptoms == "anaphylaxis") {
    score <- score + 1
  } else {
    score <- score + 0
  }

  if (tryptase_level < 15) {
    score <- score + 0
  } else if (tryptase_level >= 25) {
    score <- score + 2
  } else {
    score <- score + 1
  }

  prediction <- ""
  sensitivity <- ""
  specificity <- ""

  if (score < 2) {
    prediction <- "Low Probability of Clonal Mast Cell Disease"
    sensitivity <- "N/A (NPV 96%)"
    specificity <- "N/A"
  } else {
    prediction <- "High Probability of Clonal Mast Cell Disease"
    sensitivity <- "92%"
    specificity <- "81%"
  }

  return(list(
    REMA_Score = score,
    Prediction = prediction,
    Test_Characteristics_at_Cutoff_2 = list(
      Sensitivity = sensitivity,
      Specificity = specificity
    ),
    Inputs = list(
      Sex = sex,
      Symptoms = clinical_symptoms,
      Tryptase = tryptase_level
    )
  ))
}

sins_spine_score <- function(location, pain_type, bone_lesion_type, spinal_alignment, vertebral_collapse, posterior_involvement) {

  location <- tolower(as.character(location))
  pain_type <- tolower(as.character(pain_type))
  bone_lesion_type <- tolower(as.character(bone_lesion_type))
  spinal_alignment <- tolower(as.character(spinal_alignment))
  vertebral_collapse <- tolower(as.character(vertebral_collapse))
  posterior_involvement <- tolower(as.character(posterior_involvement))

  score <- 0

  if (location == "junctional") {
    score <- score + 3
  } else if (location == "mobile") {
    score <- score + 2
  } else if (location == "semirigid") {
    score <- score + 1
  } else if (location == "rigid") {
    score <- score + 0
  } else {
    stop("Error: Location must be 'junctional' (Occiput-C2, C7-T2, T11-L1, L5-S1), 'mobile' (C3-C6, L2-L4), 'semirigid' (T3-T10), or 'rigid' (S2-S5).")
  }

  if (pain_type == "mechanical") {
    score <- score + 3
  } else if (pain_type == "occasional_non_mechanical") {
    score <- score + 1
  } else if (pain_type == "pain_free") {
    score <- score + 0
  } else {
    stop("Error: Pain type must be 'mechanical', 'occasional_non_mechanical', or 'pain_free'.")
  }

  if (bone_lesion_type == "lytic") {
    score <- score + 2
  } else if (bone_lesion_type == "mixed") {
    score <- score + 1
  } else if (bone_lesion_type == "blastic") {
    score <- score + 0
  } else {
    stop("Error: Bone lesion type must be 'lytic', 'mixed', or 'blastic'.")
  }

  if (spinal_alignment == "subluxation_translation") {
    score <- score + 4
  } else if (spinal_alignment == "de_novo_deformity") {
    score <- score + 2
  } else if (spinal_alignment == "normal") {
    score <- score + 0
  } else {
    stop("Error: Spinal alignment must be 'subluxation_translation', 'de_novo_deformity', or 'normal'.")
  }

  if (vertebral_collapse == "gt_50_percent") {
    score <- score + 3
  } else if (vertebral_collapse == "lt_50_percent") {
    score <- score + 2
  } else if (vertebral_collapse == "no_collapse_gt_50_involved") {
    score <- score + 1
  } else if (vertebral_collapse == "none") {
    score <- score + 0
  } else {
    stop("Error: Vertebral collapse must be 'gt_50_percent', 'lt_50_percent', 'no_collapse_gt_50_involved', or 'none'.")
  }

  if (posterior_involvement == "bilateral") {
    score <- score + 3
  } else if (posterior_involvement == "unilateral") {
    score <- score + 1
  } else if (posterior_involvement == "none") {
    score <- score + 0
  } else {
    stop("Error: Posterior involvement must be 'bilateral', 'unilateral', or 'none'.")
  }

  stability <- ""
  recommendation <- ""

  if (score <= 6) {
    stability <- "Stable"
    recommendation <- "Spine is likely stable. Surgical consultation may not be urgent based on stability alone."
  } else if (score <= 12) {
    stability <- "Indeterminate Instability"
    recommendation <- "Spinal instability is possible. Surgical consultation recommended."
  } else {
    stability <- "Unstable"
    recommendation <- "Spine is unstable. Urgent surgical consultation indicated."
  }

  return(list(
    SINS_Score = score,
    Stability_Classification = stability,
    Recommendation = recommendation,
    Inputs = list(
      Location = location,
      Pain = pain_type,
      Lesion = bone_lesion_type,
      Alignment = spinal_alignment,
      Collapse = vertebral_collapse,
      Posterior = posterior_involvement
    )
  ))
}

sf_ratio <- function(spo2_percent, fio2_percent) {

  spo2_percent <- as.numeric(spo2_percent)
  fio2_percent <- as.numeric(fio2_percent)

  if (any(is.na(c(spo2_percent, fio2_percent)))) {
    stop("Error: All inputs must be numeric.")
  }

  if (spo2_percent < 0 || spo2_percent > 100) {
    stop("Error: SpO2 must be between 0 and 100.")
  }

  if (fio2_percent <= 1) {
    fio2_fraction <- fio2_percent
  } else if (fio2_percent > 1 && fio2_percent <= 100) {
    fio2_fraction <- fio2_percent / 100
  } else {
    stop("Error: FiO2 must be a valid percentage or fraction (e.g., 21 or 0.21).")
  }

  ratio <- spo2_percent / fio2_fraction

  interpretation <- ""
  mortality_risk <- ""
  pf_equivalent <- ""

  if (ratio < 235) {
    interpretation <- "ARDS Criteria Met (Approx. P/F < 200)"
    pf_equivalent <- "< 200 mmHg"
  } else if (ratio < 315) {
    interpretation <- "Suggestive of ALI/ARDS (Approx. P/F < 300)"
    pf_equivalent <- "200-300 mmHg"
  } else {
    interpretation <- "Normal or Mild Impairment"
    pf_equivalent <- "> 300 mmHg"
  }

  return(list(
    SF_Ratio = round(ratio, 1),
    Interpretation = interpretation,
    Estimated_PF_Ratio = pf_equivalent,
    Inputs = list(
      SpO2 = spo2_percent,
      FiO2 = fio2_fraction
    )
  ))
}

ssign_rcc_score <- function(pathologic_t_stage, lymph_node_status, metastasis_status, tumor_size_ge_5cm, fuhrman_grade, tumor_necrosis_present) {

  pathologic_t_stage <- tolower(as.character(pathologic_t_stage))
  lymph_node_status <- tolower(as.character(lymph_node_status))
  metastasis_status <- as.numeric(metastasis_status)
  tumor_size_ge_5cm <- as.numeric(tumor_size_ge_5cm)
  fuhrman_grade <- as.numeric(fuhrman_grade)
  tumor_necrosis_present <- as.numeric(tumor_necrosis_present)

  if (any(is.na(c(metastasis_status, tumor_size_ge_5cm, fuhrman_grade, tumor_necrosis_present)))) {
    stop("Error: All numeric/binary inputs must be valid.")
  }

  score <- 0

  if (pathologic_t_stage == "t1a") {
    score <- score + 0
  } else if (pathologic_t_stage == "t1b") {
    score <- score + 2
  } else if (pathologic_t_stage == "t2") {
    score <- score + 3
  } else if (pathologic_t_stage %in% c("t3a", "t3b", "t3c")) {
    score <- score + 4
  } else if (pathologic_t_stage == "t4") {
    score <- score + 5
  } else {
    stop("Error: Pathologic T stage must be 't1a', 't1b', 't2', 't3a', 't3b', 't3c', or 't4'.")
  }

  if (lymph_node_status %in% c("n0", "nx")) {
    score <- score + 0
  } else if (lymph_node_status %in% c("n1", "n2")) {
    score <- score + 2
  } else {
    stop("Error: Lymph node status must be 'n0', 'nx', 'n1', or 'n2'.")
  }

  if (metastasis_status == 1) {
    score <- score + 4
  }

  if (tumor_size_ge_5cm == 1) {
    score <- score + 2
  }

  if (fuhrman_grade == 1 || fuhrman_grade == 2) {
    score <- score + 0
  } else if (fuhrman_grade == 3) {
    score <- score + 1
  } else if (fuhrman_grade == 4) {
    score <- score + 3
  } else {
    stop("Error: Fuhrman grade must be 1, 2, 3, or 4.")
  }

  if (tumor_necrosis_present == 1) {
    score <- score + 2
  }

  survival_5yr <- ""
  if (score <= 2) {
    survival_5yr <- "97.3%"
  } else if (score >= 3 && score <= 4) {
    survival_5yr <- "89.8%"
  } else if (score >= 5 && score <= 6) {
    survival_5yr <- "65.1%"
  } else if (score >= 7 && score <= 9) {
    survival_5yr <- "38.6%"
  } else {
    survival_5yr <- "19.2%"
  }

  return(list(
    SSIGN_Score = score,
    Est_5_Year_Survival = survival_5yr,
    Inputs = list(
      T_Stage = pathologic_t_stage,
      N_Stage = lymph_node_status,
      M_Stage = metastasis_status,
      Size_ge_5cm = tumor_size_ge_5cm == 1,
      Grade = fuhrman_grade,
      Necrosis = tumor_necrosis_present == 1
    )
  ))
}

stanford_sleepiness_scale <- function(alertness_level) {

  alertness_level <- as.numeric(alertness_level)

  if (is.na(alertness_level)) {
    stop("Error: Input must be numeric.")
  }

  if (alertness_level < 1 || alertness_level > 7) {
    stop("Error: Alertness level must be an integer between 1 and 7.")
  }

  description <- ""

  if (alertness_level == 1) {
    description <- "Feeling active, vital, alert, or wide awake"
  } else if (alertness_level == 2) {
    description <- "Functioning at high levels, but not at peak; able to concentrate"
  } else if (alertness_level == 3) {
    description <- "Awake, but relaxed; responsive but not fully alert"
  } else if (alertness_level == 4) {
    description <- "Somewhat foggy, let down"
  } else if (alertness_level == 5) {
    description <- "Foggy; losing interest in remaining awake; slowed down"
  } else if (alertness_level == 6) {
    description <- "Sleepy, woozy, fighting sleep; prefer to lie down"
  } else {
    description <- "No longer fighting sleep, sleep onset soon; having dream-like thoughts"
  }

  interpretation <- ""
  if (alertness_level <= 3) {
    interpretation <- "Alert / Normal"
  } else {
    interpretation <- "Sleepy / Fatigued"
  }

  return(list(
    SSS_Score = alertness_level,
    Description = description,
    Interpretation = interpretation
  ))
}

static_lung_compliance <- function(tidal_volume, plateau_pressure, peep) {

  tidal_volume <- as.numeric(tidal_volume)
  plateau_pressure <- as.numeric(plateau_pressure)
  peep <- as.numeric(peep)

  if (any(is.na(c(tidal_volume, plateau_pressure, peep)))) {
    stop("Error: All inputs must be numeric.")
  }

  if (plateau_pressure <= peep) {
    stop("Error: Plateau pressure must be greater than PEEP.")
  }

  cstat <- tidal_volume / (plateau_pressure - peep)

  interpretation <- ""
  if (cstat < 30) {
    interpretation <- "Very Low Compliance (Suggests severe ARDS)"
  } else if (cstat >= 30 && cstat < 50) {
    interpretation <- "Low Compliance"
  } else {
    interpretation <- "Normal Compliance (Typically 50-80 mL/cmH2O in intubated patients)"
  }

  return(list(
    Static_Compliance_mL_cmH2O = round(cstat, 1),
    Interpretation = interpretation,
    Inputs = list(
      Vt_mL = tidal_volume,
      Pplat_cmH2O = plateau_pressure,
      PEEP_cmH2O = peep
    )
  ))
}

safe_fibrosis_score <- function(age, bmi, diabetes, platelets, alt, ast, globulin) {

  age <- as.numeric(age)
  bmi <- as.numeric(bmi)
  diabetes <- as.numeric(diabetes)
  platelets <- as.numeric(platelets)
  alt <- as.numeric(alt)
  ast <- as.numeric(ast)
  globulin <- as.numeric(globulin)

  if (any(is.na(c(age, bmi, diabetes, platelets, alt, ast, globulin)))) {
    stop("Error: All inputs must be numeric.")
  }

  if (alt <= 0) {
    stop("Error: ALT must be greater than 0 to calculate ratio.")
  }

  ast_alt_ratio <- ast / alt

  safe_score <- -4.782 + (0.037 * age) + (0.094 * bmi) + (1.13 * diabetes) + (0.99 * ast_alt_ratio) - (0.013 * platelets) + (0.66 * globulin)

  probability <- 1 / (1 + exp(-safe_score))

  interpretation <- ""
  if (safe_score < 0) {
    interpretation <- "Low Risk of Significant Fibrosis (>= F2)"
  } else {
    interpretation <- "High Risk of Significant Fibrosis (>= F2)"
  }

  return(list(
    SAFE_Score = round(safe_score, 3),
    Probability = round(probability, 3),
    Interpretation = interpretation,
    Inputs = list(
      Age = age,
      BMI = bmi,
      Diabetes = diabetes == 1,
      Platelets = platelets,
      AST_ALT_Ratio = round(ast_alt_ratio, 2),
      Globulin = globulin
    )
  ))
}

steinhart_ahf_model <- function(age, pretest_probability_percent, nt_probnp_pg_ml) {

  age <- as.numeric(age)
  pretest_probability_percent <- as.numeric(pretest_probability_percent)
  nt_probnp_pg_ml <- as.numeric(nt_probnp_pg_ml)

  if (any(is.na(c(age, pretest_probability_percent, nt_probnp_pg_ml)))) {
    stop("Error: All inputs must be numeric.")
  }

  if (nt_probnp_pg_ml <= 0) {
    stop("Error: NT-proBNP must be positive.")
  }

  if (pretest_probability_percent < 0 || pretest_probability_percent > 100) {
    stop("Error: Pretest probability must be between 0 and 100.")
  }

  p_fraction <- pretest_probability_percent / 100
  log_nt <- log10(nt_probnp_pg_ml)

  exponent_x <- 8 + (0.011 * age) - (5.9 * p_fraction) - (2.3 * log_nt) + (0.82 * p_fraction * log_nt)

  posttest_prob <- 1 / (1 + exp(exponent_x))

  posttest_percent <- posttest_prob * 100

  interpretation <- ""
  if (posttest_percent <= 20) {
    interpretation <- "Low Probability of Acute Heart Failure (< 20%)"
  } else if (posttest_percent < 80) {
    interpretation <- "Intermediate Probability of Acute Heart Failure (20-79%)"
  } else {
    interpretation <- "High Probability of Acute Heart Failure (>= 80%)"
  }

  return(list(
    PostTest_Probability = paste0(round(posttest_percent, 1), "%"),
    Interpretation = interpretation,
    Inputs = list(
      Age = age,
      Pretest_Prob = paste0(pretest_probability_percent, "%"),
      NT_proBNP = nt_probnp_pg_ml
    )
  ))
}

step_by_step_febrile_infant <- function(age_days, ill_appearing, urinalysis_positive, procalcitonin, crp_mg_l, absolute_neutrophil_count) {

  age_days <- as.numeric(age_days)
  ill_appearing <- as.numeric(ill_appearing)
  urinalysis_positive <- as.numeric(urinalysis_positive)
  procalcitonin <- as.numeric(procalcitonin)
  crp_mg_l <- as.numeric(crp_mg_l)
  absolute_neutrophil_count <- as.numeric(absolute_neutrophil_count)

  if (any(is.na(c(age_days, ill_appearing, urinalysis_positive, procalcitonin, crp_mg_l, absolute_neutrophil_count)))) {
    stop("Error: All inputs must be numeric.")
  }

  risk_level <- ""
  recommendation <- ""

  if (ill_appearing == 1) {
    risk_level <- "High Risk"
  } else if (age_days <= 21) {
    risk_level <- "High Risk"
  } else if (urinalysis_positive == 1) {
    risk_level <- "High Risk"
  } else if (procalcitonin >= 0.5) {
    risk_level <- "High Risk"
  } else if (crp_mg_l > 20 || absolute_neutrophil_count > 10000) {
    risk_level <- "Intermediate Risk"
  } else {
    risk_level <- "Low Risk"
  }

  if (risk_level == "High Risk") {
    recommendation <- "High risk of Invasive Bacterial Infection (IBI). Admit for full sepsis evaluation and empiric antibiotics."
  } else if (risk_level == "Intermediate Risk") {
    recommendation <- "Intermediate risk. Consider observation or admission pending further results. Antibiotics may be indicated."
  } else {
    recommendation <- "Low risk of IBI (Sensitivity ~99.9%). Outpatient management without antibiotics is generally safe with follow-up."
  }

  return(list(
    Risk_Classification = risk_level,
    Recommendation = recommendation,
    Inputs = list(
      Age_Days = age_days,
      Ill_Appearing = ill_appearing == 1,
      Leukocyturia = urinalysis_positive == 1,
      PCT_ng_mL = procalcitonin,
      CRP_mg_L = crp_mg_l,
      ANC = absolute_neutrophil_count
    )
  ))
}

steroid_conversion_calculator <- function(current_steroid, current_dose_mg, target_steroid) {

  current_steroid <- tolower(as.character(current_steroid))
  target_steroid <- tolower(as.character(target_steroid))
  current_dose_mg <- as.numeric(current_dose_mg)

  if (is.na(current_dose_mg)) {
    stop("Error: Dose must be numeric.")
  }

  data <- list(
    cortisone = list(equiv = 25, anti_inflam = 0.8, mineral = 0.8, duration = "Short (8-12h)"),
    hydrocortisone = list(equiv = 20, anti_inflam = 1, mineral = 1, duration = "Short (8-12h)"),
    prednisone = list(equiv = 5, anti_inflam = 4, mineral = 0.8, duration = "Intermediate (12-36h)"),
    prednisolone = list(equiv = 5, anti_inflam = 4, mineral = 0.8, duration = "Intermediate (12-36h)"),
    triamcinolone = list(equiv = 4, anti_inflam = 5, mineral = 0, duration = "Intermediate (12-36h)"),
    methylprednisolone = list(equiv = 4, anti_inflam = 5, mineral = 0.5, duration = "Intermediate (12-36h)"),
    dexamethasone = list(equiv = 0.75, anti_inflam = 25, mineral = 0, duration = "Long (36-72h)"),
    betamethasone = list(equiv = 0.6, anti_inflam = 25, mineral = 0, duration = "Long (36-72h)")
  )

  if (!current_steroid %in% names(data)) {
    stop("Error: Current steroid name not recognized.")
  }
  if (!target_steroid %in% names(data)) {
    stop("Error: Target steroid name not recognized.")
  }

  current_data <- data[[current_steroid]]
  target_data <- data[[target_steroid]]

  base_equiv_dose <- current_dose_mg / current_data$equiv

  target_dose_mg <- base_equiv_dose * target_data$equiv

  return(list(
    Target_Dose_mg = round(target_dose_mg, 2),
    Target_Steroid_Info = list(
      Name = target_steroid,
      Anti_Inflammatory_Potency = target_data$anti_inflam,
      Mineralocorticoid_Potency = target_data$mineral,
      Biologic_Half_Life = target_data$duration
    ),
    Conversion_Ratio = paste0("1 mg ", current_steroid, " = ", round(target_data$equiv / current_data$equiv, 4), " mg ", target_steroid)
  ))
}

stone_nephrolithometry_score <- function(stone_size_mm2, tract_length_mm, obstruction_degree, number_involved_calyces, stone_density_hu) {

  stone_size_mm2 <- as.numeric(stone_size_mm2)
  tract_length_mm <- as.numeric(tract_length_mm)
  obstruction_degree <- tolower(as.character(obstruction_degree))
  number_involved_calyces <- tolower(as.character(number_involved_calyces))
  stone_density_hu <- as.numeric(stone_density_hu)

  if (any(is.na(c(stone_size_mm2, tract_length_mm, stone_density_hu)))) {
    stop("Error: Size, Tract Length, and Density must be numeric.")
  }

  if (!obstruction_degree %in% c("none_mild", "moderate_severe")) {
    stop("Error: Obstruction must be 'none_mild' or 'moderate_severe'.")
  }

  if (!number_involved_calyces %in% c("1_or_2", "3", "staghorn")) {
    stop("Error: Number of calyces must be '1_or_2', '3', or 'staghorn'.")
  }

  score <- 0

  if (stone_size_mm2 < 400) {
    score <- score + 1
  } else if (stone_size_mm2 >= 400 && stone_size_mm2 < 800) {
    score <- score + 2
  } else if (stone_size_mm2 >= 800 && stone_size_mm2 < 1600) {
    score <- score + 3
  } else {
    score <- score + 4
  }

  if (tract_length_mm <= 100) {
    score <- score + 1
  } else {
    score <- score + 2
  }

  if (obstruction_degree == "none_mild") {
    score <- score + 1
  } else {
    score <- score + 2
  }

  if (number_involved_calyces == "1_or_2") {
    score <- score + 1
  } else if (number_involved_calyces == "3") {
    score <- score + 2
  } else {
    score <- score + 3
  }

  if (stone_density_hu <= 950) {
    score <- score + 1
  } else {
    score <- score + 2
  }

  complexity <- ""
  stone_free_rate <- ""

  if (score <= 6) {
    complexity <- "Low Complexity"
    stone_free_rate <- "High (~94-100%)"
  } else if (score >= 7 && score <= 8) {
    complexity <- "Moderate Complexity"
    stone_free_rate <- "Moderate (~80%)"
  } else {
    complexity <- "High Complexity"
    stone_free_rate <- "Low (~50%)"
  }

  return(list(
    STONE_Score = score,
    Surgical_Complexity = complexity,
    Est_Stone_Free_Rate = stone_free_rate,
    Inputs = list(
      Size_mm2 = stone_size_mm2,
      Tract_mm = tract_length_mm,
      Obstruction = obstruction_degree,
      Calyces = number_involved_calyces,
      Density_HU = stone_density_hu
    )
  ))
}

stone_ureteral_score <- function(sex, duration_of_pain_hours, race, nausea_vomiting, hematuria_on_dipstick) {

  sex <- tolower(as.character(sex))
  duration_of_pain_hours <- as.numeric(duration_of_pain_hours)
  race <- tolower(as.character(race))
  nausea_vomiting <- as.numeric(nausea_vomiting)
  hematuria_on_dipstick <- as.numeric(hematuria_on_dipstick)

  if (any(is.na(c(duration_of_pain_hours, nausea_vomiting, hematuria_on_dipstick)))) {
    stop("Error: All inputs must be valid.")
  }

  if (!sex %in% c("male", "female")) {
    stop("Error: Sex must be 'male' or 'female'.")
  }

  if (!race %in% c("black", "non_black")) {
    stop("Error: Race must be 'black' or 'non_black'.")
  }

  score <- 0

  if (sex == "male") {
    score <- score + 2
  }

  if (duration_of_pain_hours < 6) {
    score <- score + 3
  } else if (duration_of_pain_hours >= 6 && duration_of_pain_hours <= 24) {
    score <- score + 1
  } else {
    score <- score + 0
  }

  if (race == "non_black") {
    score <- score + 3
  }

  if (nausea_vomiting == 1) {
    score <- score + 2
  } else if (nausea_vomiting == 0) {
    score <- score + 1
  } else {
    score <- score + 0
  }

  if (hematuria_on_dipstick == 1) {
    score <- score + 3
  }

  risk_category <- ""
  probability <- ""

  if (score <= 5) {
    risk_category <- "Low Score"
    probability <- "8.3 - 9.2%"
  } else if (score >= 6 && score <= 9) {
    risk_category <- "Moderate Score"
    probability <- "51.3 - 51.6%"
  } else {
    risk_category <- "High Score"
    probability <- "88.6 - 89.6%"
  }

  return(list(
    STONE_Score = score,
    Risk_Category = risk_category,
    Ureteral_Stone_Probability = probability,
    Inputs = list(
      Sex = sex,
      Duration_Pain = duration_of_pain_hours,
      Race = race,
      Nausea_Vomiting = nausea_vomiting,
      Hematuria = hematuria_on_dipstick == 1
    )
  ))
}

stool_osmolar_gap <- function(stool_na, stool_k, stool_osmolality = 290) {

  stool_na <- as.numeric(stool_na)
  stool_k <- as.numeric(stool_k)
  stool_osmolality <- as.numeric(stool_osmolality)

  if (any(is.na(c(stool_na, stool_k, stool_osmolality)))) {
    stop("Error: All inputs must be numeric.")
  }

  calculated_osmolality <- 2 * (stool_na + stool_k)
  gap <- stool_osmolality - calculated_osmolality

  interpretation <- ""
  if (gap > 100) {
    interpretation <- "Osmotic Diarrhea (> 100 mOsm/kg)"
  } else if (gap < 50) {
    interpretation <- "Secretory Diarrhea (< 50 mOsm/kg)"
  } else {
    interpretation <- "Indeterminate / Mixed (50-100 mOsm/kg)"
  }

  return(list(
    Stool_Osmotic_Gap = gap,
    Interpretation = interpretation,
    Calculated_Electrolytes_Osmolality = calculated_osmolality,
    Inputs = list(
      Stool_Na = stool_na,
      Stool_K = stool_k,
      Measured_Osmolality = stool_osmolality
    )
  ))
}

stop_bang_score <- function(snoring, tired, observed_apnea, pressure, bmi, age, neck_circumference, gender) {

  snoring <- as.numeric(snoring)
  tired <- as.numeric(tired)
  observed_apnea <- as.numeric(observed_apnea)
  pressure <- as.numeric(pressure)
  bmi <- as.numeric(bmi)
  age <- as.numeric(age)
  neck_circumference <- as.numeric(neck_circumference)
  gender <- tolower(as.character(gender))

  if (any(is.na(c(snoring, tired, observed_apnea, pressure, bmi, age, neck_circumference)))) {
    stop("Error: All inputs must be numeric.")
  }

  if (!gender %in% c("male", "female")) {
    stop("Error: Gender must be 'male' or 'female'.")
  }

  score <- 0

  if (snoring == 1) score <- score + 1
  if (tired == 1) score <- score + 1
  if (observed_apnea == 1) score <- score + 1
  if (pressure == 1) score <- score + 1
  if (bmi > 35) score <- score + 1
  if (age > 50) score <- score + 1

  if (neck_circumference > 40) {
    score <- score + 1
  }

  if (gender == "male") score <- score + 1

  risk_category <- ""
  if (score <= 2) {
    risk_category <- "Low Risk"
  } else if (score <= 4) {
    risk_category <- "Intermediate Risk"
  } else {
    risk_category <- "High Risk"
  }

  return(list(
    STOP_Bang_Score = score,
    Risk_Category = risk_category,
    Inputs = list(
      Snoring = snoring == 1,
      Tired = tired == 1,
      Observed = observed_apnea == 1,
      Pressure = pressure == 1,
      BMI_gt_35 = bmi > 35,
      Age_gt_50 = age > 50,
      Neck_gt_40 = neck_circumference > 40,
      Male = gender == "male"
    )
  ))
}

stumbl_battle_score <- function(age, num_rib_fractures, chronic_lung_disease, anticoagulant_use, spo2_percent) {

  age <- as.numeric(age)
  num_rib_fractures <- as.numeric(num_rib_fractures)
  chronic_lung_disease <- as.numeric(chronic_lung_disease)
  anticoagulant_use <- as.numeric(anticoagulant_use)
  spo2_percent <- as.numeric(spo2_percent)

  if (any(is.na(c(age, num_rib_fractures, chronic_lung_disease, anticoagulant_use, spo2_percent)))) {
    stop("Error: All inputs must be numeric.")
  }

  score <- 0

  if (age >= 65) {
    score <- score + 5
  }

  if (num_rib_fractures >= 3) {
    score <- score + 4
  }

  if (chronic_lung_disease == 1) {
    score <- score + 5
  }

  if (anticoagulant_use == 1) {
    score <- score + 4
  }

  if (spo2_percent < 90) {
    score <- score + 6
  }

  risk_category <- ""
  management <- ""

  if (score <= 10) {
    risk_category <- "Low Risk"
    management <- "Complications unlikely. Consider discharge with appropriate analgesia and advice."
  } else {
    risk_category <- "High Risk"
    management <- "Increased risk of complications. Hospital admission and observation recommended."
  }

  return(list(
    STUMBL_Score = score,
    Risk_Category = risk_category,
    Management_Guidance = management,
    Inputs = list(
      Age_ge_65 = age >= 65,
      Ribs_ge_3 = num_rib_fractures >= 3,
      Chronic_Lung_Disease = chronic_lung_disease == 1,
      Anticoagulants = anticoagulant_use == 1,
      SpO2_lt_90 = spo2_percent < 90
    )
  ))
}

slics_spine_score <- function(morphology, dlc_status, neurologic_status, continuous_compression = 0) {

  morphology <- tolower(as.character(morphology))
  dlc_status <- tolower(as.character(dlc_status))
  neurologic_status <- tolower(as.character(neurologic_status))
  continuous_compression <- as.numeric(continuous_compression)

  if (any(is.na(c(continuous_compression)))) {
    stop("Error: Continuous compression input must be numeric (0 or 1).")
  }

  score <- 0

  if (morphology == "no_abnormality") {
    score <- score + 0
  } else if (morphology == "compression") {
    score <- score + 1
  } else if (morphology == "burst") {
    score <- score + 2
  } else if (morphology == "distraction") {
    score <- score + 3
  } else if (morphology == "translation_rotation") {
    score <- score + 4
  } else {
    stop("Error: Morphology must be 'no_abnormality', 'compression', 'burst', 'distraction', or 'translation_rotation'.")
  }

  if (dlc_status == "intact") {
    score <- score + 0
  } else if (dlc_status == "indeterminate") {
    score <- score + 1
  } else if (dlc_status == "disrupted") {
    score <- score + 2
  } else {
    stop("Error: DLC status must be 'intact', 'indeterminate', or 'disrupted'.")
  }

  if (neurologic_status == "intact") {
    score <- score + 0
  } else if (neurologic_status == "root_injury") {
    score <- score + 1
  } else if (neurologic_status == "complete_cord") {
    score <- score + 2
  } else if (neurologic_status == "incomplete_cord") {
    score <- score + 3
  } else {
    stop("Error: Neurologic status must be 'intact', 'root_injury', 'complete_cord', or 'incomplete_cord'.")
  }

  if (continuous_compression == 1) {
    score <- score + 1
  }

  management <- ""
  if (score < 4) {
    management <- "Non-Operative"
  } else if (score == 4) {
    management <- "Indeterminate (Operative or Non-Operative)"
  } else {
    management <- "Operative"
  }

  return(list(
    SLICS_Score = score,
    Management_Recommendation = management,
    Inputs = list(
      Morphology = morphology,
      DLC = dlc_status,
      Neuro = neurologic_status,
      Continuous_Compression = continuous_compression == 1
    )
  ))
}

subtle_anterior_stemi_4_variable <- function(qtc_ms, qrs_v2_mm, r_wave_v4_mm, ste_60_v3_mm) {

  qtc_ms <- as.numeric(qtc_ms)
  qrs_v2_mm <- as.numeric(qrs_v2_mm)
  r_wave_v4_mm <- as.numeric(r_wave_v4_mm)
  ste_60_v3_mm <- as.numeric(ste_60_v3_mm)

  if (any(is.na(c(qtc_ms, qrs_v2_mm, r_wave_v4_mm, ste_60_v3_mm)))) {
    stop("Error: All inputs must be numeric.")
  }

  score <- (0.052 * qtc_ms) - (0.151 * qrs_v2_mm) - (0.268 * r_wave_v4_mm) + (1.062 * ste_60_v3_mm)

  interpretation <- ""
  if (score >= 18.2) {
    interpretation <- "Likely Anterior STEMI"
  } else {
    interpretation <- "Likely Early Repolarization"
  }

  return(list(
    Score = round(score, 2),
    Interpretation = interpretation,
    Inputs = list(
      QTc_ms = qtc_ms,
      QRS_V2_mm = qrs_v2_mm,
      R_Wave_V4_mm = r_wave_v4_mm,
      STE60_V3_mm = ste_60_v3_mm
    )
  ))
}

