}

surgical_apgar_score <- function(blood_loss_ml, lowest_map_mmhg, lowest_heart_rate) {

  blood_loss_ml <- as.numeric(blood_loss_ml)
  lowest_map_mmhg <- as.numeric(lowest_map_mmhg)
  lowest_heart_rate <- as.numeric(lowest_heart_rate)

  if (any(is.na(c(blood_loss_ml, lowest_map_mmhg, lowest_heart_rate)))) {
    stop("Error: All inputs must be numeric.")
  }

  ebl_points <- 0
  if (blood_loss_ml <= 100) {
    ebl_points <- 3
  } else if (blood_loss_ml <= 600) {
    ebl_points <- 2
  } else if (blood_loss_ml <= 1000) {
    ebl_points <- 1
  } else {
    ebl_points <- 0
  }

  map_points <- 0
  if (lowest_map_mmhg >= 75) {
    map_points <- 3
  } else if (lowest_map_mmhg >= 55) {
    map_points <- 2
  } else if (lowest_map_mmhg >= 40) {
    map_points <- 1
  } else {
    map_points <- 0
  }

  hr_points <- 0
  if (lowest_heart_rate <= 55) {
    hr_points <- 3
  } else if (lowest_heart_rate <= 65) {
    hr_points <- 2
  } else if (lowest_heart_rate <= 75) {
    hr_points <- 1
  } else {
    hr_points <- 0
  }

  sas_score <- ebl_points + map_points + hr_points

  risk_category <- ""
  complication_risk <- ""

  if (sas_score <= 4) {
    risk_category <- "High Risk"
    complication_risk <- "Major Complication or Death: 23.6%"
  } else if (sas_score <= 6) {
    risk_category <- "Medium Risk"
    complication_risk <- "Major Complication or Death: 12.6%"
  } else if (sas_score <= 8) {
    risk_category <- "Low Risk"
    complication_risk <- "Major Complication or Death: 5.5%"
  } else {
    risk_category <- "Very Low Risk"
    complication_risk <- "Major Complication or Death: 3.6%"
  }

  return(list(
    SAS_Score = sas_score,
    Risk_Category = risk_category,
    Risk_Estimate = complication_risk,
    Inputs = list(
      EBL_mL = blood_loss_ml,
      Lowest_MAP = lowest_map_mmhg,
      Lowest_HR = lowest_heart_rate
    )
  ))
}

swede_colposcopic_score <- function(acetowhitening, margins, vessels, lesion_size, iodine_staining) {

  acetowhitening <- as.numeric(acetowhitening)
  margins <- as.numeric(margins)
  vessels <- as.numeric(vessels)
  lesion_size <- as.numeric(lesion_size)
  iodine_staining <- as.numeric(iodine_staining)

  if (any(is.na(c(acetowhitening, margins, vessels, lesion_size, iodine_staining)))) {
    stop("Error: All inputs must be numeric.")
  }

  if (any(c(acetowhitening, margins, vessels, lesion_size, iodine_staining) < 0) ||
      any(c(acetowhitening, margins, vessels, lesion_size, iodine_staining) > 2)) {
    stop("Error: All component scores must be integers between 0 and 2.")
  }

  total_score <- acetowhitening + margins + vessels + lesion_size + iodine_staining

  interpretation <- ""
  if (total_score <= 4) {
    interpretation <- "Low Grade (Likely Normal or CIN 1)"
  } else if (total_score <= 7) {
    interpretation <- "High Grade (Likely CIN 2 or CIN 3)"
  } else {
    interpretation <- "High Grade / Cancer (Likely CIN 3 or Invasive Cancer)"
  }

  return(list(
    Swede_Score = total_score,
    Interpretation = interpretation,
    Inputs = list(
      Acetowhitening = acetowhitening,
      Margins = margins,
      Vessels = vessels,
      Size = lesion_size,
      Iodine = iodine_staining
    )
  ))
}

score2_cvd_risk <- function(sex, age, smoking_status, systolic_bp, total_cholesterol, hdl_cholesterol = NULL, region_risk_level = "low") {

  sex <- tolower(as.character(sex))
  age <- as.numeric(age)
  smoking_status <- as.numeric(smoking_status)
  systolic_bp <- as.numeric(systolic_bp)
  total_cholesterol <- as.numeric(total_cholesterol)
  region_risk_level <- tolower(as.character(region_risk_level))

  if (any(is.na(c(age, smoking_status, systolic_bp, total_cholesterol)))) {
    stop("Error: All inputs must be numeric.")
  }

  if (!sex %in% c("male", "female")) {
    stop("Error: Sex must be 'male' or 'female'.")
  }

  if (!region_risk_level %in% c("low", "moderate", "high", "very_high")) {
    stop("Error: Region risk must be 'low', 'moderate', 'high', or 'very_high'.")
  }

  non_hdl_cholesterol <- total_cholesterol
  if (!is.null(hdl_cholesterol)) {
    non_hdl_cholesterol <- total_cholesterol - as.numeric(hdl_cholesterol)
  }

  if (total_cholesterol > 15) {
    total_cholesterol <- total_cholesterol / 38.67
    if (!is.null(hdl_cholesterol)) {
      hdl_cholesterol <- hdl_cholesterol / 38.67
      non_hdl_cholesterol <- total_cholesterol - hdl_cholesterol
    } else {
      non_hdl_cholesterol <- total_cholesterol
    }
  }

  age_c <- (age - 60) / 5
  sbp_c <- (systolic_bp - 120) / 20
  chol_c <- (non_hdl_cholesterol - 3.5) / 1.0

  params <- list(
    low = list(
      male = c(0.38359, 0.43593, 0.49321, 0.46819, -0.05459, -0.06655, -0.08215, -0.11487, -0.13232, 0.9605, 0.02621, 0.03103),
      female = c(0.53232, 0.56448, 0.58892, 0.53273, -0.05825, -0.07237, -0.08225, -0.09785, -0.09945, 0.9776, 0.02621, 0.03103)
    ),
    moderate = list(
      male = c(0.43770, 0.48458, 0.53434, 0.50922, -0.05459, -0.06655, -0.08215, -0.11487, -0.13232, 0.9465, 0.02621, 0.03103),
      female = c(0.60474, 0.63332, 0.65066, 0.59825, -0.05825, -0.07237, -0.08225, -0.09785, -0.09945, 0.9707, 0.02621, 0.03103)
    ),
    high = list(
      male = c(0.49178, 0.53323, 0.57547, 0.55025, -0.05459, -0.06655, -0.08215, -0.11487, -0.13232, 0.9325, 0.02621, 0.03103),
      female = c(0.67716, 0.70214, 0.71239, 0.66377, -0.05825, -0.07237, -0.08225, -0.09785, -0.09945, 0.9638, 0.02621, 0.03103)
    ),
    very_high = list(
      male = c(0.54586, 0.58188, 0.61660, 0.59128, -0.05459, -0.06655, -0.08215, -0.11487, -0.13232, 0.9185, 0.02621, 0.03103),
      female = c(0.74960, 0.77096, 0.77412, 0.72930, -0.05825, -0.07237, -0.08225, -0.09785, -0.09945, 0.9569, 0.02621, 0.03103)
    )
  )

  coeffs <- params[[region_risk_level]][[sex]]

  alpha_smoker <- coeffs[1]
  alpha_chol <- coeffs[2]
  alpha_sbp <- coeffs[3]

  beta_age <- coeffs[11]

  if (smoking_status == 1) {
    lp_smoker <- alpha_smoker + (coeffs[5] * age_c)
    total_risk_lp <- lp_smoker
  } else {
    total_risk_lp <- 0
  }

  lp_chol <- (alpha_chol + (coeffs[6] * age_c)) * chol_c
  total_risk_lp <- total_risk_lp + lp_chol

  lp_sbp <- (alpha_sbp + (coeffs[7] * age_c)) * sbp_c
  total_risk_lp <- total_risk_lp + lp_sbp

  lp_age <- beta_age * age_c

  base_survival <- coeffs[10]

  risk_score <- 1 - (base_survival ^ exp(total_risk_lp))

  risk_percent <- risk_score * 100

  risk_category <- ""
  if (age < 50) {
    if (risk_percent < 2.5) risk_category <- "Low-to-Moderate Risk"
    else if (risk_percent < 7.5) risk_category <- "High Risk"
    else risk_category <- "Very High Risk"
  } else if (age < 70) {
    if (risk_percent < 5) risk_category <- "Low-to-Moderate Risk"
    else if (risk_percent < 10) risk_category <- "High Risk"
    else risk_category <- "Very High Risk"
  } else {
    if (risk_percent < 7.5) risk_category <- "Low-to-Moderate Risk"
    else if (risk_percent < 15) risk_category <- "High Risk"
    else risk_category <- "Very High Risk"
  }

  return(list(
    SCORE2_Risk_10yr = paste0(round(risk_percent, 1), "%"),
    Risk_Category = risk_category,
    Inputs = list(
      Age = age,
      Sex = sex,
      Smoker = smoking_status == 1,
      SBP = systolic_bp,
      Non_HDL_Cholesterol = round(non_hdl_cholesterol, 2),
      Region = region_risk_level
    )
  ))
}

score2_diabetes_risk <- function(sex, age, smoking_status, systolic_bp, total_cholesterol, hdl_cholesterol, hba1c, egfr, age_diabetes_diagnosis, region_risk_level = "low", cholesterol_units = "mmol/L", hba1c_units = "mmol/mol") {

  sex <- tolower(as.character(sex))
  age <- as.numeric(age)
  smoking_status <- as.numeric(smoking_status)
  systolic_bp <- as.numeric(systolic_bp)
  total_cholesterol <- as.numeric(total_cholesterol)
  hdl_cholesterol <- as.numeric(hdl_cholesterol)
  hba1c <- as.numeric(hba1c)
  egfr <- as.numeric(egfr)
  age_diabetes_diagnosis <- as.numeric(age_diabetes_diagnosis)
  region_risk_level <- tolower(as.character(region_risk_level))

  if (any(is.na(c(age, smoking_status, systolic_bp, total_cholesterol, hdl_cholesterol, hba1c, egfr, age_diabetes_diagnosis)))) {
    stop("Error: All clinical inputs must be numeric.")
  }

  if (!sex %in% c("male", "female")) {
    stop("Error: Sex must be 'male' or 'female'.")
  }

  if (!region_risk_level %in% c("low", "moderate", "high", "very_high")) {
    stop("Error: Region risk must be 'low', 'moderate', 'high', or 'very_high'.")
  }

  tc_val <- total_cholesterol
  hdl_val <- hdl_cholesterol
  if (cholesterol_units == "mg/dL") {
    tc_val <- total_cholesterol / 38.67
    hdl_val <- hdl_cholesterol / 38.67
  }

  non_hdl <- tc_val - hdl_val

  hba1c_val <- hba1c
  if (hba1c_units == "per" || hba1c_units == "dcct") {
    hba1c_val <- (hba1c - 2.15) * 10.929
  }

  diabetes_duration <- age - age_diabetes_diagnosis
  if (diabetes_duration < 0) diabetes_duration <- 0

  centered_age <- (age - 60) / 5
  centered_sbp <- (systolic_bp - 120) / 20
  centered_non_hdl <- (non_hdl - 3.5)
  centered_hba1c <- (hba1c_val - 31) / 10
  centered_egfr <- (egfr - 60) / 15
  centered_duration <- (diabetes_duration - 10) / 5

  return(list(
    Message = "Calculation requires specific region/sex regression coefficients from the SCORE2-Diabetes Working Group (2023).",
    Calculated_Variables = list(
      Age_Centered = round(centered_age, 2),
      Non_HDL_mmol_L = round(non_hdl, 2),
      HbA1c_mmol_mol = round(hba1c_val, 1),
      Diabetes_Duration_Years = diabetes_duration,
      Region = region_risk_level
    ),
    Inputs = list(
      Sex = sex,
      Age = age,
      Smoker = smoking_status == 1,
      SBP = systolic_bp,
      Total_Chol = total_cholesterol,
      HDL_Chol = hdl_cholesterol,
      eGFR = egfr
    )
  ))
}

score2_op_risk <- function(sex, age, smoking_status, systolic_bp, total_cholesterol, hdl_cholesterol = NULL, region_risk_level = "low") {

  sex <- tolower(as.character(sex))
  age <- as.numeric(age)
  smoking_status <- as.numeric(smoking_status)
  systolic_bp <- as.numeric(systolic_bp)
  total_cholesterol <- as.numeric(total_cholesterol)
  region_risk_level <- tolower(as.character(region_risk_level))

  if (any(is.na(c(age, smoking_status, systolic_bp, total_cholesterol)))) {
    stop("Error: All inputs must be numeric.")
  }

  if (!sex %in% c("male", "female")) {
    stop("Error: Sex must be 'male' or 'female'.")
  }

  if (!region_risk_level %in% c("low", "moderate", "high", "very_high")) {
    stop("Error: Region risk must be 'low', 'moderate', 'high', or 'very_high'.")
  }

  non_hdl_cholesterol <- total_cholesterol
  if (!is.null(hdl_cholesterol)) {
    non_hdl_cholesterol <- total_cholesterol - as.numeric(hdl_cholesterol)
  }

  if (total_cholesterol > 15) {
    total_cholesterol <- total_cholesterol / 38.67
    if (!is.null(hdl_cholesterol)) {
      hdl_cholesterol <- hdl_cholesterol / 38.67
      non_hdl_cholesterol <- total_cholesterol - hdl_cholesterol
    } else {
      non_hdl_cholesterol <- total_cholesterol
    }
  }

  age_c <- (age - 60) / 5
  sbp_c <- (systolic_bp - 120) / 20
  chol_c <- (non_hdl_cholesterol - 3.5) / 1.0

  params <- list(
    low = list(
      male = c(0.38359, 0.43593, 0.49321, 0.46819, -0.05459, -0.06655, -0.08215, -0.11487, -0.13232, 0.9605, 0.02621, 0.03103),
      female = c(0.53232, 0.56448, 0.58892, 0.53273, -0.05825, -0.07237, -0.08225, -0.09785, -0.09945, 0.9776, 0.02621, 0.03103)
    ),
    moderate = list(
      male = c(0.43770, 0.48458, 0.53434, 0.50922, -0.05459, -0.06655, -0.08215, -0.11487, -0.13232, 0.9465, 0.02621, 0.03103),
      female = c(0.60474, 0.63332, 0.65066, 0.59825, -0.05825, -0.07237, -0.08225, -0.09785, -0.09945, 0.9707, 0.02621, 0.03103)
    ),
    high = list(
      male = c(0.49178, 0.53323, 0.57547, 0.55025, -0.05459, -0.06655, -0.08215, -0.11487, -0.13232, 0.9325, 0.02621, 0.03103),
      female = c(0.67716, 0.70214, 0.71239, 0.66377, -0.05825, -0.07237, -0.08225, -0.09785, -0.09945, 0.9638, 0.02621, 0.03103)
    ),
    very_high = list(
      male = c(0.54586, 0.58188, 0.61660, 0.59128, -0.05459, -0.06655, -0.08215, -0.11487, -0.13232, 0.9185, 0.02621, 0.03103),
      female = c(0.74960, 0.77096, 0.77412, 0.72930, -0.05825, -0.07237, -0.08225, -0.09785, -0.09945, 0.9569, 0.02621, 0.03103)
    )
  )

  coeffs <- params[[region_risk_level]][[sex]]

  alpha_smoker <- coeffs[1]
  alpha_chol <- coeffs[2]
  alpha_sbp <- coeffs[3]

  beta_age <- coeffs[11]

  if (smoking_status == 1) {
    lp_smoker <- alpha_smoker + (coeffs[5] * age_c)
    total_risk_lp <- lp_smoker
  } else {
    total_risk_lp <- 0
  }

  lp_chol <- (alpha_chol + (coeffs[6] * age_c)) * chol_c
  total_risk_lp <- total_risk_lp + lp_chol

  lp_sbp <- (alpha_sbp + (coeffs[7] * age_c)) * sbp_c
  total_risk_lp <- total_risk_lp + lp_sbp

  lp_age <- beta_age * age_c

  base_survival <- coeffs[10]

  risk_score <- 1 - (base_survival ^ exp(total_risk_lp))

  risk_percent <- risk_score * 100

  risk_category <- ""
  if (risk_percent < 7.5) risk_category <- "Low-to-Moderate Risk"
  else if (risk_percent < 15) risk_category <- "High Risk"
  else risk_category <- "Very High Risk"

  return(list(
    SCORE2_OP_Risk_10yr = paste0(round(risk_percent, 1), "%"),
    Risk_Category = risk_category,
    Inputs = list(
      Age = age,
      Sex = sex,
      Smoker = smoking_status == 1,
      SBP = systolic_bp,
      Non_HDL_Cholesterol = round(non_hdl_cholesterol, 2),
      Region = region_risk_level
    )
  ))
}

sledai_2k_score <- function(seizure, psychosis, organic_brain_syndrome, visual_disturbance, cranial_nerve_disorder, lupus_headache, cva, vasculitis, arthritis, myositis, urinary_casts, hematuria, proteinuria, pyuria, rash, alopecia, mucosal_ulcers, pleurisy, pericarditis, low_complement, increased_dna_binding, fever, thrombocytopenia, leukopenia) {

  inputs <- c(seizure, psychosis, organic_brain_syndrome, visual_disturbance, cranial_nerve_disorder, lupus_headache, cva, vasculitis, arthritis, myositis, urinary_casts, hematuria, proteinuria, pyuria, rash, alopecia, mucosal_ulcers, pleurisy, pericarditis, low_complement, increased_dna_binding, fever, thrombocytopenia, leukopenia)

  if (any(is.na(inputs))) {
    stop("Error: All inputs must be numeric (0 or 1).")
  }

  score <- 0

  if (seizure == 1) score <- score + 8
  if (psychosis == 1) score <- score + 8
  if (organic_brain_syndrome == 1) score <- score + 8
  if (visual_disturbance == 1) score <- score + 8
  if (cranial_nerve_disorder == 1) score <- score + 8
  if (lupus_headache == 1) score <- score + 8
  if (cva == 1) score <- score + 8
  if (vasculitis == 1) score <- score + 8

  if (arthritis == 1) score <- score + 4
  if (myositis == 1) score <- score + 4
  if (urinary_casts == 1) score <- score + 4
  if (hematuria == 1) score <- score + 4
  if (proteinuria == 1) score <- score + 4
  if (pyuria == 1) score <- score + 4

  if (rash == 1) score <- score + 2
  if (alopecia == 1) score <- score + 2
  if (mucosal_ulcers == 1) score <- score + 2
  if (pleurisy == 1) score <- score + 2
  if (pericarditis == 1) score <- score + 2
  if (low_complement == 1) score <- score + 2
  if (increased_dna_binding == 1) score <- score + 2

  if (fever == 1) score <- score + 1
  if (thrombocytopenia == 1) score <- score + 1
  if (leukopenia == 1) score <- score + 1

  disease_activity <- ""
  if (score == 0) {
    disease_activity <- "No Activity"
  } else if (score <= 5) {
    disease_activity <- "Mild Activity"
  } else if (score <= 10) {
    disease_activity <- "Moderate Activity"
  } else if (score <= 19) {
    disease_activity <- "High Activity"
  } else {
    disease_activity <- "Very High Activity"
  }

  return(list(
    SLEDAI_2K_Score = score,
    Disease_Activity = disease_activity
  ))
}

pen_fast_score <- function(five_years_or_less, anaphylaxis_or_angioedema, treatment_required, severe_cutaneous_reaction = 0) {

  five_years_or_less <- as.numeric(five_years_or_less)
  anaphylaxis_or_angioedema <- as.numeric(anaphylaxis_or_angioedema)
  treatment_required <- as.numeric(treatment_required)
  severe_cutaneous_reaction <- as.numeric(severe_cutaneous_reaction)

  if (any(is.na(c(five_years_or_less, anaphylaxis_or_angioedema, treatment_required)))) {
    stop("Error: All inputs must be numeric.")
  }

  score <- 0

  if (five_years_or_less == 1) {
    score <- score + 2
  }

  if (anaphylaxis_or_angioedema == 1) {
    score <- score + 2
  }

  if (treatment_required == 1) {
    score <- score + 1
  }

  risk_category <- ""
  interpretation <- ""

  if (severe_cutaneous_reaction == 1) {
    risk_category <- "Very High Risk / Contraindicated"
    interpretation <- "History of SCAR (e.g., SJS/TEN, DRESS) is a contraindication for oral challenge."
  } else {
    if (score < 3) {
      risk_category <- "Low Risk"
      interpretation <- "Low likelihood of positive penicillin allergy test (< 5%). Consider direct oral challenge."
    } else {
      risk_category <- "Moderate/High Risk"
      interpretation <- "Higher likelihood of positive penicillin allergy test (~50%). Referral to allergist/immunologist recommended."
    }
  }

  return(list(
    PEN_FAST_Score = score,
    Risk_Category = risk_category,
    Interpretation = interpretation,
    Inputs = list(
      Five_Years_or_Less = five_years_or_less == 1,
      Anaphylaxis_Angioedema = anaphylaxis_or_angioedema == 1,
      Treatment_Required = treatment_required == 1,
      SCAR_History = severe_cutaneous_reaction == 1
    )
  ))
}

perc_rule_pulmonary_embolism <- function(age, heart_rate, oxygen_saturation, prior_pe_dvt, recent_trauma_surgery, hemoptysis, exogenous_estrogen, unilateral_leg_swelling) {

  age <- as.numeric(age)
  heart_rate <- as.numeric(heart_rate)
  oxygen_saturation <- as.numeric(oxygen_saturation)
  prior_pe_dvt <- as.numeric(prior_pe_dvt)
  recent_trauma_surgery <- as.numeric(recent_trauma_surgery)
  hemoptysis <- as.numeric(hemoptysis)
  exogenous_estrogen <- as.numeric(exogenous_estrogen)
  unilateral_leg_swelling <- as.numeric(unilateral_leg_swelling)

  if (any(is.na(c(age, heart_rate, oxygen_saturation, prior_pe_dvt, recent_trauma_surgery, hemoptysis, exogenous_estrogen, unilateral_leg_swelling)))) {
    stop("Error: All inputs must be numeric.")
  }

  criteria_met <- FALSE
  reasons <- c()

  if (age >= 50) {
    criteria_met <- TRUE
    reasons <- c(reasons, "Age >= 50")
  }

  if (heart_rate >= 100) {
    criteria_met <- TRUE
    reasons <- c(reasons, "Heart Rate >= 100")
  }

  if (oxygen_saturation < 95) {
    criteria_met <- TRUE
    reasons <- c(reasons, "SaO2 < 95%")
  }

  if (prior_pe_dvt == 1) {
    criteria_met <- TRUE
    reasons <- c(reasons, "Prior PE/DVT")
  }

  if (recent_trauma_surgery == 1) {
    criteria_met <- TRUE
    reasons <- c(reasons, "Recent trauma or surgery")
  }

  if (hemoptysis == 1) {
    criteria_met <- TRUE
    reasons <- c(reasons, "Hemoptysis")
  }

  if (exogenous_estrogen == 1) {
    criteria_met <- TRUE
    reasons <- c(reasons, "Exogenous estrogen use")
  }

  if (unilateral_leg_swelling == 1) {
    criteria_met <- TRUE
    reasons <- c(reasons, "Unilateral leg swelling")
  }

  result <- ""
  recommendation <- ""

  if (criteria_met) {
    result <- "PERC Rule Not Met (Positive)"
    recommendation <- "Risk of PE > 2%. PERC cannot rule out PE. Consider D-dimer testing or imaging."
  } else {
    result <- "PERC Rule Negative"
    recommendation <- "Risk of PE < 2%. PE ruled out without further testing (if pre-test probability is low)."
  }

  return(list(
    Result = result,
    Recommendation = recommendation,
    Positive_Criteria = if (length(reasons) > 0) reasons else "None",
    Inputs = list(
      Age = age,
      HR = heart_rate,
      SaO2 = oxygen_saturation,
      Hx_VTE = prior_pe_dvt == 1,
      Trauma_Sx = recent_trauma_surgery == 1,
      Hemoptysis = hemoptysis == 1,
      Estrogen = exogenous_estrogen == 1,
      Leg_Swelling = unilateral_leg_swelling == 1
    )
  ))
}

perioperative_anticoagulation_pause <- function(drug_name, procedure_bleeding_risk, crcl_ml_min) {

  drug_name <- tolower(as.character(drug_name))
  procedure_bleeding_risk <- tolower(as.character(procedure_bleeding_risk))
  crcl_ml_min <- as.numeric(crcl_ml_min)

  if (any(is.na(c(crcl_ml_min)))) {
    stop("Error: CrCl must be numeric.")
  }

  if (!drug_name %in% c("apixaban", "rivaroxaban", "edoxaban", "dabigatran")) {
    stop("Error: Drug must be 'apixaban', 'rivaroxaban', 'edoxaban', or 'dabigatran'.")
  }

  if (!procedure_bleeding_risk %in% c("low", "high")) {
    stop("Error: Procedure bleeding risk must be 'low' or 'high'.")
  }

  stop_instruction <- ""
  resume_instruction <- ""
  last_dose_timing <- ""

  if (drug_name == "dabigatran") {
    if (crcl_ml_min < 30) {
      stop_instruction <- "Contraindicated / Not Validated (CrCl < 30)"
      last_dose_timing <- "N/A"
    } else if (crcl_ml_min < 50) {
      if (procedure_bleeding_risk == "low") {
        stop_instruction <- "Stop 2 days before procedure"
        last_dose_timing <- "Last dose: 3 days before surgery (skip 2 days)"
      } else {
        stop_instruction <- "Stop 4 days before procedure"
        last_dose_timing <- "Last dose: 5 days before surgery (skip 4 days)"
      }
    } else {
      if (procedure_bleeding_risk == "low") {
        stop_instruction <- "Stop 1 day before procedure"
        last_dose_timing <- "Last dose: Day before surgery in morning (skip 1 day)"
      } else {
        stop_instruction <- "Stop 2 days before procedure"
        last_dose_timing <- "Last dose: 3 days before surgery (skip 2 days)"
      }
    }
  } else {
    if (crcl_ml_min < 30 && drug_name != "apixaban") {
      stop_instruction <- "Caution: CrCl < 30 (Not validated in PAUSE for Rivaroxaban/Edoxaban)"
      last_dose_timing <- "Consult Hematology"
    } else if (crcl_ml_min < 25 && drug_name == "apixaban") {
      stop_instruction <- "Caution: CrCl < 25 (Not validated in PAUSE for Apixaban)"
      last_dose_timing <- "Consult Hematology"
    } else {
      if (procedure_bleeding_risk == "low") {
        stop_instruction <- "Stop 1 day before procedure"
        last_dose_timing <- "Last dose: Day before surgery in morning (skip 1 day)"
      } else {
        stop_instruction <- "Stop 2 days before procedure"
        last_dose_timing <- "Last dose: 3 days before surgery (skip 2 days)"
      }
    }
  }

  if (procedure_bleeding_risk == "low") {
    resume_instruction <- "Resume ~24 hours after procedure, assuming adequate hemostasis."
  } else {
    resume_instruction <- "Resume ~48-72 hours after procedure, assuming adequate hemostasis."
  }

  return(list(
    PreOp_Recommendation = stop_instruction,
    Last_Dose_Timing = last_dose_timing,
    PostOp_Resumption = resume_instruction,
    Inputs = list(
      Drug = drug_name,
      Risk = procedure_bleeding_risk,
      CrCl = crcl_ml_min
    )
  ))
}

pbsc_collection_volume <- function(weight_kg, pre_cd34_count, target_yield, collection_efficiency_percent = 50) {

  weight_kg <- as.numeric(weight_kg)
  pre_cd34_count <- as.numeric(pre_cd34_count)
  target_yield <- as.numeric(target_yield)
  collection_efficiency_percent <- as.numeric(collection_efficiency_percent)

  if (any(is.na(c(weight_kg, pre_cd34_count, target_yield, collection_efficiency_percent)))) {
    stop("Error: All inputs must be numeric.")
  }

  if (pre_cd34_count <= 0) {
    stop("Error: Pre-apheresis CD34 count must be greater than 0.")
  }

  if (collection_efficiency_percent <= 0 || collection_efficiency_percent > 100) {
    stop("Error: Efficiency must be between 0 and 100.")
  }

  efficiency_decimal <- collection_efficiency_percent / 100

  blood_volume_liters <- (target_yield * weight_kg) / (pre_cd34_count * efficiency_decimal)

  return(list(
    Volume_to_Process_Liters = round(blood_volume_liters, 1),
    Inputs = list(
      Weight_kg = weight_kg,
      Pre_CD34_uL = pre_cd34_count,
      Target_Yield_10_6_kg = target_yield,
      Efficiency_Percent = collection_efficiency_percent
    )
  ))
}

pascal_classification_pfo <- function(rope_score, high_risk_pfo_features) {

  rope_score <- as.numeric(rope_score)
  high_risk_pfo_features <- as.numeric(high_risk_pfo_features)

  if (any(is.na(c(rope_score, high_risk_pfo_features)))) {
    stop("Error: All inputs must be numeric.")
  }

  if (rope_score < 0 || rope_score > 10) {
    stop("Error: RoPE score must be between 0 and 10.")
  }

  if (!high_risk_pfo_features %in% c(0, 1)) {
    stop("Error: High-risk PFO features must be 0 (No) or 1 (Yes).")
  }

  classification <- ""

  if (rope_score >= 7 && high_risk_pfo_features == 1) {
    classification <- "Probable"
  } else if ((rope_score < 7 && high_risk_pfo_features == 0)) {
    classification <- "Unlikely"
  } else {
    classification <- "Possible"
  }


  return(list(
    PASCAL_Classification = classification,
    Inputs = list(
      RoPE_Score = rope_score,
      High_Risk_PFO = high_risk_pfo_features == 1
    )
  ))
}

phases_aneurysm_score <- function(population, hypertension, age, aneurysm_size_mm, history_sah, aneurysm_site) {

  population <- tolower(as.character(population))
  hypertension <- as.numeric(hypertension)
  age <- as.numeric(age)
  aneurysm_size_mm <- as.numeric(aneurysm_size_mm)
  history_sah <- as.numeric(history_sah)
  aneurysm_site <- tolower(as.character(aneurysm_site))

  if (any(is.na(c(hypertension, age, aneurysm_size_mm, history_sah)))) {
    stop("Error: Hypertension, Age, Size, and History of SAH must be numeric.")
  }

  valid_populations <- c("other", "japanese", "finnish")
  if (!population %in% valid_populations) {
    stop("Error: Population must be 'other' (North American/European), 'japanese', or 'finnish'.")
  }

  valid_sites <- c("ica", "mca", "posterior_aca_pcom")
  if (!aneurysm_site %in% valid_sites) {
    stop("Error: Site must be 'ica' (Internal Carotid), 'mca' (Middle Cerebral), or 'posterior_aca_pcom' (Posterior circulation/Anterior Cerebral/Posterior Communicating).")
  }

  score <- 0

  if (population == "japanese") {
    score <- score + 3
  } else if (population == "finnish") {
    score <- score + 5
  } else {
    score <- score + 0
  }

  if (hypertension == 1) {
    score <- score + 1
  }

  if (age >= 70) {
    score <- score + 1
  }

  if (aneurysm_size_mm < 7.0) {
    score <- score + 0
  } else if (aneurysm_size_mm < 10.0) {
    score <- score + 3
  } else if (aneurysm_size_mm < 20.0) {
    score <- score + 6
  } else {
    score <- score + 10
  }

  if (history_sah == 1) {
    score <- score + 1
  }

  if (aneurysm_site == "mca") {
    score <- score + 2
  } else if (aneurysm_site == "posterior_aca_pcom") {
    score <- score + 4
  } else {
    score <- score + 0
  }

  risk_5_year <- ""

  if (score <= 2) {
    risk_5_year <- "0.4%"
  } else if (score == 3) {
    risk_5_year <- "0.7%"
  } else if (score == 4) {
    risk_5_year <- "0.9%"
  } else if (score == 5) {
    risk_5_year <- "1.3%"
  } else if (score == 6) {
    risk_5_year <- "1.7%"
  } else if (score == 7) {
    risk_5_year <- "2.4%"
  } else if (score == 8) {
    risk_5_year <- "3.2%"
  } else if (score == 9) {
    risk_5_year <- "4.3%"
  } else if (score == 10) {
    risk_5_year <- "5.3%"
  } else if (score == 11) {
    risk_5_year <- "7.2%"
  } else {
    risk_5_year <- "17.8%"
  }

  return(list(
    PHASES_Score = score,
    Risk_5_Year_Rupture = risk_5_year,
    Inputs = list(
      Population = population,
      Hypertension = hypertension == 1,
      Age = age,
      Size_mm = aneurysm_size_mm,
      History_SAH = history_sah == 1,
      Site = aneurysm_site
    )
  ))
}

phenytoin_correction <- function(measured_phenytoin, albumin, renal_failure) {

  measured_phenytoin <- as.numeric(measured_phenytoin)
  albumin <- as.numeric(albumin)
  renal_failure <- as.numeric(renal_failure)

  if (any(is.na(c(measured_phenytoin, albumin, renal_failure)))) {
    stop("Error: All inputs must be numeric.")
  }

  if (measured_phenytoin < 0 || albumin < 0) {
    stop("Error: Measurements cannot be negative.")
  }

  adjustment_factor <- 0.2
  if (renal_failure == 1) {
    adjustment_factor <- 0.1
  }

  corrected_phenytoin <- measured_phenytoin / ((adjustment_factor * albumin) + 0.1)

  return(list(
    Corrected_Phenytoin_mcg_mL = round(corrected_phenytoin, 1),
    Inputs = list(
      Measured_Phenytoin = measured_phenytoin,
      Albumin = albumin,
      Renal_Failure_Status = renal_failure == 1
    )
  ))
}

phoenix_sepsis_score <- function(respiratory_support_type, pao2 = NA, spo2 = NA, fio2 = NA, vasoactive_med_count, lactate_mmol_l, map_below_5th_percentile_age, platelet_count, inr, d_dimer_mg_l, fibrinogen_mg_dl, gcs_score, fixed_pupils) {

  respiratory_support_type <- tolower(as.character(respiratory_support_type))
  vasoactive_med_count <- as.numeric(vasoactive_med_count)
  lactate_mmol_l <- as.numeric(lactate_mmol_l)
  map_below_5th_percentile_age <- as.numeric(map_below_5th_percentile_age)
  platelet_count <- as.numeric(platelet_count)
  inr <- as.numeric(inr)
  d_dimer_mg_l <- as.numeric(d_dimer_mg_l)
  fibrinogen_mg_dl <- as.numeric(fibrinogen_mg_dl)
  gcs_score <- as.numeric(gcs_score)
  fixed_pupils <- as.numeric(fixed_pupils)

  resp_score <- 0

  pf_ratio <- NA
  sf_ratio <- NA

  if (!is.na(fio2) && fio2 > 0) {
    fio2_frac <- if(fio2 > 1) fio2/100 else fio2
    if (!is.na(pao2)) pf_ratio <- pao2 / fio2_frac
    if (!is.na(spo2)) sf_ratio <- spo2 / fio2_frac
  }

  if (respiratory_support_type != "none") {
    resp_score <- 1
  }

  if (respiratory_support_type == "invasive") {
    is_severe <- FALSE
    is_moderate <- FALSE

    if ((!is.na(pf_ratio) && pf_ratio < 100) || (!is.na(sf_ratio) && sf_ratio < 148)) {
      is_severe <- TRUE
    }

    if ((!is.na(pf_ratio) && pf_ratio < 200) || (!is.na(sf_ratio) && sf_ratio < 220)) {
      is_moderate <- TRUE
    }

    if (is_severe) {
      resp_score <- 3
    } else if (is_moderate) {
      resp_score <- 2
    }
  }

  cv_score <- 0

  if (map_below_5th_percentile_age == 1 || (!is.na(lactate_mmol_l) && lactate_mmol_l >= 5.0)) {
    cv_score <- 1
  }

  if (vasoactive_med_count == 1) {
    cv_score <- 2
  } else if (vasoactive_med_count == 2) {
    cv_score <- 4
  } else if (vasoactive_med_count >= 3) {
    cv_score <- 6
  }

  coag_score <- 0

  coag_criteria_met <- FALSE
  if (!is.na(platelet_count) && platelet_count < 100) coag_criteria_met <- TRUE
  if (!is.na(inr) && inr > 1.3) coag_criteria_met <- TRUE
  if (!is.na(d_dimer_mg_l) && d_dimer_mg_l > 2.0) coag_criteria_met <- TRUE
  if (!is.na(fibrinogen_mg_dl) && fibrinogen_mg_dl < 100) coag_criteria_met <- TRUE

  if (coag_criteria_met) {
    coag_score <- 1
  }

  neuro_score <- 0

  neuro_criteria_met <- FALSE
  if (!is.na(gcs_score) && gcs_score <= 10) neuro_criteria_met <- TRUE
  if (fixed_pupils == 1) neuro_criteria_met <- TRUE

  if (neuro_criteria_met) {
    neuro_score <- 1
  }

  total_score <- resp_score + cv_score + coag_score + neuro_score

  return(list(
    Phoenix_Sepsis_Score = total_score,
    Subscores = list(
      Respiratory = resp_score,
      Cardiovascular = cv_score,
      Coagulation = coag_score,
      Neurologic = neuro_score
    ),
    Diagnosis = if (total_score >= 2) "Sepsis Criteria Met (in suspected infection)" else "Sepsis Criteria Not Met"
  ))
}

phq9_score <- function(interest, depressed, sleep, energy, appetite, failure, concentration, psychomotor, suicide) {

  inputs <- c(interest, depressed, sleep, energy, appetite, failure, concentration, psychomotor, suicide)

  if (any(is.na(inputs))) {
    stop("Error: All 9 inputs must be numeric.")
  }

  if (any(inputs < 0) || any(inputs > 3)) {
    stop("Error: All item scores must be integers between 0 and 3.")
  }

  total_score <- sum(inputs)

  severity <- ""
  if (total_score <= 4) {
    severity <- "None-minimal"
  } else if (total_score <= 9) {
    severity <- "Mild"
  } else if (total_score <= 14) {
    severity <- "Moderate"
  } else if (total_score <= 19) {
    severity <- "Moderately Severe"
  } else {
    severity <- "Severe"
  }

  return(list(
    PHQ9_Score = total_score,
    Severity = severity,
    Inputs = list(
      Q1_Interest = interest,
      Q2_Depressed = depressed,
      Q3_Sleep = sleep,
      Q4_Energy = energy,
      Q5_Appetite = appetite,
      Q6_Failure = failure,
      Q7_Concentration = concentration,
      Q8_Psychomotor = psychomotor,
      Q9_Suicide = suicide
    )
  ))
}

piro_cap_score <- function(age, copd, immunocompromised, multilobar_opacities, bacteremia, shock, severe_hypoxemia, acute_renal_failure) {

  age <- as.numeric(age)
  copd <- as.numeric(copd)
  immunocompromised <- as.numeric(immunocompromised)
  multilobar_opacities <- as.numeric(multilobar_opacities)
  bacteremia <- as.numeric(bacteremia)
  shock <- as.numeric(shock)
  severe_hypoxemia <- as.numeric(severe_hypoxemia)
  acute_renal_failure <- as.numeric(acute_renal_failure)

  if (any(is.na(c(age, copd, immunocompromised, multilobar_opacities, bacteremia, shock, severe_hypoxemia, acute_renal_failure)))) {
    stop("Error: All inputs must be numeric.")
  }

  score <- 0

  if (age > 70) {
    score <- score + 1
  }

  if (copd == 1) {
    score <- score + 1
  }

  if (immunocompromised == 1) {
    score <- score + 1
  }

  if (multilobar_opacities == 1) {
    score <- score + 1
  }

  if (bacteremia == 1) {
    score <- score + 1
  }

  if (shock == 1) {
    score <- score + 1
  }

  if (severe_hypoxemia == 1) {
    score <- score + 1
  }

  if (acute_renal_failure == 1) {
    score <- score + 1
  }

  risk_level <- ""
  mortality_28_day <- ""

  if (score <= 2) {
    risk_level <- "Low Risk"
    mortality_28_day <- "2 - 4%"
  } else if (score == 3) {
    risk_level <- "Mild/Intermediate Risk"
    mortality_28_day <- "10 - 18%"
  } else if (score == 4) {
    risk_level <- "High Risk"
    mortality_28_day <- "27 - 34%"
  } else {
    risk_level <- "Very High Risk"
    mortality_28_day <- "55 - 76%"
  }

  return(list(
    PIRO_Score = score,
    Risk_Category = risk_level,
    Mortality_Risk_28_Day = mortality_28_day,
    Inputs = list(
      Age_gt_70 = age > 70,
      COPD = copd == 1,
      Immunocompromised = immunocompromised == 1,
      Multilobar_CXR = multilobar_opacities == 1,
      Bacteremia = bacteremia == 1,
      Shock = shock == 1,
      Hypoxemia_Severe = severe_hypoxemia == 1,
      Renal_Failure = acute_renal_failure == 1
    )
  ))
}

pittsburgh_knee_rules <- function(blunt_trauma_or_fall, age_years, unable_to_walk_4_steps_in_ed) {

  blunt_trauma_or_fall <- as.numeric(blunt_trauma_or_fall)
  age_years <- as.numeric(age_years)
  unable_to_walk_4_steps_in_ed <- as.numeric(unable_to_walk_4_steps_in_ed)

  if (any(is.na(c(blunt_trauma_or_fall, age_years, unable_to_walk_4_steps_in_ed)))) {
    stop("Error: All inputs must be numeric.")
  }

  recommendation <- ""

  if (blunt_trauma_or_fall == 0) {
    recommendation <- "Rule Not Applicable (Requires mechanism of blunt trauma or fall)"
  } else {
    if (age_years < 12 || age_years > 50) {
      recommendation <- "Knee X-ray Indicated"
    } else if (unable_to_walk_4_steps_in_ed == 1) {
      recommendation <- "Knee X-ray Indicated"
    } else {
      recommendation <- "Knee X-ray Not Indicated"
    }
  }

  return(list(
    Recommendation = recommendation,
    Inputs = list(
      Mechanism_Trauma_Fall = blunt_trauma_or_fall == 1,
      Age = age_years,
      Inability_to_Walk = unable_to_walk_4_steps_in_ed == 1
    )
  ))
}

pittsburgh_response_endovascular_score <- function(age, nihss_score, aspects_score, pre_stroke_mrs) {

  age <- as.numeric(age)
  nihss_score <- as.numeric(nihss_score)
  aspects_score <- as.numeric(aspects_score)
  pre_stroke_mrs <- as.numeric(pre_stroke_mrs)

  if (any(is.na(c(age, nihss_score, aspects_score, pre_stroke_mrs)))) {
    stop("Error: All inputs must be numeric.")
  }

  if (aspects_score < 0 || aspects_score > 10) {
    stop("Error: ASPECTS score must be between 0 and 10.")
  }

  score <- 0

  if (age < 60) {
    score <- score + 0
  } else if (age >= 60 && age <= 69) {
    score <- score + 2
  } else if (age >= 70 && age <= 79) {
    score <- score + 4
  } else {
    score <- score + 6
  }

  if (nihss_score < 10) {
    score <- score + 0
  } else if (nihss_score >= 10 && nihss_score <= 15) {
    score <- score + 2
  } else if (nihss_score >= 16 && nihss_score <= 20) {
    score <- score + 4
  } else {
    score <- score + 6
  }

  if (aspects_score == 10) {
    score <- score + 0
  } else if (aspects_score >= 8 && aspects_score <= 9) {
    score <- score + 2
  } else {
    score <- score + 4
  }

  if (pre_stroke_mrs == 0) {
    score <- score + 0
  } else if (pre_stroke_mrs == 1) {
    score <- score + 2
  } else {
    score <- score + 4
  }

  return(list(
    PRE_Score = score,
    Interpretation = "Higher scores indicate a lower probability of good functional outcome (mRS 0-2) at 90 days.",
    Inputs = list(
      Age = age,
      NIHSS = nihss_score,
      ASPECTS = aspects_score,
      Pre_mRS = pre_stroke_mrs
    )
  ))
}

plan_stroke_score <- function(age, preadmission_dependence, cancer, congestive_heart_failure, atrial_fibrillation, reduced_consciousness, arm_weakness, leg_weakness, aphasia_neglect) {

  age <- as.numeric(age)
  preadmission_dependence <- as.numeric(preadmission_dependence)
  cancer <- as.numeric(cancer)
  congestive_heart_failure <- as.numeric(congestive_heart_failure)
  atrial_fibrillation <- as.numeric(atrial_fibrillation)
  reduced_consciousness <- as.numeric(reduced_consciousness)
  arm_weakness <- as.numeric(arm_weakness)
  leg_weakness <- as.numeric(leg_weakness)
  aphasia_neglect <- as.numeric(aphasia_neglect)

  if (any(is.na(c(age, preadmission_dependence, cancer, congestive_heart_failure, atrial_fibrillation, reduced_consciousness, arm_weakness, leg_weakness, aphasia_neglect)))) {
    stop("Error: All inputs must be numeric.")
  }

  score <- 0

  if (age > 90) {
    score <- score + 9
  } else if (age > 80) {
    score <- score + 7
  } else if (age > 70) {
    score <- score + 5
  } else if (age > 60) {
    score <- score + 2
  } else {
    score <- score + 0
  }

  if (preadmission_dependence == 1) {
    score <- score + 1.5
  }

  if (cancer == 1) {
    score <- score + 1.5
  }

  if (congestive_heart_failure == 1) {
    score <- score + 1
  }

  if (atrial_fibrillation == 1) {
    score <- score + 1
  }

  if (reduced_consciousness == 1) {
    score <- score + 5
  }

  if (arm_weakness == 1) {
    score <- score + 2
  }

  if (leg_weakness == 1) {
    score <- score + 2
  }

  if (aphasia_neglect == 1) {
    score <- score + 1
  }

  mortality_30_day <- ""
  mortality_1_year <- ""
  poor_outcome_discharge <- ""

  if (score <= 1) {
    mortality_30_day <- "0.6%"
    mortality_1_year <- "3%"
    poor_outcome_discharge <- "7%"
  } else if (score <= 5) {
    mortality_30_day <- "1.8%"
    mortality_1_year <- "6%"
    poor_outcome_discharge <- "22%"
  } else if (score <= 10) {
    mortality_30_day <- "5%"
    mortality_1_year <- "15%"
    poor_outcome_discharge <- "47%"
  } else if (score <= 15) {
    mortality_30_day <- "13%"
    mortality_1_year <- "32%"
    poor_outcome_discharge <- "73%"
  } else if (score <= 20) {
    mortality_30_day <- "31%"
    mortality_1_year <- "59%"
    poor_outcome_discharge <- "93%"
  } else {
    mortality_30_day <- "59%"
    mortality_1_year <- "85%"
    poor_outcome_discharge <- "99%"
  }

  return(list(
    PLAN_Score = score,
    Est_30_Day_Mortality = mortality_30_day,
    Est_1_Year_Mortality = mortality_1_year,
    Poor_Outcome_Discharge_mRS_5_6 = poor_outcome_discharge,
    Inputs = list(
      Age = age,
      Pre_Admission_Dependence = preadmission_dependence == 1,
      Cancer = cancer == 1,
      CHF = congestive_heart_failure == 1,
      Atrial_Fibrillation = atrial_fibrillation == 1,
      Reduced_Consciousness = reduced_consciousness == 1,
      Arm_Weakness = arm_weakness == 1,
      Leg_Weakness = leg_weakness == 1,
      Aphasia_Neglect = aphasia_neglect == 1
    )
  ))
}

calculate_plasma_dosage <- function(weight_kg, dose_per_kg_ml = 15) {

  weight_kg <- as.numeric(weight_kg)
  dose_per_kg_ml <- as.numeric(dose_per_kg_ml)

  if (any(is.na(c(weight_kg, dose_per_kg_ml)))) {
    stop("Error: All inputs must be numeric.")
  }

  if (weight_kg <= 0 || dose_per_kg_ml <= 0) {
    stop("Error: Weight and dose must be positive.")
  }

  total_volume_ml <- weight_kg * dose_per_kg_ml

  estimated_units_low <- round(total_volume_ml / 250, 1)
  estimated_units_high <- round(total_volume_ml / 200, 1)

  return(list(
    Total_Plasma_Volume_mL = round(total_volume_ml, 0),
    Estimated_Units_FFP = paste0(estimated_units_low, " - ", estimated_units_high, " units (assuming 200-250 mL/unit)"),
    Inputs = list(
      Weight_kg = weight_kg,
      Dose_mL_kg = dose_per_kg_ml
    )
  ))
}

plasmic_score_ttp <- function(platelet_count, hemolysis_evidence, active_cancer, stem_cell_or_organ_transplant, mcv_lt_90, inr_lt_1_5, creatinine_lt_2_0) {

  platelet_count <- as.numeric(platelet_count)
  hemolysis_evidence <- as.numeric(hemolysis_evidence)
  active_cancer <- as.numeric(active_cancer)
  stem_cell_or_organ_transplant <- as.numeric(stem_cell_or_organ_transplant)
  mcv_lt_90 <- as.numeric(mcv_lt_90)
  inr_lt_1_5 <- as.numeric(inr_lt_1_5)
  creatinine_lt_2_0 <- as.numeric(creatinine_lt_2_0)

  if (any(is.na(c(platelet_count, hemolysis_evidence, active_cancer, stem_cell_or_organ_transplant, mcv_lt_90, inr_lt_1_5, creatinine_lt_2_0)))) {
    stop("Error: All inputs must be numeric (0 or 1 where applicable).")
  }

  score <- 0

  if (platelet_count < 30) {
    score <- score + 1
  }

  if (hemolysis_evidence == 1) {
    score <- score + 1
  }

  if (active_cancer == 0) {
    score <- score + 1
  }

  if (stem_cell_or_organ_transplant == 0) {
    score <- score + 1
  }

  if (mcv_lt_90 == 1) {
    score <- score + 1
  }

  if (inr_lt_1_5 == 1) {
    score <- score + 1
  }

  if (creatinine_lt_2_0 == 1) {
    score <- score + 1
  }

  risk_category <- ""
  probability <- ""

  if (score >= 0 && score <= 4) {
    risk_category <- "Low Risk"
    probability <- "0-4%"
  } else if (score == 5) {
    risk_category <- "Intermediate Risk"
    probability <- "0-24%"
  } else if (score >= 6 && score <= 7) {
    risk_category <- "High Risk"
    probability <- "62-82%"
  } else {
    risk_category <- "Invalid Score"
    probability <- "N/A"
  }

  return(list(
    PLASMIC_Score = score,
    Risk_Category = risk_category,
    TTP_Probability = probability,
    Inputs = list(
      Platelets_lt_30 = platelet_count < 30,
      Hemolysis = hemolysis_evidence == 1,
      No_Active_Cancer = active_cancer == 0,
      No_Transplant = stem_cell_or_organ_transplant == 0,
      MCV_lt_90 = mcv_lt_90 == 1,
      INR_lt_1_5 = inr_lt_1_5 == 1,
      Creatinine_lt_2_0 = creatinine_lt_2_0 == 1
    )
  ))
}

pompe_c_score <- function(altered_mental_status, dnr_status, oxygen_saturation, weight_kg, respiratory_rate, heart_rate, unilateral_leg_swelling) {

  altered_mental_status <- as.numeric(altered_mental_status)
  dnr_status <- as.numeric(dnr_status)
  oxygen_saturation <- as.numeric(oxygen_saturation)
  weight_kg <- as.numeric(weight_kg)
  respiratory_rate <- as.numeric(respiratory_rate)
  heart_rate <- as.numeric(heart_rate)
  unilateral_leg_swelling <- as.numeric(unilateral_leg_swelling)

  if (any(is.na(c(altered_mental_status, dnr_status, oxygen_saturation, weight_kg, respiratory_rate, heart_rate, unilateral_leg_swelling)))) {
    stop("Error: All inputs must be numeric.")
  }

  score <- 0

  if (altered_mental_status == 1) {
    score <- score + 18
  }

  if (dnr_status == 1) {
    score <- score + 13
  }

  if (oxygen_saturation < 90) {
    score <- score + 8
  }

  if (weight_kg < 70) {
    score <- score + 6
  }

  if (respiratory_rate >= 24) {
    score <- score + 6
  }

  if (heart_rate >= 100) {
    score <- score + 5
  }

  if (unilateral_leg_swelling == 1) {
    score <- score - 3
  }

  risk_category <- ""
  mortality_30d <- ""

  if (score <= 5) {
    risk_category <- "Low Risk"
    mortality_30d <- "1.2 - 2.6%"
  } else if (score >= 6 && score <= 19) {
    risk_category <- "Intermediate Risk"
    mortality_30d <- "9.9 - 18.3%"
  } else {
    risk_category <- "High Risk"
    mortality_30d <- "34.3 - 57.1%"
  }

  return(list(
    POMPE_C_Score = score,
    Risk_Category = risk_category,
    Est_30_Day_Mortality = mortality_30d,
    Inputs = list(
      Altered_Mental_Status = altered_mental_status == 1,
      DNR_Status = dnr_status == 1,
      SpO2_lt_90 = oxygen_saturation < 90,
      Weight_lt_70kg = weight_kg < 70,
      RR_ge_24 = respiratory_rate >= 24,
      HR_ge_100 = heart_rate >= 100,
      Leg_Swelling = unilateral_leg_swelling == 1
    )
  ))
}

panss_score <- function(positive_scale_items, negative_scale_items, general_psychopathology_items) {

  if (length(positive_scale_items) != 7) {
    stop("Error: Positive Scale must contain exactly 7 items.")
  }

  if (length(negative_scale_items) != 7) {
    stop("Error: Negative Scale must contain exactly 7 items.")
  }

  if (length(general_psychopathology_items) != 16) {
    stop("Error: General Psychopathology Scale must contain exactly 16 items.")
  }

  all_items <- c(positive_scale_items, negative_scale_items, general_psychopathology_items)

  if (any(is.na(all_items))) {
    stop("Error: All inputs must be numeric.")
  }

  if (any(all_items < 1) || any(all_items > 7)) {
    stop("Error: Item scores must be integers between 1 and 7.")
  }

  p_score <- sum(positive_scale_items)
  n_score <- sum(negative_scale_items)
  g_score <- sum(general_psychopathology_items)

  total_score <- p_score + n_score + g_score

  severity_estimate <- ""
  if (total_score <= 58) {
    severity_estimate <- "Mildly ill"
  } else if (total_score <= 75) {
    severity_estimate <- "Moderately ill"
  } else if (total_score <= 95) {
    severity_estimate <- "Markedly ill"
  } else if (total_score <= 116) {
    severity_estimate <- "Severely ill"
  } else {
    severity_estimate <- "Among the most severely ill"
  }

  return(list(
    PANSS_Total_Score = total_score,
    Severity_Estimate = severity_estimate,
    Subscales = list(
      Positive_Scale_Score = p_score,
      Negative_Scale_Score = n_score,
      General_Psychopathology_Score = g_score
    )
  ))
}

possum_risk_score <- function(age, cardiac_signs, respiratory_signs, systolic_bp, pulse, gcs, hemoglobin, wbc_count, urea, sodium, potassium, ecg_status, operative_severity, multiple_procedures, total_blood_loss, peritoneal_soiling, malignancy_status, mode_of_surgery, urea_units = "mg/dL") {

  age <- as.numeric(age)
  systolic_bp <- as.numeric(systolic_bp)
  pulse <- as.numeric(pulse)
  gcs <- as.numeric(gcs)
  hemoglobin <- as.numeric(hemoglobin)
  wbc_count <- as.numeric(wbc_count)
  urea <- as.numeric(urea)
  sodium <- as.numeric(sodium)
  potassium <- as.numeric(potassium)

  cardiac_signs <- tolower(as.character(cardiac_signs))
  respiratory_signs <- tolower(as.character(respiratory_signs))
  ecg_status <- tolower(as.character(ecg_status))
  operative_severity <- tolower(as.character(operative_severity))
  multiple_procedures <- tolower(as.character(multiple_procedures))
  total_blood_loss <- as.numeric(total_blood_loss)
  peritoneal_soiling <- tolower(as.character(peritoneal_soiling))
  malignancy_status <- tolower(as.character(malignancy_status))
  mode_of_surgery <- tolower(as.character(mode_of_surgery))

  if (any(is.na(c(age, systolic_bp, pulse, gcs, hemoglobin, wbc_count, urea, sodium, potassium, total_blood_loss)))) {
    stop("Error: All physiologic numeric inputs must be valid.")
  }

  ps_score <- 0

  if (age < 60) ps_score <- ps_score + 1
  else if (age <= 69) ps_score <- ps_score + 2
  else if (age <= 79) ps_score <- ps_score + 4
  else ps_score <- ps_score + 8

  if (cardiac_signs == "normal") ps_score <- ps_score + 1
  else if (cardiac_signs == "mild") ps_score <- ps_score + 2
  else if (cardiac_signs == "moderate") ps_score <- ps_score + 4
  else ps_score <- ps_score + 8

  if (respiratory_signs == "normal") ps_score <- ps_score + 1
  else if (respiratory_signs == "mild") ps_score <- ps_score + 2
  else if (respiratory_signs == "moderate") ps_score <- ps_score + 4
  else ps_score <- ps_score + 8

  if (systolic_bp >= 110 && systolic_bp <= 130) ps_score <- ps_score + 1
  else if ((systolic_bp >= 100 && systolic_bp <= 109) || (systolic_bp >= 131 && systolic_bp <= 170)) ps_score <- ps_score + 2
  else if ((systolic_bp >= 90 && systolic_bp <= 99) || (systolic_bp > 170)) ps_score <- ps_score + 4
  else ps_score <- ps_score + 8

  if (pulse >= 50 && pulse <= 80) ps_score <- ps_score + 1
  else if ((pulse >= 81 && pulse <= 100) || (pulse >= 40 && pulse <= 49)) ps_score <- ps_score + 2
  else if ((pulse >= 101 && pulse <= 120)) ps_score <- ps_score + 4
  else ps_score <- ps_score + 8

  if (gcs == 15) ps_score <- ps_score + 1
  else if (gcs >= 12) ps_score <- ps_score + 2
  else if (gcs >= 9) ps_score <- ps_score + 4
  else ps_score <- ps_score + 8

  if (hemoglobin >= 13 && hemoglobin <= 16) ps_score <- ps_score + 1
  else if ((hemoglobin >= 11.5 && hemoglobin <= 12.9) || (hemoglobin >= 16.1 && hemoglobin <= 17)) ps_score <- ps_score + 2
  else if ((hemoglobin >= 10.0 && hemoglobin <= 11.4) || (hemoglobin >= 17.1 && hemoglobin <= 18)) ps_score <- ps_score + 4
  else ps_score <- ps_score + 8

  if (wbc_count >= 4 && wbc_count <= 10) ps_score <- ps_score + 1
  else if ((wbc_count >= 10.1 && wbc_count <= 20) || (wbc_count >= 3.1 && wbc_count <= 3.9)) ps_score <- ps_score + 2
  else ps_score <- ps_score + 4

  urea_mmol <- urea
  if (urea_units == "mg/dL") urea_mmol <- urea / 2.8

  if (urea_mmol <= 7.5) ps_score <- ps_score + 1
  else if (urea_mmol <= 10) ps_score <- ps_score + 2
  else if (urea_mmol <= 15) ps_score <- ps_score + 4
  else ps_score <- ps_score + 8

  if (sodium > 135) ps_score <- ps_score + 1
  else if (sodium >= 131) ps_score <- ps_score + 2
  else if (sodium >= 126) ps_score <- ps_score + 4
  else ps_score <- ps_score + 8

  if (potassium >= 3.5 && potassium <= 5.0) ps_score <- ps_score + 1
  else if ((potassium >= 3.2 && potassium <= 3.4) || (potassium >= 5.1 && potassium <= 5.3)) ps_score <- ps_score + 2
  else if ((potassium >= 2.9 && potassium <= 3.1) || (potassium >= 5.4 && potassium <= 5.9)) ps_score <- ps_score + 4
  else ps_score <- ps_score + 8

  if (ecg_status == "normal") ps_score <- ps_score + 1
  else if (ecg_status == "afib_mild") ps_score <- ps_score + 2
  else if (ecg_status == "abnormal_rhythm") ps_score <- ps_score + 4
  else ps_score <- ps_score + 8

  os_score <- 0

  if (operative_severity == "minor") os_score <- os_score + 1
  else if (operative_severity == "moderate") os_score <- os_score + 2
  else if (operative_severity == "major") os_score <- os_score + 4
  else os_score <- os_score + 8

  if (multiple_procedures == "1") os_score <- os_score + 1
  else if (multiple_procedures == "2") os_score <- os_score + 4
  else os_score <- os_score + 8

  if (total_blood_loss <= 100) os_score <- os_score + 1
  else if (total_blood_loss <= 500) os_score <- os_score + 2
  else if (total_blood_loss <= 999) os_score <- os_score + 4
  else os_score <- os_score + 8

  if (peritoneal_soiling == "none") os_score <- os_score + 1
  else if (peritoneal_soiling == "minor") os_score <- os_score + 2
  else if (peritoneal_soiling == "local_pus") os_score <- os_score + 4
  else os_score <- os_score + 8

  if (malignancy_status == "none") os_score <- os_score + 1
  else if (malignancy_status == "primary") os_score <- os_score + 2
  else if (malignancy_status == "nodal") os_score <- os_score + 4
  else os_score <- os_score + 8

  if (mode_of_surgery == "elective") os_score <- os_score + 1
  else if (mode_of_surgery == "emergency_gt_24h") os_score <- os_score + 2
  else if (mode_of_surgery == "emergency_2_24h") os_score <- os_score + 4
  else os_score <- os_score + 8

  mortality_logit <- -7.04 + (0.13 * ps_score) + (0.16 * os_score)
  mortality_risk <- 1 / (1 + exp(-mortality_logit))

  morbidity_logit <- -5.91 + (0.16 * ps_score) + (0.19 * os_score)
  morbidity_risk <- 1 / (1 + exp(-morbidity_logit))

  return(list(
    Physiological_Score = ps_score,
    Operative_Severity_Score = os_score,
    Predicted_Mortality_Risk = paste0(round(mortality_risk * 100, 1), "%"),
    Predicted_Morbidity_Risk = paste0(round(morbidity_risk * 100, 1), "%"),
    Inputs = list(
      Age = age,
      PS_Components = list(Cardiac=cardiac_signs, Resp=respiratory_signs, BP=systolic_bp, Pulse=pulse, GCS=gcs, Hb=hemoglobin, WBC=wbc_count, Urea=urea, Na=sodium, K=potassium, ECG=ecg_status),
      OS_Components = list(OpSeverity=operative_severity, Procedures=multiple_procedures, BloodLoss=total_blood_loss, Soiling=peritoneal_soiling, Malignancy=malignancy_status, Urgency=mode_of_surgery)
    )
  ))
}

prague_cm_classification <- function(ge_junction_distance_cm, circumferential_metaplasia_proximal_cm, max_metaplasia_proximal_cm) {

  ge_junction_distance_cm <- as.numeric(ge_junction_distance_cm)
  circumferential_metaplasia_proximal_cm <- as.numeric(circumferential_metaplasia_proximal_cm)
  max_metaplasia_proximal_cm <- as.numeric(max_metaplasia_proximal_cm)

  if (any(is.na(c(ge_junction_distance_cm, circumferential_metaplasia_proximal_cm, max_metaplasia_proximal_cm)))) {
    stop("Error: All inputs must be numeric values in centimeters.")
  }

  if (circumferential_metaplasia_proximal_cm > ge_junction_distance_cm) {
    stop("Error: Proximal extent of circumferential metaplasia cannot be deeper (greater value) than the GE junction.")
  }

  if (max_metaplasia_proximal_cm > ge_junction_distance_cm) {
    stop("Error: Proximal extent of maximum metaplasia cannot be deeper (greater value) than the GE junction.")
  }

  if (max_metaplasia_proximal_cm > circumferential_metaplasia_proximal_cm) {
    stop("Error: Maximum extent of metaplasia must be proximal to (lower value) or equal to the circumferential extent.")
  }

  c_value <- ge_junction_distance_cm - circumferential_metaplasia_proximal_cm
  m_value <- ge_junction_distance_cm - max_metaplasia_proximal_cm

  classification_string <- paste0("C", round(c_value, 1), "M", round(m_value, 1))

  return(list(
    Prague_Classification = classification_string,
    C_Length_cm = round(c_value, 1),
    M_Length_cm = round(m_value, 1),
    Inputs = list(
      GE_Junction_cm = ge_junction_distance_cm,
      Circumferential_Top_cm = circumferential_metaplasia_proximal_cm,
      Max_Extent_Top_cm = max_metaplasia_proximal_cm
    )
  ))
}

primacy_cardiomyopathy_score <- function(sex, age_at_diagnosis, skeletal_myopathy, family_history_dcm, low_qrs_voltage, conduction_defect, lge_on_cmr) {

  sex <- tolower(as.character(sex))
  age_at_diagnosis <- as.numeric(age_at_diagnosis)
  skeletal_myopathy <- as.numeric(skeletal_myopathy)
  family_history_dcm <- as.numeric(family_history_dcm)
  low_qrs_voltage <- as.numeric(low_qrs_voltage)
  conduction_defect <- as.numeric(conduction_defect)
  lge_on_cmr <- as.numeric(lge_on_cmr)

  if (any(is.na(c(age_at_diagnosis, skeletal_myopathy, family_history_dcm, low_qrs_voltage, conduction_defect, lge_on_cmr)))) {
    stop("Error: All inputs must be numeric (0 or 1 for binary).")
  }

  if (!sex %in% c("male", "female")) {
    stop("Error: Sex must be 'male' or 'female'.")
  }

  intercept <- -0.55
  coeff_age <- -0.026 * age_at_diagnosis
  coeff_sex <- if (sex == "female") 0.2 else 0
  coeff_myopathy <- 1.8 * skeletal_myopathy
  coeff_fam_hist <- 0.9 * family_history_dcm
  coeff_low_voltage <- 1.3 * low_qrs_voltage
  coeff_conduction <- 0.7 * conduction_defect
  coeff_lge <- 0.8 * lge_on_cmr

  logit <- intercept + coeff_age + coeff_sex + coeff_myopathy + coeff_fam_hist + coeff_low_voltage + coeff_conduction + coeff_lge

  probability <- 1 / (1 + exp(-logit))
  probability_percent <- probability * 100

  risk_category <- ""
  if (probability_percent < 20) {
    risk_category <- "Low Probability of Pathogenic Variant"
  } else if (probability_percent < 50) {
    risk_category <- "Intermediate Probability"
  } else {
    risk_category <- "High Probability of Pathogenic Variant"
  }

  return(list(
    PRIMACY_Probability = paste0(round(probability_percent, 1), "%"),
    Interpretation = risk_category,
    Inputs = list(
      Sex = sex,
      Age = age_at_diagnosis,
      Skeletal_Myopathy = skeletal_myopathy == 1,
      Family_History = family_history_dcm == 1,
      Low_Voltage = low_qrs_voltage == 1,
      Conduction_Defect = conduction_defect == 1,
      LGE_Present = lge_on_cmr == 1
    )
  ))
}

prevent_cvd_risk <- function(age, sex, total_cholesterol, hdl_cholesterol, systolic_bp, diabetes, smoking, egfr, bmi, current_treatment_hypertension, current_treatment_statins) {

  age <- as.numeric(age)
  sex <- tolower(as.character(sex))
  total_cholesterol <- as.numeric(total_cholesterol)
  hdl_cholesterol <- as.numeric(hdl_cholesterol)
  systolic_bp <- as.numeric(systolic_bp)
  diabetes <- as.numeric(diabetes)
  smoking <- as.numeric(smoking)
  egfr <- as.numeric(egfr)
  bmi <- as.numeric(bmi)
  current_treatment_hypertension <- as.numeric(current_treatment_hypertension)
  current_treatment_statins <- as.numeric(current_treatment_statins)

  if (any(is.na(c(age, total_cholesterol, hdl_cholesterol, systolic_bp, diabetes, smoking, egfr, bmi, current_treatment_hypertension, current_treatment_statins)))) {
    stop("Error: All inputs must be numeric.")
  }

  if (total_cholesterol > 15) {
    total_cholesterol <- total_cholesterol / 38.67
    hdl_cholesterol <- hdl_cholesterol / 38.67
  }

  non_hdl_cholesterol <- total_cholesterol - hdl_cholesterol

  age_t <- (age - 55) / 10
  tc_t <- (non_hdl_cholesterol - 3.5)
  hdl_t <- (hdl_cholesterol - 1.3) / 0.5
  sbp_t <- (systolic_bp - 130) / 20
  egfr_t <- (egfr - 90) / -15
  egfr_t <- min(egfr_t, 0)
  bmi_t <- (bmi - 30) / 5

  coeffs <- list(
    female = c(
      base_haz = 0.0226,
      age = 0.6862,
      non_hdl = 0.1597,
      hdl = -0.1722,
      sbp = 0.2290,
      diabetes = 0.4517,
      smoking = 0.4564,
      egfr = 0.2040,
      bmi = 0.1483,
      tx_htn = 0.2290,
      tx_statins = -0.2500
    ),
    male = c(
      base_haz = 0.0362,
      age = 0.6273,
      non_hdl = 0.1656,
      hdl = -0.1469,
      sbp = 0.2152,
      diabetes = 0.4992,
      smoking = 0.4235,
      egfr = 0.1765,
      bmi = 0.1131,
      tx_htn = 0.2152,
      tx_statins = -0.2500
    )
  )

  params <- if (sex == "female") coeffs$female else coeffs$male

  lp <- (params["age"] * age_t) +
    (params["non_hdl"] * tc_t) +
    (params["hdl"] * hdl_t) +
    (params["sbp"] * sbp_t) +
    (params["diabetes"] * diabetes) +
    (params["smoking"] * smoking) +
    (params["egfr"] * egfr_t) +
    (params["bmi"] * bmi_t)

  if (current_treatment_hypertension == 1) {
    lp <- lp + (params["tx_htn"] * 0.5)
  }

  if (current_treatment_statins == 1) {
    lp <- lp + params["tx_statins"]
  }

  risk_10_year <- 1 - exp(-params["base_haz"] * exp(lp))
  risk_percent <- risk_10_year * 100

  risk_category <- ""
  if (risk_percent < 5) {
    risk_category <- "Low Risk"
  } else if (risk_percent < 7.5) {
    risk_category <- "Borderline Risk"
  } else if (risk_percent < 20) {
    risk_category <- "Intermediate Risk"
  } else {
    risk_category <- "High Risk"
  }

  return(list(
    PREVENT_Risk_Score_10yr = paste0(round(risk_percent, 1), "%"),
    Risk_Category = risk_category,
    Inputs = list(
      Age = age,
      Sex = sex,
      Total_Chol = total_cholesterol,
      HDL_Chol = hdl_cholesterol,
      SBP = systolic_bp,
      Diabetes = diabetes == 1,
      Smoker = smoking == 1,
      eGFR = egfr,
      BMI = bmi,
      Tx_HTN = current_treatment_hypertension == 1,
      Tx_Statin = current_treatment_statins == 1
    )
  ))
}

nincds_adrda_criteria <- function(dementia_established, multiple_cognitive_deficits, progressive_worsening, no_consciousness_disturbance, onset_age_40_90, absence_of_other_disorders, histopathology_evidence = 0) {

  dementia_established <- as.numeric(dementia_established)
  multiple_cognitive_deficits <- as.numeric(multiple_cognitive_deficits)
  progressive_worsening <- as.numeric(progressive_worsening)
  no_consciousness_disturbance <- as.numeric(no_consciousness_disturbance)
  onset_age_40_90 <- as.numeric(onset_age_40_90)
  absence_of_other_disorders <- as.numeric(absence_of_other_disorders)
  histopathology_evidence <- as.numeric(histopathology_evidence)

  if (any(is.na(c(dementia_established, multiple_cognitive_deficits, progressive_worsening, no_consciousness_disturbance, onset_age_40_90, absence_of_other_disorders, histopathology_evidence)))) {
    stop("Error: All inputs must be numeric (0 or 1).")
  }

  is_probable <- (dementia_established == 1 &&
                    multiple_cognitive_deficits == 1 &&
                    progressive_worsening == 1 &&
                    no_consciousness_disturbance == 1 &&
                    onset_age_40_90 == 1 &&
                    absence_of_other_disorders == 1)

  is_possible_atypical <- (dementia_established == 1 &&
                             progressive_worsening == 1 &&
                             no_consciousness_disturbance == 1 &&
                             absence_of_other_disorders == 1 &&
                             (multiple_cognitive_deficits == 0 || onset_age_40_90 == 0))

  is_possible_comorbidity <- (dementia_established == 1 &&
                                multiple_cognitive_deficits == 1 &&
                                progressive_worsening == 1 &&
                                no_consciousness_disturbance == 1 &&
                                onset_age_40_90 == 1 &&
                                absence_of_other_disorders == 0)

  diagnosis <- ""

  if (is_probable) {
    if (histopathology_evidence == 1) {
      diagnosis <- "Definite Alzheimer's Disease"
    } else {
      diagnosis <- "Probable Alzheimer's Disease"
    }
  } else if (is_possible_atypical || is_possible_comorbidity) {
    diagnosis <- "Possible Alzheimer's Disease"
  } else {
    diagnosis <- "Unlikely Alzheimer's Disease (Criteria Not Met)"
  }

  return(list(
    Diagnosis = diagnosis,
    Inputs = list(
      Dementia_Established = dementia_established == 1,
      Multiple_Deficits = multiple_cognitive_deficits == 1,
      Progressive = progressive_worsening == 1,
      No_Consciousness_Disturbance = no_consciousness_disturbance == 1,
      Age_40_to_90 = onset_age_40_90 == 1,
      No_Other_Cause = absence_of_other_disorders == 1,
      Histopathology = histopathology_evidence == 1
    )
  ))
}

breast_cancer_brain_metastasis_gpa <- function(subtype_er_pr_status, subtype_her2_status, kps, age, extracranial_metastases, number_of_brain_metastases) {

  subtype_er_pr_status <- tolower(as.character(subtype_er_pr_status))
  subtype_her2_status <- tolower(as.character(subtype_her2_status))
  kps <- as.numeric(kps)
  age <- as.numeric(age)
  extracranial_metastases <- as.numeric(extracranial_metastases)
  number_of_brain_metastases <- as.numeric(number_of_brain_metastases)

  if (any(is.na(c(kps, age, extracranial_metastases, number_of_brain_metastases)))) {
    stop("Error: All numeric inputs must be valid.")
  }

  score <- 0

  if (subtype_er_pr_status == "negative" && subtype_her2_status == "negative") {
    score <- score + 0.0
  } else if (subtype_er_pr_status == "positive" && subtype_her2_status == "negative") {
    score <- score + 1.0
  } else if (subtype_er_pr_status == "negative" && subtype_her2_status == "positive") {
    score <- score + 1.5
  } else if (subtype_er_pr_status == "positive" && subtype_her2_status == "positive") {
    score <- score + 2.0
  } else {
    stop("Error: Subtype status must be 'positive' or 'negative'.")
  }

  if (kps < 70) {
    score <- score + 0.0
  } else if (kps >= 70 && kps <= 80) {
    score <- score + 0.5
  } else {
    score <- score + 1.0
  }

  if (age >= 60) {
    score <- score + 0.0
  } else {
    score <- score + 0.5
  }

  if (extracranial_metastases == 1) {
    score <- score + 0.0
  } else {
    score <- score + 0.5 # Absent
  }

  if (number_of_brain_metastases > 1) {
    score <- score + 0.0
  } else {
    score <- score + 0.5 # Single
  }

  est_median_survival <- ""
  if (score <= 1.0) {
    est_median_survival <- "3 - 6 months"
  } else if (score <= 2.0) {
    est_median_survival <- "9 - 13 months"
  } else if (score <= 3.0) {
    est_median_survival <- "17 - 24 months"
  } else {
    est_median_survival <- "25 - 36 months"
  }

  return(list(
    Breast_GPA_Score = score,
    Estimated_Median_Survival = est_median_survival,
    Inputs = list(
      Subtype = paste("ER/PR:", subtype_er_pr_status, "HER2:", subtype_her2_status),
      KPS = kps,
      Age = age,
      ECM_Present = extracranial_metastases == 1,
      Num_Mets = number_of_brain_metastases
    )
  ))
}

nivo_score <- function(emrcd_score, arterial_ph, consolidation_cxr, gcs_score, atrial_fibrillation) {

  emrcd_score <- tolower(as.character(emrcd_score))
  arterial_ph <- as.numeric(arterial_ph)
  consolidation_cxr <- as.numeric(consolidation_cxr)
  gcs_score <- as.numeric(gcs_score)
  atrial_fibrillation <- as.numeric(atrial_fibrillation)

  if (any(is.na(c(arterial_ph, consolidation_cxr, gcs_score, atrial_fibrillation)))) {
    stop("Error: All numeric/binary inputs must be valid.")
  }

  if (!emrcd_score %in% c("1_4", "5a", "5b")) {
    stop("Error: eMRCD score must be '1_4', '5a', or '5b'.")
  }

  score <- 0

  if (emrcd_score == "5a") {
    score <- score + 2
  } else if (emrcd_score == "5b") {
    score <- score + 4
  }

  if (arterial_ph < 7.25) {
    score <- score + 2
  }

  if (consolidation_cxr == 1) {
    score <- score + 2
  }

  if (gcs_score < 15) {
    score <- score + 2
  }

  if (atrial_fibrillation == 1) {
    score <- score + 1
  }

  mortality_risk <- ""
  risk_category <- ""

  if (score <= 2) {
    risk_category <- "Low Risk"
    mortality_risk <- "3%"
  } else if (score <= 4) {
    risk_category <- "Moderate Risk"
    mortality_risk <- "13%"
  } else if (score <= 6) {
    risk_category <- "High Risk"
    mortality_risk <- "30%"
  } else if (score <= 9) {
    risk_category <- "Very High Risk"
    mortality_risk <- "52%"
  } else {
    risk_category <- "Highest Risk"
    mortality_risk <- "86%"
  }

  return(list(
    NIVO_Score = score,
    Risk_Category = risk_category,
    In_Hospital_Mortality = mortality_risk,
    Inputs = list(
      eMRCD = emrcd_score,
      pH_lt_7_25 = arterial_ph < 7.25,
      Consolidation = consolidation_cxr == 1,
      GCS_lt_15 = gcs_score < 15,
      AFib = atrial_fibrillation == 1
    )
  ))
}

nvps_pain_score <- function(face, activity, guarding, physiology_vital_signs, respiratory) {

  face <- as.numeric(face)
  activity <- as.numeric(activity)
  guarding <- as.numeric(guarding)
  physiology_vital_signs <- as.numeric(physiology_vital_signs)
  respiratory <- as.numeric(respiratory)

  if (any(is.na(c(face, activity, guarding, physiology_vital_signs, respiratory)))) {
    stop("Error: All inputs must be numeric.")
  }

  if (any(c(face, activity, guarding, physiology_vital_signs, respiratory) < 0) ||
      any(c(face, activity, guarding, physiology_vital_signs, respiratory) > 2)) {
    stop("Error: All item scores must be integers between 0 and 2.")
  }

  total_score <- face + activity + guarding + physiology_vital_signs + respiratory

  interpretation <- ""
  if (total_score <= 2) {
    interpretation <- "No Pain to Mild Pain"
  } else if (total_score <= 6) {
    interpretation <- "Moderate Pain"
  } else {
    interpretation <- "Severe Pain"
  }

  return(list(
    NVPS_Score = total_score,
    Interpretation = interpretation,
    Inputs = list(
      Face = face,
      Activity = activity,
      Guarding = guarding,
      Physiology = physiology_vital_signs,
      Respiratory = respiratory
    )
  ))
}

nafcs_score <- function(fasting_tg_mg_dl, history_pancreatitis, unexplained_abdominal_pain, secondary_factors_present, age_onset_lt_40, poor_response_treatment, tg_units = "mg/dL") {

  fasting_tg <- as.numeric(fasting_tg_mg_dl)
  history_pancreatitis <- as.numeric(history_pancreatitis)
  unexplained_abdominal_pain <- as.numeric(unexplained_abdominal_pain)
  secondary_factors_present <- as.numeric(secondary_factors_present)
  age_onset_lt_40 <- as.numeric(age_onset_lt_40)
  poor_response_treatment <- as.numeric(poor_response_treatment)

  if (any(is.na(c(fasting_tg, history_pancreatitis, unexplained_abdominal_pain, secondary_factors_present, age_onset_lt_40, poor_response_treatment)))) {
    stop("Error: All inputs must be numeric.")
  }

  tg_val <- fasting_tg
  if (tg_units == "mmol/L") {
    tg_val <- fasting_tg * 88.57
  }

  score <- 0

  if (tg_val > 1770) {
    score <- score + 3
  } else if (tg_val >= 885) {
    score <- score + 1
  }

  if (history_pancreatitis == 1) {
    score <- score + 1
  }

  if (unexplained_abdominal_pain == 1) {
    score <- score + 1
  }

  if (secondary_factors_present == 0) {
    score <- score + 2
  }

  if (age_onset_lt_40 == 1) {
    score <- score + 1
  }

  if (poor_response_treatment == 1) {
    score <- score + 1
  }

  interpretation <- ""
  if (score <= 8) {
    interpretation <- "Unlikely Familial Chylomicronemia Syndrome (FCS)"
  } else {
    interpretation <- "Very Likely Familial Chylomicronemia Syndrome (FCS)"
  }

  return(list(
    NAFCS_Score = score,
    Interpretation = interpretation,
    Inputs = list(
      TG_Level = round(tg_val, 1),
      Pancreatitis = history_pancreatitis == 1,
      Abdominal_Pain = unexplained_abdominal_pain == 1,
      No_Secondary_Factors = secondary_factors_present == 0,
      Early_Onset = age_onset_lt_40 == 1,
      Poor_Response = poor_response_treatment == 1
    )
  ))
}

novel_pneumonia_risk_score <- function(age, sex, heart_failure, copd, epilepsy, parkinsons, previous_pneumonia, current_ppi_use, current_opioid_use) {

  age <- as.numeric(age)
  sex <- tolower(as.character(sex))
  heart_failure <- as.numeric(heart_failure)
  copd <- as.numeric(copd)
  epilepsy <- as.numeric(epilepsy)
  parkinsons <- as.numeric(parkinsons)
  previous_pneumonia <- as.numeric(previous_pneumonia)
  current_ppi_use <- as.numeric(current_ppi_use)
  current_opioid_use <- as.numeric(current_opioid_use)

  if (any(is.na(c(age, heart_failure, copd, epilepsy, parkinsons, previous_pneumonia, current_ppi_use, current_opioid_use)))) {
    stop("Error: All numeric/binary inputs must be valid.")
  }

  if (!sex %in% c("male", "female")) {
    stop("Error: Sex must be 'male' or 'female'.")
  }

  score <- age / 10

  if (sex == "male") {
    score <- score + 1
  }

  if (heart_failure == 1) {
    score <- score + 1
  }

  if (copd == 1) {
    score <- score + 1
  }

  if (epilepsy == 1) {
    score <- score + 1
  }

  if (parkinsons == 1) {
    score <- score + 1
  }

  if (previous_pneumonia == 1) {
    score <- score + 3
  }

  if (current_ppi_use == 1) {
    score <- score + 2
  }

  if (current_opioid_use == 1) {
    score <- score + 2
  }

  risk_category <- ""

  if (score < 10) {
    risk_category <- "Low Risk"
  } else if (score <= 15) {
    risk_category <- "Medium Risk"
  } else {
    risk_category <- "High Risk"
  }

  return(list(
    PRS_Score = round(score, 1),
    Risk_Category = risk_category,
    Inputs = list(
      Age = age,
      Sex = sex,
      Heart_Failure = heart_failure == 1,
      COPD = copd == 1,
      Epilepsy = epilepsy == 1,
      Parkinsons = parkinsons == 1,
      Prev_Pneumonia = previous_pneumonia == 1,
      PPI_Use = current_ppi_use == 1,
      Opioid_Use = current_opioid_use == 1
    )
  ))
}

nirudak_score <- function(crt_seconds, tachycardia_present, lethargy_coma, dry_mucous_membranes, cold_mottled_extremities, sunken_eyes) {

  crt_seconds <- as.numeric(crt_seconds)
  tachycardia_present <- as.numeric(tachycardia_present)
  lethargy_coma <- as.numeric(lethargy_coma)
  dry_mucous_membranes <- as.numeric(dry_mucous_membranes)
  cold_mottled_extremities <- as.numeric(cold_mottled_extremities)
  sunken_eyes <- as.numeric(sunken_eyes)

  if (any(is.na(c(crt_seconds, tachycardia_present, lethargy_coma, dry_mucous_membranes, cold_mottled_extremities, sunken_eyes)))) {
    stop("Error: All inputs must be numeric.")
  }

  score <- 0

  if (crt_seconds >= 3) {
    score <- score + 2
  }

  if (tachycardia_present == 1) {
    score <- score + 2
  }

  if (lethargy_coma == 1) {
    score <- score + 2
  }

  if (dry_mucous_membranes == 1) {
    score <- score + 1
  }

  if (cold_mottled_extremities == 1) {
    score <- score + 2
  }

  if (sunken_eyes == 1) {
    score <- score + 1
  }

  risk_level <- ""

  if (score < 3) {
    risk_level <- "Low Risk"
  } else if (score >= 3 && score <= 5) {
    risk_level <- "Moderate Risk"
  } else {
    risk_level <- "High Risk"
  }

  return(list(
    NIRUDAK_Score = score,
    Risk_Level = risk_level,
    Inputs = list(
      CRT_ge_3s = crt_seconds >= 3,
      Tachycardia = tachycardia_present == 1,
      Lethargy_Coma = lethargy_coma == 1,
      Dry_Mouth = dry_mucous_membranes == 1,
      Cold_Mottled = cold_mottled_extremities == 1,
      Sunken_Eyes = sunken_eyes == 1
    )
  ))
}

nutric_score <- function(age, bmi, sofa_score, comorbidities_count, days_on_icu_ge_2, il6_level_pg_ml = NA) {

  age <- as.numeric(age)
  bmi <- as.numeric(bmi)
  sofa_score <- as.numeric(sofa_score)
  comorbidities_count <- as.numeric(comorbidities_count)
  days_on_icu_ge_2 <- as.numeric(days_on_icu_ge_2)

  if (any(is.na(c(age, bmi, sofa_score, comorbidities_count, days_on_icu_ge_2)))) {
    stop("Error: All inputs must be numeric.")
  }

  score <- 0

  if (age >= 75) {
    score <- score + 1
  } else if (age >= 50 && age <= 74) {
    score <- score + 1
  }

  if (bmi < 20 || bmi >= 35) {
    score <- score + 1
  }

  if (sofa_score >= 10) {
    score <- score + 1
  } else if (sofa_score >= 5) {
    score <- score + 1
  }

  if (comorbidities_count >= 2) {
    score <- score + 1
  }

  if (days_on_icu_ge_2 == 1) {
    score <- score + 1
  }

  nutric_score_final <- min(score, 5)

  if (!is.na(il6_level_pg_ml)) {
    il6_level_pg_ml <- as.numeric(il6_level_pg_ml)
    if (il6_level_pg_ml >= 1000) {
      nutric_score_final <- min(score, 4) + 1
    }
  }

  risk_level <- ""
  recommendation <- ""

  if (nutric_score_final <= 4) {
    risk_level <- "Low Risk"
    recommendation <- "Patients are at low risk for adverse outcomes from under-nutrition. Standard nutrition support may be sufficient."
  } else {
    risk_level <- "High Risk"
    recommendation <- "Patients are at high risk for adverse outcomes from under-nutrition. Consider early and aggressive nutrition support (e.g., parenteral nutrition or specialized enteral formula)."
  }

  return(list(
    NUTRIC_Score = score,
    Risk_Classification = risk_level,
    Nutrition_Recommendation = recommendation,
    Inputs = list(
      Age = age,
      BMI = bmi,
      SOFA = sofa_score,
      Comorbidities = comorbidities_count,
      ICU_Days_ge_2 = days_on_icu_ge_2 == 1,
      IL6 = il6_level_pg_ml
    )
  ))
}

years_pe_algorithm <- function(clinical_signs_dvt, hemoptysis, pe_most_likely, d_dimer_level, d_dimer_units = "ng/mL") {

  clinical_signs_dvt <- as.numeric(clinical_signs_dvt)
  hemoptysis <- as.numeric(hemoptysis)
  pe_most_likely <- as.numeric(pe_most_likely)
  d_dimer_level <- as.numeric(d_dimer_level)

  if (any(is.na(c(clinical_signs_dvt, hemoptysis, pe_most_likely, d_dimer_level)))) {
    stop("Error: All inputs must be numeric.")
  }

  d_dimer_ng_ml <- d_dimer_level
  if (d_dimer_units == "ug/mL" || d_dimer_units == "mg/L") {
    d_dimer_ng_ml <- d_dimer_level * 1000
  }

  years_count <- clinical_signs_dvt + hemoptysis + pe_most_likely

  threshold <- 0
  if (years_count == 0) {
    threshold <- 1000
  } else {
    threshold <- 500
  }

  result <- ""
  if (d_dimer_ng_ml < threshold) {
    result <- "PE Ruled Out"
  } else {
    result <- "CTPA Indicated"
  }

  return(list(
    Result = result,
    YEARS_Items_Met = years_count,
    D_Dimer_Threshold_Used = threshold,
    Inputs = list(
      Signs_DVT = clinical_signs_dvt == 1,
      Hemoptysis = hemoptysis == 1,
      PE_Most_Likely = pe_most_likely == 1,
      D_Dimer = d_dimer_level
    )
  ))
}

tash_score_trauma <- function(systolic_bp, hemoglobin, fast_positive, complex_fractures, heart_rate, base_excess, sex) {

  systolic_bp <- as.numeric(systolic_bp)
  hemoglobin <- as.numeric(hemoglobin)
  fast_positive <- as.numeric(fast_positive)
  complex_fractures <- as.numeric(complex_fractures)
  heart_rate <- as.numeric(heart_rate)
  base_excess <- as.numeric(base_excess)
  sex <- tolower(as.character(sex))

  if (any(is.na(c(systolic_bp, hemoglobin, fast_positive, complex_fractures, heart_rate, base_excess)))) {
    stop("Error: All inputs must be numeric.")
  }

  if (!sex %in% c("male", "female")) {
    stop("Error: Sex must be 'male' or 'female'.")
  }

  score <- 0

  if (systolic_bp < 100) {
    score <- score + 4
  } else if (systolic_bp <= 120) {
    score <- score + 1
  } else {
    score <- score + 0
  }

  if (hemoglobin < 7) {
    score <- score + 6
  } else if (hemoglobin < 9) {
    score <- score + 4
  } else if (hemoglobin < 11) {
    score <- score + 3
  } else if (hemoglobin < 12) {
    score <- score + 2
  } else {
    score <- score + 0
  }

  if (fast_positive == 1) {
    score <- score + 3
  }

  if (complex_fractures == 1) {
    score <- score + 3
  }

  if (heart_rate > 120) {
    score <- score + 2
  }

  if (base_excess < -10) {
    score <- score + 4
  } else if (base_excess < -6) {
    score <- score + 3
  } else if (base_excess < -2) {
    score <- score + 1
  } else {
    score <- score + 0
  }

  if (sex == "male") {
    score <- score + 1
  }

  probability <- ""
  if (score < 9) {
    probability <- "< 5%"
  } else if (score == 9) {
    probability <- "8.4%"
  } else if (score == 10) {
    probability <- "13.2%"
  } else if (score == 11) {
    probability <- "19.2%"
  } else if (score == 12) {
    probability <- "27.0%"
  } else if (score == 13) {
    probability <- "36.4%"
  } else if (score == 14) {
    probability <- "46.9%"
  } else if (score == 15) {
    probability <- "57.6%"
  } else if (score == 16) {
    probability <- "67.7%"
  } else if (score == 17) {
    probability <- "76.5%"
  } else if (score == 18) {
    probability <- "83.6%"
  } else {
    probability <- "> 84%"
  }

  return(list(
    TASH_Score = score,
    Probability_Massive_Transfusion = probability,
    Inputs = list(
      SBP = systolic_bp,
      Hemoglobin = hemoglobin,
      FAST_Positive = fast_positive == 1,
      Fractures = complex_fractures == 1,
      HR = heart_rate,
      Base_Excess = base_excess,
      Sex = sex
    )
  ))
}

tenecteplase_dosing <- function(weight_kg, indication = "stemi") {

  weight_kg <- as.numeric(weight_kg)
  indication <- tolower(as.character(indication))

  if (is.na(weight_kg)) {
    stop("Error: Weight must be numeric.")
  }

  if (weight_kg <= 0) {
    stop("Error: Weight must be positive.")
  }

  dose_mg <- 0

  if (indication == "stemi") {
    if (weight_kg < 60) {
      dose_mg <- 30
    } else if (weight_kg >= 60 && weight_kg < 70) {
      dose_mg <- 35
    } else if (weight_kg >= 70 && weight_kg < 80) {
      dose_mg <- 40
    } else if (weight_kg >= 80 && weight_kg < 90) {
      dose_mg <- 45
    } else {
      dose_mg <- 50
    }
  } else if (indication == "stroke") {
    dose_mg <- 0.25 * weight_kg
    if (dose_mg > 25) {
      dose_mg <- 25
    }
  } else {
    stop("Error: Indication must be 'stemi' or 'stroke'.")
  }

  volume_ml <- dose_mg / 5

  return(list(
    Recommended_Dose_mg = dose_mg,
    Volume_to_Administer_mL = volume_ml,
    Inputs = list(
      Weight_kg = weight_kg,
      Indication = indication
    )
  ))
}

twist_score <- function(testicular_swelling, hard_testicle, absent_cremasteric_reflex, nausea_vomiting, high_riding_testicle) {

  testicular_swelling <- as.numeric(testicular_swelling)
