  high_riding_testicle <- as.numeric(high_riding_testicle)

  if (any(is.na(c(testicular_swelling, hard_testicle, absent_cremasteric_reflex, nausea_vomiting, high_riding_testicle)))) {
    stop("Error: All inputs must be numeric (0 or 1).")
  }

  score <- 0

  if (testicular_swelling == 1) {
    score <- score + 2
  }

  if (hard_testicle == 1) {
    score <- score + 2
  }

  if (absent_cremasteric_reflex == 1) {
    score <- score + 1
  }

  if (nausea_vomiting == 1) {
    score <- score + 1
  }

  if (high_riding_testicle == 1) {
    score <- score + 1
  }

  risk_category <- ""
  recommendation <- ""

  if (score <= 2) {
