}

crafft_screening_tool <- function(drink_alcohol, smoke_marijuana, use_other_drugs, car_driven_by_high, relax_use, alone_use, forget_things, friends_family_advice, trouble_while_using) {

  drink_alcohol <- as.numeric(drink_alcohol)
  smoke_marijuana <- as.numeric(smoke_marijuana)
  use_other_drugs <- as.numeric(use_other_drugs)
  car_driven_by_high <- as.numeric(car_driven_by_high)
  relax_use <- as.numeric(relax_use)
  alone_use <- as.numeric(alone_use)
  forget_things <- as.numeric(forget_things)
  friends_family_advice <- as.numeric(friends_family_advice)
  trouble_while_using <- as.numeric(trouble_while_using)

  if (any(is.na(c(drink_alcohol, smoke_marijuana, use_other_drugs, car_driven_by_high, relax_use, alone_use, forget_things, friends_family_advice, trouble_while_using)))) {
    stop("Error: All inputs must be numeric (0 or 1).")
  }

  part_a_positive <- (drink_alcohol == 1 || smoke_marijuana == 1 || use_other_drugs == 1)

  score <- 0

  if (part_a_positive) {
    score <- car_driven_by_high + relax_use + alone_use + forget_things + friends_family_advice + trouble_while_using
  } else {
    score <- car_driven_by_high
  }

  result <- ""
  recommendation <- ""

  if (score >= 2) {
    result <- "Positive Screen (High Risk)"
    recommendation <- "Need for further assessment (e.g., brief intervention, referral)."
  } else if (score == 1) {
    result <- "Negative Screen (Medium Risk)"
    recommendation <- "Brief advice recommended, particularly regarding driving safety if 'Car' question was positive."
  } else {
    result <- "Negative Screen (Low Risk)"
    recommendation <- "Praise and encouragement."
  }

  return(list(
    CRAFFT_Score = score,
    Screening_Result = result,
    Recommendation = recommendation,
    Inputs = list(
      Part_A_Substance_Use = part_a_positive,
      Car = car_driven_by_high == 1,
      Relax = relax_use == 1,
      Alone = alone_use == 1,
      Forget = forget_things == 1,
      Friends = friends_family_advice == 1,
      Trouble = trouble_while_using == 1
    )
  ))
}

flacc_pain_score <- function(face, legs, activity, cry, consolability) {

  inputs <- c(face, legs, activity, cry, consolability)

  if (any(is.na(inputs))) {
    stop("Error: All 5 inputs must be numeric.")
  }

  if (any(inputs < 0) || any(inputs > 2)) {
    stop("Error: All item scores must be integers between 0 and 2.")
  }

  total_score <- sum(inputs)

  severity <- ""
  if (total_score == 0) {
    severity <- "Relaxed and comfortable"
  } else if (total_score <= 3) {
    severity <- "Mild discomfort"
  } else if (total_score <= 6) {
    severity <- "Moderate pain"
  } else {
    severity <- "Severe discomfort or pain"
  }

  return(list(
    FLACC_Score = total_score,
    Interpretation = severity,
    Inputs = list(
      Face = face,
      Legs = legs,
      Activity = activity,
      Cry = cry,
      Consolability = consolability
    )
  ))
}

