therapeutic_plasmapheresis <- function(weight_kg, hematocrit_percent, exchange_volume_pv = 1.0) {

  weight_kg <- as.numeric(weight_kg)
  hematocrit_percent <- as.numeric(hematocrit_percent)
  exchange_volume_pv <- as.numeric(exchange_volume_pv)

  if (any(is.na(c(weight_kg, hematocrit_percent, exchange_volume_pv)))) {
    stop("Error: All inputs must be numeric.")
  }

  if (weight_kg <= 0) stop("Error: Weight must be positive.")
  if (hematocrit_percent < 0 || hematocrit_percent >= 100) stop("Error: Hematocrit must be between 0 and 100.")

  tbv_ml <- weight_kg * 70

  epv_ml <- tbv_ml * (1 - (hematocrit_percent / 100))

  volume_to_exchange_ml <- epv_ml * exchange_volume_pv

  return(list(
    Total_Blood_Volume_mL = round(tbv_ml, 0),
    Estimated_Plasma_Volume_mL = round(epv_ml, 0),
    Volume_to_Exchange_mL = round(volume_to_exchange_ml, 0),
    Inputs = list(
      Weight_kg = weight_kg,
      Hematocrit = hematocrit_percent,
      Target_PV = exchange_volume_pv
    )
  ))
}

tdn_neurology_grade <- function(therapy_level, disability_mrs, new_neurologic_deficit) {

  therapy_level <- tolower(as.character(therapy_level))
  disability_mrs <- as.numeric(disability_mrs)
  new_neurologic_deficit <- as.numeric(new_neurologic_deficit)

  if (any(is.na(c(disability_mrs, new_neurologic_deficit)))) {
    stop("Error: Numeric inputs (mRS, Neuro Deficit) must be valid.")
  }

  t_score <- 0
  if (therapy_level == "none_bedside") {
    t_score <- 1
  } else if (therapy_level == "pharmacologic") {
    t_score <- 2
  } else if (therapy_level == "invasive") {
    t_score <- 3
  } else if (therapy_level == "icu_life_threatening") {
    t_score <- 4
  } else if (therapy_level == "death") {
    t_score <- 5
  } else {
    stop("Error: Therapy level must be 'none_bedside', 'pharmacologic', 'invasive', 'icu_life_threatening', or 'death'.")
  }

  d_score <- 0
  if (disability_mrs >= 0 && disability_mrs <= 1) {
    d_score <- 1
  } else if (disability_mrs >= 2 && disability_mrs <= 3) {
    d_score <- 2
  } else if (disability_mrs == 4) {
    d_score <- 3
  } else if (disability_mrs == 5) {
    d_score <- 4
  } else if (disability_mrs == 6) {
    d_score <- 5
  } else {
    stop("Error: Modified Rankin Scale (mRS) must be between 0 and 6.")
  }

  n_score <- if (new_neurologic_deficit == 1) 2 else 1


  tdn_grade <- max(t_score, d_score, n_score)

  definition <- ""
  if (tdn_grade == 1) {
    definition <- "Minor AE: No specific treatment (or allowed bedside meds), no impact on daily living, no new neuro deficit."
  } else if (tdn_grade == 2) {
    definition <- "Moderate AE: Pharmacologic treatment (inc. transfusion/TPN), OR hinders >=1 ADL (mRS 2-3), OR new neuro deficit."
  } else if (tdn_grade == 3) {
    definition <- "Severe AE: Invasive intervention (surgical/endoscopic/radiologic), OR hinders walking/bodily needs (mRS 4)."
  } else if (tdn_grade == 4) {
    definition <- "Life-Threatening AE: ICU management required, OR bedridden/constant help/incontinent (mRS 5)."
  } else {
    definition <- "Death: Grade 5."
  }

  return(list(
    TDN_Grade = tdn_grade,
    Definition = definition,
    Inputs = list(
      Therapy_Score = paste0("T", t_score),
      Disability_Score = paste0("D", d_score),
      Neurology_Score = paste0("N", n_score)
    )
  ))
}

tlics_score <- function(injury_morphology, neurological_status, plc_integrity) {

  injury_morphology <- tolower(as.character(injury_morphology))
  neurological_status <- tolower(as.character(neurological_status))
  plc_integrity <- tolower(as.character(plc_integrity))

  score <- 0

  if (injury_morphology == "compression") {
    score <- score + 1
  } else if (injury_morphology == "burst") {
    score <- score + 2
  } else if (injury_morphology == "translation_rotation") {
    score <- score + 3
  } else if (injury_morphology == "distraction") {
    score <- score + 4
  } else {
    stop("Error: Morphology must be 'compression', 'burst', 'translation_rotation', or 'distraction'.")
  }

  if (neurological_status == "intact") {
    score <- score + 0
  } else if (neurological_status == "root") {
    score <- score + 2
  } else if (neurological_status == "complete") {
    score <- score + 2
  } else if (neurological_status == "incomplete") {
    score <- score + 3
  } else if (neurological_status == "cauda_equina") {
    score <- score + 3
  } else {
    stop("Error: Neurological status must be 'intact', 'root', 'complete', 'incomplete', or 'cauda_equina'.")
  }

  if (plc_integrity == "intact") {
    score <- score + 0
  } else if (plc_integrity == "suspected") {
    score <- score + 2
  } else if (plc_integrity == "injured") {
    score <- score + 3
  } else {
    stop("Error: PLC status must be 'intact', 'suspected', or 'injured'.")
  }

  recommendation <- ""
  if (score <= 3) {
    recommendation <- "Non-Operative Management"
  } else if (score == 4) {
    recommendation <- "Indeterminate (Surgeon discretion)"
  } else {
    recommendation <- "Operative Management"
  }

  return(list(
    TLICS_Score = score,
    Recommendation = recommendation,
    Inputs = list(
      Morphology = injury_morphology,
      Neurology = neurological_status,
      PLC = plc_integrity
    )
  ))
}

thrive_stroke_score <- function(nihss_score, age, history_hypertension, history_diabetes, history_atrial_fibrillation) {

  nihss_score <- as.numeric(nihss_score)
  age <- as.numeric(age)
  history_hypertension <- as.numeric(history_hypertension)
  history_diabetes <- as.numeric(history_diabetes)
  history_atrial_fibrillation <- as.numeric(history_atrial_fibrillation)

  if (any(is.na(c(nihss_score, age, history_hypertension, history_diabetes, history_atrial_fibrillation)))) {
    stop("Error: All inputs must be numeric.")
  }

  score <- 0

  if (nihss_score <= 5) {
    score <- score + 0
  } else if (nihss_score >= 6 && nihss_score <= 10) {
    score <- score + 2
  } else if (nihss_score >= 11 && nihss_score <= 20) {
    score <- score + 4
  } else {
    score <- score + 7
  }

  if (age < 60) {
    score <- score + 0
  } else if (age >= 60 && age <= 79) {
    score <- score + 1
  } else {
    score <- score + 2
  }

  if (history_hypertension == 1 || history_diabetes == 1 || history_atrial_fibrillation == 1) {
    score <- score + 1
  }

  good_outcome_prob <- ""
  mortality_risk <- ""

  if (score == 0) {
    good_outcome_prob <- "88%"
    mortality_risk <- "2%"
  } else if (score == 1) {
    good_outcome_prob <- "79%"
    mortality_risk <- "5%"
  } else if (score == 2) {
    good_outcome_prob <- "69%"
    mortality_risk <- "8%"
  } else if (score == 3) {
    good_outcome_prob <- "58%"
    mortality_risk <- "14%"
  } else if (score == 4) {
    good_outcome_prob <- "46%"
    mortality_risk <- "22%"
  } else if (score == 5) {
    good_outcome_prob <- "34%"
    mortality_risk <- "33%"
  } else if (score == 6) {
    good_outcome_prob <- "24%"
    mortality_risk <- "45%"
  } else if (score == 7) {
    good_outcome_prob <- "15%"
    mortality_risk <- "58%"
  } else if (score == 8) {
    good_outcome_prob <- "9%"
    mortality_risk <- "70%"
  } else {
    good_outcome_prob <- "6%"
    mortality_risk <- "80%"
  }

  return(list(
    THRIVE_Score = score,
    Good_Outcome_Probability_90d = good_outcome_prob,
    Mortality_Risk_90d = mortality_risk,
    Inputs = list(
      NIHSS = nihss_score,
      Age = age,
      Chronic_Disease = (history_hypertension == 1 || history_diabetes == 1 || history_atrial_fibrillation == 1)
    )
  ))
}

trip_cast_score <- function(age, sex, bmi, oral_contraceptive, vte_history, cancer_history, cast_below_knee, mobility, surgery) {

  age <- as.numeric(age)
  sex <- tolower(as.character(sex))
  bmi <- as.numeric(bmi)
  oral_contraceptive <- as.numeric(oral_contraceptive)
  vte_history <- as.numeric(vte_history)
  cancer_history <- as.numeric(cancer_history)
  cast_below_knee <- as.numeric(cast_below_knee)
  mobility <- as.numeric(mobility)
  surgery <- as.numeric(surgery)

  if (any(is.na(c(age, bmi, oral_contraceptive, vte_history, cancer_history, cast_below_knee, mobility, surgery)))) {
    stop("Error: All inputs must be numeric.")
  }

  if (!sex %in% c("male", "female")) {
    stop("Error: Sex must be 'male' or 'female'.")
  }

  score <- 0

  if (age >= 35 && age <= 55) {
    score <- score + 2
  } else if (age > 55) {
    score <- score + 3
  }

  if (sex == "male") {
    score <- score + 1
  }

  if (bmi >= 25 && bmi <= 30) {
    score <- score + 1
  } else if (bmi > 30) {
    score <- score + 2
  }

  if (oral_contraceptive == 1) {
    score <- score + 4
  }

  if (vte_history == 1) {
    score <- score + 5
  }

  if (cancer_history == 1) {
    score <- score + 3
  }

  if (cast_below_knee == 0) {
    score <- score + 1
  }

  if (mobility == 1) {
    score <- score + 2
  }

  if (surgery == 1) {
    score <- score + 3
  }

  risk_category <- ""
  vte_risk <- ""

  if (score < 7) {
    risk_category <- "Low Risk"
    vte_risk <- "0 - 0.3%"
  } else if (score < 12) {
    risk_category <- "Moderate Risk"
    vte_risk <- "0.6 - 1.5%"
  } else {
    risk_category <- "High Risk"
    vte_risk <- "2.5 - 10.2%"
  }

  return(list(
    TRIP_Cast_Score = score,
    Risk_Category = risk_category,
    Estimated_VTE_Risk = vte_risk,
    Inputs = list(
      Age = age,
      Sex = sex,
      BMI = bmi,
      OCP = oral_contraceptive == 1,
      Hx_VTE = vte_history == 1,
      Hx_Cancer = cancer_history == 1,
      Cast_Below_Knee = cast_below_knee == 1,
      Reduced_Mobility = mobility == 1,
      Surgery = surgery == 1
    )
  ))
}

timi_risk_index <- function(heart_rate, systolic_bp, age) {

  heart_rate <- as.numeric(heart_rate)
  systolic_bp <- as.numeric(systolic_bp)
  age <- as.numeric(age)

  if (any(is.na(c(heart_rate, systolic_bp, age)))) {
    stop("Error: All inputs must be numeric.")
  }

  if (systolic_bp == 0) {
    stop("Error: Systolic BP cannot be zero.")
  }

  tri_score <- (heart_rate * (age / 10)^2) / systolic_bp

  risk_group <- ""
  mortality_30d <- ""

  if (tri_score < 12.5) {
    risk_group <- "Group I"
    mortality_30d <- "0.8%"
  } else if (tri_score >= 12.5 && tri_score < 17.5) {
    risk_group <- "Group II"
    mortality_30d <- "1.9%"
  } else if (tri_score >= 17.5 && tri_score < 22.5) {
    risk_group <- "Group III"
    mortality_30d <- "3.3%"
  } else if (tri_score >= 22.5 && tri_score <= 30) {
    risk_group <- "Group IV"
    mortality_30d <- "7.3%"
  } else {
    risk_group <- "Group V"
    mortality_30d <- "17.4%"
  }

  return(list(
    TIMI_Risk_Index = round(tri_score, 1),
    Risk_Group = risk_group,
    Est_30_Day_Mortality = mortality_30d,
    Inputs = list(
      HR = heart_rate,
      SBP = systolic_bp,
      Age = age
    )
  ))
}

timi_stemi_score <- function(age, history_diabetes_htn_angina, systolic_bp, heart_rate, killip_class_2_to_4, weight_kg, anterior_ste_or_lbbb, time_to_treatment_gt_4h) {

  age <- as.numeric(age)
  history_diabetes_htn_angina <- as.numeric(history_diabetes_htn_angina)
  systolic_bp <- as.numeric(systolic_bp)
  heart_rate <- as.numeric(heart_rate)
  killip_class_2_to_4 <- as.numeric(killip_class_2_to_4)
  weight_kg <- as.numeric(weight_kg)
  anterior_ste_or_lbbb <- as.numeric(anterior_ste_or_lbbb)
  time_to_treatment_gt_4h <- as.numeric(time_to_treatment_gt_4h)

  if (any(is.na(c(age, history_diabetes_htn_angina, systolic_bp, heart_rate, killip_class_2_to_4, weight_kg, anterior_ste_or_lbbb, time_to_treatment_gt_4h)))) {
    stop("Error: All inputs must be numeric.")
  }

  score <- 0

  if (age >= 75) {
    score <- score + 3
  } else if (age >= 65) {
    score <- score + 2
  }

  if (history_diabetes_htn_angina == 1) {
    score <- score + 1
  }

  if (systolic_bp < 100) {
    score <- score + 3
  }

  if (heart_rate > 100) {
    score <- score + 2
  }

  if (killip_class_2_to_4 == 1) {
    score <- score + 2
  }

  if (weight_kg < 67) {
    score <- score + 1
  }

  if (anterior_ste_or_lbbb == 1) {
    score <- score + 1
  }

  if (time_to_treatment_gt_4h == 1) {
    score <- score + 1
  }

  mortality_30_day <- ""

  if (score == 0) {
    mortality_30_day <- "0.8%"
  } else if (score == 1) {
    mortality_30_day <- "1.6%"
  } else if (score == 2) {
    mortality_30_day <- "2.2%"
  } else if (score == 3) {
    mortality_30_day <- "4.4%"
  } else if (score == 4) {
    mortality_30_day <- "7.3%"
  } else if (score == 5) {
    mortality_30_day <- "12.4%"
  } else if (score == 6) {
    mortality_30_day <- "16.1%"
  } else if (score == 7) {
    mortality_30_day <- "23.4%"
  } else if (score == 8) {
    mortality_30_day <- "26.8%"
  } else {
    mortality_30_day <- "35.9%"
  }

  return(list(
    TIMI_Score = score,
    Est_30_Day_Mortality = mortality_30_day,
    Inputs = list(
      Age = age,
      Hx_Risk_Factors = history_diabetes_htn_angina == 1,
      SBP = systolic_bp,
      HR = heart_rate,
      Killip_II_IV = killip_class_2_to_4 == 1,
      Weight = weight_kg,
      Anterior_STE_LBBB = anterior_ste_or_lbbb == 1,
      Time_gt_4h = time_to_treatment_gt_4h == 1
    )
  ))
}

