tisdale_qt_score <- function(age, sex, loop_diuretic, serum_potassium, serum_q_t_c, acute_mi, sepsis, heart_failure, one_qtc_drug, two_or_more_qtc_drugs) {

  age <- as.numeric(age)
  sex <- tolower(as.character(sex))
  loop_diuretic <- as.numeric(loop_diuretic)
  serum_potassium <- as.numeric(serum_potassium)
  serum_q_t_c <- as.numeric(serum_q_t_c)
  acute_mi <- as.numeric(acute_mi)
  sepsis <- as.numeric(sepsis)
  heart_failure <- as.numeric(heart_failure)
  one_qtc_drug <- as.numeric(one_qtc_drug)
  two_or_more_qtc_drugs <- as.numeric(two_or_more_qtc_drugs)

  if (any(is.na(c(age, loop_diuretic, serum_potassium, serum_q_t_c, acute_mi, sepsis, heart_failure, one_qtc_drug, two_or_more_qtc_drugs)))) {
    stop("Error: All inputs must be numeric.")
  }

  if (!sex %in% c("male", "female")) {
    stop("Error: Sex must be 'male' or 'female'.")
  }

  score <- 0

  if (age >= 68) {
    score <- score + 1
  }

  if (sex == "female") {
    score <- score + 1
  }

  if (loop_diuretic == 1) {
    score <- score + 1
  }

  if (serum_potassium <= 3.5) {
    score <- score + 2
  }

  if (serum_q_t_c >= 450) {
    score <- score + 2
  }

  if (acute_mi == 1) {
    score <- score + 2
  }

  if (sepsis == 1) {
    score <- score + 3
  }

  if (heart_failure == 1) {
    score <- score + 3
  }

  if (one_qtc_drug == 1) {
    score <- score + 3
  }

  if (two_or_more_qtc_drugs == 1) {
    score <- score + 3
  }

  risk_level <- ""
  if (score <= 6) {
    risk_level <- "Low Risk"
  } else if (score <= 10) {
    risk_level <- "Moderate Risk"
  } else {
    risk_level <- "High Risk"
  }

  return(list(
    Tisdale_Score = score,
    Risk_Level = risk_level,
    Inputs = list(
      Age_ge_68 = age >= 68,
      Female_Sex = sex == "female",
      Loop_Diuretic = loop_diuretic == 1,
      K_le_3_5 = serum_potassium <= 3.5,
      QTc_ge_450 = serum_q_t_c >= 450,
      Acute_MI = acute_mi == 1,
      Sepsis = sepsis == 1,
      Heart_Failure = heart_failure == 1,
      QTc_Prolonging_Meds = ifelse(two_or_more_qtc_drugs == 1, ">=2 Meds", ifelse(one_qtc_drug == 1, "1 Med", "None"))
    )
  ))
}

tokyo_guidelines_cholangitis_2018 <- function(age, temperature_c, wbc_count, crp_elevated, bilirubin_mg_dl, abnormal_liver_enzymes, imaging_biliary_dilation, imaging_etiology, albumin_g_dl, hypotension_on_meds, altered_consciousness, pao2_fio2_lt_300, creatinine_mg_dl, inr, platelet_count_x10_9_l) {

  age <- as.numeric(age)
  temperature_c <- as.numeric(temperature_c)
  wbc_count <- as.numeric(wbc_count)
  crp_elevated <- as.numeric(crp_elevated)
  bilirubin_mg_dl <- as.numeric(bilirubin_mg_dl)
  abnormal_liver_enzymes <- as.numeric(abnormal_liver_enzymes)
  imaging_biliary_dilation <- as.numeric(imaging_biliary_dilation)
  imaging_etiology <- as.numeric(imaging_etiology)
  albumin_g_dl <- as.numeric(albumin_g_dl)
  hypotension_on_meds <- as.numeric(hypotension_on_meds)
  altered_consciousness <- as.numeric(altered_consciousness)
  pao2_fio2_lt_300 <- as.numeric(pao2_fio2_lt_300)
  creatinine_mg_dl <- as.numeric(creatinine_mg_dl)
  inr <- as.numeric(inr)
  platelet_count_x10_9_l <- as.numeric(platelet_count_x10_9_l)

  if (any(is.na(c(age, temperature_c, wbc_count, bilirubin_mg_dl, albumin_g_dl, creatinine_mg_dl, inr, platelet_count_x10_9_l)))) {
    stop("Error: All numeric inputs must be valid.")
  }

  criteria_a <- FALSE
  if (temperature_c > 38.0) criteria_a <- TRUE
  if (wbc_count < 4 || wbc_count > 10) criteria_a <- TRUE
  if (crp_elevated == 1) criteria_a <- TRUE

  criteria_b <- FALSE
  if (bilirubin_mg_dl >= 2.0) criteria_b <- TRUE
  if (abnormal_liver_enzymes == 1) criteria_b <- TRUE

  criteria_c <- FALSE
  if (imaging_biliary_dilation == 1) criteria_c <- TRUE
  if (imaging_etiology == 1) criteria_c <- TRUE

  diagnosis <- "No Acute Cholangitis"

  if (criteria_a && (criteria_b || criteria_c)) {
    diagnosis <- "Suspected Acute Cholangitis"
  }

  if (criteria_a && criteria_b && criteria_c) {
    diagnosis <- "Definite Acute Cholangitis"
  }

  severity_grade <- "N/A"

  if (diagnosis != "No Acute Cholangitis") {

    is_grade_3 <- FALSE
    if (hypotension_on_meds == 1) is_grade_3 <- TRUE
    if (altered_consciousness == 1) is_grade_3 <- TRUE
    if (pao2_fio2_lt_300 == 1) is_grade_3 <- TRUE
    if (creatinine_mg_dl > 2.0) is_grade_3 <- TRUE
    if (inr > 1.5) is_grade_3 <- TRUE
    if (platelet_count_x10_9_l < 100) is_grade_3 <- TRUE

    if (is_grade_3) {
      severity_grade <- "Grade III (Severe)"
    } else {

      is_grade_2 <- FALSE
      if (wbc_count > 12 || wbc_count < 4) is_grade_2 <- TRUE
      if (temperature_c >= 39.0) is_grade_2 <- TRUE
      if (age >= 75) is_grade_2 <- TRUE
      if (bilirubin_mg_dl >= 5.0) is_grade_2 <- TRUE
      if (albumin_g_dl < 2.45) is_grade_2 <- TRUE

      if (is_grade_2) {
        severity_grade <- "Grade II (Moderate)"
      } else {
        severity_grade <- "Grade I (Mild)"
      }
    }
  }

  return(list(
    Diagnosis = diagnosis,
    Severity_Grade = severity_grade,
    Criteria_Status = list(
      A_Systemic_Inflammation = criteria_a,
      B_Cholestasis = criteria_b,
      C_Imaging = criteria_c
    )
  ))
}

tokyo_guidelines_cholecystitis_2018 <- function(murphys_sign, ruq_tenderness, temperature_c, wbc_count, crp_elevated, imaging_positive, hypotension_meds, altered_consciousness, pao2_fio2_ratio, creatinine_mg_dl, inr, platelet_count, palpable_mass, duration_gt_72h, marked_local_inflammation) {

  murphys_sign <- as.numeric(murphys_sign)
  ruq_tenderness <- as.numeric(ruq_tenderness)
  temperature_c <- as.numeric(temperature_c)
  wbc_count <- as.numeric(wbc_count)
  crp_elevated <- as.numeric(crp_elevated)
  imaging_positive <- as.numeric(imaging_positive)
  hypotension_meds <- as.numeric(hypotension_meds)
  altered_consciousness <- as.numeric(altered_consciousness)
  pao2_fio2_ratio <- as.numeric(pao2_fio2_ratio)
  creatinine_mg_dl <- as.numeric(creatinine_mg_dl)
  inr <- as.numeric(inr)
  platelet_count <- as.numeric(platelet_count)
  palpable_mass <- as.numeric(palpable_mass)
  duration_gt_72h <- as.numeric(duration_gt_72h)
  marked_local_inflammation <- as.numeric(marked_local_inflammation)

  if (any(is.na(c(temperature_c, wbc_count, creatinine_mg_dl, inr, platelet_count)))) {
    stop("Error: All numeric inputs must be valid.")
  }

  criteria_a <- FALSE
  if (murphys_sign == 1 || ruq_tenderness == 1 || palpable_mass == 1) {
    criteria_a <- TRUE
  }

  criteria_b <- FALSE
  if (temperature_c > 38.0 || wbc_count > 10 || crp_elevated == 1) {
    criteria_b <- TRUE
  }

  criteria_c <- (imaging_positive == 1)

  diagnosis <- "No Acute Cholecystitis"

  if (criteria_a && criteria_b) {
    diagnosis <- "Suspected Acute Cholecystitis"
    if (criteria_c) {
      diagnosis <- "Definite Acute Cholecystitis"
    }
  }

  severity_grade <- "N/A"

  if (diagnosis != "No Acute Cholecystitis") {

    grade_iii <- FALSE
    if (hypotension_meds == 1) grade_iii <- TRUE
    if (altered_consciousness == 1) grade_iii <- TRUE
    if (!is.na(pao2_fio2_ratio) && pao2_fio2_ratio < 300) grade_iii <- TRUE
    if (creatinine_mg_dl > 2.0) grade_iii <- TRUE
    if (inr > 1.5) grade_iii <- TRUE
    if (platelet_count < 100) grade_iii <- TRUE

    if (grade_iii) {
      severity_grade <- "Grade III (Severe)"
    } else {

      grade_ii <- FALSE
      if (wbc_count > 18) grade_ii <- TRUE
      if (palpable_mass == 1) grade_ii <- TRUE
      if (duration_gt_72h == 1) grade_ii <- TRUE
      if (marked_local_inflammation == 1) grade_ii <- TRUE

      if (grade_ii) {
        severity_grade <- "Grade II (Moderate)"
      } else {
        severity_grade <- "Grade I (Mild)"
      }
    }
  }

  return(list(
    Diagnosis = diagnosis,
    Severity_Grade = severity_grade,
    Criteria_Met = list(
      A_Local_Inflammation = criteria_a,
      B_Systemic_Inflammation = criteria_b,
      C_Imaging = criteria_c
    )
  ))
}

calculate_tpa_stroke_dosing <- function(weight_kg) {

  weight_kg <- as.numeric(weight_kg)

  if (is.na(weight_kg) || weight_kg <= 0) {
    stop("Error: Weight must be a positive number.")
  }

  total_dose_mg <- 0.9 * weight_kg

  if (total_dose_mg > 90) {
    total_dose_mg <- 90
  }

  bolus_dose_mg <- 0.1 * total_dose_mg
  infusion_dose_mg <- 0.9 * total_dose_mg

  discard_amount_mg <- 100 - total_dose_mg
  if (discard_amount_mg < 0) discard_amount_mg <- 0

  return(list(
    Total_Dose_mg = round(total_dose_mg, 2),
    Bolus_Dose_mg = round(bolus_dose_mg, 2),
    Infusion_Dose_mg = round(infusion_dose_mg, 2),
    Discard_Amount_from_100mg_Vial = round(discard_amount_mg, 2),
    Inputs = list(
      Weight_kg = weight_kg
    )
  ))
}

check_tpa_contraindications <- function(symptom_duration_hours, age, disability_status, ich_history, intracranial_neoplasm_avm_aneurysm, recent_intracranial_spinal_surgery, active_internal_bleeding, suspected_aortic_dissection, severe_uncontrolled_hypertension, recent_stroke, recent_head_trauma, current_anticoagulant_use, platelet_count, inr, aptt, pt, glucose) {

  symptom_duration_hours <- as.numeric(symptom_duration_hours)
  age <- as.numeric(age)
  disability_status <- as.numeric(disability_status)
  ich_history <- as.numeric(ich_history)
  intracranial_neoplasm_avm_aneurysm <- as.numeric(intracranial_neoplasm_avm_aneurysm)
  recent_intracranial_spinal_surgery <- as.numeric(recent_intracranial_spinal_surgery)
  active_internal_bleeding <- as.numeric(active_internal_bleeding)
  suspected_aortic_dissection <- as.numeric(suspected_aortic_dissection)
  severe_uncontrolled_hypertension <- as.numeric(severe_uncontrolled_hypertension)
  recent_stroke <- as.numeric(recent_stroke)
  recent_head_trauma <- as.numeric(recent_head_trauma)
  current_anticoagulant_use <- as.numeric(current_anticoagulant_use)
  platelet_count <- as.numeric(platelet_count)
  inr <- as.numeric(inr)
  aptt <- as.numeric(aptt)
  pt <- as.numeric(pt)
  glucose <- as.numeric(glucose)

  if (any(is.na(c(symptom_duration_hours, age, disability_status, ich_history, intracranial_neoplasm_avm_aneurysm, recent_intracranial_spinal_surgery, active_internal_bleeding, suspected_aortic_dissection, severe_uncontrolled_hypertension, recent_stroke, recent_head_trauma, current_anticoagulant_use, platelet_count, inr, aptt, pt, glucose)))) {
    stop("Error: All inputs must be numeric.")
  }

  contraindication_found <- FALSE
  reasons <- c()

  if (symptom_duration_hours > 4.5) {
    contraindication_found <- TRUE
    reasons <- c(reasons, "Time from onset > 4.5 hours")
  }

  if (symptom_duration_hours > 3 && age > 80) {
    contraindication_found <- TRUE
    reasons <- c(reasons, "Age > 80 and time > 3 hours (Relative contraindication depending on guidelines)")
  }

  if (ich_history == 1) {
    contraindication_found <- TRUE
    reasons <- c(reasons, "History of Intracranial Hemorrhage")
  }

  if (intracranial_neoplasm_avm_aneurysm == 1) {
    contraindication_found <- TRUE
    reasons <- c(reasons, "Intracranial neoplasm, AVM, or aneurysm")
  }

  if (recent_intracranial_spinal_surgery == 1) {
    contraindication_found <- TRUE
    reasons <- c(reasons, "Recent intracranial or spinal surgery")
  }

  if (active_internal_bleeding == 1) {
    contraindication_found <- TRUE
    reasons <- c(reasons, "Active internal bleeding")
  }

  if (suspected_aortic_dissection == 1) {
    contraindication_found <- TRUE
    reasons <- c(reasons, "Suspected aortic dissection")
  }

  if (severe_uncontrolled_hypertension == 1) {
    contraindication_found <- TRUE
    reasons <- c(reasons, "Severe uncontrolled hypertension (>185/110 mmHg)")
  }

  if (recent_stroke == 1) {
    contraindication_found <- TRUE
    reasons <- c(reasons, "Recent ischemic stroke (within 3 months)")
  }

  if (recent_head_trauma == 1) {
    contraindication_found <- TRUE
    reasons <- c(reasons, "Recent significant head trauma (within 3 months)")
  }

  if (platelet_count < 100000) {
    contraindication_found <- TRUE
    reasons <- c(reasons, "Platelet count < 100,000/mm3")
  }

  if (current_anticoagulant_use == 1) {
    if (inr > 1.7 || pt > 15 || aptt > 40) {
      contraindication_found <- TRUE
      reasons <- c(reasons, "Current anticoagulant use with elevated INR/PT/aPTT")
    }
  }

  if (glucose < 50 || glucose > 400) {
    if (glucose < 50) {
      contraindication_found <- TRUE
      reasons <- c(reasons, "Hypoglycemia (< 50 mg/dL)")
    }
  }

  recommendation <- ""

  if (contraindication_found) {
    recommendation <- "tPA Contraindicated"
  } else {
    recommendation <- "tPA May be Indicated (No absolute contraindications found in checked list)"
  }

  return(list(
    Recommendation = recommendation,
    Contraindications_Present = if (length(reasons) > 0) reasons else "None",
    Inputs = list(
      Time_Hours = symptom_duration_hours,
      Age = age,
      History_ICH = ich_history == 1,
      Mass_AVM = intracranial_neoplasm_avm_aneurysm == 1,
      Recent_Surgery = recent_intracranial_spinal_surgery == 1,
      Active_Bleed = active_internal_bleeding == 1,
      Dissection = suspected_aortic_dissection == 1,
      Hypertension = severe_uncontrolled_hypertension == 1,
      Recent_Stroke = recent_stroke == 1,
      Recent_Trauma = recent_head_trauma == 1,
      Anticoagulant = current_anticoagulant_use == 1,
      Labs = list(Plt = platelet_count, INR = inr, aPTT = aptt, Glucose = glucose)
    )
  ))
}

calculate_ttkg <- function(urine_potassium, serum_potassium, urine_osmolality, serum_osmolality) {

  urine_potassium <- as.numeric(urine_potassium)
  serum_potassium <- as.numeric(serum_potassium)
  urine_osmolality <- as.numeric(urine_osmolality)
  serum_osmolality <- as.numeric(serum_osmolality)

  if (any(is.na(c(urine_potassium, serum_potassium, urine_osmolality, serum_osmolality)))) {
    stop("Error: All inputs must be numeric.")
  }

  if (urine_osmolality <= serum_osmolality) {
    return(list(
      TTKG_Score = NA,
      Validity = "Invalid",
      Message = "TTKG is not valid when Urine Osmolality <= Serum Osmolality.",
      Inputs = list(
        Urine_K = urine_potassium,
        Serum_K = serum_potassium,
        Urine_Osm = urine_osmolality,
        Serum_Osm = serum_osmolality
      )
    ))
  }

  ttkg <- (urine_potassium * serum_osmolality) / (serum_potassium * urine_osmolality)

  interpretation <- ""
  if (ttkg < 3) {
    interpretation <- "Low TTKG (<3). Suggests appropriate renal K+ conservation in hypokalemia or hypoaldosteronism in hyperkalemia."
  } else if (ttkg > 7) {
    interpretation <- "High TTKG (>7). Suggests renal K+ wasting in hypokalemia (e.g., hyperaldosteronism) or appropriate excretion in hyperkalemia."
  } else {
    interpretation <- "Intermediate range (3-7)."
  }

  return(list(
    TTKG_Score = round(ttkg, 2),
    Validity = "Valid",
    Interpretation = interpretation,
    Inputs = list(
      Urine_K = urine_potassium,
      Serum_K = serum_potassium,
      Urine_Osm = urine_osmolality,
      Serum_Osm = serum_osmolality
    )
  ))
}

triss_trauma_score <- function(age, mechanism, gcs, systolic_bp, respiratory_rate, iss) {

  age <- as.numeric(age)
  mechanism <- tolower(as.character(mechanism))
  gcs <- as.numeric(gcs)
  systolic_bp <- as.numeric(systolic_bp)
  respiratory_rate <- as.numeric(respiratory_rate)
  iss <- as.numeric(iss)

  if (any(is.na(c(age, gcs, systolic_bp, respiratory_rate, iss)))) {
    stop("Error: All numeric inputs must be valid.")
  }

  if (!mechanism %in% c("blunt", "penetrating")) {
    stop("Error: Mechanism must be 'blunt' or 'penetrating'.")
  }

  if (iss < 1 || iss > 75) {
    stop("Error: ISS must be between 1 and 75.")
  }

  if (gcs < 3 || gcs > 15) {
    stop("Error: GCS must be between 3 and 15.")
  }

  gcs_code <- 0
  if (gcs >= 13) gcs_code <- 4
  else if (gcs >= 9) gcs_code <- 3
  else if (gcs >= 6) gcs_code <- 2
  else if (gcs >= 4) gcs_code <- 1
  else gcs_code <- 0

  sbp_code <- 0
  if (systolic_bp > 89) sbp_code <- 4
  else if (systolic_bp >= 76) sbp_code <- 3
  else if (systolic_bp >= 50) sbp_code <- 2
  else if (systolic_bp >= 1) sbp_code <- 1
  else sbp_code <- 0

  rr_code <- 0
  if (respiratory_rate >= 10 && respiratory_rate <= 29) rr_code <- 4
  else if (respiratory_rate > 29) rr_code <- 3
  else if (respiratory_rate >= 6) rr_code <- 2
  else if (respiratory_rate >= 1) rr_code <- 1
  else rr_code <- 0

  rts <- (0.9368 * gcs_code) + (0.7326 * sbp_code) + (0.2908 * rr_code)

  age_index <- if (age >= 55) 1 else 0

  b0 <- 0
  b1 <- 0
  b2 <- 0
  b3 <- 0

  if (mechanism == "blunt") {
    b0 <- -0.4499
    b1 <- 0.8085
    b2 <- -0.0835
    b3 <- -1.7430
  } else {
    b0 <- -2.5355
    b1 <- 0.9934
    b2 <- -0.0651
    b3 <- -1.1360
  }

  b <- b0 + (b1 * rts) + (b2 * iss) + (b3 * age_index)

  probability_survival <- 1 / (1 + exp(-b))

  return(list(
    TRISS_Probability_Survival = paste0(round(probability_survival * 100, 1), "%"),
    RTS_Calculated = round(rts, 4),
    Inputs = list(
      Age = age,
      Mechanism = mechanism,
      GCS = gcs,
      SBP = systolic_bp,
      RR = respiratory_rate,
      ISS = iss
    )
  ))
}

