t_macs_decision_aid <- function(hs_ctn_t_ng_l, heart_type_fatty_acid_binding_protein_ng_ml, ecg_ischemia, sweating, pain_radiates_to_right_arm_shoulder, pain_worsens_with_movement_palpation, vomiting) {

  hs_ctn_t_ng_l <- as.numeric(hs_ctn_t_ng_l)
  heart_type_fatty_acid_binding_protein_ng_ml <- as.numeric(heart_type_fatty_acid_binding_protein_ng_ml)
  ecg_ischemia <- as.numeric(ecg_ischemia)
  sweating <- as.numeric(sweating)
  pain_radiates_to_right_arm_shoulder <- as.numeric(pain_radiates_to_right_arm_shoulder)
  pain_worsens_with_movement_palpation <- as.numeric(pain_worsens_with_movement_palpation)
  vomiting <- as.numeric(vomiting)

  if (any(is.na(c(hs_ctn_t_ng_l, heart_type_fatty_acid_binding_protein_ng_ml, ecg_ischemia, sweating, pain_radiates_to_right_arm_shoulder, pain_worsens_with_movement_palpation, vomiting)))) {
    stop("Error: All inputs must be numeric.")
  }

  log_hs_ctn_t <- log(hs_ctn_t_ng_l)

  log_h_fabp <- log(heart_type_fatty_acid_binding_protein_ng_ml)

  log_odds <- -7.04 + (0.26 * ecg_ischemia) + (0.55 * sweating) + (0.67 * pain_radiates_to_right_arm_shoulder) - (0.53 * pain_worsens_with_movement_palpation) + (0.62 * vomiting) + (0.61 * log_hs_ctn_t) + (1.19 * log_h_fabp)

  probability <- 1 / (1 + exp(-log_odds))

  risk_category <- ""
  if (probability < 0.02) {
    risk_category <- "Very Low Risk"
  } else if (probability < 0.05) {
    risk_category <- "Low Risk"
  } else if (probability < 0.95) {
    risk_category <- "Moderate Risk"
  } else {
    risk_category <- "High Risk"
  }

  return(list(
    Probability_ACS = round(probability, 4),
    Risk_Category = risk_category,
    Inputs = list(
      hs_cTnT = hs_ctn_t_ng_l,
      H_FABP = heart_type_fatty_acid_binding_protein_ng_ml,
      ECG_Ischemia = ecg_ischemia == 1,
      Sweating = sweating == 1,
      Right_Arm_Shoulder_Pain = pain_radiates_to_right_arm_shoulder == 1,
      Worsens_Movement = pain_worsens_with_movement_palpation == 1,
      Vomiting = vomiting == 1
    )
  ))
}

truelove_witts_severity_index <- function(bowel_movements_per_day, rectal_bleeding, temperature_c, heart_rate, hemoglobin_g_dl, esr) {

  bowel_movements_per_day <- as.numeric(bowel_movements_per_day)
  rectal_bleeding <- tolower(as.character(rectal_bleeding))
  temperature_c <- as.numeric(temperature_c)
  heart_rate <- as.numeric(heart_rate)
  hemoglobin_g_dl <- as.numeric(hemoglobin_g_dl)
  esr <- as.numeric(esr)

  if (any(is.na(c(bowel_movements_per_day, temperature_c, heart_rate, hemoglobin_g_dl, esr)))) {
    stop("Error: Numeric inputs for vitals/labs must be valid.")
  }

  valid_bleeding <- c("none", "intermittent", "frequent_continuous")
  if (!rectal_bleeding %in% valid_bleeding) {
    stop("Error: Rectal bleeding must be 'none', 'intermittent', or 'frequent_continuous'.")
  }

  severity_classification <- "Mild"
  criteria_met <- 0

  if (bowel_movements_per_day >= 6) {
    criteria_met <- criteria_met + 1
  }

  if (rectal_bleeding == "frequent_continuous") {
    criteria_met <- criteria_met + 1
  }

  if (temperature_c > 37.5) {
    criteria_met <- criteria_met + 1
  }

  if (heart_rate > 90) {
    criteria_met <- criteria_met + 1
  }

  if (hemoglobin_g_dl <= 10.5) {
    criteria_met <- criteria_met + 1
  }

  if (esr > 30) {
    criteria_met <- criteria_met + 1
  }

  if (bowel_movements_per_day >= 6 && criteria_met >= 2) {
    severity_classification <- "Severe"
  } else if (bowel_movements_per_day > 4) {
    severity_classification <- "Moderate"
  } else {
    severity_classification <- "Mild"
  }

  return(list(
    Severity_Index = severity_classification,
    Inputs = list(
      Stool_Frequency = bowel_movements_per_day,
      Bleeding = rectal_bleeding,
      Temperature = temperature_c,
      Heart_Rate = heart_rate,
      Hemoglobin = hemoglobin_g_dl,
      ESR = esr
    )
  ))
}

trunk_impairment_scale <- function(static_sitting_balance, dynamic_sitting_balance, coordination) {

  static_sitting_balance <- as.numeric(static_sitting_balance)
  dynamic_sitting_balance <- as.numeric(dynamic_sitting_balance)
  coordination <- as.numeric(coordination)

  if (any(is.na(c(static_sitting_balance, dynamic_sitting_balance, coordination)))) {
    stop("Error: All inputs must be numeric.")
  }

  if (static_sitting_balance < 0 || static_sitting_balance > 7) {
    stop("Error: Static Sitting Balance score must be between 0 and 7.")
  }

  if (dynamic_sitting_balance < 0 || dynamic_sitting_balance > 10) {
    stop("Error: Dynamic Sitting Balance score must be between 0 and 10.")
  }

  if (coordination < 0 || coordination > 6) {
    stop("Error: Coordination score must be between 0 and 6.")
  }

  tis_total_score <- static_sitting_balance + dynamic_sitting_balance + coordination

  interpretation <- ""
  if (tis_total_score == 23) {
    interpretation <- "Normal Trunk Function"
  } else {
    interpretation <- paste0("Impaired Trunk Function (Score ", tis_total_score, "/23)")
  }

  return(list(
    TIS_Total_Score = tis_total_score,
    Interpretation = interpretation,
    Subscale_Scores = list(
      Static_Sitting_Balance = static_sitting_balance,
      Dynamic_Sitting_Balance = dynamic_sitting_balance,
      Coordination = coordination
    )
  ))
}

uiss_rcc_staging <- function(tnm_t_stage, tnm_n_stage, tnm_m_stage, fuhrman_grade, ecog_performance_status) {

  tnm_t_stage <- tolower(as.character(tnm_t_stage))
  tnm_n_stage <- tolower(as.character(tnm_n_stage))
  tnm_m_stage <- tolower(as.character(tnm_m_stage))
  fuhrman_grade <- as.numeric(fuhrman_grade)
  ecog_performance_status <- as.numeric(ecog_performance_status)

  if (any(is.na(c(fuhrman_grade, ecog_performance_status)))) {
    stop("Error: Grade and ECOG must be numeric.")
  }

  is_metastatic <- FALSE
  if (tnm_n_stage %in% c("n1", "n2") || tnm_m_stage == "m1") {
    is_metastatic <- TRUE
  }

  risk_group <- ""
  survival_5yr <- ""

  if (is_metastatic) {
    if (ecog_performance_status >= 2) {
      risk_group <- "High Risk"
      survival_5yr <- "0%"
    } else if (ecog_performance_status == 1) {
      risk_group <- "Intermediate Risk"
      survival_5yr <- "17%"
    } else {
      if (fuhrman_grade >= 3) {
        risk_group <- "Intermediate Risk"
        survival_5yr <- "17%"
      } else {
        risk_group <- "Low Risk"
        survival_5yr <- "39%"
      }
    }
  } else {
    if (ecog_performance_status >= 1) {
      risk_group <- "High Risk"
      survival_5yr <- "44%"
    } else {
      if (tnm_t_stage == "t4") {
        risk_group <- "High Risk"
        survival_5yr <- "44%"
      } else if (tnm_t_stage == "t3") {
        if (fuhrman_grade >= 3) {
          risk_group <- "High Risk"
          survival_5yr <- "44%"
        } else {
          risk_group <- "Intermediate Risk"
          survival_5yr <- "67%"
        }
      } else {
        if (fuhrman_grade >= 3) {
          risk_group <- "Intermediate Risk"
          survival_5yr <- "67%"
        } else {
          risk_group <- "Low Risk"
          survival_5yr <- "92%"
        }
      }
    }
  }

  disease_state <- if (is_metastatic) "Metastatic" else "Localized"

  return(list(
    UISS_Risk_Group = paste(risk_group, "-", disease_state),
    Est_5_Year_Survival = survival_5yr,
    Inputs = list(
      T_Stage = tnm_t_stage,
      N_Stage = tnm_n_stage,
      M_Stage = tnm_m_stage,
      Fuhrman_Grade = fuhrman_grade,
      ECOG_PS = ecog_performance_status
    )
  ))
}

ucsf_capra_score <- function(psa, gleason_primary, gleason_secondary, clinical_t_stage, percent_positive_cores, age) {

  psa <- as.numeric(psa)
  gleason_primary <- as.numeric(gleason_primary)
  gleason_secondary <- as.numeric(gleason_secondary)
  percent_positive_cores <- as.numeric(percent_positive_cores)
  age <- as.numeric(age)
  clinical_t_stage <- tolower(as.character(clinical_t_stage))

  if (any(is.na(c(psa, gleason_primary, gleason_secondary, percent_positive_cores, age)))) {
    stop("Error: All numeric inputs must be valid.")
  }

  score <- 0

  if (psa < 6) {
    score <- score + 0
  } else if (psa >= 6 && psa <= 10) {
    score <- score + 1
  } else if (psa > 10 && psa <= 20) {
    score <- score + 2
  } else if (psa > 20 && psa <= 30) {
    score <- score + 3
  } else {
    score <- score + 4
  }

  if (gleason_primary >= 4) {
    score <- score + 3
  } else if (gleason_secondary >= 4) {
    score <- score + 1
  } else {
    score <- score + 0
  }

  if (clinical_t_stage == "t3a") {
    score <- score + 1
  } else {
    score <- score + 0
  }

  if (percent_positive_cores >= 34) {
    score <- score + 1
  }

  if (age >= 50) {
    score <- score + 1
  }

  risk_group <- ""
  recurrence_free_5yr <- ""

  if (score <= 2) {
    risk_group <- "Low Risk"
    recurrence_free_5yr <- "~91%"
  } else if (score <= 5) {
    risk_group <- "Intermediate Risk"
    recurrence_free_5yr <- "~74%"
  } else {
    risk_group <- "High Risk"
    recurrence_free_5yr <- "~29%"
  }

  return(list(
    CAPRA_Score = score,
    Risk_Category = risk_group,
    Est_5_Year_Recurrence_Free_Survival = recurrence_free_5yr,
    Inputs = list(
      PSA = psa,
      Gleason_Sum = paste0(gleason_primary, "+", gleason_secondary),
      T_Stage = clinical_t_stage,
      Positive_Cores_Percent = percent_positive_cores,
      Age = age
    )
  ))
}

uceis_score <- function(vascular_pattern, bleeding, erosions_ulcers) {

  vascular_pattern <- as.numeric(vascular_pattern)
  bleeding <- as.numeric(bleeding)
  erosions_ulcers <- as.numeric(erosions_ulcers)

  if (any(is.na(c(vascular_pattern, bleeding, erosions_ulcers)))) {
    stop("Error: All inputs must be numeric.")
  }

  if (vascular_pattern < 0 || vascular_pattern > 2) {
    stop("Error: Vascular pattern score must be between 0 and 2.")
  }

  if (bleeding < 0 || bleeding > 3) {
    stop("Error: Bleeding score must be between 0 and 3.")
  }

  if (erosions_ulcers < 0 || erosions_ulcers > 3) {
    stop("Error: Erosions and ulcers score must be between 0 and 3.")
  }

  total_score <- vascular_pattern + bleeding + erosions_ulcers

  severity <- ""
  if (total_score <= 1) {
    severity <- "Remission"
  } else if (total_score <= 4) {
    severity <- "Mild to Moderate Activity"
  } else if (total_score <= 6) {
    severity <- "Moderate to Severe Activity"
  } else {
    severity <- "Severe Activity"
  }

  return(list(
    UCEIS_Score = total_score,
    Disease_Activity = severity,
    Inputs = list(
      Vascular_Pattern = vascular_pattern,
      Bleeding = bleeding,
      Erosions_Ulcers = erosions_ulcers
    )
  ))
}

ukeld_score <- function(bilirubin_umol_l, inr, creatinine_umol_l, sodium_mmol_l) {

  bilirubin_umol_l <- as.numeric(bilirubin_umol_l)
  inr <- as.numeric(inr)
  creatinine_umol_l <- as.numeric(creatinine_umol_l)
  sodium_mmol_l <- as.numeric(sodium_mmol_l)

  if (any(is.na(c(bilirubin_umol_l, inr, creatinine_umol_l, sodium_mmol_l)))) {
    stop("Error: All inputs must be numeric.")
  }

  inr_val <- if (inr < 1.0) 1.0 else inr
  bili_val <- if (bilirubin_umol_l < 1.0) 1.0 else bilirubin_umol_l
  creat_val <- if (creatinine_umol_l < 1.0) 1.0 else creatinine_umol_l

  ukeld <- (5.395 * log(inr_val)) + (1.266 * log(bili_val)) + (1.541 * log(creat_val)) + (1.567 * log(sodium_mmol_l))

  ukeld <- round(ukeld, 0)

  est_1yr_mortality <- exp((ukeld - 70) / 7)
  est_1yr_mortality <- round(est_1yr_mortality * 100 / (100 + est_1yr_mortality), 1)

  listing_status <- ""
  if (ukeld >= 49) {
    listing_status <- "Meets minimum listing criteria (UKELD >= 49)"
  } else {
    listing_status <- "Below minimum listing criteria (UKELD < 49)"
  }

  return(list(
    UKELD_Score = ukeld,
    Listing_Criteria = listing_status,
    Est_1_Year_Mortality_Without_Transplant = paste0(est_1yr_mortality, "%"),
    Inputs = list(
      Bilirubin_umol_L = bilirubin_umol_l,
      INR = inr_val,
      Creatinine_umol_L = creatinine_umol_l,
      Sodium_mmol_L = sodium_mmol_l
    )
  ))
}

estimate_urinary_protein_excretion <- function(urine_protein, urine_creatinine, urine_protein_units = "mg/dL", urine_creatinine_units = "mg/dL") {

  urine_protein <- as.numeric(urine_protein)
  urine_creatinine <- as.numeric(urine_creatinine)

  if (any(is.na(c(urine_protein, urine_creatinine)))) {
    stop("Error: All inputs must be numeric.")
  }

  if (urine_creatinine <= 0) {
    stop("Error: Urine creatinine must be greater than 0.")
  }

  prot_mg_dl <- urine_protein
  if (urine_protein_units == "g/L") {
    prot_mg_dl <- urine_protein * 100
  }

  creat_mg_dl <- urine_creatinine
  if (urine_creatinine_units == "mmol/L") {
    creat_mg_dl <- urine_creatinine * 11.31
  } else if (urine_creatinine_units == "umol/L" || urine_creatinine_units == "micromol/L") {
    creat_mg_dl <- urine_creatinine * 0.01131
  }

  upcr <- prot_mg_dl / creat_mg_dl

  estimated_protein_g_day <- upcr

  protein_mg_day <- estimated_protein_g_day * 1000

  return(list(
    Estimated_Protein_Excretion_g_day = round(estimated_protein_g_day, 2),
    UPCR_Ratio = round(upcr, 2),
    Inputs = list(
      Urine_Protein = urine_protein,
      Urine_Creatinine = urine_creatinine
    )
  ))
}

calculate_urine_anion_gap <- function(urine_sodium, urine_potassium, urine_chloride) {

  urine_sodium <- as.numeric(urine_sodium)
  urine_potassium <- as.numeric(urine_potassium)
  urine_chloride <- as.numeric(urine_chloride)

  if (any(is.na(c(urine_sodium, urine_potassium, urine_chloride)))) {
    stop("Error: All inputs must be numeric.")
  }

  urine_ag <- (urine_sodium + urine_potassium) - urine_chloride

  interpretation <- ""
  if (urine_ag < 0) {
    interpretation <- "Negative Gap (Suggests GI loss of bicarbonate)"
  } else if (urine_ag >= 0) {
    interpretation <- "Positive Gap (Suggests Renal Acidification Defect / RTA)"
  }

  return(list(
    Urine_Anion_Gap = round(urine_ag, 1),
    Interpretation = interpretation,
    Inputs = list(
      Urine_Na = urine_sodium,
      Urine_K = urine_potassium,
      Urine_Cl = urine_chloride
    )
  ))
}

urine_output_calculator <- function(urine_volume_ml, time_hours, weight_kg) {

  urine_volume_ml <- as.numeric(urine_volume_ml)
  time_hours <- as.numeric(time_hours)
  weight_kg <- as.numeric(weight_kg)

  if (any(is.na(c(urine_volume_ml, time_hours, weight_kg)))) {
    stop("Error: All inputs must be numeric.")
  }

  if (time_hours <= 0 || weight_kg <= 0) {
    stop("Error: Time and weight must be positive.")
  }

  hourly_output <- urine_volume_ml / time_hours

  normalized_output <- hourly_output / weight_kg

  interpretation <- ""

  if (normalized_output < 0.5) {
    interpretation <- "Oliguria (Adult < 0.5 mL/kg/hr)"
  } else {
    interpretation <- "Adequate Urine Output (Adult >= 0.5 mL/kg/hr)"
  }

  return(list(
    Urine_Output_mL_kg_hr = round(normalized_output, 2),
    Hourly_Rate_mL_hr = round(hourly_output, 1),
    Interpretation_Adult = interpretation,
    Inputs = list(
      Volume_mL = urine_volume_ml,
      Time_hrs = time_hours,
      Weight_kg = weight_kg
    )
  ))
}

urticaria_activity_score <- function(wheals_score, pruritus_score) {

  wheals_score <- as.numeric(wheals_score)
  pruritus_score <- as.numeric(pruritus_score)

  if (any(is.na(c(wheals_score, pruritus_score)))) {
    stop("Error: All inputs must be numeric.")
  }

  if (wheals_score < 0 || wheals_score > 3) {
    stop("Error: Wheals score must be between 0 and 3.")
  }

  if (pruritus_score < 0 || pruritus_score > 3) {
    stop("Error: Pruritus score must be between 0 and 3.")
  }

  total_score <- wheals_score + pruritus_score

  return(list(
    UAS_Daily_Score = total_score,
    Interpretation = "Daily score ranges from 0 to 6. Weekly score (UAS7) ranges from 0 to 42.",
    Inputs = list(
      Wheals_Score = wheals_score,
      Pruritus_Score = pruritus_score
    )
  ))
}

us_medped_fh_criteria <- function(age, total_cholesterol, relative_with_fh, units = "mg/dL") {

  age <- as.numeric(age)
  total_cholesterol <- as.numeric(total_cholesterol)
  relative_with_fh <- tolower(as.character(relative_with_fh))

  if (any(is.na(c(age, total_cholesterol)))) {
    stop("Error: Age and Cholesterol must be numeric.")
  }

  if (!relative_with_fh %in% c("first_degree", "second_degree", "third_degree", "general_population")) {
    stop("Error: Relative status must be 'first_degree', 'second_degree', 'third_degree', or 'general_population'.")
  }

  tc_mg_dl <- total_cholesterol
  if (units == "mmol/L") {
    tc_mg_dl <- total_cholesterol * 38.67
  }

  threshold <- 0

  if (relative_with_fh == "first_degree") {
    if (age < 20) threshold <- 220
    else if (age < 30) threshold <- 240
    else if (age < 40) threshold <- 270
    else threshold <- 290
  } else if (relative_with_fh == "second_degree") {
    if (age < 20) threshold <- 230
    else if (age < 30) threshold <- 250
    else if (age < 40) threshold <- 280
    else threshold <- 300
  } else if (relative_with_fh == "third_degree") {
    if (age < 20) threshold <- 240
    else if (age < 30) threshold <- 260
    else if (age < 40) threshold <- 290
    else threshold <- 310
  } else {
    if (age < 20) threshold <- 270
    else if (age < 30) threshold <- 290
    else if (age < 40) threshold <- 340
    else threshold <- 360
  }

  diagnosis <- ""
  if (tc_mg_dl >= threshold) {
    diagnosis <- "Diagnosed with Familial Hypercholesterolemia (FH)"
  } else {
    diagnosis <- "Does Not Meet Criteria for FH"
  }

  return(list(
    Diagnosis = diagnosis,
    Threshold_Used_mg_dL = threshold,
    Inputs = list(
      Age = age,
      Total_Cholesterol_mg_dL = round(tc_mg_dl, 0),
      Relative_Status = relative_with_fh
    )
  ))
}

utah_covid_risk_score <- function(age, sex, congestive_heart_failure, copd, diabetes, hypertension, immunosuppression) {

  age <- as.numeric(age)
  sex <- tolower(as.character(sex))
  congestive_heart_failure <- as.numeric(congestive_heart_failure)
  copd <- as.numeric(copd)
  diabetes <- as.numeric(diabetes)
  hypertension <- as.numeric(hypertension)
  immunosuppression <- as.numeric(immunosuppression)

  if (any(is.na(c(age, congestive_heart_failure, copd, diabetes, hypertension, immunosuppression)))) {
    stop("Error: All inputs must be numeric.")
  }

  if (!sex %in% c("male", "female")) {
    stop("Error: Sex must be 'male' or 'female'.")
  }

  score <- 0

  if (age >= 18 && age <= 39) {
    score <- score + 0
  } else if (age >= 40 && age <= 49) {
    score <- score + 1
  } else if (age >= 50 && age <= 59) {
    score <- score + 2
  } else if (age >= 60 && age <= 69) {
    score <- score + 3
  } else if (age >= 70 && age <= 79) {
    score <- score + 4
  } else if (age >= 80) {
    score <- score + 5
  }

  if (sex == "male") {
    score <- score + 1
  }

  if (congestive_heart_failure == 1) {
    score <- score + 1
  }

  if (copd == 1) {
    score <- score + 1
  }

  if (diabetes == 1) {
    score <- score + 1
  }

  if (hypertension == 1) {
    score <- score + 1
  }

  if (immunosuppression == 1) {
    score <- score + 1
  }

  risk_level <- ""

  if (score <= 0) {
    risk_level <- "Low Risk"
  } else if (score <= 2) {
    risk_level <- "Medium Risk"
  } else {
    risk_level <- "High Risk"
  }

  return(list(
    Utah_Risk_Score = score,
    Risk_Level = risk_level,
    Inputs = list(
      Age = age,
      Sex = sex,
      CHF = congestive_heart_failure == 1,
      COPD = copd == 1,
      Diabetes = diabetes == 1,
      Hypertension = hypertension == 1,
      Immunosuppression = immunosuppression == 1
    )
  ))
}

vbac_success_predictor <- function(age, height_in, weight_lb, previous_vaginal_delivery, previous_vbac, recurring_indication_cesarean, treated_chronic_hypertension) {

  age <- as.numeric(age)
  height_in <- as.numeric(height_in)
  weight_lb <- as.numeric(weight_lb)
  previous_vaginal_delivery <- as.numeric(previous_vaginal_delivery)
  previous_vbac <- as.numeric(previous_vbac)
  recurring_indication_cesarean <- as.numeric(recurring_indication_cesarean)
  treated_chronic_hypertension <- as.numeric(treated_chronic_hypertension)

  if (any(is.na(c(age, height_in, weight_lb, previous_vaginal_delivery, previous_vbac, recurring_indication_cesarean, treated_chronic_hypertension)))) {
    stop("Error: All inputs must be numeric.")
  }

  height_m <- height_in * 0.0254
  weight_kg <- weight_lb * 0.453592
  bmi <- weight_kg / (height_m ^ 2)

  logit <- 3.302 + (-0.043 * age) + (-0.052 * bmi) + (0.832 * previous_vaginal_delivery) + (0.489 * previous_vbac) + (-0.622 * recurring_indication_cesarean) + (-0.513 * treated_chronic_hypertension)

  probability <- 1 / (1 + exp(-logit))
  prob_percent <- probability * 100

  return(list(
    Predicted_VBAC_Success = paste0(round(prob_percent, 1), "%"),
    Inputs = list(
      Age = age,
      BMI = round(bmi, 1),
      Prior_Vaginal = previous_vaginal_delivery == 1,
      Prior_VBAC = previous_vbac == 1,
      Recurring_Indication = recurring_indication_cesarean == 1,
      Chronic_Hypertension = treated_chronic_hypertension == 1
    )
  ))
}

vancouver_chest_pain_rule <- function(age, prior_acs_nitrate_use, ecg_st_depression, ecg_non_specific_repolarization, troponin_elevated, pain_worse_palpation) {

  age <- as.numeric(age)
  prior_acs_nitrate_use <- as.numeric(prior_acs_nitrate_use)
  ecg_st_depression <- as.numeric(ecg_st_depression)
  ecg_non_specific_repolarization <- as.numeric(ecg_non_specific_repolarization)
  troponin_elevated <- as.numeric(troponin_elevated)
  pain_worse_palpation <- as.numeric(pain_worse_palpation)

  if (any(is.na(c(age, prior_acs_nitrate_use, ecg_st_depression, ecg_non_specific_repolarization, troponin_elevated, pain_worse_palpation)))) {
    stop("Error: All inputs must be numeric (0 or 1 for binary).")
  }

  result <- "Not Low Risk (ACS cannot be ruled out)"
  risk_category <- "Not Low Risk"

  if (troponin_elevated == 1) {
    return(list(Result = result, Risk_Category = risk_category))
  }

  if (ecg_st_depression == 1) {
    return(list(Result = result, Risk_Category = risk_category))
  }

  if (prior_acs_nitrate_use == 1) {
    if (pain_worse_palpation == 1) {
      result <- "Low Risk (ACS Ruled Out)"
      risk_category <- "Low Risk"
    }
  } else {
    if (age < 50) {
      result <- "Low Risk (ACS Ruled Out)"
      risk_category <- "Low Risk"
    } else {
      if (pain_worse_palpation == 1) {
        if (ecg_non_specific_repolarization == 0) {
          result <- "Low Risk (ACS Ruled Out)"
          risk_category <- "Low Risk"
        }
      }
    }
  }

  return(list(
    Result = result,
    Risk_Category = risk_category,
    Inputs = list(
      Age = age,
      Prior_ACS_Nitrate = prior_acs_nitrate_use == 1,
      ST_Depression = ecg_st_depression == 1,
      Nonspecific_Repolarization = ecg_non_specific_repolarization == 1,
      Troponin_Positive = troponin_elevated == 1,
      Pain_Reproducible = pain_worse_palpation == 1
    )
  ))
}

flamm_vbac_score <- function(age, vaginal_history, reason_for_prior_c_section, cervical_effacement_percent, cervical_dilation_cm) {

  age <- as.numeric(age)
  vaginal_history <- tolower(as.character(vaginal_history))
  reason_for_prior_c_section <- tolower(as.character(reason_for_prior_c_section))
  cervical_effacement_percent <- as.numeric(cervical_effacement_percent)
  cervical_dilation_cm <- as.numeric(cervical_dilation_cm)

  if (any(is.na(c(age, cervical_effacement_percent, cervical_dilation_cm)))) {
    stop("Error: Age, effacement, and dilation must be numeric.")
  }

  if (!vaginal_history %in% c("none", "before", "after", "both")) {
    stop("Error: Vaginal history must be 'none', 'before', 'after', or 'both'.")
  }

  if (!reason_for_prior_c_section %in% c("failure_to_progress", "other")) {
    stop("Error: Reason must be 'failure_to_progress' or 'other'.")
  }

  score <- 0

  if (age < 40) {
    score <- score + 2
  }

  if (vaginal_history == "both") {
    score <- score + 4
  } else if (vaginal_history == "after") {
    score <- score + 2
  } else if (vaginal_history == "before") {
    score <- score + 1
  }

  if (reason_for_prior_c_section == "other") {
    score <- score + 1
  }

  if (cervical_effacement_percent > 75) {
    score <- score + 2
  } else if (cervical_effacement_percent >= 25) {
    score <- score + 1
  }

  if (cervical_dilation_cm >= 4) {
    score <- score + 1
  }

  success_rate <- ""

  if (score <= 2) {
    success_rate <- "49%"
  } else if (score == 3) {
    success_rate <- "60%"
  } else if (score == 4) {
    success_rate <- "67%"
  } else if (score == 5) {
    success_rate <- "77%"
  } else if (score == 6) {
    success_rate <- "89%"
  } else if (score == 7) {
    success_rate <- "93%"
  } else {
    success_rate <- "95-99%"
  }

  return(list(
    Flamm_Score = score,
    Probability_Successful_VBAC = success_rate,
    Inputs = list(
      Age = age,
      History = vaginal_history,
      Reason = reason_for_prior_c_section,
      Effacement = cervical_effacement_percent,
      Dilation = cervical_dilation_cm
    )
  ))
}

vurx_index <- function(vur_grade, reflux_timing, sex) {

  vur_grade <- as.numeric(vur_grade)
  reflux_timing <- tolower(as.character(reflux_timing))
  sex <- tolower(as.character(sex))

  if (is.na(vur_grade) || !vur_grade %in% 1:5) {
    stop("Error: VUR Grade must be an integer between 1 and 5.")
  }

  if (!reflux_timing %in% c("filling", "voiding")) {
    stop("Error: Reflux timing must be 'filling' or 'voiding'.")
  }

  if (!sex %in% c("male", "female")) {
    stop("Error: Sex must be 'male' or 'female'.")
  }

  score <- 0

  if (vur_grade == 4) {
    score <- score + 3
  } else if (vur_grade == 5) {
    score <- score + 4
  }

  if (reflux_timing == "filling") {
    score <- score + 1
  }

  if (sex == "male") {
    score <- score + 1
  }

  resolution_chance <- ""
  if (score <= 2) {
    resolution_chance <- "High probability of spontaneous resolution."
  } else {
    resolution_chance <- "Low probability of spontaneous resolution (Surgical intervention often required)."
  }

  return(list(
    VURx_Score = score,
    Interpretation = resolution_chance,
    Inputs = list(
      Grade = vur_grade,
      Timing = reflux_timing,
      Sex = sex
    )
  ))
}

vacs_1_0_index <- function(age, cd4_count, hiv_rna, hemoglobin, platelets, ast, alt, creatinine, hepatitis_c_positive, sex = "male", race = "other") {

  age <- as.numeric(age)
  cd4_count <- as.numeric(cd4_count)
  hiv_rna <- as.numeric(hiv_rna)
  hemoglobin <- as.numeric(hemoglobin)
  platelets <- as.numeric(platelets)
  ast <- as.numeric(ast)
  alt <- as.numeric(alt)
  creatinine <- as.numeric(creatinine)
  hepatitis_c_positive <- as.numeric(hepatitis_c_positive)
  sex <- tolower(as.character(sex))
  race <- tolower(as.character(race))

  if (any(is.na(c(age, cd4_count, hiv_rna, hemoglobin, platelets, ast, alt, creatinine, hepatitis_c_positive)))) {
    stop("Error: All clinical and laboratory inputs must be numeric.")
  }

  fib4 <- (age * ast) / (platelets * sqrt(alt))

  is_female <- if (sex == "female") 1 else 0
  is_black <- if (race == "black" || race == "african american") 1 else 0

  egfr <- 175 * (creatinine ^ -1.154) * (age ^ -0.203) * (if (is_female) 0.742 else 1) * (if (is_black) 1.212 else 1)

  score <- 0

  if (age < 50) score <- score + 0
  else if (age >= 50 && age <= 64) score <- score + 12
  else score <- score + 27

  if (cd4_count >= 500) score <- score + 0
  else if (cd4_count >= 350) score <- score + 6
  else if (cd4_count >= 200) score <- score + 6
  else if (cd4_count >= 100) score <- score + 10
  else if (cd4_count >= 50) score <- score + 28
  else score <- score + 29

  if (hiv_rna < 500) score <- score + 0
  else if (hiv_rna < 100000) score <- score + 7
  else score <- score + 14

  if (hemoglobin >= 14) score <- score + 0
  else if (hemoglobin >= 12) score <- score + 10
  else if (hemoglobin >= 10) score <- score + 22
  else score <- score + 38

  if (fib4 < 1.45) score <- score + 0
  else if (fib4 <= 3.25) score <- score + 6
  else score <- score + 25

  if (egfr >= 60) score <- score + 0
  else if (egfr >= 45) score <- score + 6
  else if (egfr >= 30) score <- score + 8
  else score <- score + 26

  if (hepatitis_c_positive == 1) score <- score + 5

  mortality_5yr <- "Calculated Score indicates relative risk. See literature for exact probability."

  return(list(
    VACS_Index_Score = score,
    Calculated_Values = list(
      FIB_4 = round(fib4, 2),
      eGFR_MDRD = round(egfr, 1)
    ),
    Inputs = list(
      Age = age,
      CD4 = cd4_count,
      HIV_RNA = hiv_rna,
      Hemoglobin = hemoglobin,
      Platelets = platelets,
      AST = ast,
      ALT = alt,
      Creatinine = creatinine,
      HCV_Status = hepatitis_c_positive == 1
    )
  ))
}

vacs_2_0_index <- function(age, cd4_count, hiv_rna, hemoglobin, fib4_index, egfr, hepatitis_c_positive, albumin, wbc_count, bmi, sex = "male", race = "other") {

  age <- as.numeric(age)
  cd4_count <- as.numeric(cd4_count)
  hiv_rna <- as.numeric(hiv_rna)
  hemoglobin <- as.numeric(hemoglobin)
  fib4_index <- as.numeric(fib4_index)
  egfr <- as.numeric(egfr)
  hepatitis_c_positive <- as.numeric(hepatitis_c_positive)
  albumin <- as.numeric(albumin)
  wbc_count <- as.numeric(wbc_count)
  bmi <- as.numeric(bmi)
  sex <- tolower(as.character(sex))
  race <- tolower(as.character(race))

  if (any(is.na(c(age, cd4_count, hiv_rna, hemoglobin, fib4_index, egfr, hepatitis_c_positive, albumin, wbc_count, bmi)))) {
    stop("Error: All clinical and laboratory inputs must be numeric.")
  }

  intercept <- -7.449

  beta_age <- 0.056
  term_age <- beta_age * (age - 50)

  beta_cd4 <- -0.056
  beta_cd4_sq <- 0.024
  term_cd4 <- (beta_cd4 * (min(cd4_count, 500) / 100)) + (beta_cd4_sq * (((min(cd4_count, 500) - 200) / 100)^2))

  beta_rna <- 0.513
  term_rna <- beta_rna * log10(max(hiv_rna, 1) + 1)

  beta_hgb <- -0.153
  beta_hgb_sq <- 0.024
  term_hgb <- (beta_hgb * (hemoglobin - 13)) + (beta_hgb_sq * ((hemoglobin - 13)^2))

  beta_fib4 <- 0.416
  term_fib4 <- beta_fib4 * log(fib4_index + 1)

  beta_egfr <- -0.009
  beta_egfr_sq <- -0.031
  term_egfr <- (beta_egfr * (min(egfr, 180) / 10)) + (beta_egfr_sq * (((min(egfr, 180) - 65) / 10)^2))

  beta_hcv <- 0.186
  term_hcv <- beta_hcv * hepatitis_c_positive

  beta_alb <- -0.661
  term_alb <- beta_alb * (albumin - 3.5)

  beta_wbc <- 0.457
  term_wbc <- beta_wbc * log(wbc_count / 6)

  beta_bmi <- -0.112
  term_bmi <- beta_bmi * (bmi - 25)

  log_hazard <- intercept + term_age + term_cd4 + term_rna + term_hgb + term_fib4 + term_egfr + term_hcv + term_alb + term_wbc + term_bmi

  vacs_2_score <- 100 * (log_hazard - (-10.45)) / (0.04)

  mortality_5yr <- (1 - (0.92 ^ exp(log_hazard))) * 100

  return(list(
    VACS_2_0_Index = round(vacs_2_score, 0),
    Est_5_Year_Mortality = paste0(round(mortality_5yr, 1), "%"),
    Inputs = list(
      Age = age,
      CD4 = cd4_count,
      HIV_RNA = hiv_rna,
      Hemoglobin = hemoglobin,
      FIB_4 = fib4_index,
      eGFR = egfr,
      HCV_Status = hepatitis_c_positive == 1,
      Albumin = albumin,
      WBC = wbc_count,
      BMI = bmi
    )
  ))
}

vacs_cci_score <- function(age, sex, metastatic_cancer, aids, mild_liver_disease, moderate_severe_liver_disease, chronic_pulmonary_disease, dementia, hemiplegia, severe_kidney_disease, mild_kidney_disease, history_mi, congestive_heart_failure, peripheral_vascular_disease, cerebrovascular_disease, peptic_ulcer_disease, diabetes_uncomplicated, diabetes_complicated, rheumatic_disease, non_metastatic_cancer) {

  age <- as.numeric(age)
  sex <- tolower(as.character(sex))
  metastatic_cancer <- as.numeric(metastatic_cancer)
  aids <- as.numeric(aids)
  mild_liver_disease <- as.numeric(mild_liver_disease)
  moderate_severe_liver_disease <- as.numeric(moderate_severe_liver_disease)
  chronic_pulmonary_disease <- as.numeric(chronic_pulmonary_disease)
  dementia <- as.numeric(dementia)
  hemiplegia <- as.numeric(hemiplegia)
  severe_kidney_disease <- as.numeric(severe_kidney_disease)
  mild_kidney_disease <- as.numeric(mild_kidney_disease)
  history_mi <- as.numeric(history_mi)
  congestive_heart_failure <- as.numeric(congestive_heart_failure)
  peripheral_vascular_disease <- as.numeric(peripheral_vascular_disease)
  cerebrovascular_disease <- as.numeric(cerebrovascular_disease)
  peptic_ulcer_disease <- as.numeric(peptic_ulcer_disease)
  diabetes_uncomplicated <- as.numeric(diabetes_uncomplicated)
  diabetes_complicated <- as.numeric(diabetes_complicated)
  rheumatic_disease <- as.numeric(rheumatic_disease)
  non_metastatic_cancer <- as.numeric(non_metastatic_cancer)

  if (any(is.na(c(age, metastatic_cancer, aids, mild_liver_disease, moderate_severe_liver_disease, chronic_pulmonary_disease, dementia, hemiplegia, severe_kidney_disease, mild_kidney_disease, history_mi, congestive_heart_failure, peripheral_vascular_disease, cerebrovascular_disease, peptic_ulcer_disease, diabetes_uncomplicated, diabetes_complicated, rheumatic_disease, non_metastatic_cancer)))) {
    stop("Error: All inputs must be numeric (0 or 1).")
  }

  if (!sex %in% c("male", "female")) {
    stop("Error: Sex must be 'male' or 'female'.")
  }

  score <- 0

  if (metastatic_cancer == 1) score <- score + 6

  if (aids == 1) score <- score + 6

  if (moderate_severe_liver_disease == 1) score <- score + 3

  if (mild_liver_disease == 1 && moderate_severe_liver_disease == 0) score <- score + 2 # Assuming hierarchy: if severe, mild not counted additionally unless distinct

  if (diabetes_complicated == 1) score <- score + 2

  if (hemiplegia == 1) score <- score + 2

  if (severe_kidney_disease == 1) score <- score + 2

  if (non_metastatic_cancer == 1 && metastatic_cancer == 0) score <- score + 2

  if (diabetes_uncomplicated == 1 && diabetes_complicated == 0) score <- score + 1

  if (chronic_pulmonary_disease == 1) score <- score + 1

  if (dementia == 1) score <- score + 1

  if (history_mi == 1) score <- score + 1

  if (congestive_heart_failure == 1) score <- score + 1

  if (peripheral_vascular_disease == 1) score <- score + 1

  if (cerebrovascular_disease == 1) score <- score + 1

  if (peptic_ulcer_disease == 1) score <- score + 1

  if (rheumatic_disease == 1) score <- score + 1

  if (mild_kidney_disease == 1 && severe_kidney_disease == 0) score <- score + 1 # VACS-CCI specific logic often includes this differentiation

  if (age >= 50 && age <= 59) score <- score + 1
  else if (age >= 60 && age <= 69) score <- score + 2
  else if (age >= 70 && age <= 79) score <- score + 3
  else if (age >= 80) score <- score + 4

  return(list(
    VACS_CCI_Score = score,
    Interpretation = "Higher scores indicate increased 5-year and 10-year all-cause mortality risk in HIV+ patients and general populations.",
    Inputs = list(
      Age = age,
      Sex = sex,
      Metastatic_Cancer = metastatic_cancer == 1,
      AIDS = aids == 1,
      Liver_Disease = ifelse(moderate_severe_liver_disease == 1, "Severe", ifelse(mild_liver_disease == 1, "Mild", "None")),
      Diabetes = ifelse(diabetes_complicated == 1, "Complicated", ifelse(diabetes_uncomplicated == 1, "Uncomplicated", "None")),
      Kidney_Disease = ifelse(severe_kidney_disease == 1, "Severe", ifelse(mild_kidney_disease == 1, "Mild", "None"))
    )
  ))
}

vaco_index_score <- function(age, sex, myocardial_infarction, congestive_heart_failure, peripheral_vascular_disease, cerebrovascular_disease, dementia, chronic_pulmonary_disease, rheumatologic_disease, peptic_ulcer_disease, liver_disease, diabetes, hemiplegia, renal_disease, cancer, aids) {

  age <- as.numeric(age)
  sex <- tolower(as.character(sex))
  myocardial_infarction <- as.numeric(myocardial_infarction)
  congestive_heart_failure <- as.numeric(congestive_heart_failure)
  peripheral_vascular_disease <- as.numeric(peripheral_vascular_disease)
  cerebrovascular_disease <- as.numeric(cerebrovascular_disease)
  dementia <- as.numeric(dementia)
  chronic_pulmonary_disease <- as.numeric(chronic_pulmonary_disease)
  rheumatologic_disease <- as.numeric(rheumatologic_disease)
  peptic_ulcer_disease <- as.numeric(peptic_ulcer_disease)
  liver_disease <- tolower(as.character(liver_disease))
  diabetes <- tolower(as.character(diabetes))
  hemiplegia <- as.numeric(hemiplegia)
  renal_disease <- as.numeric(renal_disease)
  cancer <- tolower(as.character(cancer))
  aids <- as.numeric(aids)

  if (any(is.na(c(age, myocardial_infarction, congestive_heart_failure, peripheral_vascular_disease, cerebrovascular_disease, dementia, chronic_pulmonary_disease, rheumatologic_disease, peptic_ulcer_disease, hemiplegia, renal_disease, aids)))) {
    stop("Error: All numeric/binary inputs must be valid.")
  }

  if (!sex %in% c("male", "female")) {
    stop("Error: Sex must be 'male' or 'female'.")
  }

  if (!liver_disease %in% c("none", "mild", "moderate_severe")) {
    stop("Error: Liver disease must be 'none', 'mild', or 'moderate_severe'.")
  }

  if (!diabetes %in% c("none", "uncomplicated", "complicated")) {
    stop("Error: Diabetes must be 'none', 'uncomplicated', or 'complicated'.")
  }

  if (!cancer %in% c("none", "localized", "metastatic")) {
    stop("Error: Cancer must be 'none', 'localized', or 'metastatic'.")
  }

  cci_score <- 0

  if (myocardial_infarction == 1) cci_score <- cci_score + 1
  if (congestive_heart_failure == 1) cci_score <- cci_score + 1
  if (peripheral_vascular_disease == 1) cci_score <- cci_score + 1
  if (cerebrovascular_disease == 1) cci_score <- cci_score + 1
  if (dementia == 1) cci_score <- cci_score + 1
  if (chronic_pulmonary_disease == 1) cci_score <- cci_score + 1
  if (rheumatologic_disease == 1) cci_score <- cci_score + 1
  if (peptic_ulcer_disease == 1) cci_score <- cci_score + 1

  if (liver_disease == "mild") cci_score <- cci_score + 1
  else if (liver_disease == "moderate_severe") cci_score <- cci_score + 3

  if (diabetes == "uncomplicated") cci_score <- cci_score + 1
  else if (diabetes == "complicated") cci_score <- cci_score + 2

  if (hemiplegia == 1) cci_score <- cci_score + 2
  if (renal_disease == 1) cci_score <- cci_score + 2

  if (cancer == "localized") cci_score <- cci_score + 2
  else if (cancer == "metastatic") cci_score <- cci_score + 6

  if (aids == 1) cci_score <- cci_score + 6

  male_val <- if (sex == "male") 1 else 0
  age_term <- age - 60

  linear_predictor <- -3.881 + (0.0625 * age_term) + (0.4215 * male_val) + (0.1356 * cci_score) - (0.0019 * age_term * cci_score)

  mortality_30_day <- 1 / (1 + exp(-linear_predictor))
  mortality_percent <- mortality_30_day * 100

  return(list(
    VACO_Index_Mortality_30_Day = paste0(round(mortality_percent, 1), "%"),
    Inputs = list(
      Age = age,
      Sex = sex,
      CCI_Score = cci_score,
      Comorbidities = list(
        MI = myocardial_infarction == 1,
        CHF = congestive_heart_failure == 1,
        PVD = peripheral_vascular_disease == 1,
        CVA = cerebrovascular_disease == 1,
        Dementia = dementia == 1,
        COPD = chronic_pulmonary_disease == 1,
        Rheum = rheumatologic_disease == 1,
        PUD = peptic_ulcer_disease == 1,
        Liver = liver_disease,
        Diabetes = diabetes,
        Hemiplegia = hemiplegia == 1,
        Renal = renal_disease == 1,
        Cancer = cancer,
        AIDS = aids == 1
      )
    )
  ))
}

villalta_pts_score <- function(pain, cramps, heaviness, paresthesia, pruritus, pretibial_edema, skin_induration, hyperpigmentation, redness, venous_ectasia, pain_on_calf_compression, venous_ulcer_present) {

  inputs_severity <- c(pain, cramps, heaviness, paresthesia, pruritus, pretibial_edema, skin_induration, hyperpigmentation, redness, venous_ectasia, pain_on_calf_compression)

  if (any(is.na(c(inputs_severity, venous_ulcer_present)))) {
    stop("Error: All inputs must be numeric.")
  }

  if (any(inputs_severity < 0) || any(inputs_severity > 3)) {
    stop("Error: Symptom and sign scores must be integers between 0 and 3.")
  }

  total_score <- sum(inputs_severity)

  severity_classification <- ""

  if (venous_ulcer_present == 1) {
    severity_classification <- "Severe PTS (Ulcer Present)"
  } else {
    if (total_score < 5) {
      severity_classification <- "No PTS / Absent"
    } else if (total_score <= 9) {
      severity_classification <- "Mild PTS"
    } else if (total_score <= 14) {
      severity_classification <- "Moderate PTS"
    } else {
      severity_classification <- "Severe PTS"
    }
  }

  return(list(
    Villalta_Score = total_score,
    Classification = severity_classification,
    Inputs = list(
      Symptoms = list(Pain=pain, Cramps=cramps, Heaviness=heaviness, Paresthesia=paresthesia, Pruritus=pruritus),
      Signs = list(Edema=pretibial_edema, Induration=skin_induration, Hyperpigmentation=hyperpigmentation, Redness=redness, Ectasia=venous_ectasia, Calf_Pain=pain_on_calf_compression),
      Ulcer_Present = venous_ulcer_present == 1
    )
  ))
}

virsta_score <- function(cerebral_emboli, meningitis, permanent_intracardiac_device, history_infective_endocarditis, vertebral_osteomyelitis, preexisting_native_valve_disease, intravenous_drug_use, severe_sepsis_shock, crp_mg_l, community_acquired) {

  cerebral_emboli <- as.numeric(cerebral_emboli)
  meningitis <- as.numeric(meningitis)
  permanent_intracardiac_device <- as.numeric(permanent_intracardiac_device)
  history_infective_endocarditis <- as.numeric(history_infective_endocarditis)
  vertebral_osteomyelitis <- as.numeric(vertebral_osteomyelitis)
  preexisting_native_valve_disease <- as.numeric(preexisting_native_valve_disease)
  intravenous_drug_use <- as.numeric(intravenous_drug_use)
  severe_sepsis_shock <- as.numeric(severe_sepsis_shock)
  crp_mg_l <- as.numeric(crp_mg_l)
  community_acquired <- as.numeric(community_acquired)

  if (any(is.na(c(cerebral_emboli, meningitis, permanent_intracardiac_device, history_infective_endocarditis, vertebral_osteomyelitis, preexisting_native_valve_disease, intravenous_drug_use, severe_sepsis_shock, crp_mg_l, community_acquired)))) {
    stop("Error: All inputs must be numeric.")
  }

  score <- 0

  if (cerebral_emboli == 1) score <- score + 5
  if (meningitis == 1) score <- score + 4
  if (permanent_intracardiac_device == 1) score <- score + 4
  if (history_infective_endocarditis == 1) score <- score + 3
  if (vertebral_osteomyelitis == 1) score <- score + 3
  if (preexisting_native_valve_disease == 1) score <- score + 3
  if (intravenous_drug_use == 1) score <- score + 2
  if (severe_sepsis_shock == 1) score <- score + 1
  if (crp_mg_l >= 190.0) score <- score + 2
  if (community_acquired == 1) score <- score + 1

  risk_category <- ""
  recommendation <- ""

  if (score <= 2) {
    risk_category <- "Low Risk"
    recommendation <- "Low probability of Infective Endocarditis (NPV ~99%). Transesophageal Echocardiography (TEE) may not be necessary."
  } else {
    risk_category <- "High Risk"
    recommendation <- "High probability of Infective Endocarditis. Transesophageal Echocardiography (TEE) is recommended."
  }

  return(list(
    VIRSTA_Score = score,
    Risk_Category = risk_category,
    Recommendation = recommendation,
    Inputs = list(
      Cerebral_Emboli = cerebral_emboli == 1,
      Meningitis = meningitis == 1,
      Cardiac_Device = permanent_intracardiac_device == 1,
      Hx_IE = history_infective_endocarditis == 1,
      Osteomyelitis = vertebral_osteomyelitis == 1,
      Valve_Disease = preexisting_native_valve_disease == 1,
      IVDU = intravenous_drug_use == 1,
      Sepsis = severe_sepsis_shock == 1,
      CRP_High = crp_mg_l >= 190,
      Community_Acquired = community_acquired == 1
    )
  ))
}

visual_acuity_converter <- function(snellen_denominator) {

  snellen_denominator <- as.numeric(snellen_denominator)

  if (is.na(snellen_denominator) || snellen_denominator <= 0) {
    stop("Error: Snellen denominator must be a positive number.")
  }

  decimal_acuity <- 20 / snellen_denominator

  metric_denominator <- snellen_denominator * 0.3

  log_mar <- -log10(decimal_acuity)

  return(list(
    Snellen_Imperial = paste0("20/", snellen_denominator),
    Snellen_Metric = paste0("6/", round(metric_denominator, 1)),
    Decimal = round(decimal_acuity, 3),
    LogMAR = round(log_mar, 2)
  ))
}

vte_bleed_score <- function(active_cancer, sex, uncontrolled_hypertension, anemia, history_of_bleeding, age, renal_dysfunction) {

  active_cancer <- as.numeric(active_cancer)
  sex <- tolower(as.character(sex))
  uncontrolled_hypertension <- as.numeric(uncontrolled_hypertension)
  anemia <- as.numeric(anemia)
  history_of_bleeding <- as.numeric(history_of_bleeding)
  age <- as.numeric(age)
  renal_dysfunction <- as.numeric(renal_dysfunction)

  if (any(is.na(c(active_cancer, uncontrolled_hypertension, anemia, history_of_bleeding, age, renal_dysfunction)))) {
    stop("Error: All numeric/binary inputs must be valid.")
  }

  if (!sex %in% c("male", "female")) {
    stop("Error: Sex must be 'male' or 'female'.")
  }

  score <- 0

  if (active_cancer == 1) {
    score <- score + 2
  }

  if (sex == "male" && uncontrolled_hypertension == 1) {
    score <- score + 1
  }

  if (anemia == 1) {
    score <- score + 1.5
  }

  if (history_of_bleeding == 1) {
    score <- score + 1.5
  }

  if (age >= 60) {
    score <- score + 1.5
  }

  if (renal_dysfunction == 1) {
    score <- score + 1.5
  }

  risk_category <- ""
  bleeding_rate <- ""

  if (score < 2) {
    risk_category <- "Low Risk"
    bleeding_rate <- "2.8% (Lower risk of major bleeding)"
  } else {
    risk_category <- "High Risk"
    bleeding_rate <- "12.6% (Higher risk of major bleeding)"
  }

  return(list(
    VTE_BLEED_Score = score,
    Risk_Category = risk_category,
    Observed_Bleeding_Rate = bleeding_rate,
    Inputs = list(
      Active_Cancer = active_cancer == 1,
      Male_with_HTN = (sex == "male" && uncontrolled_hypertension == 1),
      Anemia = anemia == 1,
      History_Bleeding = history_of_bleeding == 1,
      Age_ge_60 = age >= 60,
      Renal_Dysfunction = renal_dysfunction == 1
    )
  ))
}

webster_parkinsons_scale <- function(bradykinesia, rigidity, posture, upper_extremity_swing, gait, tremor, facies, seborrhea, speech, self_care) {

  inputs <- c(bradykinesia, rigidity, posture, upper_extremity_swing, gait, tremor, facies, seborrhea, speech, self_care)

  if (any(is.na(inputs))) {
    stop("Error: All inputs must be numeric.")
  }

  if (any(inputs < 0) || any(inputs > 3)) {
    stop("Error: All item scores must be integers between 0 and 3.")
  }

  total_score <- sum(inputs)

  severity <- ""
  if (total_score <= 10) {
    severity <- "Early Illness"
  } else if (total_score <= 20) {
    severity <- "Moderate Disability"
  } else {
    severity <- "Severe or Advanced Disease"
  }

  return(list(
    Webster_Score = total_score,
    Severity_Classification = severity,
    Inputs = list(
      Bradykinesia = bradykinesia,
      Rigidity = rigidity,
      Posture = posture,
      Arm_Swing = upper_extremity_swing,
      Gait = gait,
      Tremor = tremor,
      Facies = facies,
      Seborrhea = seborrhea,
      Speech = speech,
      Self_Care = self_care
    )
  ))
}

levothyroxine_dosing_calculator <- function(weight_kg, age_years, history_cad, pregnant_trimester = "not_pregnant", tsh_level = NA) {

  weight_kg <- as.numeric(weight_kg)
  age_years <- as.numeric(age_years)
  history_cad <- as.numeric(history_cad)
  pregnant_trimester <- tolower(as.character(pregnant_trimester))
  tsh_level <- as.numeric(tsh_level)

  if (any(is.na(c(weight_kg, age_years, history_cad)))) {
    stop("Error: Weight, Age, and CAD history must be valid inputs.")
  }

  if (weight_kg <= 0) {
    stop("Error: Weight must be positive.")
  }

  dose_mcg_day <- 0
  guidance <- ""

  if (history_cad == 1) {
    dose_mcg_day <- 12.5
    guidance <- "Start low (12.5-25 mcg) due to CAD history. Titrate slowly."
  } else if (age_years > 60) {
    dose_mcg_day <- 25
    guidance <- "Start lower (25-50 mcg) due to age. Titrate based on TSH."
  } else if (pregnant_trimester != "not_pregnant") {
    guidance <- "Pregnancy increases requirements. Consult specific guidelines. Generally start higher."
    dose_mcg_day <- 1.6 * weight_kg
  } else {
    if (!is.na(tsh_level) && tsh_level > 10) {
      dose_mcg_day <- 1.6 * weight_kg
      guidance <- "Full replacement dose (1.6 mcg/kg) recommended for overt hypothyroidism."
    } else if (!is.na(tsh_level) && tsh_level <= 10) {
      dose_mcg_day <- 25
      guidance <- "Subclinical Hypothyroidism: Start low (25-50 mcg) if treatment indicated."
    } else {
      dose_mcg_day <- 1.6 * weight_kg
      guidance <- "Standard full replacement dose (1.6 mcg/kg) assuming overt hypothyroidism."
    }
  }

  return(list(
    Recommended_Starting_Dose_mcg = round(dose_mcg_day, 1),
    Guidance = guidance,
    Inputs = list(
      Weight_kg = weight_kg,
      Age = age_years,
      History_CAD = history_cad == 1,
      Pregnancy = pregnant_trimester
    )
  ))
}

wells_dvt_score <- function(active_cancer, paralysis_paresis, bedridden_recently_surgery, localized_tenderness, entire_leg_swollen, calf_swelling_gt_3cm, pitting_edema, collateral_superficial_veins, history_dvt, alternative_diagnosis_likely) {

  active_cancer <- as.numeric(active_cancer)
  paralysis_paresis <- as.numeric(paralysis_paresis)
  bedridden_recently_surgery <- as.numeric(bedridden_recently_surgery)
  localized_tenderness <- as.numeric(localized_tenderness)
  entire_leg_swollen <- as.numeric(entire_leg_swollen)
  calf_swelling_gt_3cm <- as.numeric(calf_swelling_gt_3cm)
  pitting_edema <- as.numeric(pitting_edema)
  collateral_superficial_veins <- as.numeric(collateral_superficial_veins)
  history_dvt <- as.numeric(history_dvt)
  alternative_diagnosis_likely <- as.numeric(alternative_diagnosis_likely)

  if (any(is.na(c(active_cancer, paralysis_paresis, bedridden_recently_surgery, localized_tenderness, entire_leg_swollen, calf_swelling_gt_3cm, pitting_edema, collateral_superficial_veins, history_dvt, alternative_diagnosis_likely)))) {
    stop("Error: All inputs must be numeric.")
  }

  score <- 0

  if (active_cancer == 1) score <- score + 1
  if (paralysis_paresis == 1) score <- score + 1
  if (bedridden_recently_surgery == 1) score <- score + 1
  if (localized_tenderness == 1) score <- score + 1
  if (entire_leg_swollen == 1) score <- score + 1
  if (calf_swelling_gt_3cm == 1) score <- score + 1
  if (pitting_edema == 1) score <- score + 1
  if (collateral_superficial_veins == 1) score <- score + 1
  if (history_dvt == 1) score <- score + 1
  if (alternative_diagnosis_likely == 1) score <- score - 2

  risk_category <- ""
  dvt_probability <- ""

  if (score >= 2) {
    risk_category <- "DVT Likely"
    dvt_probability <- "28%"
  } else {
    risk_category <- "DVT Unlikely"
    dvt_probability <- "6%"
  }

  return(list(
    Wells_Score = score,
    Risk_Category = risk_category,
    Probability = dvt_probability,
    Inputs = list(
      Cancer = active_cancer == 1,
      Paralysis = paralysis_paresis == 1,
      Bedridden_Surgery = bedridden_recently_surgery == 1,
      Tenderness = localized_tenderness == 1,
      Leg_Swollen = entire_leg_swollen == 1,
      Calf_Swelling = calf_swelling_gt_3cm == 1,
      Pitting_Edema = pitting_edema == 1,
      Collateral_Veins = collateral_superficial_veins == 1,
      History_DVT = history_dvt == 1,
      Alt_Diagnosis = alternative_diagnosis_likely == 1
    )
  ))
}

wells_pe_score <- function(clinical_signs_dvt, pe_number_one_diagnosis, heart_rate, immobilization_surgery, previous_pe_dvt, hemoptysis, malignancy) {

  clinical_signs_dvt <- as.numeric(clinical_signs_dvt)
  pe_number_one_diagnosis <- as.numeric(pe_number_one_diagnosis)
  heart_rate <- as.numeric(heart_rate)
  immobilization_surgery <- as.numeric(immobilization_surgery)
  previous_pe_dvt <- as.numeric(previous_pe_dvt)
  hemoptysis <- as.numeric(hemoptysis)
  malignancy <- as.numeric(malignancy)

  if (any(is.na(c(clinical_signs_dvt, pe_number_one_diagnosis, heart_rate, immobilization_surgery, previous_pe_dvt, hemoptysis, malignancy)))) {
    stop("Error: All inputs must be numeric.")
  }

  score <- 0

  if (clinical_signs_dvt == 1) score <- score + 3.0
  if (pe_number_one_diagnosis == 1) score <- score + 3.0
  if (heart_rate > 100) score <- score + 1.5
  if (immobilization_surgery == 1) score <- score + 1.5
  if (previous_pe_dvt == 1) score <- score + 1.5
  if (hemoptysis == 1) score <- score + 1.0
  if (malignancy == 1) score <- score + 1.0

  risk_3_tier <- ""
  if (score < 2) {
    risk_3_tier <- "Low Risk (1.3% risk)"
  } else if (score <= 6) {
    risk_3_tier <- "Moderate Risk (16.2% risk)"
  } else {
    risk_3_tier <- "High Risk (37.5% risk)"
  }

  risk_2_tier <- ""
  if (score <= 4) {
    risk_2_tier <- "PE Unlikely (12.1% risk)"
  } else {
    risk_2_tier <- "PE Likely (37.1% risk)"
  }

  return(list(
    Wells_Score = score,
    Risk_Tier_3 = risk_3_tier,
    Risk_Tier_2 = risk_2_tier,
    Inputs = list(
      Signs_DVT = clinical_signs_dvt == 1,
      PE_Likely = pe_number_one_diagnosis == 1,
      HR_gt_100 = heart_rate > 100,
      Immobile_Surgery = immobilization_surgery == 1,
      Prev_VTE = previous_pe_dvt == 1,
      Hemoptysis = hemoptysis == 1,
      Cancer = malignancy == 1
    )
  ))
}

hepatic_encephalopathy_grade <- function(consciousness, intellect, behavior, neuromuscular) {

  if (any(is.na(c(consciousness, intellect, behavior, neuromuscular)))) {
    stop("Error: All inputs must be numeric.")
  }

  if (any(c(consciousness, intellect, behavior, neuromuscular) < 0) || any(c(consciousness, intellect, behavior, neuromuscular) > 4)) {
    stop("Error: All inputs must be integers between 0 and 4.")
  }

  grade <- max(consciousness, intellect, behavior, neuromuscular)

  description <- ""

  if (grade == 0) {
    description <- "Grade 0: Normal consciousness, personality, and neurological exam. Minimal HE."
  } else if (grade == 1) {
    description <- "Grade 1: Mild confusion, euphoria or anxiety, shortened attention span, impaired addition/subtraction."
  } else if (grade == 2) {
    description <- "Grade 2: Lethargy, disorientation to time, inappropriate behavior, asterixis present."
  } else if (grade == 3) {
    description <- "Grade 3: Somnolence to semi-stupor, responsive to stimuli, confused, gross disorientation, asterixis usually present."
  } else {
    description <- "Grade 4: Coma, unresponsive to pain."
  }

  return(list(
    HE_Grade = grade,
    Description = description,
    Inputs = list(
      Consciousness = consciousness,
      Intellect = intellect,
      Behavior = behavior,
      Neuromuscular = neuromuscular
    )
  ))
}

westley_croup_score <- function(chest_wall_retractions, stridor, cyanosis, level_of_consciousness, air_entry) {

  chest_wall_retractions <- as.numeric(chest_wall_retractions)
  stridor <- as.numeric(stridor)
  cyanosis <- as.numeric(cyanosis)
  level_of_consciousness <- as.numeric(level_of_consciousness)
  air_entry <- as.numeric(air_entry)

  if (any(is.na(c(chest_wall_retractions, stridor, cyanosis, level_of_consciousness, air_entry)))) {
    stop("Error: All inputs must be numeric.")
  }

  if (chest_wall_retractions < 0 || chest_wall_retractions > 3) stop("Error: Retractions score must be 0-3.")
  if (stridor < 0 || stridor > 2) stop("Error: Stridor score must be 0-2.")
  if (cyanosis < 0 || cyanosis > 5) stop("Error: Cyanosis score must be 0-5.")
  if (level_of_consciousness < 0 || level_of_consciousness > 5) stop("Error: LOC score must be 0 or 5.")
  if (air_entry < 0 || air_entry > 2) stop("Error: Air entry score must be 0-2.")

  total_score <- chest_wall_retractions + stridor + cyanosis + level_of_consciousness + air_entry

  severity <- ""
  if (total_score <= 2) {
    severity <- "Mild Croup"
  } else if (total_score <= 5) {
    severity <- "Moderate Croup"
  } else if (total_score <= 11) {
    severity <- "Severe Croup"
  } else {
    severity <- "Impending Respiratory Failure"
  }

  return(list(
    Westley_Score = total_score,
    Severity_Classification = severity,
    Inputs = list(
      Retractions = chest_wall_retractions,
      Stridor = stridor,
      Cyanosis = cyanosis,
      LOC = level_of_consciousness,
      Air_Entry = air_entry
    )
  ))
}

wexner_ods_score <- function(bowel_movement_frequency, straining, sensation_incomplete_evacuation, use_of_enemas_laxatives, abdominal_pain, time_per_attempt_minutes, assistance_needed_per_attempt, unsuccessful_attempts_per_24h) {

