  assistance_needed_per_attempt <- as.numeric(assistance_needed_per_attempt)
  unsuccessful_attempts_per_24h <- as.numeric(unsuccessful_attempts_per_24h)

  if (any(is.na(c(bowel_movement_frequency, straining, sensation_incomplete_evacuation, use_of_enemas_laxatives, abdominal_pain, time_per_attempt_minutes, assistance_needed_per_attempt, unsuccessful_attempts_per_24h)))) {
