winters_formula <- function(bicarbonate, measured_paco2 = NULL) {

  bicarbonate <- as.numeric(bicarbonate)

  if (is.na(bicarbonate)) {
    stop("Error: Bicarbonate must be numeric.")
  }

  expected_paco2 <- (1.5 * bicarbonate) + 8
  lower_limit <- expected_paco2 - 2
  upper_limit <- expected_paco2 + 2

  interpretation <- "Input measured PaCO2 for compensation analysis."

  if (!is.null(measured_paco2)) {
    measured_paco2 <- as.numeric(measured_paco2)
    if (!is.na(measured_paco2)) {
      if (measured_paco2 < lower_limit) {
        interpretation <- "Concomitant Respiratory Alkalosis (PaCO2 lower than expected)"
      } else if (measured_paco2 > upper_limit) {
        interpretation <- "Concomitant Respiratory Acidosis (PaCO2 higher than expected)"
      } else {
        interpretation <- "Adequately Compensated Metabolic Acidosis"
      }
    }
  }

  return(list(
    Expected_PaCO2_Range_mmHg = paste(round(lower_limit, 1), "-", round(upper_limit, 1)),
    Interpretation = interpretation,
    Inputs = list(
      HCO3 = bicarbonate,
      PaCO2 = measured_paco2
    )
  ))
}

wisconsin_maxillofacial_criteria <- function(bony_stepoff_instability, periorbital_swelling, gcs_score, malocclusion, tooth_absence) {

  bony_stepoff_instability <- as.numeric(bony_stepoff_instability)
  periorbital_swelling <- as.numeric(periorbital_swelling)
  gcs_score <- as.numeric(gcs_score)
  malocclusion <- as.numeric(malocclusion)
  tooth_absence <- as.numeric(tooth_absence)

  if (any(is.na(c(bony_stepoff_instability, periorbital_swelling, gcs_score, malocclusion, tooth_absence)))) {
    stop("Error: All inputs must be numeric.")
  }

  if (gcs_score < 3 || gcs_score > 15) {
    stop("Error: GCS score must be between 3 and 15.")
  }

  criteria_met <- FALSE

  if (bony_stepoff_instability == 1) criteria_met <- TRUE
  if (periorbital_swelling == 1) criteria_met <- TRUE
  if (gcs_score < 14) criteria_met <- TRUE
  if (malocclusion == 1) criteria_met <- TRUE
  if (tooth_absence == 1) criteria_met <- TRUE

  recommendation <- ""
  if (criteria_met) {
    recommendation <- "CT Maxillofacial Indicated (High sensitivity for fracture)"
  } else {
    recommendation <- "CT Maxillofacial Not Indicated (Low risk of fracture)"
  }

  return(list(
    Result = recommendation,
    Criteria_Met = criteria_met,
    Inputs = list(
      Bony_Stepoff = bony_stepoff_instability == 1,
      Periorbital_Swelling = periorbital_swelling == 1,
      GCS_lt_14 = gcs_score < 14,
      Malocclusion = malocclusion == 1,
      Tooth_Absence = tooth_absence == 1
    )
  ))
}

wat1_pediatric_score <- function(loose_stools, vomiting_retching, temperature_gt_37_8, tremor, sweating, uncoordinated_movements, yawning_sneezing, startle_to_touch, muscle_tone, time_to_calm, agitation_state) {

  inputs <- c(loose_stools, vomiting_retching, temperature_gt_37_8, tremor, sweating, uncoordinated_movements, yawning_sneezing, startle_to_touch, muscle_tone, time_to_calm, agitation_state)

  if (any(is.na(inputs))) {
    stop("Error: All inputs must be numeric.")
  }

  score <- 0

  if (loose_stools == 1) score <- score + 1
  if (vomiting_retching == 1) score <- score + 1
  if (temperature_gt_37_8 == 1) score <- score + 1
  if (tremor == 1) score <- score + 1
  if (sweating == 1) score <- score + 1
  if (uncoordinated_movements == 1) score <- score + 1
  if (yawning_sneezing == 1) score <- score + 1
  if (startle_to_touch == 1) score <- score + 1
  if (muscle_tone == 1) score <- score + 1
  if (time_to_calm == 1) score <- score + 1

  if (agitation_state >= 1) {
    score <- score + 1
  }

  risk_category <- ""
  if (score >= 3) {
    risk_category <- "Withdrawal Symptoms Likely (Score >= 3)"
  } else {
    risk_category <- "No/Mild Withdrawal Symptoms"
  }

  return(list(
    WAT1_Score = score,
    Interpretation = risk_category,
    Inputs = list(
      Loose_Stools = loose_stools == 1,
      Vomiting = vomiting_retching == 1,
      Fever = temperature_gt_37_8 == 1,
      Tremor = tremor == 1,
      Sweating = sweating == 1,
      Uncoordinated = uncoordinated_movements == 1,
      Yawning = yawning_sneezing == 1,
      Startle = startle_to_touch == 1,
      Tone = muscle_tone == 1,
      Time_Calm = time_to_calm == 1,
      Agitation = agitation_state == 1
    )
  ))
}

wast_screening_tool <- function(tension_level, argument_difficulty, partner_abuse_history, partner_frightening, hit_kicked_punched, physical_abuse_outside, sexual_abuse_outside, sexual_abuse_current_partner) {

  tension_level <- as.numeric(tension_level)
  argument_difficulty <- as.numeric(argument_difficulty)
  partner_abuse_history <- as.numeric(partner_abuse_history)
  partner_frightening <- as.numeric(partner_frightening)
  hit_kicked_punched <- as.numeric(hit_kicked_punched)
  physical_abuse_outside <- as.numeric(physical_abuse_outside)
  sexual_abuse_outside <- as.numeric(sexual_abuse_outside)
  sexual_abuse_current_partner <- as.numeric(sexual_abuse_current_partner)

  if (any(is.na(c(tension_level, argument_difficulty, partner_abuse_history, partner_frightening, hit_kicked_punched, physical_abuse_outside, sexual_abuse_outside, sexual_abuse_current_partner)))) {
    stop("Error: All inputs must be numeric (0-2 for scale, 0-1 for binary).")
  }

  short_score <- 0
  if (tension_level == 2) short_score <- short_score + 1
  if (argument_difficulty == 2) short_score <- short_score + 1

  short_screen_positive <- short_score >= 1

  full_score <- short_score
  if (partner_abuse_history == 1) full_score <- full_score + 1
  if (partner_frightening == 1) full_score <- full_score + 1
  if (hit_kicked_punched == 1) full_score <- full_score + 1
  if (physical_abuse_outside == 1) full_score <- full_score + 1
  if (sexual_abuse_outside == 1) full_score <- full_score + 1
  if (sexual_abuse_current_partner == 1) full_score <- full_score + 1

  interpretation <- ""
  recommendation <- ""

  if (short_screen_positive) {
    interpretation <- "Short Screen Positive. Indicates potential relationship tension/difficulty."
    recommendation <- "Administer full WAST or further assessment for Intimate Partner Violence (IPV)."
  } else {
    interpretation <- "Short Screen Negative."
    recommendation <- "Routine care."
}

  return(list(
    WAST_Short_Result = interpretation,
    WAST_Total_Items_Positive = full_score,
    Recommendation = recommendation,
    Inputs = list(
      Tension = tension_level,
      Arguments = argument_difficulty,
      Abuse_History = partner_abuse_history,
      Frightened = partner_frightening,
      Physical_Violence = hit_kicked_punched,
      Outside_Physical = physical_abuse_outside,
      Outside_Sexual = sexual_abuse_outside,
      Partner_Sexual = sexual_abuse_current_partner
    )
  ))
}

who_pv_criteria <- function(sex, hemoglobin, hematocrit, red_cell_mass_elevated, bone_marrow_biopsy, jak2_mutation, serum_epo_low) {

  sex <- tolower(as.character(sex))
  hemoglobin <- as.numeric(hemoglobin)
  hematocrit <- as.numeric(hematocrit)
  red_cell_mass_elevated <- as.numeric(red_cell_mass_elevated)
  bone_marrow_biopsy <- as.numeric(bone_marrow_biopsy)
  jak2_mutation <- as.numeric(jak2_mutation)
  serum_epo_low <- as.numeric(serum_epo_low)

  if (any(is.na(c(hemoglobin, hematocrit, red_cell_mass_elevated, bone_marrow_biopsy, jak2_mutation, serum_epo_low)))) {
    stop("Error: All inputs must be numeric.")
  }

  if (!sex %in% c("male", "female")) {
    stop("Error: Sex must be 'male' or 'female'.")
  }

  major_1 <- FALSE
  if (red_cell_mass_elevated == 1) {
    major_1 <- TRUE
  } else {
    if (sex == "male") {
      if (hemoglobin > 16.5 || hematocrit > 49) {
        major_1 <- TRUE
      }
    } else {
      if (hemoglobin > 16.0 || hematocrit > 48) {
        major_1 <- TRUE
      }
    }
  }

  major_2 <- (bone_marrow_biopsy == 1)
  major_3 <- (jak2_mutation == 1)
  minor <- (serum_epo_low == 1)

  diagnosis_met <- FALSE

  if (major_1 && major_2 && major_3) {
    diagnosis_met <- TRUE
  } else if (major_1 && major_2 && minor) {
    diagnosis_met <- TRUE
  }

  if (!diagnosis_met) {
    if (sex == "male") {
      if (hemoglobin > 18.5 || hematocrit > 55.5) {
        if (major_3 && minor) {
          diagnosis_met <- TRUE
        }
      }
    } else {
      if (hemoglobin > 16.5 || hematocrit > 49.5) {
        if (major_3 && minor) {
          diagnosis_met <- TRUE
        }
      }
    }
  }

  result <- if (diagnosis_met) "Criteria Met for Polycythemia Vera" else "Criteria Not Met"

  return(list(
    Diagnosis = result,
    Criteria_Status = list(
      Major_1_Blood_Volume = major_1,
      Major_2_Bone_Marrow = major_2,
      Major_3_JAK2 = major_3,
      Minor_EPO = minor
    )
  ))
}

who_sm_criteria <- function(bone_marrow_aggregates, aberrant_cd25_expression, kit_d816v_mutation, serum_tryptase_elevated, spindle_cells_abnormal) {

  bone_marrow_aggregates <- as.numeric(bone_marrow_aggregates)
  aberrant_cd25_expression <- as.numeric(aberrant_cd25_expression)
  kit_d816v_mutation <- as.numeric(kit_d816v_mutation)
  serum_tryptase_elevated <- as.numeric(serum_tryptase_elevated)
  spindle_cells_abnormal <- as.numeric(spindle_cells_abnormal)

  if (any(is.na(c(bone_marrow_aggregates, aberrant_cd25_expression, kit_d816v_mutation, serum_tryptase_elevated, spindle_cells_abnormal)))) {
    stop("Error: All inputs must be numeric (0 or 1).")
  }

  major_criterion <- (bone_marrow_aggregates == 1)

  minor_count <- 0
  if (aberrant_cd25_expression == 1) minor_count <- minor_count + 1
  if (kit_d816v_mutation == 1) minor_count <- minor_count + 1
  if (serum_tryptase_elevated == 1) minor_count <- minor_count + 1
  if (spindle_cells_abnormal == 1) minor_count <- minor_count + 1

  diagnosis_met <- FALSE
  if (major_criterion && minor_count >= 1) {
    diagnosis_met <- TRUE
  } else if (minor_count >= 3) {
    diagnosis_met <- TRUE
  }

  result <- if (diagnosis_met) "Criteria Met for Systemic Mastocytosis" else "Criteria Not Met"

  return(list(
    Diagnosis = result,
    Criteria_Status = list(
      Major_Criterion = major_criterion,
      Minor_Criteria_Count = minor_count
    )
  ))
}

wound_closure_classification <- function(wound_status) {

  wound_status <- tolower(as.character(wound_status))

  valid_statuses <- c("primary", "secondary", "tertiary")

  if (!wound_status %in% valid_statuses) {
    stop("Error: wound_status must be one of: 'primary', 'secondary', or 'tertiary'.")
  }

  classification <- ""
  description <- ""
  examples <- ""

  if (wound_status == "primary") {
    classification <- "Primary Intention (Primary Closure)"
    description <- "Wound edges are brought together (approximated) and closed with sutures, staples, or adhesive strips. Healing occurs quickly with minimal scarring."
    examples <- "Clean surgical incisions, simple lacerations repair."
  } else if (wound_status == "secondary") {
    classification <- "Secondary Intention"
    description <- "Wound is left open and allowed to heal from the bottom up through granulation tissue formation, contraction, and epithelialization. Used for wounds with tissue loss or infection risk."
    examples <- "Pressure ulcers, severe burns, infected wounds, dehisced surgical wounds."
  } else if (wound_status == "tertiary") {
    classification <- "Tertiary Intention (Delayed Primary Closure)"
    description <- "Wound is initially left open to allow for debridement or treatment of infection/edema, then closed primarily after a few days (typically 3-5 days) once granulation tissue appears and the risk of infection is low."
    examples <- "Contaminated wounds, dog bites, wounds requiring serial debridement."
  }

  return(list(
    Classification_Type = classification,
    Description = description,
    Examples = examples,
    Input_Code = wound_status
  ))
}

wifi_classification <- function(wound_grade, ischemia_grade, infection_grade) {

  wound_grade <- as.numeric(wound_grade)
  ischemia_grade <- as.numeric(ischemia_grade)
  infection_grade <- as.numeric(infection_grade)

  if (any(is.na(c(wound_grade, ischemia_grade, infection_grade)))) {
    stop("Error: All inputs must be numeric.")
  }

  if (any(c(wound_grade, ischemia_grade, infection_grade) < 0) ||
      any(c(wound_grade, ischemia_grade, infection_grade) > 3)) {
    stop("Error: Grades must be integers between 0 and 3.")
  }

  clinical_stage <- 0
  amputation_risk_1yr <- "Very Low"
  revasc_benefit <- "Very Low"

  risk_category <- 1

  if (infection_grade == 3 || ischemia_grade == 3 || (wound_grade == 3 && ischemia_grade >= 2)) {
    risk_category <- 4
  } else if ((wound_grade == 3 && ischemia_grade == 1) || (wound_grade == 2 && ischemia_grade == 2) || (wound_grade == 1 && ischemia_grade == 3) || (infection_grade == 2 && ischemia_grade >= 2)) {
    risk_category <- 3
  } else if (wound_grade > 0 || ischemia_grade > 0 || infection_grade > 0) {
    if (wound_grade == 2 || ischemia_grade == 2 || infection_grade == 2) {
      if (risk_category < 3) risk_category <- 2
    }
    if (risk_category == 1 && (wound_grade + ischemia_grade + infection_grade >= 2)) {
      risk_category <- 2
    }
  }

  if (wound_grade == 3 && ischemia_grade == 0 && infection_grade == 0) risk_category <- 3

  if (risk_category == 1) {
    amputation_risk_1yr <- "Very Low"
    revasc_benefit <- "Very Low"
    clinical_stage <- 1
  } else if (risk_category == 2) {
    amputation_risk_1yr <- "Low"
    revasc_benefit <- "Low"
    clinical_stage <- 2
  } else if (risk_category == 3) {
    amputation_risk_1yr <- "Moderate"
    revasc_benefit <- "High"
    clinical_stage <- 3
  } else {
    amputation_risk_1yr <- "High"
    revasc_benefit <- "High"
    clinical_stage <- 4
  }

  return(list(
    WIfI_Stage = clinical_stage,
    Amputation_Risk_1_Year = amputation_risk_1yr,
    Revascularization_Benefit = revasc_benefit,
    Inputs = list(
      Wound = wound_grade,
      Ischemia = ischemia_grade,
      Infection = infection_grade
    )
  ))
}

wpss_score <- function(who_classification, karyotype, transfusion_requirement) {

  who_classification <- tolower(as.character(who_classification))
  karyotype <- tolower(as.character(karyotype))
  transfusion_requirement <- tolower(as.character(transfusion_requirement))

  valid_who <- c("rcud_rars_rcmd", "raeb_1", "raeb_2")
  if (!who_classification %in% valid_who) {
    stop("Error: who_classification must be 'rcud_rars_rcmd', 'raeb_1', or 'raeb_2'.")
  }

  valid_karyotype <- c("good", "intermediate", "poor")
  if (!karyotype %in% valid_karyotype) {
    stop("Error: karyotype must be 'good', 'intermediate', or 'poor'.")
  }

  valid_transfusion <- c("no", "regular")
  if (!transfusion_requirement %in% valid_transfusion) {
    stop("Error: transfusion_requirement must be 'no' or 'regular'.")
  }

  score <- 0

  if (who_classification == "raeb_1") {
    score <- score + 1
  } else if (who_classification == "raeb_2") {
    score <- score + 2
  }

  if (karyotype == "intermediate") {
    score <- score + 1
  } else if (karyotype == "poor") {
    score <- score + 2
  }

  if (transfusion_requirement == "regular") {
    score <- score + 1
  }

  risk_group <- ""
  median_survival <- ""
  aml_risk_2yr <- ""

  if (score == 0) {
    risk_group <- "Very Low"
    median_survival <- "141 months"
    aml_risk_2yr <- "2%"
  } else if (score == 1) {
    risk_group <- "Low"
    median_survival <- "66 months"
    aml_risk_2yr <- "8%"
  } else if (score == 2) {
    risk_group <- "Intermediate"
    median_survival <- "48 months"
    aml_risk_2yr <- "19%"
  } else if (score >= 3 && score <= 4) {
    risk_group <- "High"
    median_survival <- "26 months"
    aml_risk_2yr <- "42%"
  } else {
    risk_group <- "Very High"
    median_survival <- "9 months"
    aml_risk_2yr <- "84%"
  }

  return(list(
    WPSS_Score = score,
    Risk_Group = risk_group,
    Median_Survival = median_survival,
    AML_Progression_Risk_2yr = aml_risk_2yr,
    Inputs = list(
      WHO_Class = who_classification,
      Karyotype = karyotype,
      Transfusion = transfusion_requirement
    )
  ))
}

nrs_2002_score <- function(nutritional_score, disease_severity_score, age) {

  nutritional_score <- as.numeric(nutritional_score)
  disease_severity_score <- as.numeric(disease_severity_score)
  age <- as.numeric(age)

  if (any(is.na(c(nutritional_score, disease_severity_score, age)))) {
    stop("Error: All inputs must be numeric.")
  }

  if (nutritional_score < 0 || nutritional_score > 3) {
    stop("Error: Nutritional score must be between 0 and 3.")
  }

  if (disease_severity_score < 0 || disease_severity_score > 3) {
    stop("Error: Disease severity score must be between 0 and 3.")
  }

  total_score <- nutritional_score + disease_severity_score

  if (age >= 70) {
    total_score <- total_score + 1
  }

  interpretation <- ""
  if (total_score >= 3) {
    interpretation <- "At nutritional risk. Initiate nutritional care plan."
  } else {
    interpretation <- "Not at nutritional risk. Rescreen weekly."
  }

  return(list(
    NRS_2002_Score = total_score,
    Interpretation = interpretation,
    Inputs = list(
      Nutritional_Score = nutritional_score,
      Disease_Severity_Score = disease_severity_score,
      Age = age
    )
  ))
}

nri_score <- function(albumin_g_dl, current_weight_kg, usual_weight_kg) {

  albumin_g_dl <- as.numeric(albumin_g_dl)
  current_weight_kg <- as.numeric(current_weight_kg)
  usual_weight_kg <- as.numeric(usual_weight_kg)

  if (any(is.na(c(albumin_g_dl, current_weight_kg, usual_weight_kg)))) {
    stop("Error: All inputs must be numeric.")
  }

  if (albumin_g_dl <= 0 || current_weight_kg <= 0 || usual_weight_kg <= 0) {
    stop("Error: Inputs must be positive values.")
  }

  albumin_g_l <- albumin_g_dl * 10

  weight_ratio <- current_weight_kg / usual_weight_kg

  if (weight_ratio > 1) {
    weight_ratio <- 1
  }

  nri_value <- (1.519 * albumin_g_l) + (41.7 * weight_ratio)

  risk_category <- ""

  if (nri_value > 100) {
    risk_category <- "No Risk"
  } else if (nri_value >= 97.5) {
    risk_category <- "Mild Risk"
  } else if (nri_value >= 83.5) {
    risk_category <- "Moderate Risk"
  } else {
    risk_category <- "Severe Risk"
  }

  return(list(
    NRI_Score = round(nri_value, 1),
    Risk_Category = risk_category,
    Inputs = list(
      Albumin_g_dL = albumin_g_dl,
      Current_Weight = current_weight_kg,
      Usual_Weight = usual_weight_kg
    )
  ))
}




